import Combine
import Foundation
import SwiftUI

/// UI language. Base strings are English; translations come from the tables below.
enum AppLanguage: String, CaseIterable, Identifiable {
    case system, en, ru, uk, es, pt, fr, de, zh, ja, ko, vi, tl
    var id: String { rawValue }

    /// Label for the picker item (in its own language). "Follow system" is
    /// shown in the *system's* language, not the current app language, so it
    /// stays stable and reads naturally regardless of what's selected.
    var label: String {
        switch self {
        case .system: return Localization.shared.string("Follow system", in: Localization.systemLanguage)
        case .en: return "English"
        case .ru: return "Русский"
        case .uk: return "Українська"
        case .es: return "Español"
        case .pt: return "Português"
        case .fr: return "Français"
        case .de: return "Deutsch"
        case .zh: return "中文"
        case .ja: return "日本語"
        case .ko: return "한국어"
        case .vi: return "Tiếng Việt"
        case .tl: return "Filipino"
        }
    }
}

extension AppLanguage {
    /// The code the Translation framework knows the language by.
    var translationCode: String {
        switch self {
        case .system: return Localization.systemLanguage.translationCode
        case .tl: return "fil"
        default: return rawValue
        }
    }

    /// The language's name in English — what a model is told to write in.
    var englishName: String {
        switch self {
        case .system: return Localization.systemLanguage.englishName
        case .en: return "English"
        case .ru: return "Russian"
        case .uk: return "Ukrainian"
        case .es: return "Spanish"
        case .pt: return "Portuguese"
        case .fr: return "French"
        case .de: return "German"
        case .zh: return "Chinese"
        case .ja: return "Japanese"
        case .ko: return "Korean"
        case .vi: return "Vietnamese"
        case .tl: return "Filipino"
        }
    }
}

/// Translation store; ObservableObject so views re-render when the language changes.
///
/// WHY @unchecked Sendable: `L()` is called from background contexts too (the
/// oracles, MeetingArchive), while the picker writes `language` on the main
/// thread — the lock below is what makes that pair safe, which the compiler
/// cannot see through on its own.
final class Localization: ObservableObject, @unchecked Sendable {
    static let shared = Localization()

    /// Explicit and stored: without any @Published property the protocol's
    /// reflection-based default would mint a fresh publisher per access, and
    /// the views' subscriptions would never hear `setLanguage`.
    let objectWillChange = ObservableObjectPublisher()

    /// Guards `_language` — the only mutable state.
    private let lock = NSLock()
    private var _language: AppLanguage

    private(set) var language: AppLanguage {
        get { lock.withLock { _language } }
        set { lock.withLock { _language = newValue } }
    }

    private init() {
        let stored = Settings.shared.uiLanguage
        self._language = AppLanguage(rawValue: stored) ?? .system
    }

    func setLanguage(_ lang: AppLanguage) {
        // Same timing as @Published's willSet had — and setLanguage is only
        // ever called from the pickers, on the main thread, where SwiftUI
        // wants this publisher fired.
        objectWillChange.send()
        language = lang
        Settings.shared.uiLanguage = lang.rawValue
    }

    /// The language the system resolves to (never .system).
    static var systemLanguage: AppLanguage {
        let code = Locale.preferredLanguages.first?
            .split(separator: "-").first.map(String.init) ?? "en"
        switch code {
        case "ru": return .ru
        case "uk": return .uk
        case "es": return .es
        case "pt": return .pt
        case "fr": return .fr
        case "de": return .de
        case "zh": return .zh
        case "ja": return .ja
        case "ko": return .ko
        case "vi": return .vi
        case "fil", "tl": return .tl   // macOS reports "fil" for Filipino
        default: return .en
        }
    }

    /// Effective language, taking "Follow system" into account.
    var effective: AppLanguage {
        language == .system ? Self.systemLanguage : language
    }

    func translate(_ en: String) -> String { string(en, in: effective) }

    /// Translate into a specific language — used for labels that must render
    /// in a fixed language regardless of the current UI language.
    func string(_ en: String, in lang: AppLanguage) -> String {
        switch lang {
        case .ru: return Self.ru[en] ?? en
        case .uk: return Self.uk[en] ?? en
        case .es: return Self.es[en] ?? en
        case .pt: return Self.pt[en] ?? en
        case .fr: return Self.fr[en] ?? en
        case .de: return Self.de[en] ?? en
        case .zh: return Self.zh[en] ?? en
        case .ja: return Self.ja[en] ?? en
        case .ko: return Self.ko[en] ?? en
        case .vi: return Self.vi[en] ?? en
        case .tl: return Self.tl[en] ?? en
        default: return en
        }
    }
}

/// Translates a base-English string.
func L(_ en: String) -> String { Localization.shared.translate(en) }

/// Translation with substituted arguments: Lf("Step %d of %d", 1, 4).
func Lf(_ en: String, _ args: CVarArg...) -> String {
    String(format: Localization.shared.translate(en), arguments: args)
}

