        "Recording stopped by itself — ten minutes of silence.": "Запись остановилась сама — десять минут тишины.",
        "%@ call started": "Начался звонок в %@",
        "Not this one": "Не этот",
        "Record": "Записать",
        "Record this call": "Записать этот звонок",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Диктовка, работающая офлайн — распознавание целиком на этом Mac.",
        "Translation that works offline — speak your language, another comes out.": "Перевод, работающий офлайн — говорите на своём языке, выходит другой.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Опциональный агент, знающий ваши встречи, — ответы цитируют момент, откуда взяты.",
        "%d MB of %d MB": "%d МБ из %d МБ",
        "Already clicked and nothing changed?": "Нажали, а ничего не изменилось?",
        "Applications": "Applications",
        "Downloading the speech model": "Скачиваю модель распознавания",
        "Grant…": "Выдать…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Отсюда ничего не уходит. Две маленькие пробы — и всё готово.",
        "Resume Download": "Продолжить загрузку",
        "Show me where to look": "Показать, куда смотреть",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Запускать Dictate при входе в систему — он появится в Dock и в строке меню; иконку Dock можно скрыть позже в настройках",
        "Start Using Dictate": "Начать пользоваться Dictate",
        "Stopped · %d MB of %d MB kept on disk": "Остановлено · %d МБ из %d МБ сохранено на диске",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "Соединение прервалось. Продолжение начнётся с того же места — все %d МБ заново скачивать не придётся.",
        "The download stopped at %d MB": "Загрузка остановилась на %d МБ",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Модель компилируется под ваш чип, чтобы распознавание потом было быстрым. Это занимает минуту при первом запуске и больше не повторяется.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Это происходит один раз. Модель остаётся на вашем Mac — поэтому диктовка потом работает без интернета.",
        "To hear you. Audio is processed on this Mac and discarded.": "Чтобы вас слышать. Звук обрабатывается на этом Mac и не сохраняется.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Чтобы впечатывать распознанный текст в приложение, где вы работаете. Это единственный способ, которым приложение может вставлять текст в другие.",
        "Try it here first": "Попробуйте прямо здесь",
        "Two permissions from macOS": "Два разрешения от macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "Их запрашивает macOS, не мы. Без обоих Dictate работать не может.",
        "Show or hide the conversations": "Показать или скрыть разговоры",
        "Show or hide the sidebar": "Показать или скрыть сайдбар",
        "Show or hide the meeting list": "Показать или скрыть список встреч",
        "Preparing the model for this Mac": "Готовлю модель для этого Mac",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Ещё не готово — после запуска это занимает несколько секунд. Держите %@, и всё начнётся.",
        "Transcript text": "Текст транскрипта",
        "Smaller text": "Мелкий текст",
        "Standard text": "Стандартный текст",
        "Larger text": "Крупный текст",
        "100 languages · from your system settings": "100 языков · из настроек системы",
        "Add tag": "Добавить тег",
        "Appearance": "Оформление",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Спрашиваем один раз. Дальше запись запускается из меню-бара без вопросов. Esc — не записывать.",
        "Check for updates": "Проверить обновления",
        "Choose your keys and languages": "Выберите клавиши и языки",
        "Click, then press a key": "Нажмите сюда, затем клавишу",
        "Dark": "Тёмное",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate запишет ваш микрофон и звук звонка и сохранит расшифровку на этом Mac. Запись других людей может требовать их согласия там, где вы находитесь.",
        "Don't Record": "Не записывать",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Держите клавишу, пока говорите. Всё можно поменять позже в настройках.",
        "I speak": "Я говорю",
        "Light": "Светлое",
        "Looking through %d meetings…": "Просматриваю %d встреч…",
        "Match system": "Как в системе",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Лучше всего работают клавиши-модификаторы: удержание не вводит символ. Esc всегда отменяет текущую диктовку.",
        "Reading “%@”…": "Читаю «%@»…",
        "Record this call?": "Записать этот звонок?",
        "Searching your meetings…": "Ищу по вашим встречам…",
        "Start Recording": "Начать запись",
        "Tags": "Теги",
        "Voices": "Голоса",
        "Summary": "Резюме",
        "Outline": "Оглавление",
        "Hide outline": "Скрыть оглавление",
        "Show outline": "Показать оглавление",
        "two levels": "два уровня",
        "%d moments": "Моментов: %d",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Хранится на этом Mac. Удаление мгновенно; после 50 бесед самые старые вытесняются.",
        "Ask across all meetings…": "Спросить по всем встречам…",
        "Recently Added": "Недавно добавленные",
        "%d meetings · %d h of audio": "%d встреч · %d ч аудио",
        "%d meetings · %d min of audio": "%d встреч · %d мин аудио",
        "Show more": "Показать полностью",
        "Try one of these": "Попробуйте что-то из этого",
        "Accessibility access is turned off": "Доступ Accessibility выключен",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "Диктовка вас слышит, но не может печатать. Включите доступ снова, чтобы продолжить.",
        "Recent dictations": "Недавние диктовки",
        "Secure input is active — the hotkey cannot work": "Включён защищённый ввод — горячая клавиша не может работать",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "У какого-то приложения в фокусе поле пароля. macOS не говорит, у какого. Кликните в обычное текстовое поле — и диктовка снова заработает.",
        "Start Recording Meeting": "Записать встречу",
        "Stop Recording Meeting": "Остановить запись встречи",
        "dictate in %@": "диктовка на %@",
        "dictate in any language": "диктовка на любом языке",
        "translate %@ → %@": "перевод %@ → %@",
        "translate into %@": "перевод на %@",
        "%d waiting": "Ожидает: %d",
        "%d words typed": "Напечатано слов: %d",
        "Add a Key…": "Добавить ключ…",
        "Both will be inserted in the order you spoke them": "Обе будут вставлены в том порядке, в котором вы их сказали",
        "Check Audio Setup": "Проверить настройки звука",
        "Clear All Filters": "Сбросить все фильтры",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "F-клавиши также управляют системой (яркость, медиа) — macOS сделает и то, и другое. Чтобы использовать её как обычную клавишу, включите «Use F1, F2, etc. as standard function keys» в настройках клавиатуры.",
        "How this works": "Как это работает",
        "Input device changed": "Устройство ввода изменилось",
        "Insert text by": "Вставлять текст",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Он был отозван или заменён после подключения. Ключ удалён из Связки ключей — с ним ничего не отправлялось повторно.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Начните звонок в браузере и запустите запись. Dictate записывает ваш микрофон и звук звонка, распознаёт оба на этом Mac и хранит транскрипт здесь. Ничего не загружается в сеть.",
        "No meeting has all of these tags": "Ни одна встреча не имеет всех этих тегов",
        "No meeting has this tag": "Ни одна встреча не имеет этого тега",
        "Nothing was said, or nothing was heard": "Ничего не было сказано — или ничего не было слышно",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Здесь виден только неподтверждённый хвост — остальное уже в документе",
        "Open Console": "Открыть консоль",
        "Open Settings": "Открыть настройки",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Вставка мгновенна, но на миг подменяет буфер обмена. Печать работает там, где вставка заблокирована — в некоторых терминалах и удалённых рабочих столах.",
        "Pasting it at once": "Вставкой целиком",
        "Recording ended here — this Mac went to sleep.": "Запись закончилась здесь — Mac уснул.",
        "Remove “%@”": "Убрать «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return — отправить · Shift-Return — новая строка · Esc — очистить",
        "Show Floating Timer": "Показать плавающий таймер",
        "Start Recording a Meeting": "Записать встречу",
        "Still recognizing the previous dictation": "Предыдущая диктовка ещё распознаётся",
        "Still recognizing the previous dictation · %d words": "Предыдущая диктовка ещё распознаётся · %d слов",
        "Switched to %@": "Переключено на %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Фильтры тегов объединяются через «и» — встреча должна нести каждый выбранный тег.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Ответ прервался. Ваш вопрос сохранён выше — повторите, когда появится связь. Поиск и транскрипты работают.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Запись шла, но речь не распознана ни с одной стороны. Обычно это значит, что звук звонка не был захвачен — вкладка браузера без доступа к звуку или не то устройство вывода.",
        "The saved key no longer works": "Сохранённый ключ больше не работает",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Переключатель останется выключенным, пока доступ не выдан в System Settings › Privacy & Security › Calendars. Читаются только названия событий, пересекающихся с записью.",
        "This Mac is offline": "Этот Mac офлайн",
        "Too many questions at once": "Слишком много вопросов сразу",
        "Typing as you speak": "Печатаю, пока вы говорите",
        "Typing into %@ as you speak": "Печатаю в %@, пока вы говорите",
        "Typing it out character by character": "Печатью по буквам",
        "Your provider account is out of credit": "На счету провайдера закончились кредиты",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Провайдер ограничивает частоту запросов. Подождите пару секунд и повторите — ничего не потеряно.",
        "macOS denied calendar access": "macOS отказала в доступе к календарю",
        "API key": "API-ключ",
        "All Meetings": "Все встречи",
        "Assistant": "Ассистент",
        "Checking the key with %@. No transcript is sent — only a test request.": "Проверяем ключ у %@. Транскрипты не отправляются — только тестовый запрос.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Закрытие окна не останавливает запись. Остановите её здесь или из меню-бара в любой момент.",
        "Connect an assistant to answer questions": "Подключите ассистента, чтобы получать ответы",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate может записать звонок в браузере и сохранить транскрипт на этом Mac. Запустите запись из меню-бара, когда начнётся следующий звонок — согласие спросим один раз.",
        "Done": "Готово",
        "Every change takes effect immediately.": "Каждое изменение применяется сразу.",
        "Get one at %@.": "Получить на %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Зажмите клавишу, говорите, отпустите. Сказанное будет напечатано там, где курсор, — в любом приложении на этом Mac.",
        "Keys": "Клавиши",
        "Languages": "Языки",
        "Library": "Библиотека",
        "Paste a key from your own account.": "Вставьте ключ от собственного аккаунта.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Сохранён в Связке ключей, но не проверен — этот Mac офлайн. Проверим при первом вопросе.",
        "Set Up Dictate": "Настроить Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Хранится в Связке ключей macOS на этом Mac. Не записывается в файлы настроек, не синхронизируется.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Ключ отклонён. Возможно, он отозван, от другого провайдера или без кредитов — сам ключ не был сохранён.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Транскрипты, поиск и цитаты работают без этого. Ассистент нужен только чтобы написать ответ.",
        "Try Again": "Повторить",
        "Updates": "Обновления",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Каждый вопрос оплачивается вашему провайдеру — обычно доли цента. Отправляются только вопрос и найденные цитаты; записи не покидают этот Mac.",
        "Send": "Отправить",
        "Conversations": "Разговоры",
        "New question": "Новый вопрос",
        "Deleted “%@”": "Удалено: «%@»",
        "Undo": "Отменить",
        "Questions you ask are kept here so you can return to an answer.": "Заданные вопросы сохраняются здесь — к ответу можно вернуться.",
        "Rename": "Переименовать",
        "Delete": "Удалить",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Голоса сличаются по звуку — имя применяется только к репликам этого голоса.",
        "Give two voices the same name to merge them.": "Дайте двум голосам одно имя, чтобы объединить их.",
        "Voices are told apart by sound — one person can show up as two.": "Голоса различаются по звуку — один человек может отобразиться как два.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "Кликните по имени, чтобы переименовать голос, — одинаковое имя объединяет два. Резюме и ответы опираются на то, что было сказано, а не на то, кто это сказал.",
        "Voice separation improves over time.": "Разделение голосов со временем становится точнее.",
        "About voice separation": "О разделении голосов",
        "Call · voice %d": "Звонок · голос %d",
        "Starred": "Избранные",
        "Other browser calls": "Другие браузерные звонки",
        "Sources": "Источники",
        "Star meeting": "В избранное",
        "Unstar meeting": "Убрать из избранного",
        "Export transcript…": "Экспортировать транскрипт…",
        "Still recording": "Запись продолжается",
        "Got it": "Понятно",
        "Call": "Звонок",
        "Dictating": "Диктовка",
        "Dictating in %@": "Диктовка: %@",
        "Translating into English": "Перевожу на английский",
        "Translating into %@": "Перевожу на %@",
        "Release %@ to insert": "Отпустите %@, чтобы вставить",
        "Also recording this meeting": "Одновременно записывается митинг",
        "%@ MB/s · about %@ left": "%@ МБ/с · осталось около %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Недостаточно места на диске: загрузке нужно около %d МБ, свободно %d МБ. Освободите место и повторите.",
        "Fix…": "Исправить…",
        "Checked automatically · last %@": "Проверяется автоматически · последняя: %@",
        "Source code": "Исходный код",
        "Report an issue": "Сообщить о проблеме",
        "Finishing the transcript…": "Завершаю транскрипт…",
        "Disk almost full — will stop to keep the transcript": "Диск почти полон — запись остановится, чтобы сохранить транскрипт",
        "Dictate is running from its disk image": "Dictate запущен из образа диска",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Разрешения, выданные копии из образа диска, пропадут после его извлечения, а модель будет скачиваться каждый раз заново. Сначала переместите Dictate в папку «Программы».",
        "Move to Applications": "Переместить в «Программы»",
        "Quit": "Завершить",
        "Couldn't move Dictate automatically": "Не удалось переместить Dictate автоматически",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Перетащите Dictate из образа диска в папку «Программы» и запустите его оттуда.",
        "OK": "OK",
        "Inserted into %@": "Вставлено в %@",
        "Inserted": "Вставлено",
        "Accessibility is off — dictation can hear you but cannot type": "Универсальный доступ выключен — диктовка слышит вас, но не может печатать",
        "Open Privacy & Security…": "Открыть «Конфиденциальность и безопасность»…",
        "1 dictation still being recognized": "1 диктовка ещё распознаётся",
        "%d dictations still being recognized": "%d диктовки ещё распознаются",
        "Language Packs…": "Языковые пакеты…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Если выключено, Dictate живёт только в строке меню. Клик по значку в Dock открывает «Митинги»; значок в строке меню есть в любом случае.",
        "Interface language": "Язык интерфейса",
        "Granted": "Выдано",
        "No": "Нет",
        "Model ready": "Модель готова",
        "On-device recognition": "Распознавание на устройстве",
        "Spoken language": "Язык речи",
        "Download failed. Check your connection and retry.": "Загрузка не удалась. Проверьте соединение и повторите.",
        "Not set": "Не назначена",
        "Remove": "Убрать",
        "Download & continue": "Скачать и продолжить",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Около %@ — скачивается один раз. Это единственный момент, когда Dictate нужен интернет.",
        "Hold %@ and say something — the recognized text shows up below.": "Зажмите %@ и скажите что-нибудь — распознанный текст появится ниже.",
        "Recognized text appears here…": "Распознанный текст появится здесь…",
        // Menu bar
        "Settings…": "Настройки…",
        "Quit Dictate": "Завершить Dictate",
        "Dictate — voice dictation": "Dictate — голосовая диктовка",
        // HUD
        "Recognizing…": "Распознаю…",
        "Esc to cancel": "Esc — отмена",
        // Errors
        "Couldn't start recording: %@": "Не удалось начать запись: %@",
        "Recording truncated at %d seconds (limit)": "Запись обрезана на %d секундах (лимит)",
        "Audio device changed during recording — recording cancelled, please try again.": "Аудиоустройство сменилось во время записи — запись отменена, попробуйте ещё раз.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "Разрешение «Универсальный доступ» выключено, поэтому клавиша не слышна. Включите его: Системные настройки → Конфиденциальность и безопасность → Универсальный доступ. Dictate подхватит сам, перезапуск не нужен.",
        "Microphone unavailable (no input audio format)": "Микрофон недоступен (нет входного аудиоформата)",
        // Key names
        "Right Option (⌥)": "Правый Option (⌥)",
        "Left Option (⌥)": "Левый Option (⌥)",
        "Right Command (⌘)": "Правый Command (⌘)",
        "Left Command (⌘)": "Левый Command (⌘)",
        "Right Shift (⇧)": "Правый Shift (⇧)",
        "Left Shift (⇧)": "Левый Shift (⇧)",
        "Right Control (⌃)": "Правый Control (⌃)",
        "Left Control (⌃)": "Левый Control (⌃)",
        "Space": "Пробел",
        "Follow system": "Как в системе",
        "Translating…": "Перевожу…",
        "Tip: hold %@ instead — your speech comes out in English.": "Совет: зажмите %@ вместо обычной — речь напечатается по-английски.",
        "Hold to talk in your language, release to insert it in English.": "Зажмите и говорите на своём языке, отпустите — вставится по-английски.",
        "Hold %@ and say it again — this time it's typed in English.": "Зажмите %@ и скажите то же самое — теперь это напечатается по-английски.",
        "Translate to": "Переводить на",
        "Translation data isn't downloaded — open Settings to get it": "Данные перевода не скачаны — скачайте их в настройках",
        "Translation data": "Данные перевода",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "Клавиша перевода распознаёт вашу речь, а затем macOS переводит её прямо на этом Mac. При выборе языка macOS может один раз скачать его данные перевода.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "Распознавание работает на Neural Engine вашего Mac — Whisper large-v3-turbo: 100 языков, хорошо справляется с акцентом и достаточно быстрый для живого текста. Перевод тоже идёт на этом Mac. Ваш голос не покидает этот компьютер.",
        "Hold %@ and say it again — this time it comes out in %@.": "Зажмите %@ и скажите то же самое — теперь это выйдет на %@.",
        "Hold to talk in your language, release to insert it in %@.": "Зажмите и говорите на своём языке, отпустите — вставится на %@.",
        "Not downloaded": "Не скачаны",
        "Translation languages": "Языки перевода",
        "Downloaded": "Скачан",
        "Manage in System Settings…": "Управлять в Системных настройках…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "Уже включено в Системных настройках, а галочки нет? Выключите и снова включите переключатель Dictate — после обновления приложения macOS иногда держит устаревшую запись.",
        "Agent: %@, on your key.": "Агент: %@, на вашем ключе.",
        "Agent: off.": "Агент: выключен.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "На этом Mac Apple Intelligence не поддерживается для этого региона или языка. Агент с вашим ключом всё равно работает.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence требует macOS 26. Агент с вашим ключом всё равно работает.",
        "Copy diagnostics": "Скопировать диагностику",
        "Debug audio dumps": "Отладочные аудиозаписи",
        "Diagnostics": "Диагностика",
        "Downloading…": "Загрузка…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Освободит %@. Новые митинги останутся с названиями по дате, пока вы не загрузите её снова. Уже написанные резюме сохранятся.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Освободит %@. Больше ничего не изменится — чтение митингов выключено.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Освободит %@. Названия и резюме будет писать Apple Intelligence.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Установлена, но не работает: у этого Mac %d ГБ памяти, а нужно 16.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Установлена, но не работает: у этого Mac %d ГБ памяти, а нужно 16. Митинги на этом Mac ничто не читает.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Установлена, но не работает: у этого Mac %d ГБ памяти, а нужно 16. Названия и резюме вместо этого пишет Apple Intelligence.",
        "Installed · %@": "Установлена · %@",
        "Installed, not in use · %@": "Установлена, не используется · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Во время работы она держит около %@ памяти — на этом Mac это заметно.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, версия и какие функции включены. Ни транскриптов, ни ключей.",
        "Meeting archive": "Архив митингов",
        "Meeting model": "Модель митингов",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Модель митингов установлена. Новые митинги получают названия и резюме на этом Mac.",
        "Meeting reading: Apple Intelligence.": "Чтение митингов: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Чтение митингов: на этом Mac пока нечем.",
        "Meeting reading: the downloaded model (%@).": "Чтение митингов: загруженная модель (%@).",
        "Not available on this Mac.": "Недоступно на этом Mac.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "Не установлена. Разовая загрузка %@ даст названия, резюме и оглавление.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "На этом Mac пока нечем читать: Apple Intelligence здесь не поддерживается. Агент с вашим ключом всё равно работает.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "На этом Mac пока нечем читать: загрузите модель митингов ниже или добавьте ключ для агента.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "На этом Mac пока нечем читать: загрузите модель митингов ниже или включите Apple Intelligence в Системных настройках.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "На этом Mac пока нечем читать: macOS ещё настраивает Apple Intelligence. Агент с вашим ключом всё равно работает.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "На этом Mac пока нечем читать: включите Apple Intelligence в Системных настройках или добавьте ключ для агента.",
        "Open System Settings": "Открыть Системные настройки",
        "Paused: not enough free memory right now. It resumes on its own.": "Пауза: сейчас не хватает свободной памяти. Продолжится само.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Подготовка модели под процессор этого Mac… Несколько минут, один раз.",
        "Raw call audio kept for debugging only.": "Сырой звук звонков, хранится только для отладки.",
        "Reading is on, but nothing on this Mac can read yet.": "Чтение включено, но на этом Mac пока нечем читать.",
        "Reads with Apple Intelligence.": "Читает через Apple Intelligence.",
        "Reads with the downloaded model.": "Читает загруженной моделью.",
        "Recognition runs on the Neural Engine.": "Распознавание работает на Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "Распознавание работает на процессоре этого Mac — Whisper large-v3-turbo: 100 языков, хорошо справляется с акцентом. Медленнее, чем на Apple Silicon, и перевод тоже идёт на этом Mac. Ваш голос не покидает этот компьютер.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "Распознавание работает на процессоре этого Mac — медленнее, чем на Apple Silicon.",
        "Remove the debug audio dumps?": "Удалить отладочные аудиозаписи?",
        "Remove the meeting model?": "Удалить модель митингов?",
