        "Storage": "Хранилище",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Резюме на этом Mac пишет Apple Intelligence. Загружаемой модели нужно 16 ГБ памяти; у этого Mac — %d.",
        "Summary paused: not enough free memory. It resumes on its own.": "Резюме на паузе: не хватает свободной памяти. Продолжится само.",
        "Tell the voices on a call apart.": "Различать голоса в звонке.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "Модели митингов нужно 16 ГБ памяти; у этого Mac — %d.",
        "These are recordings kept only for debugging. Nothing else is affected.": "Это записи, которые хранятся только для отладки. Больше ничего не затрагивается.",
        "This Mac": "Этот Mac",
        "This build of Dictate does not include the meeting model.": "Эта сборка Dictate не включает модель митингов.",
        "Titles and summaries come from Apple Intelligence instead.": "Названия и резюме вместо этого пишет Apple Intelligence.",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "Включите Apple Intelligence в разделе Системные настройки › Apple Intelligence и Siri или добавьте ключ для агента.",
        "Waiting for the call to end.": "Ждёт окончания звонка.",
        "Your transcripts, as Markdown files you own.": "Ваши транскрипты — файлы Markdown, которые принадлежат вам.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS ещё настраивает Apple Intelligence — загляните позже или добавьте ключ для агента.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. Отчёт в любом случае остаётся в файле встречи; это создаёт копию.",
