        "The model returned no report.": "Модель не вернула отчёт.",
        "The model stopped before the report was finished.": "Модель остановилась, не дописав отчёт.",
        "The saved key no longer works. It has been removed from the Keychain.": "Сохранённый ключ больше не работает. Он удалён из Связки ключей.",
        "What is sent": "Что отправляется",
        "Writing · about a minute": "Пишу · около минуты",
        "Written by Dictate on this Mac from the transcript": "Написано Dictate на этом Mac по транскрипту",
        "Your %@ account refused the request for billing reasons.": "Ваш аккаунт %@ отклонил запрос по биллингу.",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "Отправляет этот транскрипт в %@ на вашем ключе. Отчёт ложится в файл встречи.",
        "Set up templates…": "Настроить шаблоны…",
        "Write report": "Написать отчёт",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@ ограничивает частоту запросов. Ничего не потеряно — попробуйте через минуту.",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "Этот Mac офлайн. Ничего не отправлено — попробуйте, когда вернётся связь.",
        "Write a “%@” report?": "Написать отчёт «%@»?",
