        "Decisions": "Решения",
        "Decisions & actions": "Решения и задачи",
        "Every date, deadline or time window that was mentioned, and what it is for": "Каждая дата, срок или окно времени, которые прозвучали, и к чему они относятся",
        "Key points": "Ключевые тезисы",
        "Meeting summary": "Итоги встречи",
