        "Purpose": "Цель",
        "Risks and concerns": "Риски и опасения",
        "The main arguments and facts, with the numbers, names and dates that were said": "Главные аргументы и факты — с цифрами, именами и датами, которые прозвучали",
        "The next meeting or checkpoint, if one was agreed": "Следующая встреча или контрольная точка, если о ней договорились",
        "Waiting on": "Ждём от других",
        "We are the team on this call; the reader took part in it.": "Мы — команда на этом звонке; читатель в нём участвовал.",
        "What could go wrong, who raised it, how serious it sounded": "Что может пойти не так, кто это поднял и насколько серьёзно это звучало",
        "What each side is waiting for from the other": "Чего каждая сторона ждёт от другой",
        "What was decided, by whom, and what it replaces": "Что решили, кто решил и что это заменяет",
        "What was raised and not settled, and who owns it": "Что подняли и не закрыли, и кто за это отвечает",
        "Who does what, by when — one line per task": "Кто что делает и к какому сроку — по строке на задачу",
        "Why we met and what we set out to settle": "Зачем встречались и что собирались решить",
        "%d more": "ещё %d",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "Название остаётся на языке встречи; саммари и все отчёты пишутся на этом. Имена полей в отчёте остаются ровно как напечатаны.",
        "About “%@”:": "По встрече «%@»:",
        "Replace the report with a new “%@” one?": "Заменить отчёт новым по шаблону «%@»?",
        "Replace report": "Заменить отчёт",
        "Written · replaces it": "Есть · будет заменён",
        "Dictate updated to %@.": "Dictate обновился до %@.",
        "Dismiss": "Закрыть",
        "New": "Новое",
        "New in this version": "Новое в этой версии",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Откройте встречу, нажмите Write report в её шапке и выберите шаблон. Отчёт ляжет на карточку и PDF-файлом в Dictate Meetings › Reports.",
        "Reports from templates": "Отчёты по шаблонам",
        "See what’s new": "Что нового",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Settings › Meetings › Write summaries and reports in: саммари и все отчёты пишутся на языке, на котором вы читаете, на каком бы языке ни шёл звонок.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Settings › Templates: начните с «Итоги встречи» или «Решения и задачи» либо назовите свои поля и опишите модели, что писать под каждым.",
        "Summaries in your language": "Саммари на вашем языке",
        "What’s new": "Что нового",
        "What’s new in Dictate %@": "Что нового в Dictate %@",
        "Your own templates": "Свои шаблоны",
        "Install update %@ and relaunch": "Установить обновление %@ и перезапустить",
        "The update waits until the recording ends.": "Обновление подождёт, пока закончится запись.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "Обновление %@ уже в пути — скачивается. Установится само в ближайший спокойный момент; в строке меню можно раньше.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "Обновление %@ готово — установите из строки меню, или оно установится само в ближайший спокойный момент.",
        "An update is already on its way — it installs itself at the next quiet moment.": "Обновление уже в пути — установится само в ближайший спокойный момент.",
        "Downloading update %@…": "Скачивается обновление %@…",
        "Preparing update %@…": "Готовится обновление %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate обновился до %@. Что нового — в окне Meetings.",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence отказался составлять резюме этой встречи.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "Транскрипт, поиск и агент не пострадали. У скачиваемой модели, которая живёт на этом Mac, таких ограничений нет.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Встречи записаны и структурированы: спикеры, саммари, аутлайн, поиск. Dictate предлагает записать звонок — и никогда не пишет без вашего ответа.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "Модели встреч нужно 16 ГБ памяти; у этого Mac — %d. Она не работает, а занятые ею %@ на диске можно освободить.",
        "Clipboard restored.": "Буфер обмена восстановлен.",
        "Your words were inserted untranslated.": "Ваши слова вставлены без перевода.",
        "A small panel appears when a call starts, and you decide there.": "При начале звонка появляется небольшая панель, и вы решаете там.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Пишет резюме и оглавление и даёт агенту материал для ответов. В любом случае никуда ничего не отправляется.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Выключено — только ваш микрофон; включено — расшифровывается и вторая сторона.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Превращает сплошной блок текста в реплики с именами. Разделение идёт по звуку и бывает неточным; имена можно менять.",
        "Find in this transcript…": "Найти в этом транскрипте…",
        "%d of %d": "%d из %d",
        "No matches": "Совпадений нет",
        "Previous match": "Предыдущее совпадение",
        "Next match": "Следующее совпадение",
        "Close find": "Закрыть поиск",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "Выбран %@, но ключа ещё нет. Агент и отчёты выключены, пока он не добавлен.",
        "%@ · required for dictation, cannot be removed.": "%@ · нужна для диктовки, удалить нельзя.",
        "%@ — not written": "%@ — не написан",
        "%d h": "%d ч",
        "%d meetings have a %@ report. They stay if this template goes.": "Отчёт «%@» есть у %d встреч. Они останутся, если шаблон удалить.",
        "%d min ago": "%d мин назад",
        "%d written": "написано: %d",
        "%d written, %d not written": "написано: %d, не написано: %d",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 языков. Применяется к этому окну и строке меню сразу. Язык, на котором вы говорите, задаётся в разделе «Диктовка».",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Ключ из вашего собственного аккаунта %@. Хранится в Связке ключей, никогда — в файле настроек.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Вопрос отправляет сам вопрос и фрагменты, найденные поиском. Отчёт отправляет всю расшифровку встречи — около 12 000 слов за час разговора. Оба уходят в %@ по вашему ключу и только по вашему запросу. Записи никогда не покидают этот Mac.",
        "About": "О программе",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "Apple Intelligence на этом Mac недоступен, поэтому запасного варианта нет.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence нужна более новая macOS, чем стоит на этом Mac, поэтому запасного варианта нет.",
        "Applies to this window, the meetings window and the panels over your other apps.": "Действует на это окно, окно встреч и панели поверх других приложений.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Спрашиваем один раз. Дальше панель будет короткой и останется, пока вы не ответите. Запись можно начать и из строки меню в любой момент звонка.",
        "Calendar": "Календарь",
        "Collapse %@": "Свернуть %@",
        "Copy": "Скопировать",
        "Dictation": "Диктовка",
        "Expand %@": "Развернуть %@",
        "Export…": "Экспортировать…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "Текст есть и в «Недавних диктовках», так что буфер обмена снова ваш, когда захотите.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Хранятся внутри файла этой встречи, поэтому путешествуют вместе с расшифровкой. Экспорт делает копию туда, куда захотите.",
        "No report": "Без отчёта",
        "No report for this meeting yet.": "Для этой встречи отчёта ещё нет.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "При удалении ничего не теряется: расшифровка, поиск и агент от неё не зависят.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Здесь ничего не настраивается. Каждая строка выше либо сообщает, что умеет этот Mac, либо указывает на раздел, где это задаётся.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "На этом Mac пока нечему читать встречи: Apple Intelligence нужна более новая macOS. Агент с вашим ключом всё равно работает.",
        "Nothing was kept from this take — earlier ones are still here.": "Из этой попытки ничего не сохранилось — предыдущие по-прежнему здесь.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "Ничего не записалось, поэтому нечего сохранять. Предыдущие по-прежнему здесь.",
        "Off — dictation cannot type": "Выключено — диктовка не может печатать",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Выключено: расшифровки, резюме, планы и поиск работают как раньше. Агент отвечает на вопросы по всем вашим встречам и пишет отчёты по вашим шаблонам; он работает в облаке по вашему собственному API-ключу.",
        "On this Mac": "На этом Mac",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Один файл с докачкой. Закрытие Dictate ставит её на паузу; потом она продолжится с того же места.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Однократная загрузка %@, после чего заголовки, резюме и планы делаются целиком на этом Mac. Для работы нужно 16 ГБ памяти; пока модель пишет, она занимает около %@.",
        "Open System Settings…": "Открыть Системные настройки…",
        "Or start from the menu bar later in the call.": "Или начните из строки меню позже во время звонка.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "Сейчас на паузе: не хватает свободной памяти. Она продолжится сама, а встречи, ждущие резюме, сохраняют свои расшифровки.",
        "Permissions": "Разрешения",
        "Reads with Apple Intelligence until the download finishes.": "Читает через Apple Intelligence, пока не завершится загрузка.",
        "Reads with the downloaded model — paused until there is free memory.": "Читает загруженной моделью — на паузе, пока не освободится память.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Шаблоны отчётов — в разделе «Шаблоны»; готовые отчёты — в библиотеке, в разделе «Отчёты».",
        "Report · %@": "Отчёт · %@",
        "Report · %@ +%d": "Отчёт · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Отчётам нужен агент, а он выключен. Выберите Claude или ChatGPT в разделе «Резюме и отчёты»; шаблоны до тех пор сохраняются.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Работает целиком на этом Mac. Без неё заголовки и резюме делает Apple Intelligence.",
        "Startup": "Запуск",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Хранится в Связке ключей, никогда — в файле настроек. Агент отвечает на вопросы по всем вашим встречам и пишет отчёты по вашим шаблонам.",
        "Summaries": "Резюме",
        "Summaries & reports": "Резюме и отчёты",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "Загрузка — способ получать резюме на этом Mac без Apple Intelligence. Расшифровка и поиск работают в любом случае.",
        "This Mac was offline. Nothing was sent.": "Этот Mac был не в сети. Ничего не отправлено.",
        "This take was not kept. Earlier ones are still here.": "Эта попытка не сохранилась. Предыдущие по-прежнему здесь.",
        "Uses 41 MB of speaker models.": "Использует 41 МБ моделей голосов.",
        "What’s new in %@": "Что нового в %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Читает ли что-нибудь эти записи — резюме, планы, отчёты и агент — задаётся в разделе «Резюме и отчёты». Этот раздел только о том, что записывается на этом Mac.",
        "Write again": "Написать заново",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "«Написать отчёт» выше перечисляет ваши шаблоны (%d). Написание отправляет эту расшифровку в %@ по вашему ключу; отчёт хранится внутри файла встречи и путешествует вместе с расшифровкой. Экспорт делает копию туда, куда захотите.",
        "Written %@": "Написан %@",
        "Written by %@": "Написал %@",
        "Written by %@ %@ at %@": "Написал %@ %@ в %@",
        "Written in": "Язык текста",
        "Your agent, on your key": "Ваш агент, по вашему ключу",
        "click to insert": "нажмите, чтобы вставить",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS ещё настраивает Apple Intelligence. Это может занять время, и отсюда его не поторопить.",
        "macOS resets this switch after some updates and never asks a second time.": "macOS сбрасывает этот переключатель после некоторых обновлений и никогда не спрашивает повторно.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-клик — скопировать вместо вставки. Очищается при выходе из Dictate.",
        "Meeting names": "Названия встреч",
        "%d meetings, reports included": "встреч: %d, включая отчёты",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "Загрузите модель встреч в разделе «Резюме и отчёты» или добавьте ключ для агента.",
        "Calls": "Звонки",
        "Reports folder": "Папка отчётов",
        "%d PDFs written before %@": "PDF, записанных до %@: %d",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate больше не пишет PDF сам. Эти файлы ваши — храните или удаляйте; в приложении от них ничего не зависит.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "Уже написанный отчёт будет заменён. Эта расшифровка отправится в %@ по вашему ключу.",
        "%@ · report not written": "%@ · отчёт не написан",
        "%d of %d selected · %d meetings without one": "выбрано %d из %d · без отчёта: %d",
        "%d passages from %d meetings": "фрагментов: %d из %d встреч",
        "%d written across %d templates": "написано %d по %d шаблонам",
        "%d written · %d meetings without one · %d fields": "написано %d · без отчёта %d · полей %d",
        "%d written · writing %d · %d not written": "написано %d · пишется %d · не написано %d",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Отчёт пишется по запросу — с карточки встречи или для выделенных здесь. Каждый отправляет расшифровку той встречи в %@ по вашему ключу и хранится внутри файла встречи.",
        "All reports": "Все отчёты",
        "Answer": "Ответ",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Ответил %@ по %d из %d встреч. Цитаты дословно из расшифровок на этом Mac.",
        "Copy as Markdown": "Скопировать как Markdown",
        "Copy as plain text": "Скопировать как обычный текст",
        "Copy the answer only": "Скопировать только ответ",
        "Copy with quotes": "Скопировать с цитатами",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "У каждого шаблона свои отчёты: что написано и какие встречи могли бы получить отчёт. Сами шаблоны редактируются в Настройках › Шаблоны.",
        "Edit template…": "Изменить шаблон…",
        "No report yet · %d meetings": "Отчёта ещё нет · встреч: %d",
        "None written · %d fields": "Ничего не написано · полей: %d",
        "Nothing written from this template yet": "По этому шаблону ещё ничего не написано",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Выключено: эти %d пропускаются, пишется отчётов: %d. Замену нельзя отменить.",
        "Pick a template": "Выберите шаблон",
        "Quotes": "Цитаты",
        "Replace the %d that already have one": "Заменить %d уже написанных",
        "Report not written — the request was refused. The meeting has the detail.": "Отчёт не написан — запрос отклонён. Подробности на карточке встречи.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Отправляет расшифровок: %d в %@ по вашему ключу — около %@ слов. Каждый отчёт хранится внутри файла своей встречи. Записи никогда не покидают этот Mac.",
        "The %d existing reports are overwritten. This cannot be undone.": "Существующие отчёты (%d) будут перезаписаны. Это нельзя отменить.",
        "Write": "Написать",
        "Write %d": "Написать %d",
        "Write %d reports…": "Написать отчётов: %d…",
        "Write a “%@” report for %d meetings?": "Написать отчёт «%@» для %d встреч?",
        "Write a “%@” report for “%@”?": "Написать отчёт «%@» для «%@»?",
        "Write all %d…": "Написать все %d…",
        "Write for a selection…": "Написать для выделенных…",
        "Write report › %@": "Написать отчёт › %@",
        "Written": "Написано",
        "No instruction — goes by its name alone": "Без инструкции — по одному названию",
        "Drag to reorder": "Перетащите, чтобы изменить порядок",
        "Every report is kept inside its meeting’s file.": "Каждый отчёт хранится внутри файла своей встречи.",
        "A refusal stops that meeting only; the rest continue.": "Отказ останавливает только эту встречу; остальные продолжаются.",
        "Always assume": "Считать данностью",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Факты, которых в звонке не произносят, но каждый отчёт должен принимать как данность: кто вы, какая сторона клиент, какие слова ваша команда понимает по-своему. Отправляется с каждым отчётом по этому шаблону.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Необязательно. Без этого модель читает звонок с нуля: для встречи коллег это обычно нормально, для звонка с внешней стороной — нет.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Мы — агентство продаж. Клиент — всегда другая сторона, не мы. «Места» значит платные лицензии пользователей.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Показывается на карточке встречи, в библиотеке в разделе Reports и как заголовок внутри готового отчёта.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Каждое поле становится заголовком в отчёте, в этом порядке. Перетащите поле за ручку, чтобы переместить. Инструкция необязательна и может быть любой длины; поле без неё берётся по одному названию.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Каждое поле заполняется только из расшифровки этого звонка. Поле, которого звонок не коснулся, получает «Not discussed».",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Шаблон — это название и несколько полей. Отчёт по нему пишется по запросу, один на шаблон для каждой встречи.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Шаблонов пока нет. Шаблон — это название и несколько полей; отчёт по нему пишется по запросу с карточки встречи, один на шаблон для каждой встречи.",
    ]

    static let uk: [String: String] = [
        "Settings": "Налаштування",
        "Keyboard shortcuts": "Сполучення клавіш",
        "Storage & models": "Сховище та моделі",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Keychain відмовився зберегти ключ — він залишився в полі. Розблокуйте в'язку і спробуйте ще раз.",
        "Couldn't reach the update server. Try again once you're online.": "Не вдалося зв'язатися з сервером оновлень. Спробуйте, коли з'явиться мережа.",
        "You're up to date — Dictate %@ is the newest version.": "У вас остання версія — новішої за Dictate %@ немає.",
        "Recorded meetings appear here.": "Записані зустрічі з'являться тут.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Тут лише ваш мікрофон — друга сторона дзвінка не записувалась, і її не відновити.",
        "Turning both on covers the calls that come next.": "Якщо увімкнути обидва, наступні дзвінки буде записано повністю.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ відхилив запит через білінг. Поповніть рахунок у провайдера або відключіть агента в налаштуваннях.",
        "Agent": "Агент",
        "Ask your agent": "Запитати агента",
        "Ask your agent anything…": "Запитайте агента про будь-що…",
        "Has read %d of %d meetings": "Прочитав %d із %d зустрічей",
        "Has read 1 meeting": "Прочитав 1 зустріч",
        "Has read all %d meetings": "Прочитав усі %d зустрічей",
        "Meetings & Agent…": "Зустрічі та агент…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "«Не зараз» залишить агента вимкненим і прихованим. Пошук і транскрипти працюють як раніше.",
        "Nothing to read yet": "Поки нічого читати",
        "Off — has read nothing yet": "Вимкнений — ще нічого не прочитав",
        "Reading %d of %d meetings…": "Читаю %d із %d зустрічей…",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "Саме це пише резюме та зміст і дає агентові матеріал для відповідей. Вимкнено — залишається сирий транскрипт: ні резюме, ні змісту, ні агента. У будь-якому разі нікуди нічого не надсилається.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Ваш агент відповідає на запитання по всьому, що ви записали, — «що ми вирішили щодо дати заморозки» — і називає зустріч та момент, звідки взято відповідь. Для цього потрібна модель, яка читає ваші зустрічі, а вона зараз вимкнена. У будь-якому разі з цього Mac нічого не йде.",
        "Your agent has nothing to read yet": "Вашому агентові поки нічого читати",
        "Your agent has read 1 meeting": "Ваш агент прочитав 1 зустріч",
        "Your agent has read all %d meetings": "Ваш агент прочитав усі %d зустрічей",
        "Your agent is off": "Ваш агент вимкнений",
        "Your agent is reading — %d of %d meetings so far": "Ваш агент читає — поки %d із %d зустрічей",
        "answers with %@": "відповідає через %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Ніщо тут не почує дзвінок, поки доступ не надано в System Settings › Privacy & Security › Microphone.",
        "There is no summary or outline — reading your meetings is off.": "Немає ні резюме, ні змісту — читання зустрічей вимкнене.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Тут лише ваш мікрофон — другої сторони дзвінка немає, текст одним суцільним блоком, і немає ні резюме, ні змісту.",
        "Turn both on": "Увімкнути обидва",
        "Turn it on": "Увімкнути",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Якщо увімкнути, вони будуть написані й для наступних записів. «Написати зараз» залишить перемикач вимкненим.",
        "Waiting on microphone access.": "Чекає на доступ до мікрофона.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Чекає на «%@» вище — поки нічого розділяти, звук дзвінка не пишеться.",
        "Write one, this once": "Написати зараз, один раз",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "«Написати зараз» прочитає лише цей транскрипт і залишить перемикачі вимкненими. Друга сторона цього дзвінка не записувалась, і її не відновити.",
        "Writing…": "Пишу…",
        "macOS denied microphone access": "macOS відмовила в доступі до мікрофона",
        "%@ call — not being recorded": "Дзвінок у %@ — не записується",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "Запис дзвінків вимкнено, і цей минає без транскрипту. Якщо увімкнути, після дзвінка буде транскрипт із пошуком і резюме — усе зберігається на цьому Mac.",
        "Call — not being recorded": "Дзвінок — не записується",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Дзвінки не помічаються автоматично. Можна запускати кожен тут — або дозволити Dictate пропонувати запис, коли дзвінок починається.",
        "Connect a provider…": "Підключити провайдера…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "Диктування працює як раніше. Кожен перемикач нижче каже, що він додає; можна увімкнути один і не чіпати решту.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "Диктування вже працює — затисніть клавішу диктування і говоріть будь-де. Усе нижче — про зустрічі, і ніщо з цього не є обов'язковим. Увімкніть потрібне; решта залишиться вимкненою.",
        "Don't offer this again": "Більше не пропонувати",
        "Everything here is off, so calls pass unnoticed": "Тут усе вимкнено, і дзвінки минають непоміченими",
        "Let the model read your meetings": "Дозволити моделі читати ваші зустрічі",
        "Not watching for calls": "Дзвінки не відстежуються",
        "Notice when a call starts": "Помічати, коли починається дзвінок",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Вимкнено — у записі лише ваш мікрофон: ваша половина розмови одним суцільним блоком. Увімкнено — обидві сторони розшифровуються як репліки з іменами.",
        "On": "Увімк.",
        "Or leave this and set them up later in Settings.": "Або пропустіть — їх можна увімкнути пізніше в налаштуваннях.",
        "Read meeting names from Calendar": "Брати назви зустрічей із Календаря",
        "Record the call audio too": "Записувати і звук дзвінка",
        "Record the call audio, and separate the voices": "Записувати звук дзвінка та розділяти голоси",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Записи з'являються вже з назвою, а не як «Дзвінок у Zoom, 14:02». Читаються лише події, що збігаються в часі із записом.",
        "Separate the voices": "Розділяти голоси",
        "Set up calls…": "Налаштувати дзвінки…",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "Агент шукає та читає ваші транскрипти на цьому Mac; письмова відповідь надходить від провайдера, якого ви підключаєте зі своїм ключем.",
        "Three things are off. Here is what each one adds.": "Три функції вимкнені. Ось що додає кожна.",
        "Turn all on": "Увімкнути все",
        "Turn all three on": "Увімкнути всі три",
        "Turn on": "Увімкнути",
        "Turn on reading": "Увімкнути читання",
        "Watching for calls": "Дзвінки відстежуються",
        "What it does": "Що це робить",
        "With this on, a small panel appears when a call starts and you decide there — no need to remember to start anything.": "Коли увімкнено, на початку дзвінка з'являється невелика панель, і ви вирішуєте там — не треба пам'ятати, що щось слід запускати.",
        "listening": "слухаю",
        "Back to the top": "На початок",
        "Show everything tagged #%@": "Показати все з тегом #%@",
        "Remove #%@ from this meeting": "Прибрати #%@ з цього мітингу",
        "Tag": "Тег",
        "Create #%@": "Створити #%@",
        "Show Live Transcript": "Показати транскрипт поточного дзвінка",
