        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "У якогось застосунку у фокусі поле пароля. macOS не каже, у якого. Клацніть у звичайне текстове поле — і диктування знову запрацює.",
        "Start Recording Meeting": "Записати зустріч",
        "Stop Recording Meeting": "Зупинити запис зустрічі",
        "dictate in %@": "диктування %@",
        "dictate in any language": "диктування будь-якою мовою",
        "translate %@ → %@": "переклад %@ → %@",
        "translate into %@": "переклад на %@",
        "%d waiting": "Очікує: %d",
        "%d words typed": "Надруковано слів: %d",
        "Add a Key…": "Додати ключ…",
        "Both will be inserted in the order you spoke them": "Обидві будуть вставлені в тому порядку, в якому ви їх сказали",
        "Check Audio Setup": "Перевірити налаштування звуку",
        "Clear All Filters": "Скинути всі фільтри",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "F-клавіші також керують системою (яскравість, медіа) — macOS зробить і те, й інше. Щоб використовувати її як звичайну клавішу, увімкніть «Use F1, F2, etc. as standard function keys» у налаштуваннях клавіатури.",
        "How this works": "Як це працює",
        "Input device changed": "Пристрій введення змінився",
        "Insert text by": "Вставляти текст",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Його відкликано або замінено після підключення. Ключ видалено з В’язки ключів — з ним нічого не надсилалося повторно.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Почніть дзвінок у браузері й запустіть запис. Dictate записує ваш мікрофон і звук дзвінка, розпізнає обидва на цьому Mac і зберігає транскрипт тут. Нічого не завантажується в мережу.",
        "No meeting has all of these tags": "Жодна зустріч не має всіх цих тегів",
        "No meeting has this tag": "Жодна зустріч не має цього тега",
        "Nothing was said, or nothing was heard": "Нічого не було сказано — або нічого не було чути",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Тут видно лише непідтверджений хвіст — решта вже в документі",
        "Open Console": "Відкрити консоль",
        "Open Settings": "Відкрити налаштування",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Вставка миттєва, але на мить підмінює буфер обміну. Друк працює там, де вставку заблоковано — у деяких терміналах і віддалених робочих столах.",
        "Pasting it at once": "Вставкою одразу",
        "Recording ended here — this Mac went to sleep.": "Запис закінчився тут — Mac заснув.",
        "Remove “%@”": "Прибрати «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return — надіслати · Shift-Return — новий рядок · Esc — очистити",
        "Show Floating Timer": "Показати плаваючий таймер",
        "Start Recording a Meeting": "Записати зустріч",
        "Still recognizing the previous dictation": "Попередня диктовка ще розпізнається",
        "Still recognizing the previous dictation · %d words": "Попередня диктовка ще розпізнається · %d слів",
        "Switched to %@": "Перемкнено на %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Фільтри тегів поєднуються через «і» — зустріч має нести кожен вибраний тег.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Відповідь перервалася. Ваше запитання збережено вище — повторіть, коли з’явиться зв’язок. Пошук і транскрипти працюють.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Запис тривав, але мовлення не розпізнано з жодного боку. Зазвичай це означає, що звук дзвінка не було захоплено — вкладка браузера без доступу до звуку або не той пристрій виводу.",
        "The saved key no longer works": "Збережений ключ більше не працює",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Перемикач залишиться вимкненим, доки доступ не надано в System Settings › Privacy & Security › Calendars. Читаються лише назви подій, що перетинаються із записом.",
        "This Mac is offline": "Цей Mac офлайн",
        "Too many questions at once": "Забагато запитань одразу",
        "Typing as you speak": "Друкую, поки ви говорите",
        "Typing into %@ as you speak": "Друкую в %@, поки ви говорите",
        "Typing it out character by character": "Друком по літерах",
        "Your provider account is out of credit": "На рахунку провайдера закінчилися кредити",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Провайдер обмежує частоту запитів. Зачекайте кілька секунд і повторіть — нічого не втрачено.",
        "macOS denied calendar access": "macOS відмовила в доступі до календаря",
        "API key": "API-ключ",
        "All Meetings": "Усі зустрічі",
        "Assistant": "Асистент",
        "Checking the key with %@. No transcript is sent — only a test request.": "Перевіряємо ключ у %@. Транскрипти не надсилаються — лише тестовий запит.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Закриття вікна не зупиняє запис. Зупиніть його тут або з меню-бара будь-коли.",
        "Connect an assistant to answer questions": "Підключіть асистента, щоб отримувати відповіді",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate може записати дзвінок у браузері й зберегти транскрипт на цьому Mac. Запустіть запис із меню-бара, коли почнеться наступний дзвінок — згоду спитаємо один раз.",
        "Done": "Готово",
        "Every change takes effect immediately.": "Кожна зміна застосовується одразу.",
        "Get one at %@.": "Отримати на %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Затисніть клавішу, говоріть, відпустіть. Сказане буде надруковано там, де курсор, — у будь-якому застосунку на цьому Mac.",
        "Keys": "Клавіші",
        "Languages": "Мови",
        "Library": "Бібліотека",
        "Paste a key from your own account.": "Вставте ключ від власного акаунта.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Збережено у В’язці ключів, але не перевірено — цей Mac офлайн. Перевіримо під час першого запитання.",
        "Set Up Dictate": "Налаштувати Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Зберігається у В’язці ключів macOS на цьому Mac. Не записується у файли налаштувань, не синхронізується.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Ключ відхилено. Можливо, його відкликано, він від іншого провайдера або без кредитів — сам ключ не збережено.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Транскрипти, пошук і цитати працюють без цього. Асистент потрібен лише щоб написати відповідь.",
        "Try Again": "Спробувати ще раз",
        "Updates": "Оновлення",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Кожне запитання оплачується вашому провайдеру — зазвичай частки цента. Надсилаються лише запитання та знайдені цитати; записи не покидають цей Mac.",
        "Send": "Надіслати",
        "Conversations": "Розмови",
        "New question": "Нове запитання",
        "Deleted “%@”": "Видалено: «%@»",
        "Undo": "Скасувати",
        "Questions you ask are kept here so you can return to an answer.": "Поставлені запитання зберігаються тут — до відповіді можна повернутися.",
        "Rename": "Перейменувати",
        "Delete": "Видалити",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Голоси звіряються за звуком — ім'я застосовується лише до реплік цього голосу.",
        "Give two voices the same name to merge them.": "Дайте двом голосам одне ім'я, щоб об'єднати їх.",
        "Voices are told apart by sound — one person can show up as two.": "Голоси розрізняються за звуком — одна людина може відобразитися як дві.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "Клацніть ім'я, щоб перейменувати голос, — однакове ім'я об'єднує два. Резюме й відповіді спираються на те, що було сказано, а не на те, хто це сказав.",
        "Voice separation improves over time.": "Розділення голосів з часом стає точнішим.",
        "About voice separation": "Про розділення голосів",
        "Call · voice %d": "Дзвінок · голос %d",
        "Starred": "Обрані",
        "Other browser calls": "Інші браузерні дзвінки",
        "Sources": "Джерела",
        "Star meeting": "В обрані",
        "Unstar meeting": "Прибрати з обраних",
        "Export transcript…": "Експортувати транскрипт…",
        "Still recording": "Запис триває",
        "Got it": "Зрозуміло",
        "Call": "Дзвінок",
        "Dictating": "Диктування",
        "Dictating in %@": "Диктування: %@",
        "Translating into English": "Перекладаю англійською",
        "Translating into %@": "Перекладаю: %@",
        "Release %@ to insert": "Відпустіть %@, щоб вставити",
        "Also recording this meeting": "Одночасно записується зустріч",
        "%@ MB/s · about %@ left": "%@ МБ/с · залишилося близько %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Недостатньо місця на диску: завантаженню потрібно близько %d МБ, вільно %d МБ. Звільніть місце і повторіть.",
        "Fix…": "Виправити…",
        "Checked automatically · last %@": "Перевіряється автоматично · остання: %@",
        "Source code": "Джерельний код",
        "Report an issue": "Повідомити про проблему",
        "Finishing the transcript…": "Завершую транскрипт…",
        "Disk almost full — will stop to keep the transcript": "Диск майже повний — запис зупиниться, щоб зберегти транскрипт",
        "Dictate is running from its disk image": "Dictate запущено з образу диска",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Дозволи, надані копії з образу диска, зникнуть після його вилучення, а модель завантажуватиметься щоразу заново. Спершу перемістіть Dictate до теки «Програми».",
        "Move to Applications": "Перемістити до «Програм»",
        "Quit": "Завершити",
        "Couldn't move Dictate automatically": "Не вдалося перемістити Dictate автоматично",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Перетягніть Dictate з образу диска до теки «Програми» і запустіть його звідти.",
        "OK": "OK",
        "Inserted into %@": "Вставлено в %@",
        "Inserted": "Вставлено",
        "Accessibility is off — dictation can hear you but cannot type": "Універсальний доступ вимкнено — диктування чує вас, але не може друкувати",
        "Open Privacy & Security…": "Відкрити «Конфіденційність і безпеку»…",
        "1 dictation still being recognized": "1 диктування ще розпізнається",
        "%d dictations still being recognized": "%d диктування ще розпізнаються",
        "Language Packs…": "Мовні пакети…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Якщо вимкнено, Dictate живе лише в рядку меню. Клацання значка в Dock відкриває «Зустрічі»; значок у рядку меню є в будь-якому разі.",
        "Interface language": "Мова інтерфейсу",
        "Granted": "Надано",
        "No": "Ні",
        "Model ready": "Модель готова",
        "On-device recognition": "Розпізнавання на пристрої",
        "Spoken language": "Мова мовлення",
        "Download failed. Check your connection and retry.": "Не вдалося завантажити. Перевірте з'єднання і повторіть.",
        "Not set": "Не призначена",
        "Remove": "Прибрати",
        "Download & continue": "Завантажити й продовжити",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Близько %@ — завантажується один раз. Це єдиний момент, коли Dictate потрібен інтернет.",
        "Hold %@ and say something — the recognized text shows up below.": "Затисніть %@ і скажіть щось — розпізнаний текст з'явиться нижче.",
        "Recognized text appears here…": "Розпізнаний текст з'явиться тут…",
        "Settings…": "Налаштування…",
        "Quit Dictate": "Завершити Dictate",
        "Dictate — voice dictation": "Dictate — голосове диктування",
        "Recognizing…": "Розпізнаю…",
        "Esc to cancel": "Esc — скасувати",
        "Couldn't start recording: %@": "Не вдалося почати запис: %@",
        "Recording truncated at %d seconds (limit)": "Запис обрізано на %d секундах (ліміт)",
        "Audio device changed during recording — recording cancelled, please try again.": "Аудіопристрій змінився під час запису — запис скасовано, спробуйте ще раз.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "Дозвіл «Універсальний доступ» вимкнено, тому клавішу не чути. Увімкніть його: Системні налаштування → Конфіденційність і безпека → Універсальний доступ. Dictate підхопить сам, перезапуск не потрібен.",
        "Microphone unavailable (no input audio format)": "Мікрофон недоступний (немає вхідного аудіоформату)",
        "Right Option (⌥)": "Правий Option (⌥)",
        "Left Option (⌥)": "Лівий Option (⌥)",
        "Right Command (⌘)": "Правий Command (⌘)",
        "Left Command (⌘)": "Лівий Command (⌘)",
        "Right Shift (⇧)": "Правий Shift (⇧)",
        "Left Shift (⇧)": "Лівий Shift (⇧)",
        "Right Control (⌃)": "Правий Control (⌃)",
        "Left Control (⌃)": "Лівий Control (⌃)",
        "Space": "Пробіл",
        "Follow system": "Як у системі",
        "Translating…": "Перекладаю…",
        "Tip: hold %@ instead — your speech comes out in English.": "Порада: затисніть %@ замість звичайної — мова надрукується англійською.",
        "Hold to talk in your language, release to insert it in English.": "Затисніть і говоріть своєю мовою, відпустіть — вставиться англійською.",
        "Hold %@ and say it again — this time it's typed in English.": "Затисніть %@ і скажіть те саме — цього разу надрукується англійською.",
        "Translate to": "Перекладати на",
        "Translation data isn't downloaded — open Settings to get it": "Дані перекладу не завантажені — завантажте їх у налаштуваннях",
        "Translation data": "Дані перекладу",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "Клавіша перекладу розпізнає вашу мову, а потім macOS перекладає її просто на цьому Mac. Під час вибору мови macOS може один раз завантажити її дані перекладу.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "Розпізнавання працює на Neural Engine вашого Mac — Whisper large-v3-turbo: 100 мов, добре дає раду з акцентом і достатньо швидкий для живого тексту. Переклад теж відбувається на цьому Mac. Ваш голос не залишає цей комп’ютер.",
        "Hold %@ and say it again — this time it comes out in %@.": "Затисніть %@ і скажіть те саме — цього разу вийде на %@.",
        "Hold to talk in your language, release to insert it in %@.": "Затисніть і говоріть своєю мовою, відпустіть — вставиться на %@.",
        "Not downloaded": "Не завантажені",
        "Translation languages": "Мови перекладу",
        "Downloaded": "Завантажено",
        "Manage in System Settings…": "Керувати в Системних параметрах…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "Уже ввімкнено в Системних параметрах, а позначки немає? Вимкніть і знову ввімкніть перемикач Dictate — після оновлення застосунку macOS іноді тримає застарілий запис.",
        "Agent: %@, on your key.": "Агент: %@, на вашому ключі.",
        "Agent: off.": "Агент: вимкнено.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "На цьому Mac Apple Intelligence не підтримується для цього регіону або мови. Агент з вашим ключем усе одно працює.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence потребує macOS 26. Агент з вашим ключем усе одно працює.",
        "Copy diagnostics": "Скопіювати діагностику",
        "Debug audio dumps": "Налагоджувальні аудіозаписи",
        "Diagnostics": "Діагностика",
        "Downloading…": "Завантаження…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Звільнить %@. Нові зустрічі залишаться з назвами за датою, доки ви не завантажите її знову. Уже написані резюме збережуться.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Звільнить %@. Більше нічого не зміниться — читання зустрічей вимкнено.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Звільнить %@. Назви та резюме писатиме Apple Intelligence.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Встановлена, але не працює: у цього Mac %d ГБ пам’яті, а потрібно 16.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Встановлена, але не працює: у цього Mac %d ГБ пам’яті, а потрібно 16. Зустрічі на цьому Mac ніщо не читає.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Встановлена, але не працює: у цього Mac %d ГБ пам’яті, а потрібно 16. Назви та резюме натомість пише Apple Intelligence.",
        "Installed · %@": "Встановлена · %@",
        "Installed, not in use · %@": "Встановлена, не використовується · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Під час роботи вона тримає близько %@ пам’яті — на цьому Mac це помітно.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, версія та які функції ввімкнено. Ні транскриптів, ні ключів.",
        "Meeting archive": "Архів зустрічей",
        "Meeting model": "Модель зустрічей",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Модель зустрічей встановлено. Нові зустрічі отримують назви та резюме на цьому Mac.",
        "Meeting reading: Apple Intelligence.": "Читання зустрічей: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Читання зустрічей: на цьому Mac поки нічим.",
        "Meeting reading: the downloaded model (%@).": "Читання зустрічей: завантажена модель (%@).",
        "Not available on this Mac.": "Недоступно на цьому Mac.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "Не встановлена. Одноразове завантаження %@ дасть назви, резюме та зміст.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "На цьому Mac поки нічим читати: Apple Intelligence тут не підтримується. Агент з вашим ключем усе одно працює.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "На цьому Mac поки нічим читати: завантажте модель зустрічей нижче або додайте ключ для агента.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "На цьому Mac поки нічим читати: завантажте модель зустрічей нижче або ввімкніть Apple Intelligence у Системних параметрах.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "На цьому Mac поки нічим читати: macOS ще налаштовує Apple Intelligence. Агент з вашим ключем усе одно працює.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "На цьому Mac поки нічим читати: увімкніть Apple Intelligence у Системних параметрах або додайте ключ для агента.",
        "Open System Settings": "Відкрити Системні параметри",
        "Paused: not enough free memory right now. It resumes on its own.": "Пауза: зараз бракує вільної пам’яті. Продовжиться само.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Підготовка моделі під процесор цього Mac… Кілька хвилин, один раз.",
        "Raw call audio kept for debugging only.": "Сирий звук дзвінків, зберігається лише для налагодження.",
        "Reading is on, but nothing on this Mac can read yet.": "Читання ввімкнено, але на цьому Mac поки нічим читати.",
        "Reads with Apple Intelligence.": "Читає через Apple Intelligence.",
        "Reads with the downloaded model.": "Читає завантаженою моделлю.",
        "Recognition runs on the Neural Engine.": "Розпізнавання працює на Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "Розпізнавання працює на процесорі цього Mac — Whisper large-v3-turbo: 100 мов, добре дає раду з акцентом. Повільніше, ніж на Apple Silicon, і переклад теж відбувається на цьому Mac. Ваш голос не залишає цей комп’ютер.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "Розпізнавання працює на процесорі цього Mac — повільніше, ніж на Apple Silicon.",
        "Remove the debug audio dumps?": "Видалити налагоджувальні аудіозаписи?",
        "Remove the meeting model?": "Видалити модель зустрічей?",
        "Remove…": "Видалити…",
        "Speaker models": "Моделі спікерів",
        "Speech model": "Модель мовлення",
        "Storage": "Сховище",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Резюме на цьому Mac пише Apple Intelligence. Завантажуваній моделі потрібно 16 ГБ пам’яті; у цього Mac — %d.",
        "Summary paused: not enough free memory. It resumes on its own.": "Резюме на паузі: бракує вільної пам’яті. Продовжиться само.",
        "Tell the voices on a call apart.": "Розрізняти голоси у дзвінку.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "Моделі зустрічей потрібно 16 ГБ пам’яті; у цього Mac — %d.",
        "These are recordings kept only for debugging. Nothing else is affected.": "Це записи, які зберігаються лише для налагодження. Більше нічого не зачіпається.",
        "This Mac": "Цей Mac",
        "This build of Dictate does not include the meeting model.": "Ця збірка Dictate не містить моделі зустрічей.",
        "Titles and summaries come from Apple Intelligence instead.": "Назви та резюме натомість пише Apple Intelligence.",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "Увімкніть Apple Intelligence у розділі Системні параметри › Apple Intelligence і Siri або додайте ключ для агента.",
        "Waiting for the call to end.": "Чекає на завершення дзвінка.",
        "Your transcripts, as Markdown files you own.": "Ваші транскрипти — файли Markdown, що належать вам.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS ще налаштовує Apple Intelligence — загляньте пізніше або додайте ключ для агента.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. Звіт у будь-якому разі залишається у файлі зустрічі; це створює копію.",
        "%d fields": "Полів: %d",
        "Add field": "Додати поле",
        "Agent & reports": "Агент і звіти",
        "Also one table (CSV): a row per meeting, a column per field": "І одна таблиця (CSV): рядок на зустріч, стовпець на поле",
        "Answers with": "Відповідає через",
        "Choose folder…": "Вибрати теку…",
        "Copy report": "Копіювати звіт",
        "Date": "Дата",
        "Export %d “%@” reports": "Експортувати %d звітів “%@”",
        "Export reports…": "Експортувати звіти…",
        "Export report…": "Експортувати звіт…",
        "Export the “%@” report": "Експортувати звіт “%@”",
        "Field name": "Назва поля",
        "Fields": "Поля",
        "Format:": "Формат:",
        "Markdown": "Markdown",
        "Meeting": "Зустріч",
        "New template": "Новий шаблон",
        "New template…": "Новий шаблон…",
        "No reports written with “%@” yet.": "Звітів за “%@” поки немає.",
        "No templates yet.": "Шаблонів поки немає.",
        "Not discussed": "Не обговорювалось",
        "One empty field. You name it.": "Одне порожнє поле. Назва за вами.",
        "One file per meeting, named by date and title, in a folder you choose. Transcripts are not included.": "По файлу на зустріч, з датою та назвою в імені, у вибраній вами теці. Транскрипти не включаються.",
        "PDF": "PDF",
        "Plain text": "Звичайний текст",
        "Questions across your meetings, and reports.": "Запитання по всіх ваших зустрічах — і звіти.",
        "Remove field": "Прибрати поле",
        "Remove template": "Видалити шаблон",
        "Remove template…": "Видалити шаблон…",
        "Remove “%@”?": "Видалити “%@”?",
        "Report": "Звіт",
        "Report not written": "Звіт не написано",
        "Reports": "Звіти",
        "Reports already written with it stay in their meetings.": "Уже написані з ним звіти залишаються у своїх зустрічах.",
        "Same as Dictate": "Як у Dictate",
        "Template name": "Назва шаблону",
        "Templates": "Шаблони",
        "The model returned no report.": "Модель не повернула звіт.",
        "The model stopped before the report was finished.": "Модель зупинилася, не дописавши звіт.",
        "The saved key no longer works. It has been removed from the Keychain.": "Збережений ключ більше не працює. Його видалено з В’язки ключів.",
        "What is sent": "Що надсилається",
        "Writing · about a minute": "Пишу · близько хвилини",
        "Written by Dictate on this Mac from the transcript": "Написано Dictate на цьому Mac за транскриптом",
        "Your %@ account refused the request for billing reasons.": "Ваш обліковий запис %@ відхилив запит через білінг.",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "Надсилає цей транскрипт до %@ на вашому ключі. Звіт лягає у файл зустрічі.",
        "Set up templates…": "Налаштувати шаблони…",
        "Write report": "Написати звіт",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@ обмежує частоту запитів. Нічого не втрачено — спробуйте за хвилину.",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "Цей Mac офлайн. Нічого не надіслано — спробуйте, коли з’явиться зв’язок.",
        "Write a “%@” report?": "Написати звіт «%@»?",
        "Action items": "Завдання",
        "Dates and deadlines": "Дати й терміни",
        "Decisions": "Рішення",
        "Decisions & actions": "Рішення та завдання",
        "Every date, deadline or time window that was mentioned, and what it is for": "Кожна дата, термін чи часове вікно, що прозвучали, і до чого вони стосуються",
        "Key points": "Ключові тези",
        "Meeting summary": "Підсумки зустрічі",
        "Next step": "Наступний крок",
        "Open questions": "Відкриті питання",
        "Purpose": "Мета",
        "Risks and concerns": "Ризики та застереження",
        "The main arguments and facts, with the numbers, names and dates that were said": "Головні аргументи й факти — з цифрами, іменами та датами, що прозвучали",
        "The next meeting or checkpoint, if one was agreed": "Наступна зустріч або контрольна точка, якщо про неї домовилися",
        "Waiting on": "Чекаємо від інших",
        "We are the team on this call; the reader took part in it.": "Ми — команда на цьому дзвінку; читач брав у ньому участь.",
        "What could go wrong, who raised it, how serious it sounded": "Що може піти не так, хто це порушив і наскільки серйозно це звучало",
        "What each side is waiting for from the other": "Чого кожна сторона чекає від іншої",
        "What was decided, by whom, and what it replaces": "Що вирішили, хто вирішив і що це замінює",
        "What was raised and not settled, and who owns it": "Що порушили й не закрили, і хто за це відповідає",
        "Who does what, by when — one line per task": "Хто що робить і до якого терміну — по рядку на завдання",
        "Why we met and what we set out to settle": "Навіщо зустрічалися і що збиралися вирішити",
        "%d more": "ще %d",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "Назва лишається мовою зустрічі; підсумок і всі звіти пишуться цією. Назви полів у звіті лишаються рівно як надруковано.",
        "About “%@”:": "Щодо зустрічі «%@»:",
        "Replace the report with a new “%@” one?": "Замінити звіт новим за шаблоном «%@»?",
        "Replace report": "Замінити звіт",
        "Written · replaces it": "Є · буде замінено",
        "Dictate updated to %@.": "Dictate оновився до %@.",
        "Dismiss": "Закрити",
        "New": "Нове",
        "New in this version": "Нове в цій версії",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Відкрийте зустріч, натисніть Write report у її шапці та оберіть шаблон. Звіт ляже на картку та PDF-файлом у Dictate Meetings › Reports.",
        "Reports from templates": "Звіти за шаблонами",
        "See what’s new": "Що нового",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Settings › Meetings › Write summaries and reports in: підсумок і всі звіти пишуться мовою, якою ви читаєте, якою б мовою не йшов дзвінок.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Settings › Templates: почніть із «Підсумки зустрічі» або «Рішення та завдання» або назвіть власні поля й опишіть моделі, що писати під кожним.",
        "Summaries in your language": "Підсумки вашою мовою",
        "What’s new": "Що нового",
        "What’s new in Dictate %@": "Що нового в Dictate %@",
        "Your own templates": "Власні шаблони",
        "Install update %@ and relaunch": "Установити оновлення %@ і перезапустити",
        "The update waits until the recording ends.": "Оновлення почекає, поки закінчиться запис.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "Оновлення %@ вже в дорозі — завантажується. Установиться саме у найближчий спокійний момент; у рядку меню можна раніше.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "Оновлення %@ готове — установіть із рядка меню, або воно встановиться саме у найближчий спокійний момент.",
        "An update is already on its way — it installs itself at the next quiet moment.": "Оновлення вже в дорозі — установиться саме у найближчий спокійний момент.",
        "Downloading update %@…": "Завантажується оновлення %@…",
        "Preparing update %@…": "Готується оновлення %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate оновився до %@. Що нового — у вікні Meetings.",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence відмовився складати резюме цієї зустрічі.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "Транскрипт, пошук і агент не постраждали. У моделі для завантаження, що живе на цьому Mac, таких обмежень немає.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Зустрічі записані й структуровані: спікери, самарі, аутлайн, пошук. Dictate пропонує записати дзвінок — і ніколи не пише без вашої відповіді.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "Моделі зустрічей потрібно 16 ГБ пам’яті; у цього Mac — %d. Вона не працює, а зайняті нею %@ на диску можна звільнити.",
        "Clipboard restored.": "Буфер обміну відновлено.",
        "Your words were inserted untranslated.": "Ваші слова вставлено без перекладу.",
        "A small panel appears when a call starts, and you decide there.": "На початку дзвінка з'являється невелика панель, і ви вирішуєте там.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Пише резюме та зміст і дає агентові матеріал для відповідей. У будь-якому разі нікуди нічого не надсилається.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Вимкнено — лише ваш мікрофон; увімкнено — розшифровується і друга сторона.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Перетворює суцільний блок тексту на репліки з іменами. Розділення йде за звуком і буває неточним; імена можна змінювати.",
        "Find in this transcript…": "Знайти в цьому транскрипті…",
        "%d of %d": "%d з %d",
        "No matches": "Збігів немає",
        "Previous match": "Попередній збіг",
        "Next match": "Наступний збіг",
        "Close find": "Закрити пошук",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "Вибрано %@, але ключа ще немає. Агент і звіти вимкнені, доки його не додано.",
        "%@ · required for dictation, cannot be removed.": "%@ · потрібна для диктування, видалити не можна.",
        "%@ — not written": "%@ — не написано",
        "%d h": "%d год",
        "%d meetings have a %@ report. They stay if this template goes.": "Звіт «%@» є у %d зустрічей. Вони залишаться, якщо шаблон видалити.",
        "%d min ago": "%d хв тому",
        "%d written": "написано: %d",
        "%d written, %d not written": "написано: %d, не написано: %d",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 мов. Застосовується до цього вікна й рядка меню одразу. Мова, якою ви говорите, задається в розділі «Диктування».",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Ключ із вашого власного облікового запису %@. Зберігається у В’язці ключів, ніколи — у файлі налаштувань.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Запитання надсилає саме запитання та фрагменти, знайдені пошуком. Звіт надсилає всю розшифровку зустрічі — близько 12 000 слів за годину розмови. Обидва йдуть до %@ за вашим ключем і лише на ваш запит. Записи ніколи не залишають цей Mac.",
        "About": "Про програму",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "Apple Intelligence на цьому Mac недоступний, тож запасного варіанта немає.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence потребує новішої macOS, ніж на цьому Mac, тож запасного варіанта немає.",
        "Applies to this window, the meetings window and the panels over your other apps.": "Діє на це вікно, вікно зустрічей і панелі поверх інших програм.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Питаємо один раз. Далі панель буде короткою й залишиться, доки ви не відповісте. Запис можна почати і з рядка меню в будь-який момент дзвінка.",
        "Calendar": "Календар",
        "Collapse %@": "Згорнути %@",
        "Copy": "Скопіювати",
        "Dictation": "Диктування",
        "Expand %@": "Розгорнути %@",
        "Export…": "Експортувати…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "Текст є і в «Недавніх диктуваннях», тож буфер обміну знову ваш, коли забажаєте.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Зберігаються всередині файлу цієї зустрічі, тож подорожують разом із розшифровкою. Експорт робить копію туди, куди забажаєте.",
        "No report": "Без звіту",
        "No report for this meeting yet.": "Для цієї зустрічі звіту ще немає.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "При видаленні нічого не втрачається: розшифровка, пошук і агент від неї не залежать.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Тут нічого не налаштовується. Кожен рядок вище або повідомляє, що вміє цей Mac, або вказує на розділ, де це задається.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "На цьому Mac поки нічому читати зустрічі: Apple Intelligence потребує новішої macOS. Агент із вашим ключем усе одно працює.",
        "Nothing was kept from this take — earlier ones are still here.": "Із цієї спроби нічого не збереглося — попередні досі тут.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "Нічого не записалося, тож нічого зберігати. Попередні досі тут.",
        "Off — dictation cannot type": "Вимкнено — диктування не може друкувати",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Вимкнено: розшифровки, резюме, плани й пошук працюють як раніше. Агент відповідає на запитання по всіх ваших зустрічах і пише звіти за вашими шаблонами; він працює в хмарі за вашим власним API-ключем.",
        "On this Mac": "На цьому Mac",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Один файл із докачуванням. Закриття Dictate ставить його на паузу; потім він продовжиться з того ж місця.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Одноразове завантаження %@, після чого заголовки, резюме й плани робляться повністю на цьому Mac. Для роботи потрібно 16 ГБ пам’яті; поки модель пише, вона займає близько %@.",
        "Open System Settings…": "Відкрити Системні параметри…",
        "Or start from the menu bar later in the call.": "Або почніть із рядка меню пізніше під час дзвінка.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "Зараз на паузі: бракує вільної пам’яті. Вона продовжиться сама, а зустрічі, що чекають на резюме, зберігають свої розшифровки.",
        "Permissions": "Дозволи",
        "Reads with Apple Intelligence until the download finishes.": "Читає через Apple Intelligence, доки не завершиться завантаження.",
        "Reads with the downloaded model — paused until there is free memory.": "Читає завантаженою моделлю — на паузі, доки не звільниться пам’ять.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Шаблони звітів — у розділі «Шаблони»; готові звіти — у бібліотеці, у розділі «Звіти».",
        "Report · %@": "Звіт · %@",
        "Report · %@ +%d": "Звіт · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Звітам потрібен агент, а він вимкнений. Виберіть Claude або ChatGPT у розділі «Резюме та звіти»; шаблони до того часу зберігаються.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Працює повністю на цьому Mac. Без неї заголовки й резюме робить Apple Intelligence.",
        "Startup": "Запуск",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Зберігається у В’язці ключів, ніколи — у файлі налаштувань. Агент відповідає на запитання по всіх ваших зустрічах і пише звіти за вашими шаблонами.",
        "Summaries": "Резюме",
        "Summaries & reports": "Резюме та звіти",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "Завантаження — спосіб отримувати резюме на цьому Mac без Apple Intelligence. Розшифровка й пошук працюють у будь-якому разі.",
        "This Mac was offline. Nothing was sent.": "Цей Mac був не в мережі. Нічого не надіслано.",
        "This take was not kept. Earlier ones are still here.": "Ця спроба не збереглася. Попередні досі тут.",
        "Uses 41 MB of speaker models.": "Використовує 41 МБ моделей голосів.",
        "What’s new in %@": "Що нового в %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Чи читає щось ці записи — резюме, плани, звіти й агент — задається в розділі «Резюме та звіти». Цей розділ лише про те, що записується на цьому Mac.",
        "Write again": "Написати заново",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "«Написати звіт» вище перелічує ваші шаблони (%d). Написання надсилає цю розшифровку до %@ за вашим ключем; звіт зберігається всередині файлу зустрічі й подорожує разом із розшифровкою. Експорт робить копію туди, куди забажаєте.",
        "Written %@": "Написано %@",
        "Written by %@": "Написав %@",
        "Written by %@ %@ at %@": "Написав %@ %@ о %@",
        "Written in": "Мова тексту",
        "Your agent, on your key": "Ваш агент, за вашим ключем",
        "click to insert": "натисніть, щоб вставити",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS ще налаштовує Apple Intelligence. Це може тривати якийсь час, і звідси його не пришвидшити.",
        "macOS resets this switch after some updates and never asks a second time.": "macOS скидає цей перемикач після деяких оновлень і ніколи не питає вдруге.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-клік — скопіювати замість вставлення. Очищається при виході з Dictate.",
        "Meeting names": "Назви зустрічей",
        "%d meetings, reports included": "зустрічей: %d, включно зі звітами",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "Завантажте модель зустрічей у розділі «Резюме та звіти» або додайте ключ для агента.",
        "Calls": "Дзвінки",
        "Reports folder": "Тека звітів",
        "%d PDFs written before %@": "PDF, записаних до %@: %d",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate більше не пише PDF сам. Ці файли ваші — зберігайте або видаляйте; у програмі від них нічого не залежить.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "Уже написаний звіт буде замінено. Ця розшифровка піде до %@ за вашим ключем.",
        "%@ · report not written": "%@ · звіт не написано",
        "%d of %d selected · %d meetings without one": "вибрано %d із %d · без звіту: %d",
        "%d passages from %d meetings": "фрагментів: %d із %d зустрічей",
        "%d written across %d templates": "написано %d за %d шаблонами",
        "%d written · %d meetings without one · %d fields": "написано %d · без звіту %d · полів %d",
        "%d written · writing %d · %d not written": "написано %d · пишеться %d · не написано %d",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Звіт пишеться на запит — із картки зустрічі або для виділених тут. Кожен надсилає розшифровку тієї зустрічі до %@ за вашим ключем і зберігається всередині файлу зустрічі.",
        "All reports": "Усі звіти",
        "Answer": "Відповідь",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Відповів %@ за %d із %d зустрічей. Цитати дослівно з розшифровок на цьому Mac.",
        "Copy as Markdown": "Скопіювати як Markdown",
        "Copy as plain text": "Скопіювати як звичайний текст",
        "Copy the answer only": "Скопіювати лише відповідь",
        "Copy with quotes": "Скопіювати з цитатами",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "У кожного шаблону свої звіти: що написано і які зустрічі могли б отримати звіт. Самі шаблони редагуються в Параметрах › Шаблони.",
        "Edit template…": "Змінити шаблон…",
        "No report yet · %d meetings": "Звіту ще немає · зустрічей: %d",
        "None written · %d fields": "Нічого не написано · полів: %d",
        "Nothing written from this template yet": "За цим шаблоном ще нічого не написано",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Вимкнено: ці %d пропускаються, пишеться звітів: %d. Заміну не можна скасувати.",
        "Pick a template": "Виберіть шаблон",
        "Quotes": "Цитати",
        "Replace the %d that already have one": "Замінити %d уже написаних",
        "Report not written — the request was refused. The meeting has the detail.": "Звіт не написано — запит відхилено. Подробиці на картці зустрічі.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Надсилає розшифровок: %d до %@ за вашим ключем — близько %@ слів. Кожен звіт зберігається всередині файлу своєї зустрічі. Записи ніколи не залишають цей Mac.",
        "The %d existing reports are overwritten. This cannot be undone.": "Наявні звіти (%d) буде перезаписано. Це не можна скасувати.",
        "Write": "Написати",
        "Write %d": "Написати %d",
        "Write %d reports…": "Написати звітів: %d…",
        "Write a “%@” report for %d meetings?": "Написати звіт «%@» для %d зустрічей?",
        "Write a “%@” report for “%@”?": "Написати звіт «%@» для «%@»?",
        "Write all %d…": "Написати всі %d…",
        "Write for a selection…": "Написати для виділених…",
        "Write report › %@": "Написати звіт › %@",
        "Written": "Написано",
        "No instruction — goes by its name alone": "Без інструкції — лише за назвою",
        "Drag to reorder": "Перетягніть, щоб змінити порядок",
        "Every report is kept inside its meeting’s file.": "Кожен звіт зберігається всередині файлу своєї зустрічі.",
        "A refusal stops that meeting only; the rest continue.": "Відмова зупиняє лише цю зустріч; решта продовжуються.",
        "Always assume": "Вважати даністю",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Факти, яких у дзвінку не промовляють, але кожен звіт має приймати як даність: хто ви, яка сторона клієнт, які слова ваша команда розуміє по-своєму. Надсилається з кожним звітом за цим шаблоном.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Необов’язково. Без цього модель читає дзвінок з нуля: для зустрічі колег це зазвичай нормально, для дзвінка із зовнішньою стороною — ні.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Ми — агенція продажів. Клієнт — завжди інша сторона, не ми. «Місця» означає платні ліцензії користувачів.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Показується на картці зустрічі, у бібліотеці в розділі Reports і як заголовок усередині готового звіту.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Кожне поле стає заголовком у звіті, у цьому порядку. Перетягніть поле за ручку, щоб перемістити. Інструкція необов’язкова й може бути будь-якої довжини; поле без неї береться лише за назвою.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Кожне поле заповнюється лише з розшифровки цього дзвінка. Поле, якого дзвінок не торкнувся, отримує «Not discussed».",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Шаблон — це назва й кілька полів. Звіт за ним пишеться на запит, один на шаблон для кожної зустрічі.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Шаблонів поки немає. Шаблон — це назва й кілька полів; звіт за ним пишеться на запит із картки зустрічі, один на шаблон для кожної зустрічі.",
    ]

    static let es: [String: String] = [
        "Settings": "Ajustes",
        "Keyboard shortcuts": "Atajos de teclado",
        "Storage & models": "Almacenamiento y modelos",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "El llavero rechazó guardar la clave; sigue en el campo. Desbloquee el llavero e inténtelo de nuevo.",
        "Couldn't reach the update server. Try again once you're online.": "No se pudo contactar el servidor de actualizaciones. Inténtelo cuando esté en línea.",
        "You're up to date — Dictate %@ is the newest version.": "Está al día: Dictate %@ es la versión más reciente.",
        "Recorded meetings appear here.": "Las reuniones grabadas aparecen aquí.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Esto es solo su micrófono: la otra parte de la llamada no se grabó y no se puede recuperar.",
        "Turning both on covers the calls that come next.": "Al activar ambos, las próximas llamadas quedan cubiertas.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ rechazó la solicitud por motivos de facturación. Añada crédito en su cuenta del proveedor o desconecte el agente en Ajustes.",
        "Agent": "Agente",
        "Ask your agent": "Preguntar al agente",
        "Ask your agent anything…": "Pregúntele lo que sea a su agente…",
        "Has read %d of %d meetings": "Ha leído %d de %d reuniones",
        "Has read 1 meeting": "Ha leído 1 reunión",
        "Has read all %d meetings": "Ha leído las %d reuniones",
        "Meetings & Agent…": "Reuniones y agente…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Ahora no deja el agente desactivado y oculto. La búsqueda y las transcripciones no se ven afectadas.",
        "Nothing to read yet": "Aún no hay nada que leer",
        "Off — has read nothing yet": "Desactivado: aún no ha leído nada",
        "Reading %d of %d meetings…": "Leyendo %d de %d reuniones…",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "Esto es lo que escribe el resumen y el esquema, y lo que da al agente algo con que responder. Desactivado, queda la transcripción en bruto: sin resumen, sin esquema y sin agente. En ningún caso se envía nada a ninguna parte.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Su agente responde a preguntas sobre todo lo que ha grabado — «qué decidimos sobre la fecha de congelación» — y cita la reunión y el momento de donde salió. Necesita el modelo que lee sus reuniones, que ahora está desactivado. En cualquier caso, nada sale de este Mac.",
        "Your agent has nothing to read yet": "Su agente aún no tiene nada que leer",
        "Your agent has read 1 meeting": "Su agente ha leído 1 reunión",
        "Your agent has read all %d meetings": "Su agente ha leído las %d reuniones",
        "Your agent is off": "Su agente está desactivado",
        "Your agent is reading — %d of %d meetings so far": "Su agente está leyendo: %d de %d reuniones por ahora",
        "answers with %@": "responde con %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Nada aquí puede oír una llamada hasta que se conceda en Ajustes del Sistema › Privacidad y seguridad › Micrófono.",
        "There is no summary or outline — reading your meetings is off.": "No hay resumen ni esquema: leer sus reuniones está desactivado.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Esto es solo su micrófono: falta la otra parte de la llamada, el texto es un bloque continuo y no hay resumen ni esquema.",
        "Turn both on": "Activar ambos",
        "Turn it on": "Activarlo",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Al activarlo, también se escriben para las próximas grabaciones. Escribir uno ahora deja el interruptor apagado.",
        "Waiting on microphone access.": "Esperando el acceso al micrófono.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Espera a «%@» arriba: aún no hay audio de llamada que separar.",
        "Write one, this once": "Escribir uno, solo esta vez",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "Escribir uno ahora lee solo esta transcripción y deja los interruptores apagados. La otra parte de esta llamada no se grabó y no se puede recuperar.",
        "Writing…": "Escribiendo…",
        "macOS denied microphone access": "macOS denegó el acceso al micrófono",
        "%@ call — not being recorded": "Llamada de %@ — no se está grabando",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "La grabación de llamadas está desactivada, así que esta pasa sin transcribir. Al activarla obtendrá después una transcripción con búsqueda y un resumen, guardados en este Mac.",
        "Call — not being recorded": "Llamada — no se está grabando",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Las llamadas no se detectan automáticamente. Puede iniciar cada una aquí, o dejar que Dictate lo proponga cuando empiece una llamada.",
        "Connect a provider…": "Conectar un proveedor…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "El dictado sigue funcionando. Cada interruptor de abajo dice qué añade; puede activar uno y dejar el resto en paz.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "El dictado ya funciona: mantenga pulsada la tecla de dictado y hable en cualquier parte. Todo lo de abajo trata de reuniones, y nada es obligatorio. Active lo que quiera; el resto queda desactivado.",
        "Don't offer this again": "No volver a ofrecer",
