        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Las grabaciones llegan ya con título, en vez de «Llamada de Zoom, 14:02». Solo se leen los títulos que coinciden con una grabación.",
        "Separate the voices": "Separar las voces",
        "Set up calls…": "Configurar llamadas…",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "El agente busca y lee sus transcripciones en este Mac; la respuesta escrita viene de un proveedor que usted conecta con su propia clave.",
        "Three things are off. Here is what each one adds.": "Hay tres cosas desactivadas. Esto es lo que añade cada una.",
