        "%d s": "%d s",
        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "La grabación del audio del sistema no está permitida. Activa Dictate en Ajustes del Sistema → Privacidad y seguridad → Grabación de pantalla y audio del sistema, y vuelve a intentarlo.",
        "Stop": "Detener",
        "Automatic (any language)": "Automático (cualquier idioma)",
        "detect while you speak": "se detecta al hablar",
        "Search language…": "Buscar idioma…",
