        "No language matches your search.": "Ningún idioma coincide con tu búsqueda.",
        "Translate key": "Tecla de traducción",
        "%@ is using the microphone right now — close it and try again": "%@ está usando el micrófono ahora — ciérralo e inténtalo de nuevo",
        "That was very quiet — move closer to the microphone": "Fue muy bajo — acércate al micrófono",
        "That was too loud — move back a little from the microphone": "Fue demasiado alto — aléjate un poco del micrófono",
        "Sorry, I didn't catch that — could you say it again?": "Perdona, no te he oído bien — ¿podrías repetirlo?",
        "Not inserted — text copied, press ⌘V to paste": "No insertado — texto copiado, pulsa ⌘V para pegar",
        "Another app is using the microphone right now — close it and try again": "Otra app está usando el micrófono ahora — ciérrala e inténtalo de nuevo",
        "General": "General",
        "Type a key…": "Pulsa una tecla…",
        "Hold to talk, release to insert what you said.": "Mantén para hablar, suelta para insertar lo que dijiste.",
        "Downloaded %d of %d MB": "Descargados %d de %d MB",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Preparando el modelo para el Neural Engine… Unos minutos, una sola vez.",
        "Warming up the model…": "Calentando el modelo…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate se está ejecutando desde la imagen descargada: arrástralo a «Aplicaciones», expulsa la imagen y ábrelo desde allí. Los permisos concedidos a esta copia temporal no se conservarán.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "¿Sigue sin funcionar? Restablece el permiso: esto borra el registro dañado de macOS; luego concédelo en la nueva solicitud.",
        "Words: %d · %.1f s": "Palabras: %d · %.1f s",
        "Words: %d": "Palabras: %d",
        "Cancelled": "Cancelado",
        "Changed your mind? Esc cancels the recording.": "¿Cambiaste de idea? Esc cancela la grabación.",
        "About Dictate": "Acerca de Dictate",
        // Onboarding — general
        "Welcome to Dictate": "Te damos la bienvenida a Dictate",
        "Back": "Atrás",
        "Next": "Siguiente",
        "Step %d of %d": "Paso %d de %d",
        // Welcome
        // Hotkey
        "Dictation key": "Tecla de dictado",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Esta tecla escribe caracteres — mientras la mantengas presionada, irán a parar a tu texto. Es más seguro un modificador (Option, Cmd, Shift, Ctrl) o una tecla F.",
        // Permissions
        "Microphone": "Micrófono",
        "Accessibility": "Accesibilidad",
        // Settings
        "Dictate Settings": "Configuración de Dictate",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "Esta tecla escribe caracteres — durante el dictado irán al texto. Mejor un modificador o una tecla F.",
        "Launch at login": "Abrir al iniciar sesión",
        "Show in Dock": "Mostrar en el Dock",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "El agente busca y lee tus transcripciones en este Mac, y cada respuesta nombra las reuniones en que se basa.",
        "Undo remove": "Deshacer eliminación",
        "Call started": "Ha empezado una llamada",
        "Recording stopped by itself — the call ended.": "La grabación se detuvo sola — la llamada terminó.",
        "Recording stopped by itself — ten minutes of silence.": "La grabación se detuvo sola — diez minutos de silencio.",
        "%@ call started": "Empezó una llamada de %@",
        "Not this one": "Esta no",
        "Record": "Grabar",
        "Record this call": "Grabar esta llamada",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Dictado que funciona sin conexión — el reconocimiento ocurre por completo en este Mac.",
        "Translation that works offline — speak your language, another comes out.": "Traducción que funciona sin conexión — habla tu idioma y sale otro.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Un agente opcional que conoce tus reuniones — las respuestas citan el momento del que salieron.",
        "%d MB of %d MB": "%d MB de %d MB",
        "Already clicked and nothing changed?": "¿Hiciste clic y no cambió nada?",
        "Applications": "Aplicaciones",
        "Downloading the speech model": "Descargando el modelo de voz",
        "Grant…": "Conceder…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Nada sale de esta ventana. Dos pequeñas pruebas y habrás terminado.",
        "Resume Download": "Reanudar descarga",
        "Show me where to look": "Muéstrame dónde mirar",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Iniciar Dictate al iniciar sesión — aparece en el Dock y en la barra de menús; el icono del Dock puede ocultarse luego en Ajustes",
        "Start Using Dictate": "Empezar a usar Dictate",
        "Stopped · %d MB of %d MB kept on disk": "Detenida · %d MB de %d MB guardados en disco",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "La conexión se interrumpió. Al reanudar continúa desde donde se detuvo — no volverás a descargar los %d MB completos.",
        "The download stopped at %d MB": "La descarga se detuvo en %d MB",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "El modelo se compila para tu chip para que el reconocimiento sea rápido después. Tarda un minuto en el primer arranque y no vuelve a ocurrir.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Esto ocurre una vez. El modelo se queda en tu Mac y es la razón de que el dictado funcione luego sin conexión a internet.",
        "To hear you. Audio is processed on this Mac and discarded.": "Para oírte. El audio se procesa en este Mac y se descarta.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Para escribir el texto reconocido en la app que estás usando. Es la única forma en que una app puede insertar texto en otra.",
        "Try it here first": "Pruébalo aquí primero",
        "Two permissions from macOS": "Dos permisos de macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "Los pide macOS, no nosotros. Dictate no puede funcionar sin ambos.",
        "Show or hide the conversations": "Mostrar u ocultar las conversaciones",
        "Show or hide the sidebar": "Mostrar u ocultar la barra lateral",
        "Show or hide the meeting list": "Mostrar u ocultar la lista de reuniones",
        "Preparing the model for this Mac": "Preparando el modelo para este Mac",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Aún no está listo — tarda unos segundos tras el arranque. Mantén %@ pulsada y empezará.",
        "Transcript text": "Texto de la transcripción",
        "Smaller text": "Texto más pequeño",
        "Standard text": "Texto estándar",
        "Larger text": "Texto más grande",
        "100 languages · from your system settings": "100 idiomas · de los ajustes del sistema",
        "Add tag": "Añadir etiqueta",
        "Appearance": "Apariencia",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Se pregunta una vez. Después, la grabación empieza desde la barra de menús sin avisos. Esc significa no grabar.",
        "Check for updates": "Buscar actualizaciones",
        "Choose your keys and languages": "Elige tus teclas e idiomas",
        "Click, then press a key": "Haz clic y pulsa una tecla",
        "Dark": "Oscuro",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate grabará tu micrófono y el audio de la llamada, y guardará la transcripción en este Mac. Grabar a otras personas puede requerir su consentimiento donde estés.",
        "Don't Record": "No grabar",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Mantén la tecla pulsada mientras hablas. Todo puede cambiarse luego en Ajustes.",
        "I speak": "Yo hablo",
        "Light": "Claro",
        "Looking through %d meetings…": "Revisando %d reuniones…",
        "Match system": "Igual que el sistema",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Las teclas modificadoras funcionan mejor: nunca insertan un carácter al mantenerlas. Esc siempre cancela un dictado en curso.",
        "Reading “%@”…": "Leyendo “%@”…",
        "Record this call?": "¿Grabar esta llamada?",
        "Searching your meetings…": "Buscando en tus reuniones…",
        "Start Recording": "Empezar a grabar",
        "Tags": "Etiquetas",
