        "Show outline": "Mostrar esquema",
        "two levels": "dos niveles",
        "%d moments": "%d momentos",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Se guarda en este Mac. Borrar es inmediato; pasadas 50 conversaciones, las más antiguas se descartan.",
        "Ask across all meetings…": "Preguntar en todas las reuniones…",
        "Recently Added": "Añadidas recientemente",
        "%d meetings · %d h of audio": "%d reuniones · %d h de audio",
        "%d meetings · %d min of audio": "%d reuniones · %d min de audio",
        "Show more": "Mostrar más",
        "Try one of these": "Prueba una de estas",
        "Accessibility access is turned off": "El acceso de Accesibilidad está desactivado",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "El dictado te oye pero no puede escribir. Reactívalo para continuar.",
        "Recent dictations": "Dictados recientes",
        "Secure input is active — the hotkey cannot work": "La entrada segura está activa — la tecla no puede funcionar",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "Algo tiene un campo de contraseña enfocado. macOS no dice qué app. Haz clic en un campo de texto normal y el dictado vuelve a funcionar.",
        "Start Recording Meeting": "Grabar una reunión",
        "Stop Recording Meeting": "Detener la grabación de la reunión",
        "dictate in %@": "dictar en %@",
        "dictate in any language": "dictar en cualquier idioma",
        "translate %@ → %@": "traducir %@ → %@",
        "translate into %@": "traducir a %@",
        "%d waiting": "%d en espera",
        "%d words typed": "%d palabras escritas",
        "Add a Key…": "Añadir una clave…",
        "Both will be inserted in the order you spoke them": "Ambas se insertarán en el orden en que las dijiste",
        "Check Audio Setup": "Comprobar el audio",
        "Clear All Filters": "Quitar todos los filtros",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "Las teclas F también activan un control del sistema (brillo, multimedia) — macOS hará ambas cosas. Para usarla como tecla normal, activa «Use F1, F2, etc. as standard function keys» en los ajustes de teclado.",
        "How this works": "Cómo funciona",
        "Input device changed": "El dispositivo de entrada cambió",
        "Insert text by": "Insertar el texto",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Fue revocada o sustituida desde que conectaste. Se ha eliminado del llavero — no se reintentó nada con ella.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Únete a una llamada en el navegador y empieza a grabar. Dictate captura tu micrófono y el audio de la llamada, transcribe ambos en este Mac y guarda la transcripción aquí. No se sube nada.",
        "No meeting has all of these tags": "Ninguna reunión tiene todas estas etiquetas",
        "No meeting has this tag": "Ninguna reunión tiene esta etiqueta",
        "Nothing was said, or nothing was heard": "No se dijo nada, o no se oyó nada",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Aquí solo se ve la cola sin confirmar — el resto ya está en el documento",
        "Open Console": "Abrir la consola",
        "Open Settings": "Abrir Ajustes",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Pegar es instantáneo pero sustituye el portapapeles un momento. Escribir funciona en apps que bloquean el pegado, como algunos terminales y escritorios remotos.",
        "Pasting it at once": "Pegándolo de una vez",
        "Recording ended here — this Mac went to sleep.": "La grabación terminó aquí — este Mac se durmió.",
        "Remove “%@”": "Quitar «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return envía · Mayús-Return añade línea · Esc borra",
        "Show Floating Timer": "Mostrar el temporizador flotante",
        "Start Recording a Meeting": "Grabar una reunión",
        "Still recognizing the previous dictation": "Aún reconociendo el dictado anterior",
        "Still recognizing the previous dictation · %d words": "Aún reconociendo el dictado anterior · %d palabras",
        "Switched to %@": "Cambiado a %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Los filtros de etiquetas se combinan con «y» — la reunión debe llevar todas las etiquetas elegidas.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "La respuesta se detuvo. Tu pregunta queda arriba — reintenta cuando vuelva la conexión. La búsqueda y las transcripciones siguen funcionando.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "La grabación corrió, pero no se reconoció voz en ningún lado. Normalmente significa que el audio de la llamada nunca se capturó — una pestaña sin permiso de audio o el dispositivo de salida equivocado.",
        "The saved key no longer works": "La clave guardada ya no funciona",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "El interruptor sigue apagado hasta concederlo en System Settings › Privacy & Security › Calendars. Solo se leen los títulos de eventos que coinciden con una grabación.",
        "This Mac is offline": "Este Mac está sin conexión",
        "Too many questions at once": "Demasiadas preguntas a la vez",
        "Typing as you speak": "Escribiendo mientras hablas",
        "Typing into %@ as you speak": "Escribiendo en %@ mientras hablas",
        "Typing it out character by character": "Escribiéndolo letra a letra",
        "Your provider account is out of credit": "Tu cuenta del proveedor no tiene crédito",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Tu proveedor está limitando la frecuencia. Espera unos segundos y reintenta — no se perdió nada.",
        "macOS denied calendar access": "macOS denegó el acceso al calendario",
        "API key": "Clave API",
        "All Meetings": "Todas las reuniones",
        "Assistant": "Asistente",
        "Checking the key with %@. No transcript is sent — only a test request.": "Comprobando la clave con %@. No se envía ninguna transcripción — solo una solicitud de prueba.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Cerrar la ventana no detiene la grabación. Deténla aquí o desde la barra de menús en cualquier momento.",
        "Connect an assistant to answer questions": "Conecta un asistente para responder preguntas",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate puede grabar una llamada del navegador y guardar la transcripción en este Mac. Iníciala desde la barra de menús cuando empiece tu próxima llamada — se pedirá consentimiento una vez.",
        "Done": "Hecho",
        "Every change takes effect immediately.": "Cada cambio surte efecto al instante.",
        "Get one at %@.": "Consigue una en %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Mantén pulsada una tecla, habla, suéltala. Lo que dijiste se escribe donde está el cursor, en cualquier app de este Mac.",
        "Keys": "Teclas",
        "Languages": "Idiomas",
        "Library": "Biblioteca",
        "Paste a key from your own account.": "Pega una clave de tu propia cuenta.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Guardada en tu llavero, pero sin verificar — este Mac está sin conexión. Se comprobará la primera vez que preguntes algo.",
        "Set Up Dictate": "Configurar Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Se guarda en el llavero de macOS en este Mac. Nunca se escribe en un archivo de ajustes ni se sincroniza.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "La clave fue rechazada. Puede estar revocada, ser de otro proveedor o no tener crédito — la clave no se guardó.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Las transcripciones, la búsqueda y las citas funcionan sin esto. El asistente solo hace falta para redactar la respuesta.",
        "Try Again": "Reintentar",
        "Updates": "Actualizaciones",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Pagas a tu proveedor por pregunta — normalmente una fracción de céntimo. Solo se envían tu pregunta y los pasajes citados; las grabaciones nunca salen de este Mac.",
        "Send": "Enviar",
        "Conversations": "Conversaciones",
        "New question": "Nueva pregunta",
        "Deleted “%@”": "Eliminado: “%@”",
        "Undo": "Deshacer",
        "Questions you ask are kept here so you can return to an answer.": "Las preguntas se guardan aquí para volver a una respuesta.",
        "Rename": "Renombrar",
        "Delete": "Eliminar",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Las voces se emparejan por sonido: el nombre solo se aplica a los turnos de esta voz.",
        "Give two voices the same name to merge them.": "Dé el mismo nombre a dos voces para fusionarlas.",
        "Voices are told apart by sound — one person can show up as two.": "Las voces se distinguen por el sonido: una persona puede aparecer como dos.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "Haga clic en un nombre para renombrar una voz; el mismo nombre fusiona dos. Los resúmenes y las respuestas se basan en lo que se dijo, no en quién lo dijo.",
        "Voice separation improves over time.": "La separación de voces mejora con el tiempo.",
        "About voice separation": "Sobre la separación de voces",
        "Call · voice %d": "Llamada · voz %d",
        "Starred": "Destacadas",
        "Other browser calls": "Otras llamadas del navegador",
        "Sources": "Fuentes",
        "Star meeting": "Destacar reunión",
        "Unstar meeting": "Quitar de destacadas",
        "Export transcript…": "Exportar transcripción…",
        "Still recording": "Sigue grabando",
        "Got it": "Entendido",
        "Call": "Llamada",
        "Dictating": "Dictando",
        "Dictating in %@": "Dictando en %@",
        "Translating into English": "Traduciendo al inglés",
        "Translating into %@": "Traduciendo al %@",
        "Release %@ to insert": "Suelta %@ para insertar",
        "Also recording this meeting": "También se está grabando esta reunión",
        "%@ MB/s · about %@ left": "%@ MB/s · quedan unos %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "No hay espacio suficiente: la descarga necesita unos %d MB y hay %d MB libres. Libera espacio e inténtalo de nuevo.",
        "Fix…": "Corregir…",
        "Checked automatically · last %@": "Comprobación automática · última: %@",
        "Source code": "Código fuente",
        "Report an issue": "Informar de un problema",
        "Finishing the transcript…": "Terminando la transcripción…",
        "Disk almost full — will stop to keep the transcript": "Disco casi lleno: se detendrá para conservar la transcripción",
        "Dictate is running from its disk image": "Dictate se está ejecutando desde su imagen de disco",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Los permisos concedidos desde una imagen de disco se pierden al expulsarla, y el modelo se descargaría de nuevo cada vez. Mueve primero Dictate a la carpeta Aplicaciones.",
        "Move to Applications": "Mover a Aplicaciones",
        "Quit": "Salir",
        "Couldn't move Dictate automatically": "No se pudo mover Dictate automáticamente",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Arrastra Dictate desde la imagen de disco a la carpeta Aplicaciones y ábrelo desde allí.",
        "OK": "OK",
        "Inserted into %@": "Insertado en %@",
        "Inserted": "Insertado",
        "Accessibility is off — dictation can hear you but cannot type": "La Accesibilidad está desactivada: el dictado te oye pero no puede escribir",
        "Open Privacy & Security…": "Abrir Privacidad y seguridad…",
        "1 dictation still being recognized": "1 dictado aún se está reconociendo",
        "%d dictations still being recognized": "%d dictados aún se están reconociendo",
        "Language Packs…": "Paquetes de idioma…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Si está desactivado, Dictate vive solo en la barra de menús. Al hacer clic en el icono del Dock se abre Reuniones; el icono de la barra de menús está siempre.",
        "Interface language": "Idioma de la interfaz",
        "Granted": "Concedido",
        "No": "No",
        "Model ready": "Modelo listo",
        "On-device recognition": "Reconocimiento en el dispositivo",
        "Spoken language": "Idioma hablado",
        "Download failed. Check your connection and retry.": "La descarga falló. Revisa tu conexión e inténtalo de nuevo.",
        "Not set": "Sin asignar",
        "Remove": "Quitar",
        "Download & continue": "Descargar y continuar",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Unos %@ — se descarga una sola vez. Es el único momento en que Dictate necesita internet.",
        "Hold %@ and say something — the recognized text shows up below.": "Mantén presionada %@ y di algo — el texto reconocido aparece abajo.",
        "Recognized text appears here…": "El texto reconocido aparecerá aquí…",
        // Menu bar
        "Settings…": "Configuración…",
        "Quit Dictate": "Salir de Dictate",
        "Dictate — voice dictation": "Dictate — dictado por voz",
        // HUD
        "Recognizing…": "Reconociendo…",
        "Esc to cancel": "Esc para cancelar",
        // Errors
        "Couldn't start recording: %@": "No se pudo iniciar la grabación: %@",
        "Recording truncated at %d seconds (limit)": "Grabación cortada a los %d segundos (límite)",
        "Audio device changed during recording — recording cancelled, please try again.": "El dispositivo de audio cambió durante la grabación — la grabación se canceló, inténtalo de nuevo.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "El permiso de Accesibilidad está desactivado, así que la tecla no se detecta. Actívalo en Configuración del Sistema → Privacidad y seguridad → Accesibilidad — Dictate lo detecta automáticamente, sin reiniciar.",
        "Microphone unavailable (no input audio format)": "Micrófono no disponible (sin formato de audio de entrada)",
        // Key names
        "Right Option (⌥)": "Option derecha (⌥)",
        "Left Option (⌥)": "Option izquierda (⌥)",
        "Right Command (⌘)": "Command derecha (⌘)",
        "Left Command (⌘)": "Command izquierda (⌘)",
        "Right Shift (⇧)": "Shift derecha (⇧)",
        "Left Shift (⇧)": "Shift izquierda (⇧)",
        "Right Control (⌃)": "Control derecha (⌃)",
        "Left Control (⌃)": "Control izquierda (⌃)",
        "Space": "Espacio",
        "Follow system": "Igual que el sistema",
        "Translating…": "Traduciendo…",
        "Tip: hold %@ instead — your speech comes out in English.": "Consejo: mantén %@ en su lugar — tu voz saldrá en inglés.",
        "Hold to talk in your language, release to insert it in English.": "Mantén pulsado y habla en tu idioma; suelta y se inserta en inglés.",
        "Hold %@ and say it again — this time it's typed in English.": "Mantén %@ y dilo otra vez: esta vez se escribe en inglés.",
        "Translate to": "Traducir a",
        "Translation data isn't downloaded — open Settings to get it": "Los datos de traducción no están descargados: descárgalos en la configuración",
        "Translation data": "Datos de traducción",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "La tecla de traducción transcribe tu voz y luego macOS la traduce en este Mac. Al elegir un idioma, macOS puede descargar sus datos de traducción una vez.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "El reconocimiento se ejecuta en el Neural Engine de tu Mac: Whisper large-v3-turbo, 100 idiomas, se maneja bien con los acentos y es lo bastante rápido para el texto en vivo. La traducción también ocurre en este Mac. Tu voz nunca sale de este ordenador.",
        "Hold %@ and say it again — this time it comes out in %@.": "Mantén %@ y dilo otra vez: esta vez sale en %@.",
        "Hold to talk in your language, release to insert it in %@.": "Mantén pulsado y habla en tu idioma; suelta y se inserta en %@.",
        "Not downloaded": "Sin descargar",
        "Translation languages": "Idiomas de traducción",
        "Downloaded": "Descargado",
        "Manage in System Settings…": "Gestionar en Ajustes del Sistema…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "¿Ya está activado en Ajustes del Sistema pero aquí no aparece en verde? Apaga y vuelve a encender el interruptor de Dictate: tras una actualización, macOS a veces conserva una entrada obsoleta.",
        "Agent: %@, on your key.": "Agente: %@, con su clave.",
        "Agent: off.": "Agente: desactivado.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "Apple Intelligence no está disponible en este Mac para esta región o idioma. El agente con su propia clave sigue funcionando.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence necesita macOS 26. El agente con su propia clave sigue funcionando.",
        "Copy diagnostics": "Copiar diagnóstico",
        "Debug audio dumps": "Volcados de audio de depuración",
        "Diagnostics": "Diagnóstico",
        "Downloading…": "Descargando…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Libera %@. Las reuniones nuevas conservarán la fecha como nombre hasta que lo descargue de nuevo. Los resúmenes ya escritos se mantienen.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Libera %@. Nada más cambia — la lectura de sus reuniones está desactivada.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Libera %@. Los títulos y resúmenes vendrán de Apple Intelligence.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Instalado pero sin ejecutarse: este Mac tiene %d GB de memoria y necesita 16.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Instalado pero sin ejecutarse: este Mac tiene %d GB de memoria y necesita 16. Nada en este Mac lee las reuniones.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Instalado pero sin ejecutarse: este Mac tiene %d GB de memoria y necesita 16. Los títulos y resúmenes vienen de Apple Intelligence en su lugar.",
        "Installed · %@": "Instalado · %@",
        "Installed, not in use · %@": "Instalado, sin usar · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Mientras escribe ocupa unos %@ de memoria, algo que este Mac notará.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, versión y qué funciones están activadas. Sin transcripciones, sin claves.",
        "Meeting archive": "Archivo de reuniones",
        "Meeting model": "Modelo de reuniones",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Modelo de reuniones instalado. Las reuniones nuevas reciben títulos y resúmenes en este Mac.",
        "Meeting reading: Apple Intelligence.": "Lectura de reuniones: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Lectura de reuniones: nada en este Mac puede hacerlo todavía.",
        "Meeting reading: the downloaded model (%@).": "Lectura de reuniones: el modelo descargado (%@).",
        "Not available on this Mac.": "No disponible en este Mac.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "No instalado. Una descarga única de %@ escribe títulos, resúmenes y un índice.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "Nada en este Mac puede leer todavía: Apple Intelligence no está disponible aquí. El agente con su propia clave sigue funcionando.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "Nada en este Mac puede leer todavía: descargue el modelo de reuniones más abajo, o añada una clave para el agente.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "Nada en este Mac puede leer todavía: descargue el modelo de reuniones más abajo, o active Apple Intelligence en Ajustes del Sistema.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "Nada en este Mac puede leer todavía: macOS aún está configurando Apple Intelligence. El agente con su propia clave sigue funcionando.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "Nada en este Mac puede leer todavía: active Apple Intelligence en Ajustes del Sistema, o añada una clave para el agente.",
        "Open System Settings": "Abrir Ajustes del Sistema",
        "Paused: not enough free memory right now. It resumes on its own.": "En pausa: ahora mismo no hay suficiente memoria libre. Se reanuda por sí solo.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Preparando el modelo para el procesador de este Mac… Unos minutos, una sola vez.",
        "Raw call audio kept for debugging only.": "Audio de llamadas en bruto, guardado solo para depuración.",
        "Reading is on, but nothing on this Mac can read yet.": "La lectura está activada, pero nada en este Mac puede leer todavía.",
        "Reads with Apple Intelligence.": "Lee con Apple Intelligence.",
        "Reads with the downloaded model.": "Lee con el modelo descargado.",
        "Recognition runs on the Neural Engine.": "El reconocimiento se ejecuta en el Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "El reconocimiento se ejecuta en el procesador de este Mac — Whisper large-v3-turbo: 100 idiomas, se maneja bien con los acentos. Más lento que en Apple Silicon, y la traducción también ocurre en este Mac. Su voz nunca sale de este ordenador.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "El reconocimiento se ejecuta en el procesador de este Mac — más lento que en Apple Silicon.",
        "Remove the debug audio dumps?": "¿Eliminar los volcados de audio de depuración?",
        "Remove the meeting model?": "¿Eliminar el modelo de reuniones?",
