        "Storage": "Almacenamiento",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Los resúmenes en este Mac vienen de Apple Intelligence. El modelo descargable necesita 16 GB de memoria; este Mac tiene %d.",
        "Summary paused: not enough free memory. It resumes on its own.": "Resumen en pausa: no hay suficiente memoria libre. Se reanuda por sí solo.",
        "Tell the voices on a call apart.": "Distinguir las voces de una llamada.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "El modelo de reuniones necesita 16 GB de memoria; este Mac tiene %d.",
        "These are recordings kept only for debugging. Nothing else is affected.": "Son grabaciones guardadas solo para depuración. Nada más se ve afectado.",
        "This Mac": "Este Mac",
        "This build of Dictate does not include the meeting model.": "Esta compilación de Dictate no incluye el modelo de reuniones.",
        "Titles and summaries come from Apple Intelligence instead.": "Los títulos y resúmenes vienen de Apple Intelligence en su lugar.",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "Active Apple Intelligence en Ajustes del Sistema › Apple Intelligence y Siri, o añada una clave para el agente.",
