        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS aún está configurando Apple Intelligence — vuelva más tarde, o añada una clave para el agente.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. El informe se queda en el archivo de la reunión de todos modos; esto crea una copia.",
