        "Template name": "Nombre de la plantilla",
        "Templates": "Plantillas",
        "The model returned no report.": "El modelo no devolvió ningún informe.",
        "The model stopped before the report was finished.": "El modelo se detuvo antes de terminar el informe.",
        "The saved key no longer works. It has been removed from the Keychain.": "La clave guardada ya no funciona. Se ha eliminado del llavero.",
        "What is sent": "Qué se envía",
        "Writing · about a minute": "Escribiendo · alrededor de un minuto",
        "Written by Dictate on this Mac from the transcript": "Escrito por Dictate en este Mac a partir de la transcripción",
        "Your %@ account refused the request for billing reasons.": "Su cuenta de %@ rechazó la solicitud por motivos de facturación.",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "Envía esta transcripción a %@ con su clave. El informe queda en el archivo de la reunión.",
        "Set up templates…": "Configurar plantillas…",
        "Write report": "Escribir informe",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@ está limitando las solicitudes. No se perdió nada: inténtelo de nuevo en un minuto.",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "Este Mac está sin conexión. No se envió nada: inténtelo cuando vuelva la conexión.",
        "Write a “%@” report?": "¿Escribir un informe “%@”?",
        "Action items": "Tareas",
        "Dates and deadlines": "Fechas y plazos",
