        "Purpose": "Propósito",
        "Risks and concerns": "Riesgos e inquietudes",
        "The main arguments and facts, with the numbers, names and dates that were said": "Los argumentos y hechos principales, con las cifras, nombres y fechas que se dijeron",
        "The next meeting or checkpoint, if one was agreed": "La próxima reunión o punto de control, si se acordó uno",
        "Waiting on": "A la espera de",
        "We are the team on this call; the reader took part in it.": "Somos el equipo en esta llamada; el lector participó en ella.",
        "What could go wrong, who raised it, how serious it sounded": "Qué podría salir mal, quién lo planteó y qué tan serio sonó",
        "What each side is waiting for from the other": "Qué espera cada parte de la otra",
        "What was decided, by whom, and what it replaces": "Qué se decidió, quién lo decidió y qué sustituye",
        "What was raised and not settled, and who owns it": "Qué se planteó sin resolver, y quién se encarga",
        "Who does what, by when — one line per task": "Quién hace qué y para cuándo: una línea por tarea",
        "Why we met and what we set out to settle": "Por qué nos reunimos y qué queríamos resolver",
        "%d more": "%d más",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "El título conserva el idioma de la reunión; el resumen y todos los informes se escriben en este. Los nombres de los campos de un informe se mantienen tal como se escribieron.",
        "About “%@”:": "Sobre “%@”:",
        "Replace the report with a new “%@” one?": "¿Sustituir el informe por uno nuevo “%@”?",
        "Replace report": "Sustituir informe",
        "Written · replaces it": "Escrito · se sustituye",
        "Dictate updated to %@.": "Dictate se actualizó a %@.",
        "Dismiss": "Cerrar",
        "New": "Nuevo",
        "New in this version": "Nuevo en esta versión",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Abra una reunión, pulse Write report en su cabecera y elija una plantilla. El informe aparece en la tarjeta y como PDF en Dictate Meetings › Reports.",
        "Reports from templates": "Informes con plantillas",
        "See what’s new": "Ver novedades",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Ajustes › Reuniones › Escribir resúmenes e informes en: el resumen y todos los informes llegan en el idioma en que usted lee, sea cual sea el idioma de la llamada.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Ajustes › Plantillas: empiece con Resumen de la reunión o Decisiones y tareas, o nombre sus propios campos y diga al modelo qué va debajo de cada uno.",
        "Summaries in your language": "Resúmenes en su idioma",
        "What’s new": "Novedades",
        "What’s new in Dictate %@": "Novedades de Dictate %@",
        "Your own templates": "Sus propias plantillas",
        "Install update %@ and relaunch": "Instalar la actualización %@ y reiniciar",
        "The update waits until the recording ends.": "La actualización espera a que termine la grabación.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "La actualización %@ está en camino: descargando. Se instalará sola en el próximo momento tranquilo; la barra de menús la ofrece antes.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "La actualización %@ está lista: instálela desde la barra de menús, o se instalará sola en el próximo momento tranquilo.",
        "An update is already on its way — it installs itself at the next quiet moment.": "Ya hay una actualización en camino: se instalará sola en el próximo momento tranquilo.",
        "Downloading update %@…": "Descargando la actualización %@…",
        "Preparing update %@…": "Preparando la actualización %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate se actualizó a %@. Las novedades están en la ventana Reuniones.",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence se negó a resumir esta reunión.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "La transcripción, la búsqueda y el agente no cambian. Un modelo descargable, guardado en este Mac, no tiene esa restricción.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Reuniones grabadas y estructuradas: participantes, resumen, esquema, búsqueda. Dictate ofrece grabar una llamada; nunca graba sin tu respuesta.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "El modelo de reuniones necesita 16 GB de memoria; este Mac tiene %d. No se está ejecutando, y los %@ que ocupa en disco se pueden liberar.",
        "Clipboard restored.": "Portapapeles restaurado.",
        "Your words were inserted untranslated.": "Tus palabras se insertaron sin traducir.",
        "A small panel appears when a call starts, and you decide there.": "Aparece un pequeño panel cuando empieza una llamada y usted decide ahí.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Escribe el resumen y el esquema, y da al agente algo con que responder. En ningún caso se envía nada a ninguna parte.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Desactivado, solo obtiene su propio micrófono; activado, la otra parte también se transcribe.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Convierte un bloque de texto en turnos con nombre. La separación es por sonido y puede ser imprecisa; los nombres pueden cambiarse.",
        "Find in this transcript…": "Buscar en esta transcripción…",
        "%d of %d": "%d de %d",
        "No matches": "Sin coincidencias",
        "Previous match": "Coincidencia anterior",
        "Next match": "Coincidencia siguiente",
        "Close find": "Cerrar la búsqueda",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "Se ha elegido %@, pero aún no hay clave. El agente y los informes quedan apagados hasta que se añada una.",
        "%@ · required for dictation, cannot be removed.": "%@ · necesario para dictar, no se puede eliminar.",
        "%@ — not written": "%@ — sin escribir",
        "%d h": "%d h",
        "%d meetings have a %@ report. They stay if this template goes.": "%d reuniones tienen un informe «%@». Se conservan si esta plantilla desaparece.",
        "%d min ago": "hace %d min",
        "%d written": "%d escritos",
        "%d written, %d not written": "%d escritos, %d sin escribir",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 idiomas. Se aplica a esta ventana y a la barra de menús de inmediato. El idioma que hablas se elige en Dictado.",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Una clave de tu propia cuenta de %@. Se guarda en tu llavero, nunca en un archivo de ajustes.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Una pregunta envía la pregunta y los pasajes que encontró la búsqueda. Un informe envía la transcripción completa de esa reunión: unas 12.000 palabras por hora de conversación. Ambos van a %@ con tu clave, y solo cuando lo pides. Las grabaciones nunca salen de este Mac.",
        "About": "Acerca de",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "Apple Intelligence no está disponible en este Mac, así que no hay alternativa a la que recurrir.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence necesita un macOS más reciente que el de este Mac, así que no hay alternativa a la que recurrir.",
        "Applies to this window, the meetings window and the panels over your other apps.": "Se aplica a esta ventana, a la de reuniones y a los paneles sobre tus otras apps.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Se pregunta una vez. A partir de ahora el panel es la versión corta y se queda hasta que respondas. También puedes empezar a grabar desde la barra de menús en cualquier momento de la llamada.",
        "Calendar": "Calendario",
        "Collapse %@": "Contraer %@",
        "Copy": "Copiar",
        "Dictation": "Dictado",
        "Expand %@": "Expandir %@",
        "Export…": "Exportar…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "También está en Dictados recientes, así que el portapapeles vuelve a ser tuyo cuando quieras.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Se guardan dentro del archivo de esta reunión, así que viajan con la transcripción. Exportar hace una copia donde quieras.",
        "No report": "Sin informe",
        "No report for this meeting yet.": "Todavía no hay informe para esta reunión.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "No se pierde nada al eliminarlo: la transcripción, la búsqueda y el agente no dependen de él.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Aquí no se configura nada. Cada línea de arriba informa de lo que puede hacer este Mac o señala el panel que lo controla.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "Nada en este Mac puede leer todavía: Apple Intelligence necesita un macOS más reciente. El agente con tu propia clave sigue funcionando.",
        "Nothing was kept from this take — earlier ones are still here.": "De esta toma no quedó nada; las anteriores siguen aquí.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "No se grabó nada, así que no quedó nada. Las anteriores siguen aquí.",
        "Off — dictation cannot type": "Desactivado: el dictado no puede escribir",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Apagado: las transcripciones, los resúmenes, los esquemas y la búsqueda funcionan como antes. El agente responde preguntas sobre todas tus reuniones y escribe informes a partir de tus plantillas; se ejecuta en la nube con tu propia clave de API.",
        "On this Mac": "En este Mac",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Un solo archivo reanudable. Cerrar Dictate lo pausa; luego continúa donde se quedó.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Una descarga única de %@ y, a partir de ahí, títulos, resúmenes y esquemas se hacen por completo en este Mac. Necesita 16 GB de memoria para funcionar y ocupa unos %@ mientras escribe.",
        "Open System Settings…": "Abrir Ajustes del Sistema…",
        "Or start from the menu bar later in the call.": "O empieza desde la barra de menús más adelante en la llamada.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "En pausa ahora mismo: no hay suficiente memoria libre. Se reanuda por sí solo y las reuniones que esperan resumen conservan su transcripción.",
        "Permissions": "Permisos",
        "Reads with Apple Intelligence until the download finishes.": "Lee con Apple Intelligence hasta que termine la descarga.",
        "Reads with the downloaded model — paused until there is free memory.": "Lee con el modelo descargado; en pausa hasta que haya memoria libre.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Las plantillas de informe están en Plantillas; los informes escritos, en la biblioteca, bajo Informes.",
        "Report · %@": "Informe · %@",
        "Report · %@ +%d": "Informe · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Los informes necesitan el agente, que está apagado. Elige Claude o ChatGPT en Resúmenes e informes; las plantillas se conservan mientras tanto.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Funciona por completo en este Mac. Sin él, los títulos y resúmenes vienen de Apple Intelligence.",
        "Startup": "Inicio",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Se guarda en tu llavero, nunca en un archivo de ajustes. El agente responde preguntas sobre todas tus reuniones y escribe informes a partir de tus plantillas.",
        "Summaries": "Resúmenes",
        "Summaries & reports": "Resúmenes e informes",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "La descarga es la forma de tener resúmenes en este Mac sin Apple Intelligence. La transcripción y la búsqueda funcionan de todos modos.",
        "This Mac was offline. Nothing was sent.": "Este Mac estaba sin conexión. No se envió nada.",
        "This take was not kept. Earlier ones are still here.": "Esta toma no se conservó. Las anteriores siguen aquí.",
        "Uses 41 MB of speaker models.": "Usa 41 MB de modelos de voces.",
        "What’s new in %@": "Novedades de %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Si algo lee estas grabaciones (resúmenes, esquemas, informes y el agente) se decide en Resúmenes e informes. Este panel trata solo de lo que se graba en este Mac.",
        "Write again": "Escribir de nuevo",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "Escribir informe, arriba, muestra tus %d plantillas. Escribir uno envía esta transcripción a %@ con tu clave; el informe se guarda dentro del archivo de esta reunión, así que viaja con la transcripción. Exportar hace una copia donde quieras.",
        "Written %@": "Escrito el %@",
        "Written by %@": "Escrito por %@",
        "Written by %@ %@ at %@": "Escrito por %@ el %@ a las %@",
        "Written in": "Escrito en",
        "Your agent, on your key": "Tu agente, con tu clave",
        "click to insert": "clic para insertar",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS todavía está preparando Apple Intelligence. Puede tardar un rato y no se puede acelerar desde aquí.",
        "macOS resets this switch after some updates and never asks a second time.": "macOS restablece este interruptor tras algunas actualizaciones y nunca vuelve a preguntar.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-clic para copiar en su lugar. Se borra al salir de Dictate.",
        "Meeting names": "Nombres de reuniones",
        "%d meetings, reports included": "%d reuniones, informes incluidos",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "Descarga el modelo de reuniones en Resúmenes e informes o añade una clave para el agente.",
        "Calls": "Llamadas",
        "Reports folder": "Carpeta de informes",
        "%d PDFs written before %@": "%d PDF escritos antes de %@",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate ya no escribe PDF por su cuenta. Son tuyos: consérvalos o bórralos; nada en la app depende de ellos.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "El informe ya escrito se sustituye. Envía esta transcripción a %@ con tu clave.",
        "%@ · report not written": "%@ · informe sin escribir",
        "%d of %d selected · %d meetings without one": "%d de %d seleccionadas · %d reuniones sin informe",
        "%d passages from %d meetings": "%d pasajes de %d reuniones",
        "%d written across %d templates": "%d escritos con %d plantillas",
        "%d written · %d meetings without one · %d fields": "%d escritos · %d reuniones sin informe · %d campos",
        "%d written · writing %d · %d not written": "%d escritos · escribiendo %d · %d sin escribir",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Un informe se escribe cuando lo pides: desde la ficha de una reunión o para una selección aquí. Cada uno envía la transcripción de esa reunión a %@ con tu clave y se guarda dentro del archivo de la reunión.",
        "All reports": "Todos los informes",
        "Answer": "Respuesta",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Respondido por %@ a partir de %d de %d reuniones. Las citas son literales de las transcripciones de este Mac.",
        "Copy as Markdown": "Copiar como Markdown",
        "Copy as plain text": "Copiar como texto sin formato",
        "Copy the answer only": "Copiar solo la respuesta",
        "Copy with quotes": "Copiar con citas",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "Cada plantilla guarda sus propios informes: lo que está escrito y las reuniones que podrían tener uno. Las plantillas se editan en Ajustes › Plantillas.",
        "Edit template…": "Editar plantilla…",
        "No report yet · %d meetings": "Sin informe todavía · %d reuniones",
        "None written · %d fields": "Ninguno escrito · %d campos",
        "Nothing written from this template yet": "Aún no hay nada escrito con esta plantilla",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Desactivado: esas %d se omiten y se escriben %d informes. Sustituir no se puede deshacer.",
        "Pick a template": "Elige una plantilla",
        "Quotes": "Citas",
        "Replace the %d that already have one": "Sustituir las %d que ya lo tienen",
        "Report not written — the request was refused. The meeting has the detail.": "Informe sin escribir: la solicitud fue rechazada. El detalle está en la reunión.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Envía %d transcripciones a %@ con tu clave: unas %@ palabras. Cada informe se guarda dentro del archivo de su reunión. Las grabaciones nunca salen de este Mac.",
        "The %d existing reports are overwritten. This cannot be undone.": "Los %d informes existentes se sobrescriben. Esto no se puede deshacer.",
        "Write": "Escribir",
        "Write %d": "Escribir %d",
        "Write %d reports…": "Escribir %d informes…",
        "Write a “%@” report for %d meetings?": "¿Escribir un informe «%@» para %d reuniones?",
        "Write a “%@” report for “%@”?": "¿Escribir un informe «%@» para «%@»?",
        "Write all %d…": "Escribir los %d…",
        "Write for a selection…": "Escribir para una selección…",
        "Write report › %@": "Escribir informe › %@",
        "Written": "Escritos",
        "No instruction — goes by its name alone": "Sin instrucción: se guía solo por el nombre",
        "Drag to reorder": "Arrastra para reordenar",
        "Every report is kept inside its meeting’s file.": "Cada informe se guarda dentro del archivo de su reunión.",
        "A refusal stops that meeting only; the rest continue.": "Un rechazo detiene solo esa reunión; las demás continúan.",
        "Always assume": "Dar por sentado",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Hechos que la llamada nunca dice pero que todo informe debe dar por sentados: quién eres, qué parte es el cliente, palabras que tu equipo usa de una forma particular. Se envía con cada informe de esta plantilla.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Opcional. Sin esto el modelo lee la llamada en frío, lo que suele valer para una reunión entre colegas y falla en una llamada con alguien de fuera.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Somos una agencia de ventas. El cliente es siempre la otra parte, nunca nosotros. «Puestos» significa licencias de usuario de pago.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Se muestra en la ficha de la reunión, en la biblioteca bajo Informes y como encabezado dentro del informe escrito.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Cada campo se convierte en un encabezado del informe, en este orden. Arrastra un campo por su asa para moverlo. La instrucción es opcional y puede ser tan larga como haga falta; un campo sin ella se guía solo por el nombre.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Cada campo se rellena solo con la transcripción de esta llamada. Uno que la llamada no tocó dice «Not discussed».",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Una plantilla es un nombre y unos cuantos campos. El informe se escribe a partir de ella cuando lo pides, uno por plantilla y reunión.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Aún no hay plantillas. Una plantilla es un nombre y unos cuantos campos; el informe se escribe a partir de ella cuando lo pides desde la ficha de una reunión, uno por plantilla y reunión.",
    ]

    static let pt: [String: String] = [
        "Settings": "Definições",
        "Keyboard shortcuts": "Atalhos de teclado",
        "Storage & models": "Armazenamento e modelos",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "As Chaves recusaram salvar a chave — ela continua no campo. Desbloqueie as chaves e tente de novo.",
        "Couldn't reach the update server. Try again once you're online.": "Não foi possível contatar o servidor de atualizações. Tente de novo quando estiver online.",
        "You're up to date — Dictate %@ is the newest version.": "Você está em dia — Dictate %@ é a versão mais recente.",
        "Recorded meetings appear here.": "As reuniões gravadas aparecem aqui.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Isto é só o seu microfone — o outro lado da chamada não foi gravado e não pode ser recuperado.",
        "Turning both on covers the calls that come next.": "Ao ativar ambos, as próximas chamadas ficam cobertas.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ recusou a solicitação por motivos de cobrança. Adicione crédito na conta do provedor ou desconecte o agente nos Ajustes.",
        "Agent": "Agente",
        "Ask your agent": "Perguntar ao agente",
        "Ask your agent anything…": "Pergunte qualquer coisa ao seu agente…",
        "Has read %d of %d meetings": "Leu %d de %d reuniões",
        "Has read 1 meeting": "Leu 1 reunião",
        "Has read all %d meetings": "Leu todas as %d reuniões",
        "Meetings & Agent…": "Reuniões e agente…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Agora não deixa o agente desativado e oculto. A busca e as transcrições não são afetadas.",
        "Nothing to read yet": "Ainda não há nada para ler",
        "Off — has read nothing yet": "Desativado — ainda não leu nada",
        "Reading %d of %d meetings…": "Lendo %d de %d reuniões…",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "É isto que escreve o resumo e a estrutura, e o que dá ao agente algo para responder. Desativado, fica a transcrição bruta — sem resumo, sem estrutura e sem agente. De qualquer forma, nada é enviado a lugar nenhum.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Seu agente responde a perguntas sobre tudo o que você gravou — «o que decidimos sobre a data de congelamento» — e cita a reunião e o momento de onde veio. Precisa do modelo que lê suas reuniões, que está desativado. De qualquer forma, nada sai deste Mac.",
        "Your agent has nothing to read yet": "Seu agente ainda não tem nada para ler",
        "Your agent has read 1 meeting": "Seu agente leu 1 reunião",
        "Your agent has read all %d meetings": "Seu agente leu todas as %d reuniões",
        "Your agent is off": "Seu agente está desativado",
        "Your agent is reading — %d of %d meetings so far": "Seu agente está lendo — %d de %d reuniões até agora",
        "answers with %@": "responde com %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Nada aqui pode ouvir uma chamada até que seja concedido em Ajustes do Sistema › Privacidade e Segurança › Microfone.",
        "There is no summary or outline — reading your meetings is off.": "Não há resumo nem estrutura — a leitura das reuniões está desativada.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Isto é só o seu microfone — falta o outro lado da chamada, o texto é um bloco contínuo e não há resumo nem estrutura.",
        "Turn both on": "Ativar ambos",
        "Turn it on": "Ativar",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Ao ativar, eles também são escritos para as próximas gravações. Escrever um agora deixa o interruptor desligado.",
        "Waiting on microphone access.": "Aguardando o acesso ao microfone.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Espera por «%@» acima — ainda não há áudio de chamada para separar.",
        "Write one, this once": "Escrever um, só desta vez",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "Escrever um agora lê só esta transcrição e deixa os interruptores desligados. O outro lado desta chamada não foi gravado e não pode ser recuperado.",
        "Writing…": "Escrevendo…",
        "macOS denied microphone access": "O macOS negou o acesso ao microfone",
        "%@ call — not being recorded": "Chamada no %@ — não está sendo gravada",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "A gravação de chamadas está desativada, então esta passa sem transcrição. Ao ativá-la, você ganha depois uma transcrição pesquisável e um resumo, guardados neste Mac.",
        "Call — not being recorded": "Chamada — não está sendo gravada",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "As chamadas não são percebidas automaticamente. Você pode iniciar cada uma aqui, ou deixar o Dictate oferecer quando uma chamada começar.",
        "Connect a provider…": "Conectar um provedor…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "O ditado continua funcionando. Cada interruptor abaixo diz o que acrescenta; você pode ativar um e deixar o resto em paz.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "O ditado já funciona — segure a tecla de ditado e fale em qualquer lugar. Tudo abaixo é sobre reuniões, e nada disso é obrigatório. Ative o que quiser; o resto fica desativado.",
        "Don't offer this again": "Não oferecer de novo",
        "Everything here is off, so calls pass unnoticed": "Tudo aqui está desativado, então as chamadas passam despercebidas",
        "Let the model read your meetings": "Deixar o modelo ler suas reuniões",
        "Not watching for calls": "Sem vigiar chamadas",
        "Notice when a call starts": "Perceber quando uma chamada começa",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Desativado, a gravação contém só o seu microfone — a sua metade da conversa, em um bloco contínuo. Ativado, os dois lados são transcritos como falas nomeadas.",
        "On": "Ativado",
        "Or leave this and set them up later in Settings.": "Ou deixe isto e configure depois nos Ajustes.",
        "Read meeting names from Calendar": "Ler nomes de reuniões do Calendário",
        "Record the call audio too": "Gravar também o áudio da chamada",
        "Record the call audio, and separate the voices": "Gravar o áudio da chamada e separar as vozes",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "As gravações chegam já com título, em vez de «Chamada no Zoom, 14:02». Só são lidos títulos que coincidem com uma gravação.",
        "Separate the voices": "Separar as vozes",
        "Set up calls…": "Configurar chamadas…",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "O agente busca e lê suas transcrições neste Mac; a resposta escrita vem de um provedor que você conecta com sua própria chave.",
        "Three things are off. Here is what each one adds.": "Três coisas estão desativadas. Eis o que cada uma acrescenta.",
        "Turn all on": "Ativar tudo",
        "Turn all three on": "Ativar as três",
        "Turn on": "Ativar",
        "Turn on reading": "Ativar a leitura",
        "Watching for calls": "Vigiando chamadas",
        "What it does": "O que faz",
        "With this on, a small panel appears when a call starts and you decide there — no need to remember to start anything.": "Com isto ativado, um pequeno painel aparece quando uma chamada começa e você decide ali — sem precisar lembrar de iniciar nada.",
        "listening": "escutando",
        "Back to the top": "Voltar ao topo",
        "Show everything tagged #%@": "Mostrar tudo com a tag #%@",
        "Remove #%@ from this meeting": "Remover #%@ desta reunião",
        "Tag": "Tag",
        "Create #%@": "Criar #%@",
        "Show Live Transcript": "Mostrar a transcrição em curso",
        "Hide": "Ocultar",
