        "Name": "Nome",
        "Save": "Salvar",
        "%d min": "%d min",
        "%d s": "%d s",
        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "A gravação do áudio do sistema não está permitida. Ative o Dictate em Ajustes do Sistema → Privacidade e Segurança → Gravação de Tela e Áudio do Sistema e tente novamente.",
        "Stop": "Parar",
        "Automatic (any language)": "Automático (qualquer idioma)",
        "detect while you speak": "detectado enquanto você fala",
        "Search language…": "Buscar idioma…",
        "Suggested": "Sugeridos",
        "No language matches your search.": "Nenhum idioma corresponde à busca.",
        "Translate key": "Tecla de tradução",
        "%@ is using the microphone right now — close it and try again": "%@ está usando o microfone agora — feche-o e tente novamente",
        "That was very quiet — move closer to the microphone": "Ficou muito baixo — aproxime-se do microfone",
        "That was too loud — move back a little from the microphone": "Ficou muito alto — afaste-se um pouco do microfone",
        "Sorry, I didn't catch that — could you say it again?": "Desculpe, não consegui ouvir — pode repetir?",
        "Not inserted — text copied, press ⌘V to paste": "Não inserido — texto copiado, pressione ⌘V para colar",
        "Another app is using the microphone right now — close it and try again": "Outro app está usando o microfone agora — feche-o e tente novamente",
        "General": "Geral",
        "Type a key…": "Pressione uma tecla…",
        "Hold to talk, release to insert what you said.": "Segure para falar, solte para inserir o que você disse.",
        "Downloaded %d of %d MB": "Baixados %d de %d MB",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Preparando o modelo para o Neural Engine… Alguns minutos, uma única vez.",
        "Warming up the model…": "Aquecendo o modelo…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "O Dictate está sendo executado a partir da imagem baixada — arraste-o para «Aplicativos», ejete a imagem e abra a partir de lá. As permissões concedidas a esta cópia temporária não serão mantidas.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Ainda travado? Redefina a permissão — isso apaga o registro quebrado do macOS; depois conceda-a na nova solicitação.",
        "Words: %d · %.1f s": "Palavras: %d · %.1f s",
        "Words: %d": "Palavras: %d",
        "Cancelled": "Cancelado",
        "Changed your mind? Esc cancels the recording.": "Mudou de ideia? Esc cancela a gravação.",
        "About Dictate": "Sobre o Dictate",
        // Onboarding — general
        "Welcome to Dictate": "Boas-vindas ao Dictate",
        "Back": "Voltar",
        "Next": "Avançar",
        "Step %d of %d": "Etapa %d de %d",
        // Welcome
        // Hotkey
        "Dictation key": "Tecla de ditado",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Essa tecla digita caracteres — enquanto você a segura, eles vão parar no seu texto. É mais seguro usar um modificador (Option, Cmd, Shift, Ctrl) ou uma tecla F.",
        // Permissions
        "Microphone": "Microfone",
        "Accessibility": "Acessibilidade",
        // Settings
        "Dictate Settings": "Ajustes do Dictate",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "A tecla digita caracteres — durante o ditado eles vão parar no texto. Melhor usar um modificador ou uma tecla F.",
        "Launch at login": "Abrir ao iniciar a sessão",
        "Show in Dock": "Mostrar na Dock",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "O agente pesquisa e lê as suas transcrições neste Mac, e cada resposta nomeia as reuniões em que se baseia.",
        "Undo remove": "Anular remoção",
        "Call started": "Começou uma chamada",
        "Recording stopped by itself — the call ended.": "A gravação parou sozinha — a chamada terminou.",
        "Recording stopped by itself — ten minutes of silence.": "A gravação parou sozinha — dez minutos de silêncio.",
        "%@ call started": "Começou uma chamada no %@",
        "Not this one": "Esta não",
        "Record": "Gravar",
        "Record this call": "Gravar esta chamada",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Ditado que funciona offline — o reconhecimento acontece inteiramente neste Mac.",
        "Translation that works offline — speak your language, another comes out.": "Tradução que funciona offline — fale a sua língua e sai outra.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Um agente opcional que conhece as suas reuniões — as respostas citam o momento de onde vieram.",
        "%d MB of %d MB": "%d MB de %d MB",
        "Already clicked and nothing changed?": "Clicou e nada mudou?",
        "Applications": "Aplicações",
        "Downloading the speech model": "A descarregar o modelo de voz",
        "Grant…": "Conceder…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Nada sai desta janela. Duas pequenas experiências e está pronto.",
        "Resume Download": "Retomar descarga",
        "Show me where to look": "Mostrar onde procurar",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Iniciar o Dictate ao iniciar sessão — aparece na Dock e na barra de menus; o ícone da Dock pode ser ocultado depois nas Definições",
        "Start Using Dictate": "Começar a usar o Dictate",
        "Stopped · %d MB of %d MB kept on disk": "Parada · %d MB de %d MB guardados no disco",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "A ligação foi interrompida. Ao retomar continua de onde parou — não vai descarregar os %d MB inteiros de novo.",
        "The download stopped at %d MB": "A descarga parou nos %d MB",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "O modelo é compilado para o seu chip para que o reconhecimento seja rápido depois. Demora um minuto no primeiro arranque e nunca mais acontece.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Isto acontece uma vez. O modelo fica no seu Mac e é a razão de o ditado funcionar depois sem ligação à internet.",
        "To hear you. Audio is processed on this Mac and discarded.": "Para o ouvir. O áudio é processado neste Mac e descartado.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Para escrever o texto reconhecido na app que está a usar. É a única forma de uma app inserir texto noutra.",
        "Try it here first": "Experimente aqui primeiro",
        "Two permissions from macOS": "Duas permissões do macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "É o macOS que as pede, não nós. O Dictate não funciona sem ambas.",
        "Show or hide the conversations": "Mostrar ou ocultar as conversas",
        "Show or hide the sidebar": "Mostrar ou ocultar a barra lateral",
        "Show or hide the meeting list": "Mostrar ou ocultar a lista de reuniões",
        "Preparing the model for this Mac": "A preparar o modelo para este Mac",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Ainda não está pronto — demora alguns segundos após o arranque. Mantenha %@ premida e vai começar.",
        "Transcript text": "Texto da transcrição",
        "Smaller text": "Texto mais pequeno",
        "Standard text": "Texto padrão",
        "Larger text": "Texto maior",
        "100 languages · from your system settings": "100 idiomas · das definições do sistema",
        "Add tag": "Adicionar etiqueta",
        "Appearance": "Aparência",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Perguntamos uma vez. Depois, a gravação começa na barra de menus sem avisos. Esc significa não gravar.",
        "Check for updates": "Procurar atualizações",
        "Choose your keys and languages": "Escolha as suas teclas e idiomas",
        "Click, then press a key": "Clique e prima uma tecla",
        "Dark": "Escuro",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "O Dictate vai gravar o seu microfone e o áudio da chamada, e guardar a transcrição neste Mac. Gravar outras pessoas pode exigir o consentimento delas onde você está.",
        "Don't Record": "Não gravar",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Mantenha a tecla premida enquanto fala. Tudo pode ser alterado depois nas Definições.",
        "I speak": "Eu falo",
        "Light": "Claro",
        "Looking through %d meetings…": "A percorrer %d reuniões…",
        "Match system": "Igual ao sistema",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "As teclas modificadoras funcionam melhor: nunca inserem um carácter ao serem mantidas. Esc cancela sempre um ditado em curso.",
        "Reading “%@”…": "A ler “%@”…",
        "Record this call?": "Gravar esta chamada?",
        "Searching your meetings…": "A pesquisar nas suas reuniões…",
        "Start Recording": "Começar a gravar",
        "Tags": "Etiquetas",
        "Voices": "Vozes",
        "Summary": "Resumo",
        "Outline": "Estrutura",
        "Hide outline": "Ocultar estrutura",
        "Show outline": "Mostrar estrutura",
        "two levels": "dois níveis",
        "%d moments": "%d momentos",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Guardado neste Mac. Apagar é imediato; após 50 conversas, as mais antigas saem.",
        "Ask across all meetings…": "Perguntar em todas as reuniões…",
        "Recently Added": "Adicionadas recentemente",
        "%d meetings · %d h of audio": "%d reuniões · %d h de áudio",
        "%d meetings · %d min of audio": "%d reuniões · %d min de áudio",
        "Show more": "Mostrar mais",
        "Try one of these": "Experimente uma destas",
        "Accessibility access is turned off": "O acesso de Acessibilidade está desligado",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "O ditado ouve você mas não consegue digitar. Reative para continuar.",
        "Recent dictations": "Ditados recentes",
        "Secure input is active — the hotkey cannot work": "A entrada segura está ativa — a tecla não pode funcionar",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "Algo está com um campo de senha em foco. O macOS não diz qual app. Clique num campo de texto comum e o ditado volta a funcionar.",
        "Start Recording Meeting": "Gravar uma reunião",
        "Stop Recording Meeting": "Parar a gravação da reunião",
        "dictate in %@": "ditar em %@",
        "dictate in any language": "ditar em qualquer idioma",
        "translate %@ → %@": "traduzir %@ → %@",
        "translate into %@": "traduzir para %@",
        "%d waiting": "%d aguardando",
        "%d words typed": "%d palavras digitadas",
        "Add a Key…": "Adicionar uma chave…",
        "Both will be inserted in the order you spoke them": "Ambas serão inseridas na ordem em que você as falou",
        "Check Audio Setup": "Verificar o áudio",
        "Clear All Filters": "Limpar todos os filtros",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "As teclas F também acionam um controle do sistema (brilho, mídia) — o macOS fará ambos. Para usá-la como tecla comum, ative «Use F1, F2, etc. as standard function keys» nos ajustes de teclado.",
        "How this works": "Como funciona",
        "Input device changed": "O dispositivo de entrada mudou",
        "Insert text by": "Inserir o texto",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Foi revogada ou substituída desde a conexão. Foi removida das Chaves — nada foi reenviado com ela.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Entre numa chamada no navegador e comece a gravar. O Dictate captura seu microfone e o áudio da chamada, transcreve ambos neste Mac e guarda a transcrição aqui. Nada é enviado.",
        "No meeting has all of these tags": "Nenhuma reunião tem todas essas tags",
        "No meeting has this tag": "Nenhuma reunião tem essa tag",
        "Nothing was said, or nothing was heard": "Nada foi dito, ou nada foi ouvido",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Aqui aparece só a cauda não confirmada — o resto já está no documento",
        "Open Console": "Abrir o console",
        "Open Settings": "Abrir Ajustes",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Colar é instantâneo mas substitui a área de transferência por um momento. Digitar funciona em apps que bloqueiam colar, como alguns terminais e desktops remotos.",
        "Pasting it at once": "Colando de uma vez",
        "Recording ended here — this Mac went to sleep.": "A gravação terminou aqui — este Mac dormiu.",
        "Remove “%@”": "Remover «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return envia · Shift-Return adiciona linha · Esc limpa",
        "Show Floating Timer": "Mostrar o cronômetro flutuante",
        "Start Recording a Meeting": "Gravar uma reunião",
        "Still recognizing the previous dictation": "Ainda reconhecendo o ditado anterior",
        "Still recognizing the previous dictation · %d words": "Ainda reconhecendo o ditado anterior · %d palavras",
        "Switched to %@": "Trocado para %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Filtros de tag combinam com «e» — a reunião precisa ter todas as tags escolhidas.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "A resposta parou. Sua pergunta fica acima — tente de novo quando a conexão voltar. Busca e transcrições continuam funcionando.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "A gravação rodou, mas nenhuma fala foi reconhecida de nenhum lado. Normalmente significa que o áudio da chamada nunca foi capturado — uma aba sem permissão de áudio ou o dispositivo de saída errado.",
        "The saved key no longer works": "A chave salva não funciona mais",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "O interruptor fica desligado até ser concedido em System Settings › Privacy & Security › Calendars. Só são lidos títulos de eventos que coincidem com uma gravação.",
        "This Mac is offline": "Este Mac está offline",
        "Too many questions at once": "Perguntas demais de uma vez",
        "Typing as you speak": "Digitando enquanto você fala",
        "Typing into %@ as you speak": "Digitando em %@ enquanto você fala",
        "Typing it out character by character": "Digitando letra por letra",
        "Your provider account is out of credit": "A conta do seu provedor está sem crédito",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Seu provedor está limitando a frequência. Aguarde alguns segundos e tente de novo — nada foi perdido.",
        "macOS denied calendar access": "O macOS negou o acesso ao calendário",
        "API key": "Chave de API",
        "All Meetings": "Todas as reuniões",
        "Assistant": "Assistente",
        "Checking the key with %@. No transcript is sent — only a test request.": "Verificando a chave com %@. Nenhuma transcrição é enviada — apenas uma solicitação de teste.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Fechar a janela não interrompe a gravação. Pare-a aqui ou pela barra de menus a qualquer momento.",
        "Connect an assistant to answer questions": "Conecte um assistente para responder perguntas",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "O Dictate pode gravar uma chamada do navegador e manter a transcrição neste Mac. Inicie pela barra de menus quando a próxima chamada começar — o consentimento será pedido uma vez.",
        "Done": "Concluído",
        "Every change takes effect immediately.": "Cada alteração entra em vigor imediatamente.",
        "Get one at %@.": "Obtenha uma em %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Segure uma tecla, fale, solte. O que você disse é digitado onde está o cursor, em qualquer app deste Mac.",
        "Keys": "Teclas",
        "Languages": "Idiomas",
        "Library": "Biblioteca",
        "Paste a key from your own account.": "Cole uma chave da sua própria conta.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Salva nas suas Chaves, mas não verificada — este Mac está offline. Será conferida na primeira pergunta.",
        "Set Up Dictate": "Configurar o Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Guardada nas Chaves do macOS neste Mac. Nunca escrita em arquivo de ajustes, nunca sincronizada.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "A chave foi recusada. Pode estar revogada, ser de outro provedor ou sem créditos — a chave não foi salva.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Transcrições, busca e citações funcionam sem isso. O assistente só é necessário para escrever a resposta.",
        "Try Again": "Tentar Novamente",
        "Updates": "Atualizações",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Você paga ao seu provedor por pergunta — normalmente uma fração de centavo. Apenas a pergunta e os trechos citados são enviados; as gravações nunca saem deste Mac.",
        "Send": "Enviar",
        "Conversations": "Conversas",
        "New question": "Nova pergunta",
        "Deleted “%@”": "Eliminado: “%@”",
        "Undo": "Desfazer",
        "Questions you ask are kept here so you can return to an answer.": "As perguntas ficam guardadas aqui para voltar a uma resposta.",
        "Rename": "Mudar o nome",
        "Delete": "Eliminar",
        "Voices are matched by sound — the name applies only to this voice's turns.": "As vozes são associadas pelo som — o nome aplica-se apenas às falas desta voz.",
        "Give two voices the same name to merge them.": "Dê o mesmo nome a duas vozes para as fundir.",
        "Voices are told apart by sound — one person can show up as two.": "As vozes são distinguidas pelo som — uma pessoa pode aparecer como duas.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "Clique num nome para renomear uma voz — o mesmo nome funde duas. Os resumos e as respostas baseiam-se no que foi dito, não em quem o disse.",
        "Voice separation improves over time.": "A separação de vozes melhora com o tempo.",
        "About voice separation": "Sobre a separação de vozes",
        "Call · voice %d": "Chamada · voz %d",
        "Starred": "Destacadas",
        "Other browser calls": "Outras chamadas do navegador",
        "Sources": "Fontes",
        "Star meeting": "Destacar reunião",
        "Unstar meeting": "Remover destaque",
        "Export transcript…": "Exportar transcrição…",
        "Still recording": "Continua a gravar",
        "Got it": "Entendi",
        "Call": "Chamada",
        "Dictating": "A ditar",
        "Dictating in %@": "A ditar em %@",
        "Translating into English": "A traduzir para inglês",
        "Translating into %@": "A traduzir para %@",
        "Release %@ to insert": "Solte %@ para inserir",
        "Also recording this meeting": "Também está a ser gravada esta reunião",
        "%@ MB/s · about %@ left": "%@ MB/s · faltam cerca de %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Espaço em disco insuficiente: a descarga precisa de cerca de %d MB e há %d MB livres. Liberte espaço e tente de novo.",
        "Fix…": "Corrigir…",
        "Checked automatically · last %@": "Verificação automática · última: %@",
        "Source code": "Código-fonte",
        "Report an issue": "Comunicar um problema",
        "Finishing the transcript…": "A terminar a transcrição…",
        "Disk almost full — will stop to keep the transcript": "Disco quase cheio — vai parar para manter a transcrição",
        "Dictate is running from its disk image": "O Dictate está a ser executado a partir da imagem de disco",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "As permissões concedidas a partir de uma imagem de disco perdem-se assim que esta é ejetada, e o modelo seria descarregado de novo de cada vez. Mova primeiro o Dictate para a pasta Aplicações.",
        "Move to Applications": "Mover para Aplicações",
