        "Not set": "Não definida",
        "Remove": "Remover",
        "Download & continue": "Baixar e continuar",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Cerca de %@ — baixado uma única vez. É o único momento em que o Dictate precisa de internet.",
        "Hold %@ and say something — the recognized text shows up below.": "Segure %@ e diga algo — o texto reconhecido aparece abaixo.",
        "Recognized text appears here…": "O texto reconhecido aparecerá aqui…",
