        "Audio device changed during recording — recording cancelled, please try again.": "O dispositivo de áudio mudou durante a gravação — a gravação foi cancelada, tente novamente.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "A permissão de Acessibilidade está desativada, então a tecla não é detectada. Ative em Ajustes do Sistema → Privacidade e Segurança → Acessibilidade — o Dictate detecta sozinho, sem precisar reiniciar.",
