        "Right Shift (⇧)": "Shift direita (⇧)",
        "Left Shift (⇧)": "Shift esquerda (⇧)",
        "Right Control (⌃)": "Control direita (⌃)",
        "Left Control (⌃)": "Control esquerda (⌃)",
        "Space": "Espaço",
        "Follow system": "Igual ao sistema",
        "Translating…": "Traduzindo…",
        "Tip: hold %@ instead — your speech comes out in English.": "Dica: segure %@ em vez da tecla normal — sua fala sai em inglês.",
        "Hold to talk in your language, release to insert it in English.": "Segure e fale no seu idioma; solte e o texto é inserido em inglês.",
        "Hold %@ and say it again — this time it's typed in English.": "Segure %@ e diga de novo — desta vez sai em inglês.",
        "Translate to": "Traduzir para",
        "Translation data isn't downloaded — open Settings to get it": "Os dados de tradução não foram baixados — baixe-os nos ajustes",
        "Translation data": "Dados de tradução",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "A tecla de tradução transcreve sua fala e depois o macOS a traduz neste Mac. Ao escolher um idioma, o macOS pode baixar seus dados de tradução uma vez.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "O reconhecimento roda no Neural Engine do seu Mac — Whisper large-v3-turbo: 100 idiomas, lida bem com sotaques e é rápido o bastante para o texto ao vivo. A tradução também acontece neste Mac. Sua voz nunca sai deste computador.",
        "Hold %@ and say it again — this time it comes out in %@.": "Segure %@ e diga de novo — desta vez sai em %@.",
        "Hold to talk in your language, release to insert it in %@.": "Segure e fale no seu idioma; solte e o texto é inserido em %@.",
        "Not downloaded": "Não baixados",
        "Translation languages": "Idiomas de tradução",
        "Downloaded": "Baixado",
        "Manage in System Settings…": "Gerenciar nos Ajustes do Sistema…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "Já está ativado nos Ajustes do Sistema mas aqui não fica verde? Desligue e ligue de novo o interruptor do Dictate — após uma atualização, o macOS às vezes mantém um registro obsoleto.",
        "Agent: %@, on your key.": "Agente: %@, na sua chave.",
        "Agent: off.": "Agente: desativado.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "A Apple Intelligence não está disponível neste Mac para esta região ou idioma. O agente com sua própria chave continua funcionando.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "A Apple Intelligence precisa do macOS 26. O agente com sua própria chave continua funcionando.",
        "Copy diagnostics": "Copiar diagnóstico",
        "Debug audio dumps": "Dumps de áudio de depuração",
        "Diagnostics": "Diagnóstico",
        "Downloading…": "Baixando…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Libera %@. As novas reuniões manterão a data como nome até você baixá-lo de novo. Os resumos já escritos permanecem.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Libera %@. Nada mais muda — a leitura das suas reuniões está desativada.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Libera %@. Títulos e resumos virão da Apple Intelligence.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Instalado mas sem rodar: este Mac tem %d GB de memória e ele precisa de 16.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Instalado mas sem rodar: este Mac tem %d GB de memória e ele precisa de 16. Nada neste Mac lê reuniões.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Instalado mas sem rodar: este Mac tem %d GB de memória e ele precisa de 16. Títulos e resumos vêm da Apple Intelligence em vez disso.",
        "Installed · %@": "Instalado · %@",
        "Installed, not in use · %@": "Instalado, sem uso · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Enquanto escreve, ocupa cerca de %@ de memória, o que este Mac vai sentir.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, versão e quais recursos estão ativados. Sem transcrições, sem chaves.",
        "Meeting archive": "Arquivo de reuniões",
        "Meeting model": "Modelo de reuniões",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Modelo de reuniões instalado. As novas reuniões recebem títulos e resumos neste Mac.",
        "Meeting reading: Apple Intelligence.": "Leitura de reuniões: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Leitura de reuniões: nada neste Mac consegue fazê-lo ainda.",
        "Meeting reading: the downloaded model (%@).": "Leitura de reuniões: o modelo baixado (%@).",
        "Not available on this Mac.": "Não disponível neste Mac.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "Não instalado. Um download único de %@ escreve títulos, resumos e um índice.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "Nada neste Mac consegue ler ainda: a Apple Intelligence não está disponível aqui. O agente com sua própria chave continua funcionando.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "Nada neste Mac consegue ler ainda: baixe o modelo de reuniões abaixo, ou adicione uma chave para o agente.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "Nada neste Mac consegue ler ainda: baixe o modelo de reuniões abaixo, ou ative a Apple Intelligence nos Ajustes do Sistema.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "Nada neste Mac consegue ler ainda: o macOS ainda está configurando a Apple Intelligence. O agente com sua própria chave continua funcionando.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "Nada neste Mac consegue ler ainda: ative a Apple Intelligence nos Ajustes do Sistema, ou adicione uma chave para o agente.",
        "Open System Settings": "Abrir Ajustes do Sistema",
        "Paused: not enough free memory right now. It resumes on its own.": "Pausado: não há memória livre suficiente agora. Retoma sozinho.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Preparando o modelo para o processador deste Mac… Alguns minutos, uma única vez.",
        "Raw call audio kept for debugging only.": "Áudio bruto das chamadas, guardado só para depuração.",
        "Reading is on, but nothing on this Mac can read yet.": "A leitura está ativada, mas nada neste Mac consegue ler ainda.",
        "Reads with Apple Intelligence.": "Lê com a Apple Intelligence.",
        "Reads with the downloaded model.": "Lê com o modelo baixado.",
        "Recognition runs on the Neural Engine.": "O reconhecimento roda no Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "O reconhecimento roda no processador deste Mac — Whisper large-v3-turbo: 100 idiomas, lida bem com sotaques. Mais lento do que em Apple Silicon, e a tradução também acontece neste Mac. Sua voz nunca sai deste computador.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "O reconhecimento roda no processador deste Mac — mais lento do que em Apple Silicon.",
        "Remove the debug audio dumps?": "Remover os dumps de áudio de depuração?",
