        "Storage": "Armazenamento",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Os resumos neste Mac vêm da Apple Intelligence. O modelo para download precisa de 16 GB de memória; este Mac tem %d.",
        "Summary paused: not enough free memory. It resumes on its own.": "Resumo pausado: não há memória livre suficiente. Retoma sozinho.",
        "Tell the voices on a call apart.": "Distinguir as vozes numa chamada.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "O modelo de reuniões precisa de 16 GB de memória; este Mac tem %d.",
        "These are recordings kept only for debugging. Nothing else is affected.": "São gravações guardadas só para depuração. Nada mais é afetado.",
        "This Mac": "Este Mac",
        "This build of Dictate does not include the meeting model.": "Esta compilação do Dictate não inclui o modelo de reuniões.",
        "Titles and summaries come from Apple Intelligence instead.": "Títulos e resumos vêm da Apple Intelligence em vez disso.",
