        "Waiting for the call to end.": "Aguardando o fim da chamada.",
        "Your transcripts, as Markdown files you own.": "Suas transcrições, como arquivos Markdown que são seus.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "O macOS ainda está configurando a Apple Intelligence — volte mais tarde, ou adicione uma chave para o agente.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. O relatório fica no arquivo da reunião de qualquer forma; isto cria uma cópia.",
