        "Risks and concerns": "Riscos e preocupações",
        "The main arguments and facts, with the numbers, names and dates that were said": "Os principais argumentos e fatos, com os números, nomes e datas que foram ditos",
        "The next meeting or checkpoint, if one was agreed": "A próxima reunião ou ponto de verificação, se foi combinado",
        "Waiting on": "Aguardando de",
        "We are the team on this call; the reader took part in it.": "Somos a equipe nesta chamada; o leitor participou dela.",
        "What could go wrong, who raised it, how serious it sounded": "O que pode dar errado, quem levantou e quão sério pareceu",
        "What each side is waiting for from the other": "O que cada lado espera do outro",
        "What was decided, by whom, and what it replaces": "O que foi decidido, por quem, e o que isso substitui",
        "What was raised and not settled, and who owns it": "O que foi levantado e não resolvido, e quem é responsável",
        "Who does what, by when — one line per task": "Quem faz o quê, até quando — uma linha por tarefa",
        "Why we met and what we set out to settle": "Por que nos reunimos e o que queríamos resolver",
        "%d more": "mais %d",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "O título mantém o idioma da reunião; o resumo e todos os relatórios são escritos neste. Os nomes dos campos de um relatório ficam exatamente como digitados.",
        "About “%@”:": "Sobre “%@”:",
        "Replace the report with a new “%@” one?": "Substituir o relatório por um novo “%@”?",
        "Replace report": "Substituir relatório",
        "Written · replaces it": "Escrito · será substituído",
        "Dictate updated to %@.": "O Dictate foi atualizado para %@.",
        "Dismiss": "Fechar",
        "New": "Novo",
        "New in this version": "Novo nesta versão",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Abra uma reunião, pressione Write report no cabeçalho e escolha um modelo. O relatório aparece no cartão e como PDF em Dictate Meetings › Reports.",
        "Reports from templates": "Relatórios a partir de modelos",
        "See what’s new": "Ver novidades",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Ajustes › Reuniões › Escrever resumos e relatórios em: o resumo e todos os relatórios vêm no idioma em que você lê, seja qual for o idioma da chamada.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Ajustes › Modelos: comece pelo Resumo da reunião ou Decisões e tarefas, ou nomeie seus próprios campos e diga ao modelo o que vai embaixo de cada um.",
        "Summaries in your language": "Resumos no seu idioma",
        "What’s new": "Novidades",
        "What’s new in Dictate %@": "Novidades do Dictate %@",
        "Your own templates": "Seus próprios modelos",
        "Install update %@ and relaunch": "Instalar a atualização %@ e reiniciar",
        "The update waits until the recording ends.": "A atualização espera a gravação terminar.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "A atualização %@ está a caminho: baixando. Instala-se sozinha no próximo momento tranquilo; a barra de menus oferece antes.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "A atualização %@ está pronta: instale pela barra de menus, ou ela se instala sozinha no próximo momento tranquilo.",
        "An update is already on its way — it installs itself at the next quiet moment.": "Já há uma atualização a caminho: ela se instala sozinha no próximo momento tranquilo.",
        "Downloading update %@…": "Baixando a atualização %@…",
        "Preparing update %@…": "Preparando a atualização %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "O Dictate foi atualizado para %@. As novidades estão na janela Reuniões.",
        "Apple Intelligence declined to summarize this meeting.": "A Apple Intelligence recusou-se a resumir esta reunião.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "A transcrição, a pesquisa e o agente não mudam. Um modelo descarregável, guardado neste Mac, não tem essa restrição.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Reuniões gravadas e estruturadas: oradores, resumo, esquema, pesquisa. O Dictate oferece gravar uma chamada — nunca grava sem a sua resposta.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "O modelo de reuniões precisa de 16 GB de memória; este Mac tem %d. Ele não está rodando, e os %@ que ocupa no disco podem ser liberados.",
        "Clipboard restored.": "Área de transferência restaurada.",
        "Your words were inserted untranslated.": "As suas palavras foram inseridas sem tradução.",
        "A small panel appears when a call starts, and you decide there.": "Um pequeno painel aparece quando uma chamada começa e você decide ali.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Escreve o resumo e a estrutura, e dá ao agente algo para responder. De qualquer forma, nada é enviado a lugar nenhum.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Desativado, você tem só o próprio microfone; ativado, o outro lado também é transcrito.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Transforma um bloco de texto em falas nomeadas. A separação é pelo som e pode ser imprecisa; os nomes podem ser mudados.",
        "Find in this transcript…": "Procurar nesta transcrição…",
        "%d of %d": "%d de %d",
        "No matches": "Sem correspondências",
        "Previous match": "Correspondência anterior",
        "Next match": "Correspondência seguinte",
        "Close find": "Fechar a procura",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "%@ está escolhido, mas ainda não há chave. O agente e os relatórios ficam desligados até que uma seja adicionada.",
        "%@ · required for dictation, cannot be removed.": "%@ · necessário para ditar, não pode ser removido.",
        "%@ — not written": "%@ — não escrito",
        "%d h": "%d h",
        "%d meetings have a %@ report. They stay if this template goes.": "%d reuniões têm um relatório «%@». Elas ficam se este modelo for removido.",
        "%d min ago": "há %d min",
        "%d written": "%d escritos",
        "%d written, %d not written": "%d escritos, %d não escritos",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 idiomas. Aplica-se a esta janela e à barra de menus de imediato. O idioma que você fala é definido em Ditado.",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Uma chave da sua própria conta %@. Guardada nas suas Chaves, nunca num arquivo de ajustes.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Uma pergunta envia a pergunta e os trechos que a busca encontrou. Um relatório envia a transcrição inteira daquela reunião — cerca de 12.000 palavras por hora de conversa. Ambos vão para %@ com a sua chave, e só quando você pede. As gravações nunca saem deste Mac.",
        "About": "Sobre",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "O Apple Intelligence não está disponível neste Mac, então não há alternativa.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "O Apple Intelligence precisa de um macOS mais recente do que o deste Mac, então não há alternativa.",
        "Applies to this window, the meetings window and the panels over your other apps.": "Aplica-se a esta janela, à janela de reuniões e aos painéis sobre os seus outros apps.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Perguntado uma vez. Daqui em diante o painel é a versão curta e fica até você responder. Você também pode começar a gravar pela barra de menus a qualquer momento da chamada.",
        "Calendar": "Calendário",
        "Collapse %@": "Recolher %@",
        "Copy": "Copiar",
        "Dictation": "Ditado",
        "Expand %@": "Expandir %@",
        "Export…": "Exportar…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "Também está em Ditados recentes, então a área de transferência volta a ser sua quando quiser.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Guardados dentro do arquivo desta reunião, por isso viajam com a transcrição. Exportar faz uma cópia onde você quiser.",
        "No report": "Sem relatório",
        "No report for this meeting yet.": "Ainda não há relatório para esta reunião.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "Nada se perde ao removê-lo: a transcrição, a busca e o agente não dependem dele.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Nada se define aqui. Cada linha acima informa o que este Mac pode fazer ou aponta para o painel responsável.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "Nada neste Mac consegue ler ainda: o Apple Intelligence precisa de um macOS mais recente. O agente com a sua própria chave continua funcionando.",
        "Nothing was kept from this take — earlier ones are still here.": "Nada ficou desta tentativa — as anteriores continuam aqui.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "Nada foi gravado, então nada ficou. As anteriores continuam aqui.",
        "Off — dictation cannot type": "Desligado — o ditado não consegue digitar",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Desligado: transcrições, resumos, esquemas e busca funcionam como antes. O agente responde perguntas sobre todas as suas reuniões e escreve relatórios a partir dos seus modelos; ele roda na nuvem com a sua própria chave de API.",
        "On this Mac": "Neste Mac",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Um único arquivo retomável. Fechar o Dictate pausa a transferência; ela continua de onde parou.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Uma transferência única de %@ e, depois, títulos, resumos e esquemas são feitos inteiramente neste Mac. Precisa de 16 GB de memória para rodar e ocupa cerca de %@ enquanto escreve.",
        "Open System Settings…": "Abrir Ajustes do Sistema…",
        "Or start from the menu bar later in the call.": "Ou comece pela barra de menus mais tarde na chamada.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "Em pausa agora: não há memória livre suficiente. Retoma sozinho, e as reuniões à espera de resumo mantêm as transcrições.",
        "Permissions": "Permissões",
        "Reads with Apple Intelligence until the download finishes.": "Lê com o Apple Intelligence até a transferência terminar.",
        "Reads with the downloaded model — paused until there is free memory.": "Lê com o modelo transferido — em pausa até haver memória livre.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Os modelos de relatório estão em Modelos; os relatórios escritos ficam na biblioteca, em Relatórios.",
        "Report · %@": "Relatório · %@",
        "Report · %@ +%d": "Relatório · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Os relatórios precisam do agente, que está desligado. Escolha Claude ou ChatGPT em Resumos e relatórios; os modelos ficam guardados até lá.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Roda inteiramente neste Mac. Sem ele, títulos e resumos vêm do Apple Intelligence.",
        "Startup": "Inicialização",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Guardada nas suas Chaves, nunca num arquivo de ajustes. O agente responde perguntas sobre todas as suas reuniões e escreve relatórios a partir dos seus modelos.",
        "Summaries": "Resumos",
        "Summaries & reports": "Resumos e relatórios",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "A transferência é a forma de ter resumos neste Mac sem o Apple Intelligence. A transcrição e a busca funcionam de qualquer maneira.",
        "This Mac was offline. Nothing was sent.": "Este Mac estava offline. Nada foi enviado.",
        "This take was not kept. Earlier ones are still here.": "Esta tentativa não ficou. As anteriores continuam aqui.",
        "Uses 41 MB of speaker models.": "Usa 41 MB de modelos de vozes.",
        "What’s new in %@": "Novidades da %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Se algo lê estas gravações — resumos, esquemas, relatórios e o agente — fica em Resumos e relatórios. Este painel trata apenas do que é gravado neste Mac.",
        "Write again": "Escrever de novo",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "Escrever relatório, acima, lista os seus %d modelos. Escrever um envia esta transcrição para %@ com a sua chave; o relatório fica dentro do arquivo desta reunião e viaja com a transcrição. Exportar faz uma cópia onde você quiser.",
        "Written %@": "Escrito em %@",
        "Written by %@": "Escrito por %@",
        "Written by %@ %@ at %@": "Escrito por %@ em %@ às %@",
        "Written in": "Escrito em",
        "Your agent, on your key": "O seu agente, com a sua chave",
        "click to insert": "clique para inserir",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "O macOS ainda está preparando o Apple Intelligence. Pode demorar um pouco e não dá para apressar daqui.",
        "macOS resets this switch after some updates and never asks a second time.": "O macOS redefine este interruptor após algumas atualizações e nunca pergunta uma segunda vez.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-clique para copiar em vez disso. Apagado quando o Dictate é encerrado.",
        "Meeting names": "Nomes das reuniões",
        "%d meetings, reports included": "%d reuniões, relatórios incluídos",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "Transfira o modelo de reuniões em Resumos e relatórios ou adicione uma chave para o agente.",
        "Calls": "Chamadas",
        "Reports folder": "Pasta de relatórios",
        "%d PDFs written before %@": "%d PDFs escritos antes da %@",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "O Dictate não escreve mais PDFs por conta própria. Eles são seus para guardar ou apagar; nada no app depende deles.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "O relatório já escrito é substituído. Envia esta transcrição para %@ com a sua chave.",
        "%@ · report not written": "%@ · relatório não escrito",
        "%d of %d selected · %d meetings without one": "%d de %d selecionadas · %d reuniões sem relatório",
        "%d passages from %d meetings": "%d trechos de %d reuniões",
        "%d written across %d templates": "%d escritos em %d modelos",
        "%d written · %d meetings without one · %d fields": "%d escritos · %d reuniões sem relatório · %d campos",
        "%d written · writing %d · %d not written": "%d escritos · escrevendo %d · %d não escritos",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Um relatório é escrito quando você pede — no cartão de uma reunião ou para uma seleção aqui. Cada um envia a transcrição daquela reunião para %@ com a sua chave e fica guardado dentro do arquivo da reunião.",
        "All reports": "Todos os relatórios",
        "Answer": "Resposta",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Respondido por %@ a partir de %d de %d reuniões. As citações são literais das transcrições neste Mac.",
        "Copy as Markdown": "Copiar como Markdown",
        "Copy as plain text": "Copiar como texto simples",
        "Copy the answer only": "Copiar só a resposta",
        "Copy with quotes": "Copiar com citações",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "Cada modelo guarda os seus relatórios: o que está escrito e as reuniões que poderiam ter um. Os modelos em si são editados em Ajustes › Modelos.",
        "Edit template…": "Editar modelo…",
        "No report yet · %d meetings": "Ainda sem relatório · %d reuniões",
        "None written · %d fields": "Nenhum escrito · %d campos",
        "Nothing written from this template yet": "Ainda nada escrito com este modelo",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Desligado: essas %d são ignoradas e %d relatórios são escritos. Substituir não pode ser desfeito.",
        "Pick a template": "Escolha um modelo",
        "Quotes": "Citações",
        "Replace the %d that already have one": "Substituir as %d que já têm um",
        "Report not written — the request was refused. The meeting has the detail.": "Relatório não escrito — o pedido foi recusado. O detalhe está na reunião.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Envia %d transcrições para %@ com a sua chave — cerca de %@ palavras. Cada relatório fica dentro do arquivo da sua reunião. As gravações nunca saem deste Mac.",
        "The %d existing reports are overwritten. This cannot be undone.": "Os %d relatórios existentes são sobrescritos. Isso não pode ser desfeito.",
        "Write": "Escrever",
        "Write %d": "Escrever %d",
        "Write %d reports…": "Escrever %d relatórios…",
        "Write a “%@” report for %d meetings?": "Escrever um relatório «%@» para %d reuniões?",
        "Write a “%@” report for “%@”?": "Escrever um relatório «%@» para «%@»?",
        "Write all %d…": "Escrever todos os %d…",
        "Write for a selection…": "Escrever para uma seleção…",
        "Write report › %@": "Escrever relatório › %@",
        "Written": "Escritos",
        "No instruction — goes by its name alone": "Sem instrução — vai só pelo nome",
        "Drag to reorder": "Arraste para reordenar",
        "Every report is kept inside its meeting’s file.": "Cada relatório fica dentro do arquivo da sua reunião.",
        "A refusal stops that meeting only; the rest continue.": "Uma recusa interrompe só aquela reunião; as outras continuam.",
        "Always assume": "Tomar como certo",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Fatos que a chamada nunca diz, mas que todo relatório deve tomar como certos: quem você é, qual lado é o cliente, palavras que a sua equipe usa de um jeito próprio. Enviado com cada relatório deste modelo.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Opcional. Sem isso o modelo lê a chamada do zero, o que costuma servir para uma reunião entre colegas e falha numa chamada com alguém de fora.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Somos uma agência de vendas. O cliente é sempre a outra parte, nunca nós. «Assentos» significa licenças de usuário pagas.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Aparece no cartão da reunião, na biblioteca em Relatórios e como título dentro do relatório escrito.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Cada campo vira um título no relatório, nesta ordem. Arraste um campo pela alça para movê-lo. A instrução é opcional e pode ser tão longa quanto precisar; um campo sem ela vai só pelo nome.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Cada campo é preenchido só com a transcrição desta chamada. Um que a chamada não abordou diz «Not discussed».",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Um modelo é um nome e alguns campos. O relatório é escrito a partir dele quando você pede, um por modelo e por reunião.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Ainda não há modelos. Um modelo é um nome e alguns campos; o relatório é escrito a partir dele quando você pede no cartão de uma reunião, um por modelo e por reunião.",
    ]

    static let fr: [String: String] = [
        "Settings": "Réglages",
        "Keyboard shortcuts": "Raccourcis clavier",
        "Storage & models": "Stockage et modèles",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Le trousseau a refusé d'enregistrer la clé — elle reste dans le champ. Déverrouillez le trousseau et réessayez.",
        "Couldn't reach the update server. Try again once you're online.": "Impossible de joindre le serveur de mise à jour. Réessayez une fois en ligne.",
        "You're up to date — Dictate %@ is the newest version.": "Vous êtes à jour — Dictate %@ est la version la plus récente.",
        "Recorded meetings appear here.": "Les réunions enregistrées apparaissent ici.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Ceci n'est que votre micro — l'autre partie de l'appel n'a pas été enregistrée et ne peut pas être récupérée.",
        "Turning both on covers the calls that come next.": "En activant les deux, les prochains appels seront couverts.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ a refusé la requête pour des raisons de facturation. Ajoutez du crédit chez votre fournisseur ou déconnectez l'agent dans Réglages.",
        "Agent": "Agent",
        "Ask your agent": "Demander à l'agent",
