        "Has read all %d meetings": "A lu les %d réunions",
        "Meetings & Agent…": "Réunions et agent…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Pas maintenant laisse l'agent désactivé et masqué. La recherche et les transcriptions ne sont pas affectées.",
        "Nothing to read yet": "Rien à lire pour l'instant",
        "Off — has read nothing yet": "Désactivé — n'a encore rien lu",
        "Reading %d of %d meetings…": "Lecture de %d réunions sur %d…",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "C'est ce qui écrit le résumé et le plan, et ce qui donne à votre agent de quoi répondre. Désactivé, il reste la transcription brute — ni résumé, ni plan, ni agent. Dans tous les cas, rien n'est envoyé nulle part.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Votre agent répond aux questions sur tout ce que vous avez enregistré — « qu'avons-nous décidé pour la date de gel » — et cite la réunion et le moment d'où vient la réponse. Il lui faut le modèle qui lit vos réunions, actuellement désactivé. Dans tous les cas, rien ne quitte ce Mac.",
        "Your agent has nothing to read yet": "Votre agent n'a encore rien à lire",
        "Your agent has read 1 meeting": "Votre agent a lu 1 réunion",
        "Your agent has read all %d meetings": "Votre agent a lu les %d réunions",
        "Your agent is off": "Votre agent est désactivé",
        "Your agent is reading — %d of %d meetings so far": "Votre agent lit — %d réunions sur %d pour l'instant",
        "answers with %@": "répond avec %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Rien ici ne peut entendre un appel tant que l'accès n'est pas accordé dans Réglages Système › Confidentialité et sécurité › Micro.",
        "There is no summary or outline — reading your meetings is off.": "Il n'y a ni résumé ni plan — la lecture de vos réunions est désactivée.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Ceci n'est que votre micro — l'autre partie de l'appel manque, le texte est un seul bloc, et il n'y a ni résumé ni plan.",
        "Turn both on": "Activer les deux",
