        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "En l'activant, ils seront aussi écrits pour les prochains enregistrements. En écrire un maintenant laisse l'interrupteur éteint.",
        "Waiting on microphone access.": "En attente de l'accès au micro.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Attend « %@ » ci-dessus — il n'y a pas encore d'audio d'appel à séparer.",
        "Write one, this once": "En écrire un, pour cette fois",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "En écrire un maintenant ne lit que cette transcription et laisse les interrupteurs éteints. L'autre partie de cet appel n'a pas été enregistrée et ne peut pas être récupérée.",
        "Writing…": "Écriture…",
