        "Call — not being recorded": "Appel — non enregistré",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Les appels ne sont pas détectés automatiquement. Vous pouvez lancer chacun ici, ou laisser Dictate le proposer quand un appel commence.",
        "Connect a provider…": "Connecter un fournisseur…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "La dictée fonctionne toujours. Chaque interrupteur ci-dessous dit ce qu'il ajoute ; vous pouvez en activer un et laisser les autres.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "La dictée fonctionne déjà — maintenez la touche de dictée et parlez n'importe où. Tout ce qui suit concerne les réunions, et rien n'est obligatoire. Activez ce que vous voulez ; le reste reste désactivé.",
