        "Preparing the model for the Neural Engine… A few minutes, one time.": "Préparation du modèle pour le Neural Engine… Quelques minutes, une seule fois.",
        "Warming up the model…": "Préchauffage du modèle…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate s’exécute depuis l’image téléchargée — glissez-le dans « Applications », éjectez l’image et lancez-le depuis ce dossier. Les autorisations accordées à cette copie temporaire ne seront pas conservées.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Toujours bloqué ? Réinitialisez l’autorisation — cela efface l’entrée macOS corrompue ; accordez-la ensuite dans la nouvelle demande.",
        "Words: %d · %.1f s": "Mots : %d · %.1f s",
        "Words: %d": "Mots : %d",
        "Cancelled": "Annulé",
        "Changed your mind? Esc cancels the recording.": "Vous changez d’avis ? Esc annule l’enregistrement.",
        "About Dictate": "À propos de Dictate",
        // Onboarding — general
        "Welcome to Dictate": "Bienvenue dans Dictate",
        "Back": "Retour",
        "Next": "Suivant",
        "Step %d of %d": "Étape %d sur %d",
        // Welcome
        // Hotkey
        "Dictation key": "Touche de dictée",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Cette touche saisit des caractères — tant que vous la maintenez, ils atterrissent dans votre texte. Mieux vaut un modificateur (Option, Cmd, Shift, Ctrl) ou une touche F.",
        // Permissions
        "Microphone": "Microphone",
        "Accessibility": "Accessibilité",
        // Settings
        "Dictate Settings": "Réglages de Dictate",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "Cette touche saisit des caractères — pendant la dictée, ils se retrouveront dans le texte. Préférez un modificateur ou une touche F.",
        "Launch at login": "Ouvrir à l’ouverture de session",
        "Show in Dock": "Afficher dans le Dock",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "L'agent cherche et lit vos transcriptions sur ce Mac, et chaque réponse nomme les réunions sur lesquelles elle s'appuie.",
        "Undo remove": "Annuler la suppression",
        "Call started": "Un appel a commencé",
        "Recording stopped by itself — the call ended.": "L'enregistrement s'est arrêté de lui-même — l'appel s'est terminé.",
        "Recording stopped by itself — ten minutes of silence.": "L'enregistrement s'est arrêté de lui-même — dix minutes de silence.",
        "%@ call started": "Un appel %@ a commencé",
        "Not this one": "Pas celui-ci",
        "Record": "Enregistrer",
        "Record this call": "Enregistrer cet appel",
        "Dictation that works offline — recognition runs entirely on this Mac.": "La dictée qui fonctionne hors ligne — la reconnaissance se fait entièrement sur ce Mac.",
        "Translation that works offline — speak your language, another comes out.": "La traduction qui fonctionne hors ligne — parlez votre langue, une autre en sort.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Un agent optionnel qui connaît vos réunions — les réponses citent le moment dont elles viennent.",
        "%d MB of %d MB": "%d Mo sur %d Mo",
        "Already clicked and nothing changed?": "Vous avez cliqué et rien n’a changé ?",
        "Applications": "Applications",
        "Downloading the speech model": "Téléchargement du modèle vocal",
        "Grant…": "Accorder…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Rien ne sort de cette fenêtre. Deux petites choses à essayer, et c’est terminé.",
        "Resume Download": "Reprendre le téléchargement",
        "Show me where to look": "Montrez-moi où regarder",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Lancer Dictate à l’ouverture de session — il apparaît dans le Dock et la barre des menus ; l’icône du Dock peut être masquée plus tard dans les Réglages",
        "Start Using Dictate": "Commencer à utiliser Dictate",
        "Stopped · %d MB of %d MB kept on disk": "Arrêté · %d Mo sur %d Mo conservés sur le disque",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "La connexion a été interrompue. La reprise continue là où elle s’est arrêtée — vous ne retéléchargerez pas les %d Mo entiers.",
        "The download stopped at %d MB": "Le téléchargement s’est arrêté à %d Mo",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Le modèle est compilé pour votre puce afin que la reconnaissance soit rapide ensuite. Cela prend une minute au premier lancement et ne se reproduit jamais.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Cela n’arrive qu’une fois. Le modèle reste sur votre Mac — c’est pourquoi la dictée fonctionne ensuite sans connexion internet.",
        "To hear you. Audio is processed on this Mac and discarded.": "Pour vous entendre. L’audio est traité sur ce Mac puis supprimé.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Pour taper le texte reconnu dans l’app que vous utilisez. C’est la seule façon pour une app d’insérer du texte ailleurs.",
        "Try it here first": "Essayez ici d’abord",
        "Two permissions from macOS": "Deux autorisations de macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "C’est macOS qui les demande, pas nous. Dictate ne peut pas fonctionner sans les deux.",
        "Show or hide the conversations": "Afficher ou masquer les conversations",
        "Show or hide the sidebar": "Afficher ou masquer la barre latérale",
        "Show or hide the meeting list": "Afficher ou masquer la liste des réunions",
        "Preparing the model for this Mac": "Préparation du modèle pour ce Mac",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Pas encore prêt — cela prend quelques secondes après le lancement. Maintenez %@ et cela démarrera.",
        "Transcript text": "Texte de la transcription",
        "Smaller text": "Texte plus petit",
        "Standard text": "Texte standard",
        "Larger text": "Texte plus grand",
        "100 languages · from your system settings": "100 langues · des réglages du système",
        "Add tag": "Ajouter un tag",
        "Appearance": "Apparence",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Demandé une seule fois. Ensuite, l'enregistrement démarre depuis la barre des menus sans confirmation. Échap signifie ne pas enregistrer.",
        "Check for updates": "Rechercher les mises à jour",
        "Choose your keys and languages": "Choisissez vos touches et vos langues",
        "Click, then press a key": "Cliquez, puis appuyez sur une touche",
        "Dark": "Sombre",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate enregistrera votre micro et l'audio de l'appel, et conservera la transcription sur ce Mac. Enregistrer d'autres personnes peut exiger leur consentement selon l'endroit où vous êtes.",
        "Don't Record": "Ne pas enregistrer",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Maintenez la touche pendant que vous parlez. Tout peut être modifié plus tard dans les Réglages.",
        "I speak": "Je parle",
        "Light": "Clair",
        "Looking through %d meetings…": "Parcours de %d réunions…",
        "Match system": "Comme le système",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Les touches de modification marchent le mieux : les maintenir n'insère jamais de caractère. Échap annule toujours une dictée en cours.",
        "Reading “%@”…": "Lecture de « %@ »…",
        "Record this call?": "Enregistrer cet appel ?",
        "Searching your meetings…": "Recherche dans vos réunions…",
        "Start Recording": "Démarrer l'enregistrement",
        "Tags": "Tags",
        "Voices": "Voix",
        "Summary": "Résumé",
        "Outline": "Plan",
        "Hide outline": "Masquer le plan",
        "Show outline": "Afficher le plan",
        "two levels": "deux niveaux",
        "%d moments": "%d moments",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Conservé sur ce Mac. La suppression est immédiate ; au-delà de 50 conversations, les plus anciennes disparaissent.",
        "Ask across all meetings…": "Demander dans toutes les réunions…",
        "Recently Added": "Ajoutées récemment",
        "%d meetings · %d h of audio": "%d réunions · %d h d'audio",
        "%d meetings · %d min of audio": "%d réunions · %d min d'audio",
        "Show more": "Afficher plus",
        "Try one of these": "Essayez l’une de celles-ci",
        "Accessibility access is turned off": "L’accès Accessibilité est désactivé",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "La dictée vous entend mais ne peut pas taper. Réactivez-le pour continuer.",
        "Recent dictations": "Dictées récentes",
        "Secure input is active — the hotkey cannot work": "La saisie sécurisée est active — la touche ne peut pas fonctionner",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "Une app a un champ de mot de passe actif. macOS ne dit pas laquelle. Cliquez dans un champ de texte ordinaire et la dictée refonctionne.",
        "Start Recording Meeting": "Enregistrer une réunion",
        "Stop Recording Meeting": "Arrêter l’enregistrement de la réunion",
        "dictate in %@": "dicter en %@",
        "dictate in any language": "dicter dans n’importe quelle langue",
        "translate %@ → %@": "traduire %@ → %@",
        "translate into %@": "traduire vers %@",
        "%d waiting": "%d en attente",
        "%d words typed": "%d mots tapés",
        "Add a Key…": "Ajouter une clé…",
        "Both will be inserted in the order you spoke them": "Les deux seront insérées dans l’ordre où vous les avez dites",
        "Check Audio Setup": "Vérifier l’audio",
        "Clear All Filters": "Effacer tous les filtres",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "Les touches F déclenchent aussi un contrôle système (luminosité, médias) — macOS fera les deux. Pour l’utiliser comme touche normale, activez « Use F1, F2, etc. as standard function keys » dans les réglages du clavier.",
        "How this works": "Comment ça marche",
        "Input device changed": "Le périphérique d’entrée a changé",
        "Insert text by": "Insérer le texte",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Elle a été révoquée ou remplacée depuis la connexion. Elle a été retirée du trousseau — rien n’a été renvoyé avec.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Rejoignez un appel dans le navigateur, puis lancez l’enregistrement. Dictate capture votre micro et l’audio de l’appel, transcrit les deux sur ce Mac et garde la transcription ici. Rien n’est envoyé.",
        "No meeting has all of these tags": "Aucune réunion ne porte toutes ces étiquettes",
        "No meeting has this tag": "Aucune réunion ne porte cette étiquette",
        "Nothing was said, or nothing was heard": "Rien n’a été dit, ou rien n’a été entendu",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Seule la fin non confirmée s’affiche ici — le reste est déjà dans le document",
        "Open Console": "Ouvrir la console",
        "Open Settings": "Ouvrir les Réglages",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Coller est instantané mais remplace le presse-papiers un instant. Taper fonctionne dans les apps qui bloquent le collage, comme certains terminaux et bureaux à distance.",
        "Pasting it at once": "En le collant d’un coup",
        "Recording ended here — this Mac went to sleep.": "L’enregistrement s’est arrêté ici — ce Mac s’est endormi.",
        "Remove “%@”": "Retirer « %@ »",
        "Return sends · Shift-Return adds a line · Esc clears": "Retour envoie · Maj-Retour ajoute une ligne · Échap efface",
        "Show Floating Timer": "Afficher le minuteur flottant",
        "Start Recording a Meeting": "Enregistrer une réunion",
        "Still recognizing the previous dictation": "Reconnaissance de la dictée précédente en cours",
        "Still recognizing the previous dictation · %d words": "Reconnaissance de la dictée précédente · %d mots",
        "Switched to %@": "Passé sur %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Les filtres d’étiquettes se combinent avec « et » — la réunion doit porter chaque étiquette choisie.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "La réponse s’est arrêtée. Votre question reste au-dessus — réessayez quand la connexion revient. La recherche et les transcriptions fonctionnent toujours.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "L’enregistrement a tourné, mais aucune parole n’a été reconnue d’aucun côté. En général l’audio de l’appel n’a jamais été capturé — un onglet sans autorisation audio ou le mauvais périphérique de sortie.",
        "The saved key no longer works": "La clé enregistrée ne fonctionne plus",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "L’interrupteur reste désactivé tant que l’accès n’est pas accordé dans System Settings › Privacy & Security › Calendars. Seuls les titres d’événements chevauchant un enregistrement sont lus.",
        "This Mac is offline": "Ce Mac est hors ligne",
        "Too many questions at once": "Trop de questions à la fois",
        "Typing as you speak": "Frappe pendant que vous parlez",
        "Typing into %@ as you speak": "Frappe dans %@ pendant que vous parlez",
        "Typing it out character by character": "En le tapant lettre par lettre",
        "Your provider account is out of credit": "Le compte de votre fournisseur n’a plus de crédit",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Votre fournisseur limite la fréquence. Attendez quelques secondes et réessayez — rien n’est perdu.",
        "macOS denied calendar access": "macOS a refusé l’accès au calendrier",
        "API key": "Clé API",
        "All Meetings": "Toutes les réunions",
        "Assistant": "Assistant",
        "Checking the key with %@. No transcript is sent — only a test request.": "Vérification de la clé auprès de %@. Aucune transcription n’est envoyée — seulement une requête de test.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Fermer la fenêtre n’arrête pas l’enregistrement. Arrêtez-le ici ou depuis la barre des menus à tout moment.",
        "Connect an assistant to answer questions": "Connectez un assistant pour répondre aux questions",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate peut enregistrer un appel dans le navigateur et garder la transcription sur ce Mac. Lancez-le depuis la barre des menus au prochain appel — le consentement sera demandé une fois.",
        "Done": "Terminé",
        "Every change takes effect immediately.": "Chaque changement prend effet immédiatement.",
        "Get one at %@.": "Obtenez-en une sur %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Maintenez une touche, parlez, relâchez. Ce que vous avez dit est tapé là où se trouve le curseur, dans n’importe quelle app de ce Mac.",
        "Keys": "Touches",
        "Languages": "Langues",
        "Library": "Bibliothèque",
        "Paste a key from your own account.": "Collez une clé de votre propre compte.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Enregistrée dans votre trousseau, mais non vérifiée — ce Mac est hors ligne. Elle sera vérifiée à votre première question.",
        "Set Up Dictate": "Configurer Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Stockée dans le trousseau macOS de ce Mac. Jamais écrite dans un fichier de réglages, jamais synchronisée.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "La clé a été refusée. Elle est peut-être révoquée, d’un autre fournisseur ou sans crédit — la clé n’a pas été enregistrée.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Les transcriptions, la recherche et les citations fonctionnent sans cela. L’assistant ne sert qu’à rédiger la réponse.",
        "Try Again": "Réessayer",
        "Updates": "Mises à jour",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Vous payez votre fournisseur par question — en général une fraction de centime. Seules votre question et les citations trouvées sont envoyées ; les enregistrements ne quittent jamais ce Mac.",
        "Send": "Envoyer",
        "Conversations": "Conversations",
        "New question": "Nouvelle question",
        "Deleted “%@”": "Supprimé : « %@ »",
        "Undo": "Annuler",
        "Questions you ask are kept here so you can return to an answer.": "Vos questions sont conservées ici pour revenir à une réponse.",
        "Rename": "Renommer",
        "Delete": "Supprimer",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Les voix sont associées au son — le nom ne s'applique qu'aux répliques de cette voix.",
        "Give two voices the same name to merge them.": "Donnez le même nom à deux voix pour les fusionner.",
        "Voices are told apart by sound — one person can show up as two.": "Les voix sont distinguées au son — une même personne peut apparaître comme deux.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "Cliquez sur un nom pour renommer une voix — le même nom en fusionne deux. Les résumés et les réponses s'appuient sur ce qui a été dit, pas sur qui l'a dit.",
        "Voice separation improves over time.": "La séparation des voix s'améliore avec le temps.",
        "About voice separation": "À propos de la séparation des voix",
        "Call · voice %d": "Appel · voix %d",
        "Starred": "Favoris",
        "Other browser calls": "Autres appels du navigateur",
        "Sources": "Sources",
        "Star meeting": "Ajouter aux favoris",
        "Unstar meeting": "Retirer des favoris",
        "Export transcript…": "Exporter la transcription…",
        "Still recording": "Enregistrement en cours",
        "Got it": "Compris",
        "Call": "Appel",
        "Dictating": "Dictée",
        "Dictating in %@": "Dictée en %@",
        "Translating into English": "Traduction vers l’anglais",
        "Translating into %@": "Traduction vers %@",
        "Release %@ to insert": "Relâchez %@ pour insérer",
        "Also recording this meeting": "Cette réunion est aussi en cours d’enregistrement",
        "%@ MB/s · about %@ left": "%@ Mo/s · environ %@ restantes",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Espace disque insuffisant : le téléchargement nécessite environ %d Mo et %d Mo sont libres. Libérez de l’espace et réessayez.",
        "Fix…": "Corriger…",
        "Checked automatically · last %@": "Vérification automatique · dernière : %@",
        "Source code": "Code source",
        "Report an issue": "Signaler un problème",
        "Finishing the transcript…": "Finalisation de la transcription…",
        "Disk almost full — will stop to keep the transcript": "Disque presque plein — arrêt prévu pour garder la transcription",
        "Dictate is running from its disk image": "Dictate s’exécute depuis son image disque",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Les autorisations accordées depuis une image disque sont perdues dès son éjection, et le modèle serait retéléchargé à chaque fois. Déplacez d’abord Dictate dans le dossier Applications.",
        "Move to Applications": "Déplacer vers Applications",
        "Quit": "Quitter",
        "Couldn't move Dictate automatically": "Impossible de déplacer Dictate automatiquement",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Faites glisser Dictate de l’image disque vers le dossier Applications, puis lancez-le depuis là.",
        "OK": "OK",
        "Inserted into %@": "Inséré dans %@",
        "Inserted": "Inséré",
        "Accessibility is off — dictation can hear you but cannot type": "L’accessibilité est désactivée — la dictée vous entend mais ne peut pas écrire",
        "Open Privacy & Security…": "Ouvrir Confidentialité et sécurité…",
        "1 dictation still being recognized": "1 dictée encore en cours de reconnaissance",
        "%d dictations still being recognized": "%d dictées encore en cours de reconnaissance",
        "Language Packs…": "Packs de langue…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Si désactivé, Dictate ne vit que dans la barre des menus. Cliquer sur l’icône du Dock ouvre Réunions ; l’icône de la barre des menus reste toujours là.",
        "Interface language": "Langue de l’interface",
        "Granted": "Accordée",
        "No": "Non",
        "Model ready": "Modèle prêt",
        "On-device recognition": "Reconnaissance sur l’appareil",
        "Spoken language": "Langue parlée",
        "Download failed. Check your connection and retry.": "Échec du téléchargement. Vérifiez votre connexion et réessayez.",
        "Not set": "Non définie",
        "Remove": "Supprimer",
        "Download & continue": "Télécharger et continuer",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Environ %@ — téléchargé une seule fois. C’est le seul moment où Dictate a besoin d’Internet.",
        "Hold %@ and say something — the recognized text shows up below.": "Maintenez %@ et dites quelque chose — le texte reconnu s’affiche ci-dessous.",
        "Recognized text appears here…": "Le texte reconnu s’affichera ici…",
        // Menu bar
        "Settings…": "Réglages…",
        "Quit Dictate": "Quitter Dictate",
        "Dictate — voice dictation": "Dictate — dictée vocale",
        // HUD
        "Recognizing…": "Reconnaissance…",
        "Esc to cancel": "Échap pour annuler",
        // Errors
        "Couldn't start recording: %@": "Impossible de démarrer l’enregistrement : %@",
        "Recording truncated at %d seconds (limit)": "Enregistrement tronqué à %d secondes (limite)",
        "Audio device changed during recording — recording cancelled, please try again.": "Le périphérique audio a changé pendant l’enregistrement — enregistrement annulé, veuillez réessayer.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "L’autorisation Accessibilité est désactivée, la touche ne peut donc pas être détectée. Activez-la dans Réglages Système → Confidentialité et sécurité → Accessibilité — Dictate la prend en compte automatiquement, sans redémarrage.",
        "Microphone unavailable (no input audio format)": "Micro indisponible (aucun format audio d’entrée)",
        // Key names
        "Right Option (⌥)": "Option droite (⌥)",
        "Left Option (⌥)": "Option gauche (⌥)",
        "Right Command (⌘)": "Command droite (⌘)",
        "Left Command (⌘)": "Command gauche (⌘)",
        "Right Shift (⇧)": "Shift droite (⇧)",
        "Left Shift (⇧)": "Shift gauche (⇧)",
        "Right Control (⌃)": "Control droite (⌃)",
        "Left Control (⌃)": "Control gauche (⌃)",
        "Space": "Espace",
        "Follow system": "Comme le système",
        "Translating…": "Traduction…",
        "Tip: hold %@ instead — your speech comes out in English.": "Astuce : maintenez %@ à la place — votre voix ressort en anglais.",
        "Hold to talk in your language, release to insert it in English.": "Maintenez et parlez dans votre langue ; relâchez, le texte s’insère en anglais.",
        "Hold %@ and say it again — this time it's typed in English.": "Maintenez %@ et redites-le — cette fois, il s’écrit en anglais.",
        "Translate to": "Traduire vers",
        "Translation data isn't downloaded — open Settings to get it": "Les données de traduction ne sont pas téléchargées — téléchargez-les dans les réglages",
        "Translation data": "Données de traduction",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "La touche de traduction transcrit votre parole, puis macOS la traduit sur ce Mac. Au choix d’une langue, macOS peut télécharger une fois ses données de traduction.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "La reconnaissance s’exécute sur le Neural Engine de votre Mac — Whisper large-v3-turbo : 100 langues, à l’aise avec les accents et assez rapide pour le texte en direct. La traduction se fait aussi sur ce Mac. Votre voix ne quitte jamais cet ordinateur.",
        "Hold %@ and say it again — this time it comes out in %@.": "Maintenez %@ et redites-le — cette fois, cela sort en %@.",
        "Hold to talk in your language, release to insert it in %@.": "Maintenez et parlez dans votre langue ; relâchez, le texte s’insère en %@.",
        "Not downloaded": "Non téléchargées",
        "Translation languages": "Langues de traduction",
        "Downloaded": "Téléchargée",
        "Manage in System Settings…": "Gérer dans Réglages Système…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "Déjà activé dans Réglages Système mais toujours pas vert ici ? Désactivez puis réactivez l’interrupteur de Dictate — après une mise à jour, macOS garde parfois une entrée obsolète.",
        "Agent: %@, on your key.": "Agent : %@, avec votre clé.",
        "Agent: off.": "Agent : désactivé.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "Apple Intelligence n'est pas disponible sur ce Mac dans cette région ou cette langue. L'agent avec votre propre clé fonctionne toujours.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence nécessite macOS 26. L'agent avec votre propre clé fonctionne toujours.",
        "Copy diagnostics": "Copier le diagnostic",
        "Debug audio dumps": "Dumps audio de débogage",
        "Diagnostics": "Diagnostic",
        "Downloading…": "Téléchargement…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Libère %@. Les nouvelles réunions garderont leur date comme nom jusqu'à ce que vous le retéléchargiez. Les résumés déjà écrits restent.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Libère %@. Rien d'autre ne change — la lecture de vos réunions est désactivée.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Libère %@. Les titres et les résumés viendront d'Apple Intelligence.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Installé mais inactif : ce Mac a %d Go de mémoire et il en faut 16.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Installé mais inactif : ce Mac a %d Go de mémoire et il en faut 16. Rien sur ce Mac ne lit les réunions.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Installé mais inactif : ce Mac a %d Go de mémoire et il en faut 16. À la place, les titres et les résumés viennent d'Apple Intelligence.",
        "Installed · %@": "Installé · %@",
        "Installed, not in use · %@": "Installé, inutilisé · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Pendant qu'il écrit, il occupe environ %@ de mémoire, ce que ce Mac ressentira.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, version et fonctions activées. Ni transcriptions, ni clés.",
        "Meeting archive": "Archive des réunions",
        "Meeting model": "Modèle de réunion",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Modèle de réunion installé. Les nouvelles réunions reçoivent titres et résumés sur ce Mac.",
        "Meeting reading: Apple Intelligence.": "Lecture des réunions : Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Lecture des réunions : rien sur ce Mac ne peut encore le faire.",
        "Meeting reading: the downloaded model (%@).": "Lecture des réunions : le modèle téléchargé (%@).",
        "Not available on this Mac.": "Non disponible sur ce Mac.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "Non installé. Un téléchargement unique de %@ écrit titres, résumés et sommaire.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "Rien sur ce Mac ne peut encore lire : Apple Intelligence n'est pas disponible ici. L'agent avec votre propre clé fonctionne toujours.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "Rien sur ce Mac ne peut encore lire : téléchargez le modèle de réunion ci-dessous, ou ajoutez une clé pour l'agent.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "Rien sur ce Mac ne peut encore lire : téléchargez le modèle de réunion ci-dessous, ou activez Apple Intelligence dans Réglages Système.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "Rien sur ce Mac ne peut encore lire : macOS configure encore Apple Intelligence. L'agent avec votre propre clé fonctionne toujours.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "Rien sur ce Mac ne peut encore lire : activez Apple Intelligence dans Réglages Système, ou ajoutez une clé pour l'agent.",
        "Open System Settings": "Ouvrir Réglages Système",
        "Paused: not enough free memory right now. It resumes on its own.": "En pause : pas assez de mémoire libre pour le moment. Il reprendra de lui-même.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Préparation du modèle pour le processeur de ce Mac… Quelques minutes, une seule fois.",
        "Raw call audio kept for debugging only.": "Audio brut des appels, conservé uniquement pour le débogage.",
        "Reading is on, but nothing on this Mac can read yet.": "La lecture est activée, mais rien sur ce Mac ne peut encore lire.",
        "Reads with Apple Intelligence.": "Lit avec Apple Intelligence.",
        "Reads with the downloaded model.": "Lit avec le modèle téléchargé.",
        "Recognition runs on the Neural Engine.": "La reconnaissance s'exécute sur le Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "La reconnaissance s'exécute sur le processeur de ce Mac — Whisper large-v3-turbo : 100 langues, à l'aise avec les accents. Plus lent que sur Apple Silicon, et la traduction se fait aussi sur ce Mac. Votre voix ne quitte jamais cet ordinateur.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "La reconnaissance s'exécute sur le processeur de ce Mac — plus lent que sur Apple Silicon.",
        "Remove the debug audio dumps?": "Supprimer les dumps audio de débogage ?",
        "Remove the meeting model?": "Supprimer le modèle de réunion ?",
