        "Storage": "Stockage",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Sur ce Mac, les résumés viennent d'Apple Intelligence. Le modèle téléchargeable nécessite 16 Go de mémoire ; ce Mac en a %d.",
        "Summary paused: not enough free memory. It resumes on its own.": "Résumé en pause : pas assez de mémoire libre. Il reprendra de lui-même.",
        "Tell the voices on a call apart.": "Distinguer les voix d'un appel.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "Le modèle de réunion nécessite 16 Go de mémoire ; ce Mac en a %d.",
        "These are recordings kept only for debugging. Nothing else is affected.": "Ce sont des enregistrements conservés uniquement pour le débogage. Rien d'autre n'est affecté.",
        "This Mac": "Ce Mac",
        "This build of Dictate does not include the meeting model.": "Cette version de Dictate n'inclut pas le modèle de réunion.",
        "Titles and summaries come from Apple Intelligence instead.": "À la place, les titres et les résumés viennent d'Apple Intelligence.",
