        "Waiting for the call to end.": "En attente de la fin de l'appel.",
        "Your transcripts, as Markdown files you own.": "Vos transcriptions, en fichiers Markdown qui vous appartiennent.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS configure encore Apple Intelligence — revenez plus tard, ou ajoutez une clé pour l'agent.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. Le rapport reste de toute façon dans le fichier de la réunion ; ceci en fait une copie.",
