        "One empty field. You name it.": "Un champ vide. À vous de le nommer.",
        "One file per meeting, named by date and title, in a folder you choose. Transcripts are not included.": "Un fichier par réunion, nommé par date et titre, dans un dossier de votre choix. Les transcriptions ne sont pas incluses.",
