        "Reports": "Rapports",
        "Reports already written with it stay in their meetings.": "Les rapports déjà écrits avec lui restent dans leurs réunions.",
        "Same as Dictate": "Comme Dictate",
        "Template name": "Nom du modèle",
        "Templates": "Modèles",
        "The model returned no report.": "Le modèle n'a renvoyé aucun rapport.",
        "The model stopped before the report was finished.": "Le modèle s'est arrêté avant la fin du rapport.",
        "The saved key no longer works. It has been removed from the Keychain.": "La clé enregistrée ne fonctionne plus. Elle a été retirée du trousseau.",
        "What is sent": "Ce qui est envoyé",
        "Writing · about a minute": "Écriture · environ une minute",
        "Written by Dictate on this Mac from the transcript": "Écrit par Dictate sur ce Mac à partir de la transcription",
        "Your %@ account refused the request for billing reasons.": "Votre compte %@ a refusé la requête pour des raisons de facturation.",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "Envoie cette transcription à %@ avec votre clé. Le rapport est enregistré dans le fichier de la réunion.",
        "Set up templates…": "Configurer les modèles…",
        "Write report": "Rédiger le rapport",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@ limite le débit des requêtes. Rien n’est perdu : réessayez dans une minute.",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "Ce Mac est hors ligne. Rien n’a été envoyé : réessayez quand la connexion sera revenue.",
        "Write a “%@” report?": "Rédiger un rapport « %@ » ?",
        "Action items": "Actions",
        "Dates and deadlines": "Dates et échéances",
        "Decisions": "Décisions",
        "Decisions & actions": "Décisions et actions",
        "Every date, deadline or time window that was mentioned, and what it is for": "Chaque date, échéance ou créneau mentionné, et à quoi il correspond",
        "Key points": "Points clés",
        "Meeting summary": "Compte rendu de réunion",
        "Next step": "Prochaine étape",
        "Open questions": "Questions ouvertes",
        "Purpose": "Objectif",
        "Risks and concerns": "Risques et réserves",
        "The main arguments and facts, with the numbers, names and dates that were said": "Les principaux arguments et faits, avec les chiffres, noms et dates qui ont été dits",
        "The next meeting or checkpoint, if one was agreed": "La prochaine réunion ou le prochain point d’étape, s’il a été convenu",
        "Waiting on": "En attente de",
        "We are the team on this call; the reader took part in it.": "Nous sommes l’équipe de cet appel ; le lecteur y a participé.",
        "What could go wrong, who raised it, how serious it sounded": "Ce qui pourrait mal tourner, qui l’a soulevé et à quel point cela semblait sérieux",
        "What each side is waiting for from the other": "Ce que chaque partie attend de l’autre",
        "What was decided, by whom, and what it replaces": "Ce qui a été décidé, par qui, et ce que cela remplace",
        "What was raised and not settled, and who owns it": "Ce qui a été soulevé sans être tranché, et qui s’en charge",
        "Who does what, by when — one line per task": "Qui fait quoi, pour quand — une ligne par tâche",
        "Why we met and what we set out to settle": "Pourquoi nous nous sommes réunis et ce que nous voulions trancher",
        "%d more": "%d de plus",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "Le titre garde la langue de la réunion ; le résumé et chaque rapport sont rédigés dans celle-ci. Les noms des champs d’un rapport restent exactement tels que saisis.",
        "About “%@”:": "À propos de « %@ » :",
        "Replace the report with a new “%@” one?": "Remplacer le rapport par un nouveau « %@ » ?",
        "Replace report": "Remplacer le rapport",
        "Written · replaces it": "Rédigé · sera remplacé",
        "Dictate updated to %@.": "Dictate est passé à la version %@.",
        "Dismiss": "Fermer",
        "New": "Nouveau",
        "New in this version": "Nouveau dans cette version",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Ouvrez une réunion, cliquez sur Write report dans son en-tête, puis choisissez un modèle. Le rapport apparaît sur la fiche et en PDF dans Dictate Meetings › Reports.",
        "Reports from templates": "Des rapports à partir de modèles",
        "See what’s new": "Voir les nouveautés",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Réglages › Réunions › Rédiger les résumés et rapports en : le résumé et chaque rapport arrivent dans la langue que vous lisez, quelle que soit celle de l’appel.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Réglages › Modèles : partez du Compte rendu de réunion ou de Décisions et actions, ou nommez vos propres champs et dites au modèle ce qui va sous chacun.",
        "Summaries in your language": "Des résumés dans votre langue",
        "What’s new": "Nouveautés",
        "What’s new in Dictate %@": "Nouveautés de Dictate %@",
        "Your own templates": "Vos propres modèles",
        "Install update %@ and relaunch": "Installer la mise à jour %@ et relancer",
        "The update waits until the recording ends.": "La mise à jour attend la fin de l’enregistrement.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "La mise à jour %@ arrive : téléchargement en cours. Elle s’installera d’elle-même au prochain moment calme ; la barre des menus la propose plus tôt.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "La mise à jour %@ est prête : installez-la depuis la barre des menus, ou elle s’installera d’elle-même au prochain moment calme.",
        "An update is already on its way — it installs itself at the next quiet moment.": "Une mise à jour est déjà en route : elle s’installera d’elle-même au prochain moment calme.",
        "Downloading update %@…": "Téléchargement de la mise à jour %@…",
        "Preparing update %@…": "Préparation de la mise à jour %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate est passé à la version %@. Les nouveautés sont dans la fenêtre Réunions.",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence a refusé de résumer cette réunion.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "La transcription, la recherche et l’agent ne changent pas. Un modèle téléchargeable, conservé sur ce Mac, n’a pas cette restriction.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Des réunions enregistrées et structurées : intervenants, résumé, plan, recherche. Dictate propose d’enregistrer un appel — jamais sans votre réponse.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "Le modèle de réunion nécessite 16 Go de mémoire ; ce Mac en a %d. Il est inactif, et les %@ qu’il occupe sur le disque peuvent être libérés.",
        "Clipboard restored.": "Presse-papiers restauré.",
        "Your words were inserted untranslated.": "Vos mots ont été insérés sans traduction.",
        "A small panel appears when a call starts, and you decide there.": "Un petit panneau apparaît quand un appel commence et vous décidez là.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Écrit le résumé et le plan, et donne à votre agent de quoi répondre. Dans tous les cas, rien n’est envoyé nulle part.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Désactivé, vous n’avez que votre micro ; activé, l’autre côté est aussi transcrit.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Transforme un bloc de texte en répliques nommées. La séparation se fait au son et peut être imprécise ; les noms peuvent être changés.",
        "Find in this transcript…": "Rechercher dans cette transcription…",
        "%d of %d": "%d sur %d",
        "No matches": "Aucune correspondance",
        "Previous match": "Correspondance précédente",
        "Next match": "Correspondance suivante",
        "Close find": "Fermer la recherche",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "%@ est choisi, mais il n’y a pas encore de clé. L’agent et les rapports restent désactivés tant qu’une clé n’est pas ajoutée.",
        "%@ · required for dictation, cannot be removed.": "%@ · nécessaire à la dictée, ne peut pas être supprimé.",
        "%@ — not written": "%@ — non rédigé",
        "%d h": "%d h",
        "%d meetings have a %@ report. They stay if this template goes.": "%d réunions ont un rapport « %@ ». Ils restent si ce modèle disparaît.",
        "%d min ago": "il y a %d min",
        "%d written": "%d rédigés",
        "%d written, %d not written": "%d rédigés, %d non rédigés",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 langues. S’applique tout de suite à cette fenêtre et à la barre des menus. La langue que vous parlez se règle dans Dictée.",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Une clé de votre propre compte %@. Conservée dans votre trousseau, jamais dans un fichier de réglages.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Une question envoie la question et les passages trouvés par la recherche. Un rapport envoie toute la transcription de la réunion — environ 12 000 mots pour une heure d’échange. Les deux partent vers %@ avec votre clé, et seulement à votre demande. Les enregistrements ne quittent jamais ce Mac.",
        "About": "À propos",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "Apple Intelligence n’est pas disponible sur ce Mac, il n’y a donc pas de solution de repli.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence demande un macOS plus récent que celui de ce Mac, il n’y a donc pas de solution de repli.",
        "Applies to this window, the meetings window and the panels over your other apps.": "S’applique à cette fenêtre, à la fenêtre des réunions et aux panneaux au-dessus de vos autres apps.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Demandé une seule fois. Ensuite, le panneau est la version courte et reste jusqu’à votre réponse. Vous pouvez aussi lancer l’enregistrement depuis la barre des menus à tout moment de l’appel.",
        "Calendar": "Calendrier",
        "Collapse %@": "Replier %@",
        "Copy": "Copier",
        "Dictation": "Dictée",
        "Expand %@": "Déplier %@",
        "Export…": "Exporter…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "Il est aussi dans les Dictées récentes : le presse-papiers redevient vôtre quand vous voulez.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Conservés dans le fichier de cette réunion, ils voyagent avec la transcription. Exporter en fait une copie où vous voulez.",
        "No report": "Aucun rapport",
        "No report for this meeting yet.": "Pas encore de rapport pour cette réunion.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "Rien n’est perdu en le supprimant : la transcription, la recherche et l’agent n’en dépendent pas.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Rien ne se règle ici. Chaque ligne ci-dessus indique ce que ce Mac sait faire ou renvoie au panneau qui en a la charge.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "Rien sur ce Mac ne peut encore lire : Apple Intelligence demande un macOS plus récent. L’agent avec votre propre clé fonctionne quand même.",
        "Nothing was kept from this take — earlier ones are still here.": "Rien n’a été gardé de cette prise — les précédentes sont toujours là.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "Rien n’a été enregistré, donc rien n’a été gardé. Les précédentes sont toujours là.",
        "Off — dictation cannot type": "Désactivé — la dictée ne peut pas écrire",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Désactivé : transcriptions, résumés, plans et recherche fonctionnent comme avant. L’agent répond aux questions sur l’ensemble de vos réunions et rédige des rapports d’après vos modèles ; il tourne dans le cloud avec votre propre clé API.",
        "On this Mac": "Sur ce Mac",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Un seul fichier reprenable. Quitter Dictate le met en pause ; il reprend là où il s’était arrêté.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Un téléchargement unique de %@, puis titres, résumés et plans se font entièrement sur ce Mac. Il faut 16 Go de mémoire pour l’exécuter, et il occupe environ %@ pendant qu’il rédige.",
        "Open System Settings…": "Ouvrir Réglages Système…",
        "Or start from the menu bar later in the call.": "Ou lancez-le depuis la barre des menus plus tard dans l’appel.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "En pause pour l’instant : pas assez de mémoire libre. Il reprend de lui-même, et les réunions en attente de résumé gardent leur transcription.",
        "Permissions": "Autorisations",
        "Reads with Apple Intelligence until the download finishes.": "Lit avec Apple Intelligence jusqu’à la fin du téléchargement.",
        "Reads with the downloaded model — paused until there is free memory.": "Lit avec le modèle téléchargé — en pause jusqu’à ce qu’il y ait de la mémoire libre.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Les modèles de rapport sont dans Modèles ; les rapports rédigés sont dans la bibliothèque, sous Rapports.",
        "Report · %@": "Rapport · %@",
        "Report · %@ +%d": "Rapport · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Les rapports ont besoin de l’agent, qui est désactivé. Choisissez Claude ou ChatGPT dans Résumés et rapports ; les modèles sont conservés d’ici là.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Tourne entièrement sur ce Mac. Sans lui, titres et résumés viennent d’Apple Intelligence.",
        "Startup": "Démarrage",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Conservée dans votre trousseau, jamais dans un fichier de réglages. L’agent répond aux questions sur l’ensemble de vos réunions et rédige des rapports d’après vos modèles.",
        "Summaries": "Résumés",
        "Summaries & reports": "Résumés et rapports",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "Le téléchargement est le moyen d’avoir des résumés sur ce Mac sans Apple Intelligence. La transcription et la recherche fonctionnent dans tous les cas.",
        "This Mac was offline. Nothing was sent.": "Ce Mac était hors ligne. Rien n’a été envoyé.",
        "This take was not kept. Earlier ones are still here.": "Cette prise n’a pas été gardée. Les précédentes sont toujours là.",
        "Uses 41 MB of speaker models.": "Utilise 41 Mo de modèles de voix.",
        "What’s new in %@": "Nouveautés de %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Que quelque chose lise ces enregistrements — résumés, plans, rapports et l’agent — se règle dans Résumés et rapports. Ce panneau ne concerne que ce qui est enregistré sur ce Mac.",
        "Write again": "Rédiger à nouveau",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "Rédiger un rapport, ci-dessus, liste vos %d modèles. En rédiger un envoie cette transcription à %@ avec votre clé ; le rapport est conservé dans le fichier de cette réunion et voyage avec la transcription. Exporter en fait une copie où vous voulez.",
        "Written %@": "Rédigé le %@",
        "Written by %@": "Rédigé par %@",
        "Written by %@ %@ at %@": "Rédigé par %@ le %@ à %@",
        "Written in": "Rédigé en",
        "Your agent, on your key": "Votre agent, avec votre clé",
        "click to insert": "cliquer pour insérer",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS est encore en train de configurer Apple Intelligence. Cela peut prendre du temps et ne peut pas être accéléré d’ici.",
        "macOS resets this switch after some updates and never asks a second time.": "macOS réinitialise ce réglage après certaines mises à jour et ne redemande jamais.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-clic pour copier à la place. Effacé à la fermeture de Dictate.",
        "Meeting names": "Noms des réunions",
        "%d meetings, reports included": "%d réunions, rapports compris",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "Téléchargez le modèle de réunions dans Résumés et rapports, ou ajoutez une clé pour l’agent.",
        "Calls": "Appels",
        "Reports folder": "Dossier des rapports",
        "%d PDFs written before %@": "%d PDF écrits avant %@",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate n’écrit plus de PDF de lui-même. Ils sont à vous, à garder ou à supprimer ; rien dans l’app n’en dépend.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "Le rapport déjà rédigé est remplacé. Envoie cette transcription à %@ avec votre clé.",
        "%@ · report not written": "%@ · rapport non rédigé",
        "%d of %d selected · %d meetings without one": "%d sur %d sélectionnées · %d réunions sans rapport",
        "%d passages from %d meetings": "%d passages de %d réunions",
        "%d written across %d templates": "%d rédigés avec %d modèles",
        "%d written · %d meetings without one · %d fields": "%d rédigés · %d réunions sans rapport · %d champs",
        "%d written · writing %d · %d not written": "%d rédigés · %d en cours · %d non rédigés",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Un rapport se rédige à la demande — depuis la fiche d’une réunion, ou pour une sélection ici. Chacun envoie la transcription de cette réunion à %@ avec votre clé et reste dans le fichier de la réunion.",
        "All reports": "Tous les rapports",
        "Answer": "Réponse",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Réponse de %@ d’après %d réunions sur %d. Les citations sont reprises mot pour mot des transcriptions de ce Mac.",
        "Copy as Markdown": "Copier en Markdown",
        "Copy as plain text": "Copier en texte brut",
        "Copy the answer only": "Copier la réponse seule",
        "Copy with quotes": "Copier avec les citations",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "Chaque modèle garde ses propres rapports : ce qui est rédigé, et les réunions qui pourraient en avoir un. Les modèles se modifient dans Réglages › Modèles.",
        "Edit template…": "Modifier le modèle…",
        "No report yet · %d meetings": "Pas encore de rapport · %d réunions",
        "None written · %d fields": "Aucun rédigé · %d champs",
        "Nothing written from this template yet": "Rien de rédigé avec ce modèle pour l’instant",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Désactivé : ces %d sont ignorées et %d rapports sont rédigés. Le remplacement ne peut pas être annulé.",
        "Pick a template": "Choisissez un modèle",
        "Quotes": "Citations",
        "Replace the %d that already have one": "Remplacer les %d qui en ont déjà un",
        "Report not written — the request was refused. The meeting has the detail.": "Rapport non rédigé — la demande a été refusée. Le détail est dans la réunion.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Envoie %d transcriptions à %@ avec votre clé — environ %@ mots. Chaque rapport reste dans le fichier de sa réunion. Les enregistrements ne quittent jamais ce Mac.",
        "The %d existing reports are overwritten. This cannot be undone.": "Les %d rapports existants sont écrasés. Cela ne peut pas être annulé.",
        "Write": "Rédiger",
        "Write %d": "Rédiger %d",
        "Write %d reports…": "Rédiger %d rapports…",
        "Write a “%@” report for %d meetings?": "Rédiger un rapport « %@ » pour %d réunions ?",
        "Write a “%@” report for “%@”?": "Rédiger un rapport « %@ » pour « %@ » ?",
        "Write all %d…": "Rédiger les %d…",
        "Write for a selection…": "Rédiger pour une sélection…",
        "Write report › %@": "Rédiger un rapport › %@",
        "Written": "Rédigés",
        "No instruction — goes by its name alone": "Sans instruction — le nom seul fait foi",
        "Drag to reorder": "Glisser pour réordonner",
        "Every report is kept inside its meeting’s file.": "Chaque rapport reste dans le fichier de sa réunion.",
        "A refusal stops that meeting only; the rest continue.": "Un refus n’arrête que cette réunion ; les autres continuent.",
        "Always assume": "Tenir pour acquis",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Les faits que l’appel ne dit jamais mais que chaque rapport doit tenir pour acquis : qui vous êtes, quel côté est le client, les mots que votre équipe emploie dans un sens particulier. Envoyé avec chaque rapport de ce modèle.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Facultatif. Sans cela, le modèle lit l’appel à froid : cela convient souvent à une réunion entre collègues et pas à un appel avec un tiers.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Nous sommes une agence commerciale. Le client est toujours l’autre partie, jamais nous. « Sièges » désigne les licences utilisateur payantes.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Affiché sur la fiche de la réunion, dans la bibliothèque sous Rapports et comme titre dans le rapport rédigé.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Chaque champ devient un titre dans le rapport, dans cet ordre. Faites glisser un champ par sa poignée pour le déplacer. L’instruction est facultative et peut être aussi longue que nécessaire ; un champ sans instruction s’en tient à son nom.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Chaque champ est rempli uniquement à partir de la transcription de cet appel. Un champ que l’appel n’a pas abordé indique « Not discussed ».",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Un modèle, c’est un nom et quelques champs. Un rapport en est rédigé à la demande, un par modèle et par réunion.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Pas encore de modèle. Un modèle, c’est un nom et quelques champs ; un rapport en est rédigé à la demande depuis la fiche d’une réunion, un par modèle et par réunion.",
    ]

    static let de: [String: String] = [
        "Settings": "Einstellungen",
        "Keyboard shortcuts": "Tastaturkurzbefehle",
        "Storage & models": "Speicher & Modelle",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Der Schlüsselbund hat das Speichern verweigert — der Schlüssel bleibt im Feld. Entsperren Sie den Schlüsselbund und versuchen Sie es erneut.",
        "Couldn't reach the update server. Try again once you're online.": "Der Update-Server ist nicht erreichbar. Versuchen Sie es, sobald Sie online sind.",
        "You're up to date — Dictate %@ is the newest version.": "Sie sind auf dem neuesten Stand — Dictate %@ ist die aktuellste Version.",
        "Recorded meetings appear here.": "Aufgenommene Meetings erscheinen hier.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Das ist nur Ihr Mikrofon — die Gegenseite des Anrufs wurde nicht aufgenommen und ist nicht wiederherstellbar.",
        "Turning both on covers the calls that come next.": "Beide eingeschaltet decken die nächsten Anrufe ab.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "%@ hat die Anfrage aus Abrechnungsgründen abgelehnt. Laden Sie Guthaben beim Anbieter auf oder trennen Sie den Agenten in den Einstellungen.",
        "Agent": "Agent",
        "Ask your agent": "Agenten fragen",
        "Ask your agent anything…": "Fragen Sie Ihren Agenten, was Sie wollen …",
        "Has read %d of %d meetings": "Hat %d von %d Meetings gelesen",
        "Has read 1 meeting": "Hat 1 Meeting gelesen",
        "Has read all %d meetings": "Hat alle %d Meetings gelesen",
        "Meetings & Agent…": "Meetings & Agent …",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Jetzt nicht lässt den Agenten aus und verborgen. Suche und Transkripte bleiben unberührt.",
        "Nothing to read yet": "Noch nichts zu lesen",
        "Off — has read nothing yet": "Aus — hat noch nichts gelesen",
        "Reading %d of %d meetings…": "Liest %d von %d Meetings …",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "Das schreibt die Zusammenfassung und die Gliederung und gibt Ihrem Agenten etwas, woraus er antworten kann. Aus bleibt das rohe Transkript — keine Zusammenfassung, keine Gliederung, kein Agent. So oder so wird nichts irgendwohin gesendet.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Ihr Agent beantwortet Fragen zu allem, was Sie aufgenommen haben — „was haben wir zum Stichtag entschieden“ — und nennt das Meeting und den Moment, aus dem die Antwort stammt. Dafür braucht es das Modell, das Ihre Meetings liest, und das ist derzeit aus. So oder so verlässt nichts diesen Mac.",
        "Your agent has nothing to read yet": "Ihr Agent hat noch nichts zu lesen",
        "Your agent has read 1 meeting": "Ihr Agent hat 1 Meeting gelesen",
        "Your agent has read all %d meetings": "Ihr Agent hat alle %d Meetings gelesen",
        "Your agent is off": "Ihr Agent ist aus",
        "Your agent is reading — %d of %d meetings so far": "Ihr Agent liest — bisher %d von %d Meetings",
        "answers with %@": "antwortet mit %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Nichts hier kann einen Anruf hören, bis der Zugriff in den Systemeinstellungen › Datenschutz & Sicherheit › Mikrofon erteilt ist.",
        "There is no summary or outline — reading your meetings is off.": "Es gibt weder Zusammenfassung noch Gliederung — das Lesen der Meetings ist aus.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Das ist nur Ihr Mikrofon — die Gegenseite des Anrufs fehlt, der Text ist ein einziger Block, und es gibt weder Zusammenfassung noch Gliederung.",
        "Turn both on": "Beide einschalten",
        "Turn it on": "Einschalten",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Eingeschaltet werden sie auch für die nächsten Aufnahmen geschrieben. Jetzt eine zu schreiben lässt den Schalter aus.",
        "Waiting on microphone access.": "Wartet auf den Mikrofonzugriff.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Wartet auf „%@“ oben — es gibt noch keinen Anrufton zu trennen.",
        "Write one, this once": "Einmalig eine schreiben",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "Jetzt eine zu schreiben liest nur dieses Transkript und lässt die Schalter aus. Die Gegenseite dieses Anrufs wurde nicht aufgenommen und ist nicht wiederherstellbar.",
        "Writing…": "Schreibt …",
        "macOS denied microphone access": "macOS hat den Mikrofonzugriff verweigert",
        "%@ call — not being recorded": "%@-Anruf — wird nicht aufgenommen",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "Die Anrufaufnahme ist aus, dieser läuft also ohne Transkript vorbei. Eingeschaltet erhalten Sie danach ein durchsuchbares Transkript und eine Zusammenfassung, gespeichert auf diesem Mac.",
        "Call — not being recorded": "Anruf — wird nicht aufgenommen",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Anrufe werden nicht automatisch bemerkt. Sie können jeden hier starten — oder Dictate anbieten lassen, wenn ein Anruf beginnt.",
        "Connect a provider…": "Anbieter verbinden …",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "Das Diktieren funktioniert weiterhin. Jeder Schalter unten sagt, was er hinzufügt; Sie können einen einschalten und den Rest lassen.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "Das Diktieren funktioniert bereits — Diktiertaste halten und überall sprechen. Alles unten betrifft Meetings, und nichts davon ist Pflicht. Schalten Sie ein, was Sie möchten; der Rest bleibt aus.",
        "Don't offer this again": "Nicht mehr anbieten",
        "Everything here is off, so calls pass unnoticed": "Hier ist alles aus, Anrufe bleiben unbemerkt",
        "Let the model read your meetings": "Das Modell Ihre Meetings lesen lassen",
        "Not watching for calls": "Anrufe werden nicht beobachtet",
        "Notice when a call starts": "Bemerken, wenn ein Anruf beginnt",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Aus enthält eine Aufnahme nur Ihr Mikrofon — Ihre Hälfte des Gesprächs, in einem Block. An werden beide Seiten als benannte Wortmeldungen transkribiert.",
        "On": "An",
        "Or leave this and set them up later in Settings.": "Oder lassen Sie es und richten Sie sie später in den Einstellungen ein.",
        "Read meeting names from Calendar": "Meeting-Namen aus dem Kalender lesen",
        "Record the call audio too": "Auch den Anrufton aufnehmen",
        "Record the call audio, and separate the voices": "Anrufton aufnehmen und Stimmen trennen",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Aufnahmen kommen bereits benannt an, statt als „Zoom-Anruf, 14:02“. Gelesen werden nur Titel, die sich mit einer Aufnahme überschneiden.",
        "Separate the voices": "Stimmen trennen",
        "Set up calls…": "Anrufe einrichten …",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "Der Agent durchsucht und liest Ihre Transkripte auf diesem Mac; die geschriebene Antwort kommt von einem Anbieter, den Sie mit Ihrem eigenen Schlüssel verbinden.",
        "Three things are off. Here is what each one adds.": "Drei Dinge sind aus. Hier steht, was jedes hinzufügt.",
        "Turn all on": "Alles einschalten",
        "Turn all three on": "Alle drei einschalten",
        "Turn on": "Einschalten",
        "Turn on reading": "Lesen einschalten",
        "Watching for calls": "Anrufe werden beobachtet",
        "What it does": "Was es tut",
        "With this on, a small panel appears when a call starts and you decide there — no need to remember to start anything.": "Eingeschaltet erscheint beim Beginn eines Anrufs ein kleines Panel, und Sie entscheiden dort — an nichts muss man selbst denken.",
        "listening": "hört zu",
        "Back to the top": "Nach oben",
        "Show everything tagged #%@": "Alles mit #%@ anzeigen",
        "Remove #%@ from this meeting": "#%@ aus diesem Meeting entfernen",
        "Tag": "Tag",
        "Create #%@": "#%@ erstellen",
        "Show Live Transcript": "Laufendes Transkript anzeigen",
        "Hide": "Ausblenden",
        "Stop recording": "Aufnahme stoppen",
