        "Add your OpenAI API key in Settings to ask questions": "OpenAI-API-Schlüssel in den Einstellungen hinzufügen, um Fragen zu stellen",
        "The model refused the request (%@)": "Das Modell hat die Anfrage abgelehnt (%@)",
        "Reading…": "Lese…",
