        "detect while you speak": "wird beim Sprechen erkannt",
        "Search language…": "Sprache suchen…",
        "Suggested": "Vorschläge",
        "No language matches your search.": "Keine Sprache gefunden.",
        "Translate key": "Übersetzungstaste",
        "%@ is using the microphone right now — close it and try again": "%@ verwendet gerade das Mikrofon — schließe es und versuche es erneut",
        "That was very quiet — move closer to the microphone": "Das war sehr leise — geh näher ans Mikrofon",
        "That was too loud — move back a little from the microphone": "Das war zu laut — geh etwas weiter vom Mikrofon weg",
        "Sorry, I didn't catch that — could you say it again?": "Entschuldige, ich habe dich nicht verstanden — kannst du das wiederholen?",
        "Not inserted — text copied, press ⌘V to paste": "Nicht eingefügt — Text kopiert, ⌘V zum Einfügen",
        "Another app is using the microphone right now — close it and try again": "Eine andere App nutzt gerade das Mikrofon — schließe sie und versuch es erneut",
        "General": "Allgemein",
        "Type a key…": "Taste drücken …",
        "Hold to talk, release to insert what you said.": "Halten zum Sprechen, loslassen zum Einfügen des Gesagten.",
        "Downloaded %d of %d MB": "%d von %d MB heruntergeladen",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Das Modell wird für die Neural Engine vorbereitet… Ein paar Minuten, einmalig.",
        "Warming up the model…": "Modell wird aufgewärmt…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate läuft aus dem heruntergeladenen Image — ziehen Sie es in „Programme“, werfen Sie das Image aus und starten Sie es von dort. Berechtigungen für diese temporäre Kopie bleiben nicht erhalten.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Immer noch blockiert? Setzen Sie die Berechtigung zurück — das löscht den defekten macOS-Eintrag; erteilen Sie sie dann in der neuen Abfrage.",
        "Words: %d · %.1f s": "Wörter: %d · %.1f s",
        "Words: %d": "Wörter: %d",
        "Cancelled": "Abgebrochen",
        "Changed your mind? Esc cancels the recording.": "Umentschieden? Esc bricht die Aufnahme ab.",
        "About Dictate": "Über Dictate",
        // Onboarding — general
        "Welcome to Dictate": "Willkommen bei Dictate",
        "Back": "Zurück",
        "Next": "Weiter",
        "Step %d of %d": "Schritt %d von %d",
        // Welcome
        // Hotkey
        "Dictation key": "Diktiertaste",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "Diese Taste erzeugt Zeichen — solange Sie sie halten, landen sie in Ihrem Text. Sicherer ist eine Modifikatortaste (Option, Cmd, Shift, Ctrl) oder eine F-Taste.",
        // Permissions
        "Microphone": "Mikrofon",
        "Accessibility": "Bedienungshilfen (Accessibility)",
        // Settings
        "Dictate Settings": "Dictate-Einstellungen",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "Die Taste erzeugt Zeichen — beim Diktieren landen sie im Text. Besser eine Modifikatortaste oder F-Taste.",
        "Launch at login": "Bei der Anmeldung starten",
        "Show in Dock": "Im Dock anzeigen",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "Der Agent durchsucht und liest Ihre Transkripte auf diesem Mac, und jede Antwort nennt die Meetings, auf die sie sich stützt.",
        "Undo remove": "Entfernen widerrufen",
        "Call started": "Ein Anruf hat begonnen",
        "Recording stopped by itself — the call ended.": "Die Aufnahme hat sich selbst beendet — der Anruf ist zu Ende.",
        "Recording stopped by itself — ten minutes of silence.": "Die Aufnahme hat sich selbst beendet — zehn Minuten Stille.",
        "%@ call started": "%@-Anruf gestartet",
        "Not this one": "Diesen nicht",
        "Record": "Aufnehmen",
        "Record this call": "Diesen Anruf aufnehmen",
        "Dictation that works offline — recognition runs entirely on this Mac.": "Diktat, das offline funktioniert — die Erkennung läuft vollständig auf diesem Mac.",
        "Translation that works offline — speak your language, another comes out.": "Übersetzung, die offline funktioniert — sprechen Sie Ihre Sprache, eine andere kommt heraus.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "Ein optionaler Agent, der Ihre Meetings kennt — Antworten zitieren den Moment, aus dem sie stammen.",
        "%d MB of %d MB": "%d MB von %d MB",
        "Already clicked and nothing changed?": "Geklickt und nichts passiert?",
        "Applications": "Programme",
        "Downloading the speech model": "Sprachmodell wird geladen",
        "Grant…": "Erteilen…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "Nichts verlässt dieses Fenster. Zwei kleine Versuche, dann sind Sie fertig.",
        "Resume Download": "Download fortsetzen",
        "Show me where to look": "Zeig mir, wo ich nachsehen muss",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "Dictate beim Anmelden starten — es erscheint im Dock und in der Menüleiste; das Dock-Symbol lässt sich später in den Einstellungen ausblenden",
        "Start Using Dictate": "Dictate jetzt verwenden",
        "Stopped · %d MB of %d MB kept on disk": "Gestoppt · %d MB von %d MB auf der Festplatte behalten",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "Die Verbindung wurde unterbrochen. Beim Fortsetzen geht es an derselben Stelle weiter — Sie laden nicht die ganzen %d MB erneut.",
        "The download stopped at %d MB": "Der Download stoppte bei %d MB",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Das Modell wird für Ihren Chip kompiliert, damit die Erkennung später schnell ist. Das dauert beim ersten Start eine Minute und passiert nie wieder.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Das passiert einmal. Das Modell bleibt auf Ihrem Mac — deshalb funktioniert das Diktieren danach ohne Internetverbindung.",
        "To hear you. Audio is processed on this Mac and discarded.": "Um Sie zu hören. Audio wird auf diesem Mac verarbeitet und verworfen.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Um den erkannten Text in die App zu tippen, die Sie gerade verwenden. Nur so kann eine App Text anderswo einfügen.",
        "Try it here first": "Probieren Sie es zuerst hier",
        "Two permissions from macOS": "Zwei Berechtigungen von macOS",
        "macOS asks for these, not us. Dictate cannot work without both.": "macOS fragt danach, nicht wir. Ohne beide kann Dictate nicht arbeiten.",
        "Show or hide the conversations": "Unterhaltungen ein- oder ausblenden",
        "Show or hide the sidebar": "Seitenleiste ein- oder ausblenden",
        "Show or hide the meeting list": "Meetingliste ein- oder ausblenden",
        "Preparing the model for this Mac": "Modell wird für diesen Mac vorbereitet",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "Noch nicht bereit — nach dem Start dauert das ein paar Sekunden. Halten Sie %@ gedrückt, dann geht es los.",
        "Transcript text": "Transkript-Text",
        "Smaller text": "Kleinerer Text",
        "Standard text": "Standardtext",
        "Larger text": "Größerer Text",
        "100 languages · from your system settings": "100 Sprachen · aus den Systemeinstellungen",
        "Add tag": "Tag hinzufügen",
        "Appearance": "Erscheinungsbild",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "Einmal gefragt. Danach startet die Aufnahme aus der Menüleiste ohne Rückfrage. Esc heißt: nicht aufnehmen.",
        "Check for updates": "Nach Updates suchen",
        "Choose your keys and languages": "Tasten und Sprachen wählen",
        "Click, then press a key": "Klicken, dann eine Taste drücken",
        "Dark": "Dunkel",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate nimmt Ihr Mikrofon und den Ton des Anrufs auf und behält das Transkript auf diesem Mac. Andere aufzunehmen kann dort, wo Sie sind, deren Einwilligung erfordern.",
        "Don't Record": "Nicht aufnehmen",
        "Hold the key while you speak. Anything can be changed later in Settings.": "Halten Sie die Taste, während Sie sprechen. Alles lässt sich später in den Einstellungen ändern.",
        "I speak": "Ich spreche",
        "Light": "Hell",
        "Looking through %d meetings…": "Durchsehe %d Meetings…",
        "Match system": "Wie das System",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "Modifikatortasten funktionieren am besten: Gehalten fügen sie nie ein Zeichen ein. Esc bricht ein laufendes Diktat immer ab.",
        "Reading “%@”…": "Lese „%@“…",
        "Record this call?": "Diesen Anruf aufnehmen?",
        "Searching your meetings…": "Durchsuche Ihre Meetings…",
        "Start Recording": "Aufnahme starten",
        "Tags": "Tags",
        "Voices": "Stimmen",
        "Summary": "Zusammenfassung",
        "Outline": "Gliederung",
        "Hide outline": "Gliederung ausblenden",
        "Show outline": "Gliederung einblenden",
        "two levels": "zwei Ebenen",
        "%d moments": "%d Momente",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Bleibt auf diesem Mac. Löschen wirkt sofort; ab 50 Unterhaltungen fallen die ältesten heraus.",
        "Ask across all meetings…": "In allen Meetings fragen…",
        "Recently Added": "Zuletzt hinzugefügt",
        "%d meetings · %d h of audio": "%d Meetings · %d Std. Audio",
        "%d meetings · %d min of audio": "%d Meetings · %d Min. Audio",
        "Show more": "Mehr anzeigen",
        "Try one of these": "Probieren Sie eine davon",
        "Accessibility access is turned off": "Der Bedienungshilfen-Zugriff ist ausgeschaltet",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "Das Diktat hört Sie, kann aber nicht tippen. Aktivieren Sie den Zugriff erneut.",
        "Recent dictations": "Letzte Diktate",
        "Secure input is active — the hotkey cannot work": "Sichere Eingabe ist aktiv — die Taste kann nicht funktionieren",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "Irgendwo ist ein Passwortfeld fokussiert. macOS sagt nicht, in welcher App. Klicken Sie in ein gewöhnliches Textfeld, und das Diktat funktioniert wieder.",
        "Start Recording Meeting": "Meeting aufnehmen",
        "Stop Recording Meeting": "Meeting-Aufnahme stoppen",
        "dictate in %@": "diktieren auf %@",
        "dictate in any language": "diktieren in jeder Sprache",
        "translate %@ → %@": "übersetzen %@ → %@",
        "translate into %@": "übersetzen nach %@",
        "%d waiting": "%d wartet",
        "%d words typed": "%d Wörter getippt",
        "Add a Key…": "Schlüssel hinzufügen…",
        "Both will be inserted in the order you spoke them": "Beide werden in der Reihenfolge eingefügt, in der Sie sie gesprochen haben",
        "Check Audio Setup": "Audio-Setup prüfen",
        "Clear All Filters": "Alle Filter löschen",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "F-Tasten lösen oft auch eine Systemfunktion aus (Helligkeit, Medien) — macOS macht beides. Um sie als normale Taste zu nutzen, aktivieren Sie „Use F1, F2, etc. as standard function keys“ in den Tastatureinstellungen.",
        "How this works": "So funktioniert es",
        "Input device changed": "Eingabegerät geändert",
        "Insert text by": "Text einfügen per",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Er wurde seit der Verbindung widerrufen oder ersetzt. Er wurde aus dem Schlüsselbund entfernt — nichts wurde damit erneut gesendet.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Treten Sie einem Anruf im Browser bei und starten Sie die Aufnahme. Dictate erfasst Ihr Mikrofon und den Anrufton, transkribiert beides auf diesem Mac und behält das Transkript hier. Nichts wird hochgeladen.",
        "No meeting has all of these tags": "Kein Meeting trägt alle diese Tags",
        "No meeting has this tag": "Kein Meeting trägt diesen Tag",
        "Nothing was said, or nothing was heard": "Nichts wurde gesagt — oder nichts wurde gehört",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Hier steht nur der unbestätigte Rest — alles andere ist schon im Dokument",
        "Open Console": "Konsole öffnen",
        "Open Settings": "Einstellungen öffnen",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Einfügen ist sofort, ersetzt aber kurz die Zwischenablage. Tippen funktioniert in Apps, die Einfügen blockieren, etwa manchen Terminals und Remote-Desktops.",
        "Pasting it at once": "Auf einmal einfügen",
        "Recording ended here — this Mac went to sleep.": "Die Aufnahme endete hier — dieser Mac ging in den Ruhezustand.",
        "Remove “%@”": "„%@“ entfernen",
        "Return sends · Shift-Return adds a line · Esc clears": "Zeilenschalter sendet · Umschalt-Zeilenschalter neue Zeile · Esc leert",
        "Show Floating Timer": "Schwebenden Timer zeigen",
        "Start Recording a Meeting": "Meeting aufnehmen",
        "Still recognizing the previous dictation": "Das vorige Diktat wird noch erkannt",
        "Still recognizing the previous dictation · %d words": "Das vorige Diktat wird noch erkannt · %d Wörter",
        "Switched to %@": "Gewechselt zu %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Tag-Filter verbinden sich mit „und“ — ein Meeting muss jeden gewählten Tag tragen.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Die Antwort brach ab. Ihre Frage bleibt oben — versuchen Sie es erneut, sobald die Verbindung zurück ist. Suche und Transkripte funktionieren weiter.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Die Aufnahme lief, aber auf keiner Seite wurde Sprache erkannt. Meist wurde der Anrufton nie erfasst — ein Browser-Tab ohne Audioberechtigung oder das falsche Ausgabegerät.",
        "The saved key no longer works": "Der gesicherte Schlüssel funktioniert nicht mehr",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Der Schalter bleibt aus, bis der Zugriff in System Settings › Privacy & Security › Calendars erteilt ist. Gelesen werden nur Termine, die eine Aufnahme überlappen.",
        "This Mac is offline": "Dieser Mac ist offline",
        "Too many questions at once": "Zu viele Fragen auf einmal",
        "Typing as you speak": "Tippt, während Sie sprechen",
        "Typing into %@ as you speak": "Tippt in %@, während Sie sprechen",
        "Typing it out character by character": "Zeichen für Zeichen tippen",
        "Your provider account is out of credit": "Das Anbieterkonto hat kein Guthaben mehr",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Ihr Anbieter drosselt die Anfragen. Warten Sie ein paar Sekunden — nichts ging verloren.",
        "macOS denied calendar access": "macOS hat den Kalenderzugriff verweigert",
        "API key": "API-Schlüssel",
        "All Meetings": "Alle Meetings",
        "Assistant": "Assistent",
        "Checking the key with %@. No transcript is sent — only a test request.": "Schlüssel wird bei %@ geprüft. Es wird kein Transkript gesendet — nur eine Testanfrage.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Das Schließen des Fensters stoppt die Aufnahme nicht. Stoppen Sie sie hier oder jederzeit über die Menüleiste.",
        "Connect an assistant to answer questions": "Assistenten verbinden, um Fragen zu beantworten",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate kann einen Browser-Anruf aufnehmen und das Transkript auf diesem Mac behalten. Starten Sie die Aufnahme beim nächsten Anruf über die Menüleiste — die Zustimmung wird einmal erfragt.",
        "Done": "Fertig",
        "Every change takes effect immediately.": "Jede Änderung wirkt sofort.",
        "Get one at %@.": "Erhältlich auf %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Taste halten, sprechen, loslassen. Das Gesagte wird dort getippt, wo der Cursor steht — in jeder App auf diesem Mac.",
        "Keys": "Tasten",
        "Languages": "Sprachen",
        "Library": "Bibliothek",
        "Paste a key from your own account.": "Fügen Sie einen Schlüssel Ihres eigenen Kontos ein.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Im Schlüsselbund gesichert, aber nicht geprüft — dieser Mac ist offline. Geprüft wird bei Ihrer ersten Frage.",
        "Set Up Dictate": "Dictate einrichten",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Im macOS-Schlüsselbund auf diesem Mac gespeichert. Nie in eine Einstellungsdatei geschrieben, nie synchronisiert.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Der Schlüssel wurde abgelehnt. Er ist womöglich widerrufen, von einem anderen Anbieter oder ohne Guthaben — der Schlüssel wurde nicht gespeichert.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Transkripte, Suche und Zitate funktionieren ohne dies. Ein Assistent wird nur zum Schreiben der Antwort gebraucht.",
        "Try Again": "Erneut versuchen",
        "Updates": "Updates",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Sie zahlen Ihrem Anbieter pro Frage — meist Bruchteile eines Cents. Nur Ihre Frage und die zitierten Stellen werden gesendet; Aufnahmen verlassen diesen Mac nie.",
        "Send": "Senden",
        "Conversations": "Unterhaltungen",
        "New question": "Neue Frage",
        "Deleted “%@”": "Gelöscht: „%@“",
        "Undo": "Widerrufen",
        "Questions you ask are kept here so you can return to an answer.": "Gestellte Fragen bleiben hier — zu einer Antwort können Sie zurückkehren.",
        "Rename": "Umbenennen",
        "Delete": "Löschen",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Stimmen werden nach Klang zugeordnet — der Name gilt nur für die Beiträge dieser Stimme.",
        "Give two voices the same name to merge them.": "Geben Sie zwei Stimmen denselben Namen, um sie zusammenzuführen.",
        "Voices are told apart by sound — one person can show up as two.": "Stimmen werden nach Klang unterschieden — eine Person kann als zwei erscheinen.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "Klicken Sie auf einen Namen, um eine Stimme umzubenennen — derselbe Name führt zwei zusammen. Zusammenfassungen und Antworten stützen sich darauf, was gesagt wurde, nicht darauf, wer es gesagt hat.",
        "Voice separation improves over time.": "Die Stimmtrennung wird mit der Zeit besser.",
        "About voice separation": "Über die Stimmtrennung",
        "Call · voice %d": "Anruf · Stimme %d",
        "Starred": "Favoriten",
        "Other browser calls": "Andere Browser-Anrufe",
        "Sources": "Quellen",
        "Star meeting": "Meeting favorisieren",
        "Unstar meeting": "Favorit entfernen",
        "Export transcript…": "Transkript exportieren…",
        "Still recording": "Aufnahme läuft weiter",
        "Got it": "Verstanden",
        "Call": "Anruf",
        "Dictating": "Diktieren",
        "Dictating in %@": "Diktieren auf %@",
        "Translating into English": "Übersetze ins Englische",
        "Translating into %@": "Übersetze in %@",
        "Release %@ to insert": "%@ loslassen zum Einfügen",
        "Also recording this meeting": "Dieses Meeting wird ebenfalls aufgenommen",
        "%@ MB/s · about %@ left": "%@ MB/s · noch etwa %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Nicht genug Speicherplatz: Der Download braucht etwa %d MB, frei sind %d MB. Platz schaffen und erneut versuchen.",
        "Fix…": "Beheben…",
        "Checked automatically · last %@": "Automatisch geprüft · zuletzt: %@",
        "Source code": "Quellcode",
        "Report an issue": "Problem melden",
        "Finishing the transcript…": "Transkript wird abgeschlossen…",
        "Disk almost full — will stop to keep the transcript": "Festplatte fast voll — stoppt, um das Transkript zu behalten",
        "Dictate is running from its disk image": "Dictate läuft von seinem Disk-Image",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Berechtigungen aus einem Disk-Image gehen beim Auswerfen verloren, und das Modell würde jedes Mal neu geladen. Verschieben Sie Dictate zuerst in den Ordner „Programme“.",
        "Move to Applications": "In „Programme“ verschieben",
        "Quit": "Beenden",
        "Couldn't move Dictate automatically": "Dictate konnte nicht automatisch verschoben werden",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Ziehen Sie Dictate aus dem Disk-Image in den Ordner „Programme“ und starten Sie es von dort.",
        "OK": "OK",
        "Inserted into %@": "In %@ eingefügt",
        "Inserted": "Eingefügt",
        "Accessibility is off — dictation can hear you but cannot type": "Bedienungshilfen sind aus — das Diktat hört Sie, kann aber nicht tippen",
        "Open Privacy & Security…": "Datenschutz & Sicherheit öffnen…",
        "1 dictation still being recognized": "1 Diktat wird noch erkannt",
        "%d dictations still being recognized": "%d Diktate werden noch erkannt",
        "Language Packs…": "Sprachpakete…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Wenn deaktiviert, lebt Dictate nur in der Menüleiste. Ein Klick auf das Dock-Symbol öffnet die Meetings; das Menüleisten-Symbol ist immer da.",
        "Interface language": "Sprache der Benutzeroberfläche",
        "Granted": "Erteilt",
        "No": "Nein",
        "Model ready": "Modell bereit",
        "On-device recognition": "Erkennung auf dem Gerät",
        "Spoken language": "Gesprochene Sprache",
        "Download failed. Check your connection and retry.": "Download fehlgeschlagen. Prüfen Sie Ihre Verbindung und versuchen Sie es erneut.",
        "Not set": "Nicht festgelegt",
        "Remove": "Entfernen",
        "Download & continue": "Laden & fortfahren",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Etwa %@ — einmalig heruntergeladen. Das ist das einzige Mal, dass Dictate Internet braucht.",
        "Hold %@ and say something — the recognized text shows up below.": "Halten Sie %@ gedrückt und sagen Sie etwas — der erkannte Text erscheint unten.",
        "Recognized text appears here…": "Der erkannte Text erscheint hier …",
        // Menu bar
        "Settings…": "Einstellungen …",
        "Quit Dictate": "Dictate beenden",
        "Dictate — voice dictation": "Dictate — Sprachdiktat",
        // HUD
        "Recognizing…": "Wird erkannt …",
        "Esc to cancel": "Esc zum Abbrechen",
        // Errors
        "Couldn't start recording: %@": "Aufnahme konnte nicht gestartet werden: %@",
        "Recording truncated at %d seconds (limit)": "Aufnahme nach %d Sekunden abgeschnitten (Limit)",
        "Audio device changed during recording — recording cancelled, please try again.": "Das Audiogerät hat sich während der Aufnahme geändert — Aufnahme abgebrochen, bitte versuchen Sie es erneut.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "Die Berechtigung „Bedienungshilfen“ ist deaktiviert, daher wird die Taste nicht erkannt. Aktivieren Sie sie unter Systemeinstellungen → Datenschutz & Sicherheit → Bedienungshilfen — Dictate übernimmt das automatisch, kein Neustart nötig.",
        "Microphone unavailable (no input audio format)": "Mikrofon nicht verfügbar (kein Eingabe-Audioformat)",
        // Key names
        "Right Option (⌥)": "Option rechts (⌥)",
        "Left Option (⌥)": "Option links (⌥)",
        "Right Command (⌘)": "Command rechts (⌘)",
        "Left Command (⌘)": "Command links (⌘)",
        "Right Shift (⇧)": "Shift rechts (⇧)",
        "Left Shift (⇧)": "Shift links (⇧)",
        "Right Control (⌃)": "Control rechts (⌃)",
        "Left Control (⌃)": "Control links (⌃)",
        "Space": "Leertaste",
        "Follow system": "Wie im System",
        "Translating…": "Übersetze…",
        "Tip: hold %@ instead — your speech comes out in English.": "Tipp: Halte stattdessen %@ — deine Sprache erscheint auf Englisch.",
        "Hold to talk in your language, release to insert it in English.": "Halten und in deiner Sprache sprechen, loslassen — eingefügt wird Englisch.",
        "Hold %@ and say it again — this time it's typed in English.": "Halte %@ und sag es noch einmal — diesmal wird es auf Englisch getippt.",
        "Translate to": "Übersetzen in",
        "Translation data isn't downloaded — open Settings to get it": "Übersetzungsdaten sind nicht geladen — lade sie in den Einstellungen",
        "Translation data": "Übersetzungsdaten",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "Die Übersetzungstaste erkennt deine Sprache, dann übersetzt macOS sie auf diesem Mac. Bei der Sprachwahl lädt macOS die Übersetzungsdaten einmalig herunter.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "Die Erkennung läuft auf der Neural Engine deines Mac — Whisper large-v3-turbo: 100 Sprachen, kommt gut mit Akzenten zurecht und ist schnell genug für Live-Text. Auch die Übersetzung läuft auf diesem Mac. Deine Stimme verlässt diesen Computer nie.",
        "Hold %@ and say it again — this time it comes out in %@.": "Halte %@ und sag es noch einmal — diesmal kommt es auf %@ heraus.",
        "Hold to talk in your language, release to insert it in %@.": "Halten und in deiner Sprache sprechen, loslassen — eingefügt wird %@.",
        "Not downloaded": "Nicht geladen",
        "Translation languages": "Übersetzungssprachen",
        "Downloaded": "Geladen",
        "Manage in System Settings…": "In den Systemeinstellungen verwalten…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "In den Systemeinstellungen schon AN, aber hier nicht grün? Schalte den Dictate-Schalter aus und wieder ein — nach einem Update behält macOS manchmal einen veralteten Eintrag.",
        "Agent: %@, on your key.": "Agent: %@, mit Ihrem Schlüssel.",
        "Agent: off.": "Agent: aus.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "Apple Intelligence ist auf diesem Mac in dieser Region oder Sprache nicht verfügbar. Der Agent mit Ihrem eigenen Schlüssel funktioniert weiterhin.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence braucht macOS 26. Der Agent mit Ihrem eigenen Schlüssel funktioniert weiterhin.",
        "Copy diagnostics": "Diagnose kopieren",
        "Debug audio dumps": "Debug-Audiodumps",
        "Diagnostics": "Diagnose",
        "Downloading…": "Wird geladen…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Gibt %@ frei. Neue Meetings behalten ihr Datum als Namen, bis Sie es erneut laden. Bereits geschriebene Zusammenfassungen bleiben.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Gibt %@ frei. Sonst ändert sich nichts — das Lesen der Meetings ist aus.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Gibt %@ frei. Titel und Zusammenfassungen kommen dann von Apple Intelligence.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Installiert, aber nicht aktiv: Dieser Mac hat %d GB Arbeitsspeicher, nötig sind 16.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Installiert, aber nicht aktiv: Dieser Mac hat %d GB Arbeitsspeicher, nötig sind 16. Nichts auf diesem Mac liest Meetings.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Installiert, aber nicht aktiv: Dieser Mac hat %d GB Arbeitsspeicher, nötig sind 16. Titel und Zusammenfassungen kommen stattdessen von Apple Intelligence.",
        "Installed · %@": "Installiert · %@",
        "Installed, not in use · %@": "Installiert, ungenutzt · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Beim Schreiben belegt es rund %@ Arbeitsspeicher, was dieser Mac spüren wird.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, Version und welche Funktionen an sind. Keine Transkripte, keine Schlüssel.",
        "Meeting archive": "Meeting-Archiv",
        "Meeting model": "Meeting-Modell",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Meeting-Modell installiert. Neue Meetings erhalten Titel und Zusammenfassungen auf diesem Mac.",
        "Meeting reading: Apple Intelligence.": "Meetings lesen: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Meetings lesen: Nichts auf diesem Mac kann das bisher.",
        "Meeting reading: the downloaded model (%@).": "Meetings lesen: das geladene Modell (%@).",
        "Not available on this Mac.": "Auf diesem Mac nicht verfügbar.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "Nicht installiert. Ein einmaliger Download von %@ schreibt Titel, Zusammenfassungen und ein Inhaltsverzeichnis.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "Nichts auf diesem Mac kann bisher lesen: Apple Intelligence ist hier nicht verfügbar. Der Agent mit Ihrem eigenen Schlüssel funktioniert weiterhin.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "Nichts auf diesem Mac kann bisher lesen: Laden Sie unten das Meeting-Modell, oder fügen Sie einen Schlüssel für den Agenten hinzu.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "Nichts auf diesem Mac kann bisher lesen: Laden Sie unten das Meeting-Modell, oder schalten Sie Apple Intelligence in den Systemeinstellungen ein.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "Nichts auf diesem Mac kann bisher lesen: macOS richtet Apple Intelligence noch ein. Der Agent mit Ihrem eigenen Schlüssel funktioniert weiterhin.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "Nichts auf diesem Mac kann bisher lesen: Schalten Sie Apple Intelligence in den Systemeinstellungen ein, oder fügen Sie einen Schlüssel für den Agenten hinzu.",
        "Open System Settings": "Systemeinstellungen öffnen",
        "Paused: not enough free memory right now. It resumes on its own.": "Pausiert: Gerade ist nicht genug Arbeitsspeicher frei. Es geht von selbst weiter.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Das Modell wird für den Prozessor dieses Mac vorbereitet… Ein paar Minuten, einmalig.",
        "Raw call audio kept for debugging only.": "Roher Anrufton, nur zum Debuggen behalten.",
        "Reading is on, but nothing on this Mac can read yet.": "Lesen ist an, aber nichts auf diesem Mac kann bisher lesen.",
        "Reads with Apple Intelligence.": "Liest mit Apple Intelligence.",
        "Reads with the downloaded model.": "Liest mit dem geladenen Modell.",
        "Recognition runs on the Neural Engine.": "Die Erkennung läuft auf der Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "Die Erkennung läuft auf dem Prozessor dieses Mac — Whisper large-v3-turbo: 100 Sprachen, kommt gut mit Akzenten zurecht. Langsamer als auf Apple Silicon, und auch die Übersetzung läuft auf diesem Mac. Ihre Stimme verlässt diesen Computer nie.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "Die Erkennung läuft auf dem Prozessor dieses Mac — langsamer als auf Apple Silicon.",
        "Remove the debug audio dumps?": "Debug-Audiodumps löschen?",
        "Remove the meeting model?": "Meeting-Modell löschen?",
        "Remove…": "Löschen…",
        "Speaker models": "Sprechermodelle",
        "Speech model": "Sprachmodell",
        "Storage": "Speicher",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Zusammenfassungen kommen auf diesem Mac von Apple Intelligence. Das ladbare Modell braucht 16 GB Arbeitsspeicher; dieser Mac hat %d.",
        "Summary paused: not enough free memory. It resumes on its own.": "Zusammenfassung pausiert: Nicht genug Arbeitsspeicher frei. Es geht von selbst weiter.",
        "Tell the voices on a call apart.": "Die Stimmen in einem Anruf auseinanderhalten.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "Das Meeting-Modell braucht 16 GB Arbeitsspeicher; dieser Mac hat %d.",
        "These are recordings kept only for debugging. Nothing else is affected.": "Das sind Aufnahmen, die nur zum Debuggen behalten werden. Sonst ist nichts betroffen.",
        "This Mac": "Dieser Mac",
        "This build of Dictate does not include the meeting model.": "Diese Version von Dictate enthält das Meeting-Modell nicht.",
        "Titles and summaries come from Apple Intelligence instead.": "Titel und Zusammenfassungen kommen stattdessen von Apple Intelligence.",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "Schalten Sie Apple Intelligence in den Systemeinstellungen › Apple Intelligence & Siri ein, oder fügen Sie einen Schlüssel für den Agenten hinzu.",
        "Waiting for the call to end.": "Wartet auf das Ende des Anrufs.",
        "Your transcripts, as Markdown files you own.": "Ihre Transkripte, als Markdown-Dateien, die Ihnen gehören.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS richtet Apple Intelligence noch ein — schauen Sie später wieder vorbei, oder fügen Sie einen Schlüssel für den Agenten hinzu.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. Der Bericht bleibt so oder so in der Datei des Meetings; dies erstellt eine Kopie.",
        "%d fields": "%d Felder",
        "Add field": "Feld hinzufügen",
        "Agent & reports": "Agent & Berichte",
        "Also one table (CSV): a row per meeting, a column per field": "Zusätzlich eine Tabelle (CSV): eine Zeile pro Meeting, eine Spalte pro Feld",
        "Answers with": "Antwortet mit",
        "Choose folder…": "Ordner wählen …",
        "Copy report": "Bericht kopieren",
        "Date": "Datum",
        "Export %d “%@” reports": "%d “%@”-Berichte exportieren",
        "Export reports…": "Berichte exportieren …",
        "Export report…": "Bericht exportieren …",
        "Export the “%@” report": "Bericht “%@” exportieren",
        "Field name": "Feldname",
        "Fields": "Felder",
        "Format:": "Format:",
        "Markdown": "Markdown",
        "Meeting": "Meeting",
        "New template": "Neue Vorlage",
        "New template…": "Neue Vorlage …",
        "No reports written with “%@” yet.": "Noch keine Berichte mit “%@” geschrieben.",
        "No templates yet.": "Noch keine Vorlagen.",
        "Not discussed": "Nicht besprochen",
        "One empty field. You name it.": "Ein leeres Feld. Sie benennen es.",
        "One file per meeting, named by date and title, in a folder you choose. Transcripts are not included.": "Eine Datei pro Meeting, benannt nach Datum und Titel, in einem Ordner Ihrer Wahl. Transkripte sind nicht enthalten.",
        "PDF": "PDF",
        "Plain text": "Reiner Text",
        "Questions across your meetings, and reports.": "Fragen über Ihre Meetings hinweg, und Berichte.",
        "Remove field": "Feld entfernen",
        "Remove template": "Vorlage entfernen",
        "Remove template…": "Vorlage entfernen …",
        "Remove “%@”?": "“%@” entfernen?",
        "Report": "Bericht",
        "Report not written": "Bericht nicht geschrieben",
        "Reports": "Berichte",
        "Reports already written with it stay in their meetings.": "Bereits damit geschriebene Berichte bleiben in ihren Meetings.",
        "Same as Dictate": "Wie Dictate",
        "Template name": "Vorlagenname",
        "Templates": "Vorlagen",
        "The model returned no report.": "Das Modell hat keinen Bericht geliefert.",
        "The model stopped before the report was finished.": "Das Modell hat aufgehört, bevor der Bericht fertig war.",
        "The saved key no longer works. It has been removed from the Keychain.": "Der gesicherte Schlüssel funktioniert nicht mehr. Er wurde aus dem Schlüsselbund entfernt.",
        "What is sent": "Was gesendet wird",
        "Writing · about a minute": "Schreibt · etwa eine Minute",
        "Written by Dictate on this Mac from the transcript": "Von Dictate auf diesem Mac aus dem Transkript geschrieben",
        "Your %@ account refused the request for billing reasons.": "Ihr %@-Konto hat die Anfrage aus Abrechnungsgründen abgelehnt.",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "Sendet dieses Transkript mit Ihrem Schlüssel an %@. Der Bericht landet in der Datei des Meetings.",
        "Set up templates…": "Vorlagen einrichten…",
        "Write report": "Bericht schreiben",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@ drosselt die Anfragen. Nichts ist verloren – versuchen Sie es in einer Minute erneut.",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "Dieser Mac ist offline. Nichts wurde gesendet – versuchen Sie es erneut, sobald die Verbindung zurück ist.",
        "Write a “%@” report?": "Bericht „%@“ schreiben?",
        "Action items": "Aufgaben",
        "Dates and deadlines": "Termine und Fristen",
        "Decisions": "Entscheidungen",
        "Decisions & actions": "Entscheidungen und Aufgaben",
        "Every date, deadline or time window that was mentioned, and what it is for": "Jedes genannte Datum, jede Frist oder jedes Zeitfenster – und wofür es gilt",
        "Key points": "Kernpunkte",
        "Meeting summary": "Meeting-Zusammenfassung",
        "Next step": "Nächster Schritt",
        "Open questions": "Offene Fragen",
        "Purpose": "Zweck",
        "Risks and concerns": "Risiken und Bedenken",
        "The main arguments and facts, with the numbers, names and dates that were said": "Die wichtigsten Argumente und Fakten mit den genannten Zahlen, Namen und Daten",
        "The next meeting or checkpoint, if one was agreed": "Das nächste Meeting oder der nächste Kontrollpunkt, falls vereinbart",
        "Waiting on": "Warten auf",
        "We are the team on this call; the reader took part in it.": "Wir sind das Team in diesem Gespräch; die lesende Person hat daran teilgenommen.",
        "What could go wrong, who raised it, how serious it sounded": "Was schiefgehen könnte, wer es angesprochen hat und wie ernst es klang",
        "What each side is waiting for from the other": "Worauf jede Seite von der anderen wartet",
        "What was decided, by whom, and what it replaces": "Was entschieden wurde, von wem, und was es ersetzt",
        "What was raised and not settled, and who owns it": "Was angesprochen, aber nicht geklärt wurde – und wer dafür zuständig ist",
        "Who does what, by when — one line per task": "Wer macht was bis wann – eine Zeile pro Aufgabe",
        "Why we met and what we set out to settle": "Warum wir uns getroffen haben und was wir klären wollten",
        "%d more": "%d weitere",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "Der Titel behält die Sprache des Meetings; die Zusammenfassung und jeder Bericht werden in dieser geschrieben. Feldnamen in einem Bericht bleiben genau wie eingegeben.",
        "About “%@”:": "Zu „%@“:",
        "Replace the report with a new “%@” one?": "Bericht durch einen neuen „%@“-Bericht ersetzen?",
        "Replace report": "Bericht ersetzen",
        "Written · replaces it": "Geschrieben · wird ersetzt",
        "Dictate updated to %@.": "Dictate wurde auf %@ aktualisiert.",
        "Dismiss": "Schließen",
        "New": "Neu",
        "New in this version": "Neu in dieser Version",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Öffnen Sie ein Meeting, klicken Sie oben auf Write report und wählen Sie eine Vorlage. Der Bericht erscheint auf der Karte und als PDF unter Dictate Meetings › Reports.",
        "Reports from templates": "Berichte aus Vorlagen",
        "See what’s new": "Neuigkeiten ansehen",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Einstellungen › Meetings › Zusammenfassungen und Berichte schreiben auf: Zusammenfassung und Berichte kommen in der Sprache, die Sie lesen – egal, in welcher Sprache das Gespräch war.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Einstellungen › Vorlagen: Beginnen Sie mit Meeting-Zusammenfassung oder Entscheidungen und Aufgaben, oder benennen Sie eigene Felder und sagen Sie dem Modell, was darunter gehört.",
        "Summaries in your language": "Zusammenfassungen in Ihrer Sprache",
        "What’s new": "Neuigkeiten",
        "What’s new in Dictate %@": "Neu in Dictate %@",
        "Your own templates": "Eigene Vorlagen",
        "Install update %@ and relaunch": "Update %@ installieren und neu starten",
        "The update waits until the recording ends.": "Das Update wartet, bis die Aufnahme beendet ist.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "Update %@ ist unterwegs – wird heruntergeladen. Es installiert sich im nächsten ruhigen Moment selbst; die Menüleiste bietet es früher an.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "Update %@ ist bereit – installieren Sie es über die Menüleiste, oder es installiert sich im nächsten ruhigen Moment selbst.",
        "An update is already on its way — it installs itself at the next quiet moment.": "Ein Update ist bereits unterwegs – es installiert sich im nächsten ruhigen Moment selbst.",
        "Downloading update %@…": "Update %@ wird geladen …",
        "Preparing update %@…": "Update %@ wird vorbereitet …",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate wurde auf %@ aktualisiert. Die Neuigkeiten stehen im Meetings-Fenster.",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence hat es abgelehnt, dieses Meeting zusammenzufassen.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "Transkript, Suche und Agent bleiben unverändert. Ein herunterladbares Modell, das auf diesem Mac bleibt, kennt diese Einschränkung nicht.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Meetings, aufgezeichnet und strukturiert: Sprecher, Zusammenfassung, Gliederung, Suche. Dictate bietet an, einen Anruf aufzuzeichnen — nie ohne Ihre Antwort.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "Das Meeting-Modell braucht 16 GB Arbeitsspeicher; dieser Mac hat %d. Es läuft nicht, und die %@, die es auf der Festplatte belegt, lassen sich freigeben.",
        "Clipboard restored.": "Zwischenablage wiederhergestellt.",
        "Your words were inserted untranslated.": "Ihre Worte wurden unübersetzt eingefügt.",
        "A small panel appears when a call starts, and you decide there.": "Beim Beginn eines Anrufs erscheint ein kleines Panel, und Sie entscheiden dort.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Schreibt die Zusammenfassung und die Gliederung und gibt Ihrem Agenten etwas, woraus er antworten kann. So oder so wird nichts irgendwohin gesendet.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Aus erhalten Sie nur Ihr eigenes Mikrofon; an wird auch die Gegenseite transkribiert.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Macht aus einem Textblock benannte Wortmeldungen. Die Trennung erfolgt nach Klang und kann ungenau sein; die Namen lassen sich ändern.",
        "Find in this transcript…": "In diesem Transkript suchen…",
        "%d of %d": "%d von %d",
        "No matches": "Keine Treffer",
        "Previous match": "Vorheriger Treffer",
        "Next match": "Nächster Treffer",
        "Close find": "Suche schließen",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "%@ ist gewählt, aber es gibt noch keinen Schlüssel. Agent und Berichte bleiben aus, bis einer hinzugefügt wird.",
        "%@ · required for dictation, cannot be removed.": "%@ · für das Diktieren nötig, kann nicht entfernt werden.",
        "%@ — not written": "%@ — nicht geschrieben",
        "%d h": "%d Std.",
        "%d meetings have a %@ report. They stay if this template goes.": "%d Meetings haben einen Bericht „%@“. Sie bleiben, wenn diese Vorlage entfernt wird.",
        "%d min ago": "vor %d Min.",
        "%d written": "%d geschrieben",
        "%d written, %d not written": "%d geschrieben, %d nicht geschrieben",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 Sprachen. Gilt sofort für dieses Fenster und die Menüleiste. Was Sie sprechen, wird unter „Diktat“ eingestellt.",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Ein Schlüssel aus Ihrem eigenen %@-Konto. Liegt in Ihrem Schlüsselbund, nie in einer Einstellungsdatei.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Eine Frage sendet die Frage und die Passagen, die die Suche gefunden hat. Ein Bericht sendet das ganze Transkript des Meetings — etwa 12.000 Wörter pro Stunde Gespräch. Beides geht mit Ihrem Schlüssel an %@, und nur wenn Sie darum bitten. Die Aufnahmen verlassen diesen Mac nie.",
        "About": "Über",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "Apple Intelligence ist auf diesem Mac nicht verfügbar, es gibt also keine Ausweichmöglichkeit.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence braucht ein neueres macOS, als auf diesem Mac läuft, es gibt also keine Ausweichmöglichkeit.",
        "Applies to this window, the meetings window and the panels over your other apps.": "Gilt für dieses Fenster, das Meetings-Fenster und die Panels über Ihren anderen Apps.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Einmal gefragt. Danach ist das Panel die Kurzfassung und bleibt, bis Sie antworten. Sie können die Aufnahme auch jederzeit während eines Anrufs aus der Menüleiste starten.",
        "Calendar": "Kalender",
        "Collapse %@": "%@ einklappen",
        "Copy": "Kopieren",
        "Dictation": "Diktat",
        "Expand %@": "%@ ausklappen",
        "Export…": "Exportieren …",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "Er steht auch unter „Letzte Diktate“, die Zwischenablage gehört also wieder Ihnen, wann immer Sie möchten.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Liegen in der Datei dieses Meetings und reisen so mit dem Transkript. Exportieren legt eine Kopie ab, wo Sie möchten.",
        "No report": "Kein Bericht",
        "No report for this meeting yet.": "Für dieses Meeting gibt es noch keinen Bericht.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "Beim Entfernen geht nichts verloren: Transkript, Suche und Agent hängen nicht davon ab.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Hier wird nichts eingestellt. Jede Zeile oben meldet entweder, was dieser Mac kann, oder verweist auf den Bereich, der dafür zuständig ist.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "Auf diesem Mac kann noch nichts lesen: Apple Intelligence braucht ein neueres macOS. Der Agent mit Ihrem eigenen Schlüssel funktioniert trotzdem.",
        "Nothing was kept from this take — earlier ones are still here.": "Von dieser Aufnahme blieb nichts — die früheren sind noch da.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "Es wurde nichts aufgenommen, also blieb nichts. Die früheren sind noch da.",
        "Off — dictation cannot type": "Aus — das Diktat kann nicht tippen",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Aus: Transkripte, Zusammenfassungen, Gliederungen und Suche funktionieren wie bisher. Der Agent beantwortet Fragen über alle Ihre Meetings und schreibt Berichte nach Ihren Vorlagen; er läuft in der Cloud mit Ihrem eigenen API-Schlüssel.",
        "On this Mac": "Auf diesem Mac",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Eine fortsetzbare Datei. Wird Dictate beendet, pausiert sie und macht später dort weiter, wo sie aufgehört hat.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Einmaliger Download von %@, danach entstehen Titel, Zusammenfassungen und Gliederungen ganz auf diesem Mac. Zum Laufen braucht es 16 GB Arbeitsspeicher und belegt beim Schreiben etwa %@.",
        "Open System Settings…": "Systemeinstellungen öffnen …",
        "Or start from the menu bar later in the call.": "Oder starten Sie später im Anruf aus der Menüleiste.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "Gerade pausiert: nicht genug freier Arbeitsspeicher. Es geht von selbst weiter, und die Meetings, die auf eine Zusammenfassung warten, behalten ihre Transkripte.",
        "Permissions": "Berechtigungen",
        "Reads with Apple Intelligence until the download finishes.": "Liest mit Apple Intelligence, bis der Download fertig ist.",
        "Reads with the downloaded model — paused until there is free memory.": "Liest mit dem heruntergeladenen Modell — pausiert, bis Arbeitsspeicher frei ist.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Berichtsvorlagen stehen unter „Vorlagen“; geschriebene Berichte liegen in der Bibliothek unter „Berichte“.",
        "Report · %@": "Bericht · %@",
        "Report · %@ +%d": "Bericht · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Berichte brauchen den Agenten, und der ist aus. Wählen Sie Claude oder ChatGPT unter „Zusammenfassungen & Berichte“; die Vorlagen bleiben bis dahin erhalten.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Läuft ganz auf diesem Mac. Ohne es kommen Titel und Zusammenfassungen von Apple Intelligence.",
        "Startup": "Start",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Liegt in Ihrem Schlüsselbund, nie in einer Einstellungsdatei. Der Agent beantwortet Fragen über alle Ihre Meetings und schreibt Berichte nach Ihren Vorlagen.",
        "Summaries": "Zusammenfassungen",
        "Summaries & reports": "Zusammenfassungen & Berichte",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "Der Download ist der Weg zu Zusammenfassungen auf diesem Mac ohne Apple Intelligence. Transkript und Suche funktionieren so oder so.",
        "This Mac was offline. Nothing was sent.": "Dieser Mac war offline. Es wurde nichts gesendet.",
        "This take was not kept. Earlier ones are still here.": "Diese Aufnahme blieb nicht. Die früheren sind noch da.",
        "Uses 41 MB of speaker models.": "Belegt 41 MB an Sprechermodellen.",
        "What’s new in %@": "Neu in %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Ob irgendetwas diese Aufnahmen liest — Zusammenfassungen, Gliederungen, Berichte und der Agent — steht unter „Zusammenfassungen & Berichte“. Dieser Bereich betrifft nur, was auf diesem Mac aufgenommen wird.",
        "Write again": "Erneut schreiben",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "„Bericht schreiben“ oben listet Ihre %d Vorlagen. Einen zu schreiben sendet dieses Transkript mit Ihrem Schlüssel an %@; der Bericht liegt in der Datei dieses Meetings und reist mit dem Transkript. Exportieren legt eine Kopie ab, wo Sie möchten.",
        "Written %@": "Geschrieben am %@",
        "Written by %@": "Geschrieben von %@",
        "Written by %@ %@ at %@": "Geschrieben von %@ am %@ um %@",
        "Written in": "Geschrieben auf",
        "Your agent, on your key": "Ihr Agent, mit Ihrem Schlüssel",
        "click to insert": "Klicken zum Einfügen",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS richtet Apple Intelligence noch ein. Das kann dauern und lässt sich von hier aus nicht beschleunigen.",
        "macOS resets this switch after some updates and never asks a second time.": "macOS setzt diesen Schalter nach manchen Updates zurück und fragt nie ein zweites Mal.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-Klick kopiert stattdessen. Wird beim Beenden von Dictate geleert.",
        "Meeting names": "Meeting-Namen",
        "%d meetings, reports included": "%d Meetings, Berichte eingeschlossen",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "Laden Sie das Meeting-Modell unter „Zusammenfassungen & Berichte“ herunter oder fügen Sie einen Schlüssel für den Agenten hinzu.",
        "Calls": "Anrufe",
        "Reports folder": "Berichte-Ordner",
        "%d PDFs written before %@": "%d PDFs, geschrieben vor %@",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate schreibt keine PDFs mehr von sich aus. Sie gehören Ihnen – behalten oder löschen; nichts in der App hängt davon ab.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "Der bereits geschriebene Bericht wird ersetzt. Sendet dieses Transkript mit Ihrem Schlüssel an %@.",
        "%@ · report not written": "%@ · Bericht nicht geschrieben",
        "%d of %d selected · %d meetings without one": "%d von %d ausgewählt · %d Meetings ohne Bericht",
        "%d passages from %d meetings": "%d Passagen aus %d Meetings",
        "%d written across %d templates": "%d geschrieben mit %d Vorlagen",
        "%d written · %d meetings without one · %d fields": "%d geschrieben · %d Meetings ohne Bericht · %d Felder",
        "%d written · writing %d · %d not written": "%d geschrieben · %d in Arbeit · %d nicht geschrieben",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Ein Bericht wird auf Wunsch geschrieben — von der Karte eines Meetings oder hier für eine Auswahl. Jeder sendet das Transkript dieses Meetings mit Ihrem Schlüssel an %@ und bleibt in der Datei des Meetings.",
        "All reports": "Alle Berichte",
        "Answer": "Antwort",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Beantwortet von %@ aus %d von %d Meetings. Die Zitate stammen wörtlich aus den Transkripten auf diesem Mac.",
        "Copy as Markdown": "Als Markdown kopieren",
        "Copy as plain text": "Als reinen Text kopieren",
        "Copy the answer only": "Nur die Antwort kopieren",
        "Copy with quotes": "Mit Zitaten kopieren",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "Jede Vorlage hat ihre eigenen Berichte: was geschrieben ist, und die Meetings, die einen haben könnten. Die Vorlagen selbst werden unter Einstellungen › Vorlagen bearbeitet.",
        "Edit template…": "Vorlage bearbeiten …",
        "No report yet · %d meetings": "Noch kein Bericht · %d Meetings",
        "None written · %d fields": "Keiner geschrieben · %d Felder",
        "Nothing written from this template yet": "Mit dieser Vorlage wurde noch nichts geschrieben",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Aus: diese %d werden übersprungen und %d Berichte geschrieben. Ersetzen lässt sich nicht rückgängig machen.",
        "Pick a template": "Vorlage wählen",
        "Quotes": "Zitate",
        "Replace the %d that already have one": "Die %d ersetzen, die schon einen haben",
        "Report not written — the request was refused. The meeting has the detail.": "Bericht nicht geschrieben — die Anfrage wurde abgelehnt. Das Meeting hat die Einzelheiten.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Sendet %d Transkripte mit Ihrem Schlüssel an %@ — etwa %@ Wörter. Jeder Bericht bleibt in der Datei seines Meetings. Die Aufnahmen verlassen diesen Mac nie.",
        "The %d existing reports are overwritten. This cannot be undone.": "Die %d vorhandenen Berichte werden überschrieben. Das lässt sich nicht rückgängig machen.",
        "Write": "Schreiben",
        "Write %d": "%d schreiben",
        "Write %d reports…": "%d Berichte schreiben …",
        "Write a “%@” report for %d meetings?": "Einen Bericht „%@“ für %d Meetings schreiben?",
        "Write a “%@” report for “%@”?": "Einen Bericht „%@“ für „%@“ schreiben?",
        "Write all %d…": "Alle %d schreiben …",
        "Write for a selection…": "Für eine Auswahl schreiben …",
        "Write report › %@": "Bericht schreiben › %@",
        "Written": "Geschrieben",
        "No instruction — goes by its name alone": "Keine Anweisung — nur der Name zählt",
        "Drag to reorder": "Ziehen zum Umordnen",
        "Every report is kept inside its meeting’s file.": "Jeder Bericht liegt in der Datei seines Meetings.",
        "A refusal stops that meeting only; the rest continue.": "Eine Ablehnung stoppt nur dieses Meeting; die übrigen laufen weiter.",
        "Always assume": "Immer voraussetzen",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Fakten, die das Gespräch nie ausspricht, die aber jeder Bericht voraussetzen soll: wer Sie sind, welche Seite der Kunde ist, Wörter, die Ihr Team auf eine bestimmte Weise benutzt. Wird mit jedem Bericht aus dieser Vorlage gesendet.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Optional. Ohne das liest das Modell das Gespräch ohne Vorwissen — für ein Meeting unter Kollegen meist in Ordnung, für ein Gespräch mit einer externen Partei falsch.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Wir sind eine Vertriebsagentur. Der Kunde ist immer die andere Seite, nie wir. „Seats“ bedeutet bezahlte Nutzerlizenzen.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Erscheint auf der Karte des Meetings, in der Bibliothek unter Berichte und als Überschrift im geschriebenen Bericht.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Jedes Feld wird im Bericht zu einer Überschrift, in dieser Reihenfolge. Ziehen Sie ein Feld am Griff, um es zu verschieben. Eine Anweisung ist optional und darf so lang sein, wie sie sein muss; ein Feld ohne Anweisung richtet sich nur nach seinem Namen.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Jedes Feld wird nur aus dem Transkript dieses Gesprächs gefüllt. Ein Feld, das im Gespräch nicht vorkam, zeigt „Not discussed“.",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Eine Vorlage ist ein Name und ein paar Felder. Ein Bericht wird daraus auf Wunsch geschrieben, einer pro Vorlage und Meeting.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Noch keine Vorlagen. Eine Vorlage ist ein Name und ein paar Felder; ein Bericht wird daraus auf Wunsch von der Karte eines Meetings geschrieben, einer pro Vorlage und Meeting.",
    ]

