        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "你的代理能回答你录下的一切——「关于冻结日期我们定了什么」——并注明答案出自哪次会议、哪个时刻。它需要阅读会议的模型，而该功能目前已关闭。无论如何，任何内容都不会离开这台 Mac。",
