        "Sources": "来源",
        "Star meeting": "加星标",
        "Unstar meeting": "取消星标",
        "Export transcript…": "导出转录…",
        "Still recording": "仍在录制",
        "Got it": "知道了",
        "Call": "通话",
        "Dictating": "听写中",
        "Dictating in %@": "正在用%@听写",
        "Translating into English": "正在翻译成英语",
        "Translating into %@": "正在翻译成%@",
        "Release %@ to insert": "松开 %@ 即插入",
