        "Dictate is running from its disk image": "Dictate 正从磁盘映像运行",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "从磁盘映像授予的权限在推出后即会丢失，且每次都要重新下载模型。请先将 Dictate 移到“应用程序”文件夹。",
