        "Not set": "未设置",
        "Remove": "移除",
        "Download & continue": "下载并继续",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "约 %@——只需下载一次。这是 Dictate 唯一需要联网的时刻。",
        "Hold %@ and say something — the recognized text shows up below.": "按住 %@ 说点什么——识别出的文字会显示在下方。",
        "Recognized text appears here…": "识别出的文字将显示在这里…",
        // Menu bar
