        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "“辅助功能”权限已关闭，因此无法监听按键。请在系统设置 → 隐私与安全性 → 辅助功能中打开——Dictate 会自动生效，无需重启。",
