        "Left Shift (⇧)": "左 Shift (⇧)",
        "Right Control (⌃)": "右 Control (⌃)",
        "Left Control (⌃)": "左 Control (⌃)",
        "Space": "空格键",
        "Follow system": "跟随系统",
        "Translating…": "正在翻译…",
        "Tip: hold %@ instead — your speech comes out in English.": "提示：改按住 %@——你的话会以英文输入。",
        "Hold to talk in your language, release to insert it in English.": "按住并用你的语言说话，松开后以英文插入。",
        "Hold %@ and say it again — this time it's typed in English.": "按住 %@ 再说一遍——这次输入的是英文。",
        "Translate to": "翻译成",
        "Translation data isn't downloaded — open Settings to get it": "翻译数据尚未下载 — 请在设置中下载",
        "Translation data": "翻译数据",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "翻译键先把你的话转成文字，再由 macOS 在这台 Mac 上翻译。选择语言时，macOS 可能会一次性下载该语言的翻译数据。",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "识别在你 Mac 的神经网络引擎上运行——Whisper large-v3-turbo：支持 100 种语言，对口音很友好，快到足以实时显示文字。翻译同样在这台 Mac 上完成。你的声音永远不会离开这台电脑。",
        "Hold %@ and say it again — this time it comes out in %@.": "按住 %@ 再说一遍——这次输出的是 %@。",
        "Hold to talk in your language, release to insert it in %@.": "按住并用你的语言说话，松开后以 %@ 插入。",
        "Not downloaded": "未下载",
        "Translation languages": "翻译语言",
        "Downloaded": "已下载",
        "Manage in System Settings…": "在系统设置中管理…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "系统设置里已开启，这里却不变绿？把 Dictate 的开关关掉再打开——应用更新后 macOS 有时会保留过期的记录。",
        "Agent: %@, on your key.": "代理：%@，使用你的密钥。",
        "Agent: off.": "代理：已关闭。",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "Apple Intelligence 在这台 Mac 上不支持当前地区或语言。使用你自己密钥的代理仍然可用。",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence 需要 macOS 26。使用你自己密钥的代理仍然可用。",
        "Copy diagnostics": "拷贝诊断信息",
        "Debug audio dumps": "调试音频转储",
        "Diagnostics": "诊断",
        "Downloading…": "正在下载…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "释放 %@。在你重新下载之前，新会议将继续以日期命名。已写好的摘要保留。",
        "Frees %@. Nothing else changes — reading your meetings is off.": "释放 %@。其他一切不变——阅读会议已关闭。",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "释放 %@。标题和摘要将由 Apple Intelligence 生成。",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "已安装但未运行：这台 Mac 有 %d GB 内存，而它需要 16 GB。",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "已安装但未运行：这台 Mac 有 %d GB 内存，而它需要 16 GB。这台 Mac 上没有任何东西在阅读会议。",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "已安装但未运行：这台 Mac 有 %d GB 内存，而它需要 16 GB。标题和摘要改由 Apple Intelligence 生成。",
        "Installed · %@": "已安装 · %@",
        "Installed, not in use · %@": "已安装，未使用 · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "写的时候它约占用 %@ 内存，这台 Mac 会有感觉。",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac、macOS、版本以及已开启的功能。不含转录文字，不含密钥。",
        "Meeting archive": "会议归档",
        "Meeting model": "会议模型",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "会议模型已安装。新会议将在这台 Mac 上获得标题和摘要。",
        "Meeting reading: Apple Intelligence.": "会议阅读：Apple Intelligence。",
        "Meeting reading: nothing on this Mac can do it yet.": "会议阅读：这台 Mac 上尚无可用的方式。",
        "Meeting reading: the downloaded model (%@).": "会议阅读：已下载的模型 (%@)。",
        "Not available on this Mac.": "在这台 Mac 上不可用。",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "未安装。一次性下载 %@ 后，即可生成标题、摘要和目录。",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "这台 Mac 上尚无可用的阅读方式：Apple Intelligence 在此不可用。使用你自己密钥的代理仍然可用。",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "这台 Mac 上尚无可用的阅读方式：在下方下载会议模型，或为代理添加密钥。",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "这台 Mac 上尚无可用的阅读方式：在下方下载会议模型，或在系统设置中开启 Apple Intelligence。",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "这台 Mac 上尚无可用的阅读方式：macOS 仍在设置 Apple Intelligence。使用你自己密钥的代理仍然可用。",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "这台 Mac 上尚无可用的阅读方式：在系统设置中开启 Apple Intelligence，或为代理添加密钥。",
        "Open System Settings": "打开系统设置",
        "Paused: not enough free memory right now. It resumes on its own.": "已暂停：当前可用内存不足。它会自行恢复。",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "正在为这台 Mac 的处理器准备模型…几分钟，仅此一次。",
        "Raw call audio kept for debugging only.": "仅为调试保留的原始通话音频。",
        "Reading is on, but nothing on this Mac can read yet.": "阅读已开启，但这台 Mac 上尚无可用的阅读方式。",
        "Reads with Apple Intelligence.": "使用 Apple Intelligence 阅读。",
        "Reads with the downloaded model.": "使用已下载的模型阅读。",
        "Recognition runs on the Neural Engine.": "识别在 Neural Engine 上运行。",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "识别在这台 Mac 的处理器上运行——Whisper large-v3-turbo：支持 100 种语言，对口音很友好。比 Apple Silicon 慢，翻译同样在这台 Mac 上完成。你的声音永远不会离开这台电脑。",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "识别在这台 Mac 的处理器上运行——比 Apple Silicon 慢。",
        "Remove the debug audio dumps?": "删除调试音频转储？",
        "Remove the meeting model?": "删除会议模型？",
        "Remove…": "删除…",
        "Speaker models": "说话人模型",
        "Speech model": "语音模型",
        "Storage": "存储",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "这台 Mac 上的摘要由 Apple Intelligence 生成。可下载的模型需要 16 GB 内存；这台 Mac 有 %d GB。",
        "Summary paused: not enough free memory. It resumes on its own.": "摘要已暂停：可用内存不足。它会自行恢复。",
        "Tell the voices on a call apart.": "分辨通话中的不同声音。",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "会议模型需要 16 GB 内存；这台 Mac 有 %d GB。",
        "These are recordings kept only for debugging. Nothing else is affected.": "这些是仅为调试保留的录音。其他一切不受影响。",
        "This Mac": "这台 Mac",
        "This build of Dictate does not include the meeting model.": "此版本的 Dictate 不包含会议模型。",
        "Titles and summaries come from Apple Intelligence instead.": "标题和摘要改由 Apple Intelligence 生成。",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "在系统设置 › Apple Intelligence 与 Siri 中开启 Apple Intelligence，或为代理添加密钥。",
        "Waiting for the call to end.": "等待通话结束。",
        "Your transcripts, as Markdown files you own.": "你的转录文字，以属于你的 Markdown 文件保存。",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS 仍在设置 Apple Intelligence——稍后再来看看，或为代理添加密钥。",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@。报告无论如何都留在会议文件中；此操作只是生成一份副本。",
