        "Purpose": "目的",
        "Risks and concerns": "风险与顾虑",
        "The main arguments and facts, with the numbers, names and dates that were said": "主要论点和事实，包括说到的数字、姓名和日期",
        "The next meeting or checkpoint, if one was agreed": "下次会议或检查点（如已约定）",
        "Waiting on": "等待对方",
        "We are the team on this call; the reader took part in it.": "我们是这次通话中的团队；读者参与了通话。",
        "What could go wrong, who raised it, how serious it sounded": "可能出问题的地方、由谁提出、听起来有多严重",
        "What each side is waiting for from the other": "双方各自在等待对方的什么",
        "What was decided, by whom, and what it replaces": "决定了什么、由谁决定、取代了什么",
        "What was raised and not settled, and who owns it": "提出但未解决的事项，以及由谁负责",
        "Who does what, by when — one line per task": "谁做什么、何时完成——每项一行",
        "Why we met and what we set out to settle": "我们为什么开会、打算解决什么",
        "%d more": "还有 %d 位",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "标题保留会议的语言；摘要和所有报告都用此语言撰写。报告中的字段名保持原样。",
        "About “%@”:": "关于“%@”：",
        "Replace the report with a new “%@” one?": "用新的“%@”报告替换现有报告？",
        "Replace report": "替换报告",
        "Written · replaces it": "已写 · 将被替换",
        "Dictate updated to %@.": "Dictate 已更新到 %@。",
        "Dismiss": "关闭",
        "New": "新",
        "New in this version": "本版本新增",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "打开一个会议，点击标题栏中的 Write report，然后选择模板。报告会出现在卡片上，并以 PDF 形式保存在 Dictate Meetings › Reports。",
        "Reports from templates": "模板报告",
        "See what’s new": "查看新功能",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "设置 › 会议 › 摘要和报告的语言：无论通话使用什么语言，摘要和所有报告都用你阅读的语言生成。",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "设置 › 模板：从“会议纪要”或“决定与行动项”开始，或自定义字段并告诉模型每个字段下写什么。",
        "Summaries in your language": "用你的语言写摘要",
        "What’s new": "新功能",
        "What’s new in Dictate %@": "Dictate %@ 新功能",
        "Your own templates": "你自己的模板",
        "Install update %@ and relaunch": "安装更新 %@ 并重新启动",
        "The update waits until the recording ends.": "更新将等到录音结束。",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "更新 %@ 正在下载。它会在下一个空闲时刻自动安装；菜单栏可以提前安装。",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "更新 %@ 已就绪：可从菜单栏安装，或者它会在下一个空闲时刻自动安装。",
        "An update is already on its way — it installs itself at the next quiet moment.": "更新已在下载中，会在下一个空闲时刻自动安装。",
        "Downloading update %@…": "正在下载更新 %@…",
        "Preparing update %@…": "正在准备更新 %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate 已更新到 %@。新功能见“会议”窗口。",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence 拒绝为这次会议生成摘要。",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "转录、搜索和代理不受影响。可下载的模型保存在这台 Mac 上，没有这种限制。",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "会议被记录并结构化：说话人、摘要、大纲、搜索。Dictate 会提议录制通话——没有你的答复绝不录制。",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "会议模型需要 16 GB 内存；这台 Mac 有 %d GB。它没有在运行，占用的 %@ 磁盘空间可以释放。",
        "Clipboard restored.": "剪贴板已恢复。",
        "Your words were inserted untranslated.": "你的话已按原文插入，未翻译。",
        "A small panel appears when a call starts, and you decide there.": "通话开始时会出现一个小面板，由你当场决定。",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "撰写摘要和大纲，并让代理有内容可答。无论如何都不会向任何地方发送内容。",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "关闭时只有你自己的麦克风；开启后对方也会被转录。",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "把一整块文字变成带名字的发言。区分按音色进行，可能不够精确；名字可以修改。",
        "Find in this transcript…": "在此转录中查找…",
        "%d of %d": "第 %d 个，共 %d 个",
        "No matches": "没有匹配项",
        "Previous match": "上一个匹配项",
        "Next match": "下一个匹配项",
        "Close find": "关闭查找",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "已选择 %@，但还没有密钥。添加密钥之前，代理和报告保持关闭。",
        "%@ · required for dictation, cannot be removed.": "%@ · 听写所必需，无法移除。",
        "%@ — not written": "%@ — 未写出",
        "%d h": "%d 小时",
        "%d meetings have a %@ report. They stay if this template goes.": "%d 场会议有「%@」报告。删除此模板后它们仍保留。",
        "%d min ago": "%d 分钟前",
        "%d written": "已写出 %d 份",
        "%d written, %d not written": "已写出 %d 份，未写出 %d 份",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 种语言。立即应用于此窗口和菜单栏。您说的语言在「听写」中设置。",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "来自您自己 %@ 账户的密钥。保存在钥匙串中，绝不写入设置文件。",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "提问会发送问题和搜索找到的段落。报告会发送该会议的完整转录——一小时谈话约 12,000 词。两者都通过您的密钥发送到 %@，且仅在您请求时。录音绝不会离开这台 Mac。",
        "About": "关于",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "这台 Mac 上无法使用 Apple Intelligence，因此没有备用方案。",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence 需要比这台 Mac 更新的 macOS，因此没有备用方案。",
        "Applies to this window, the meetings window and the panels over your other apps.": "应用于此窗口、会议窗口以及覆盖在其他应用上的面板。",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "只问一次。此后面板为简短版本，并一直保留到您作答。通话中的任何时候，您也可以从菜单栏开始录音。",
