        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "保存在这场会议的文件内，随转录一起移动。导出会在您选择的位置生成副本。",
        "No report": "无报告",
        "No report for this meeting yet.": "这场会议还没有报告。",
