        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "这里不设置任何内容。上面的每一行要么说明这台 Mac 能做什么，要么指向负责它的面板。",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "这台 Mac 上还没有什么能阅读会议：Apple Intelligence 需要更新的 macOS。使用您自己密钥的代理仍然可用。",
        "Nothing was kept from this take — earlier ones are still here.": "这次没有保留任何内容——之前的仍在这里。",
