        "Off — dictation cannot type": "已关闭——听写无法输入",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "关闭：转录、摘要、大纲和搜索照常工作。代理可回答关于所有会议的问题并按您的模板撰写报告；它使用您自己的 API 密钥在云端运行。",
        "On this Mac": "在这台 Mac 上",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "单个可续传文件。关闭 Dictate 会暂停下载，之后从停止处继续。",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "一次性下载 %@，之后标题、摘要和大纲完全在这台 Mac 上生成。运行需要 16 GB 内存，写作时占用约 %@。",
        "Open System Settings…": "打开系统设置…",
        "Or start from the menu bar later in the call.": "或稍后在通话中从菜单栏开始。",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "当前已暂停：可用内存不足。它会自行恢复，等待摘要的会议保留其转录。",
        "Permissions": "权限",
        "Reads with Apple Intelligence until the download finishes.": "下载完成前使用 Apple Intelligence 阅读。",
        "Reads with the downloaded model — paused until there is free memory.": "使用已下载的模型阅读——已暂停，直到有可用内存。",
        "Report templates are under Templates; written reports are in the library, under Reports.": "报告模板在「模板」中；已写出的报告在资料库的「报告」中。",
        "Report · %@": "报告 · %@",
        "Report · %@ +%d": "报告 · %@ +%d",
