        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "完全在这台 Mac 上运行。没有它，标题和摘要来自 Apple Intelligence。",
        "Startup": "启动",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "保存在钥匙串中，绝不写入设置文件。代理可回答关于所有会议的问题并按您的模板撰写报告。",
        "Summaries": "摘要",
        "Summaries & reports": "摘要与报告",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "下载是在没有 Apple Intelligence 的情况下在这台 Mac 上获得摘要的方式。转录和搜索无论如何都可用。",
        "This Mac was offline. Nothing was sent.": "这台 Mac 处于离线状态。未发送任何内容。",
