        "What’s new in %@": "%@ 的新功能",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "是否有任何东西阅读这些录音——摘要、大纲、报告和代理——在「摘要与报告」中设置。此面板只关乎在这台 Mac 上录制什么。",
        "Write again": "重新写",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "上方的「写报告」列出您的 %d 个模板。写一份会通过您的密钥把此转录发送给 %@；报告保存在这场会议的文件内，随转录一起移动。导出会在您选择的位置生成副本。",
