        "click to insert": "点按以插入",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS 仍在设置 Apple Intelligence。这可能需要一段时间，无法从这里加快。",
        "macOS resets this switch after some updates and never asks a second time.": "某些更新后 macOS 会重置此开关，并且不会再次询问。",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-点按则改为拷贝。Dictate 退出时清除。",
