        "All reports": "全部报告",
        "Answer": "回答",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "由 %@ 作答，查阅了 %d 场会议（共 %d 场）。引文逐字取自这台 Mac 上的转录。",
