        "Copy as plain text": "拷贝为纯文本",
        "Copy the answer only": "仅拷贝回答",
        "Copy with quotes": "连同引文拷贝",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "每个模板保存自己的报告：已写出的，以及可以写出报告的会议。模板本身在「设置 › 模板」中编辑。",
        "Edit template…": "编辑模板…",
        "No report yet · %d meetings": "尚无报告 · %d 场会议",
