        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "发送 %d 份转录给 %@（使用您的密钥）——约 %@ 词。每份报告保存在其会议文件内。录音绝不会离开这台 Mac。",
        "The %d existing reports are overwritten. This cannot be undone.": "现有的 %d 份报告将被覆盖。此操作无法撤销。",
