        "Write a “%@” report for “%@”?": "写「%@」报告，会议「%@」？",
        "Write all %d…": "全部写出（%d）…",
        "Write for a selection…": "为所选会议写出…",
        "Write report › %@": "写报告 › %@",
        "Written": "已写出",
        "No instruction — goes by its name alone": "无说明——仅按名称",
        "Drag to reorder": "拖动以调整顺序",
        "Every report is kept inside its meeting’s file.": "每份报告都保存在其会议文件内。",
        "A refusal stops that meeting only; the rest continue.": "拒绝只会停止那一场会议，其余继续。",
        "Always assume": "始终假定",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "通话中从未说出、但每份报告都应视为前提的事实：您是谁，哪一方是客户，您的团队对哪些词有特定用法。随此模板的每份报告发送。",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "可选。没有它，模型会从零读通话：同事之间的会议通常没问题，与外部方的通话则会出错。",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "我们是销售代理。客户始终是对方，绝不是我们。「席位」指付费用户许可。",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "显示在会议卡片、资料库的「报告」中，以及写出的报告内的标题处。",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "每个字段按此顺序成为报告中的一个标题。拖动字段的手柄可移动它。说明可选，可以按需写长；没有说明的字段仅按名称处理。",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "每个字段只从本次通话的转录中填写。通话未涉及的字段显示「Not discussed」。",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "模板由名称和几个字段组成。报告按需据此写出，每场会议每个模板一份。",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "还没有模板。模板由名称和几个字段组成；报告按需从会议卡片据此写出，每场会议每个模板一份。",
    ]

