        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "システムオーディオの録音が許可されていません。システム設定 → プライバシーとセキュリティ → 画面収録とシステムオーディオで Dictate を有効にして、もう一度お試しください。",
