        "Sorry, I didn't catch that — could you say it again?": "すみません、聞き取れませんでした — もう一度お願いします",
        "Not inserted — text copied, press ⌘V to paste": "挿入されませんでした — テキストをコピー済み、⌘V で貼り付け",
