        "Downloaded %d of %d MB": "%d / %d MB をダウンロード済み",
        "Preparing the model for the Neural Engine… A few minutes, one time.": "Neural Engine 用にモデルを準備しています… 数分かかりますが、一度だけです。",
        "Warming up the model…": "モデルをウォームアップ中…",
        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate はダウンロードしたイメージから起動されています。「アプリケーション」にドラッグし、イメージを取り出してからそこから起動してください。この一時コピーに与えた権限は保持されません。",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "まだ進めない？権限をリセットしてください。macOS の壊れた記録が消去されるので、新しいダイアログで許可し直してください。",
