        "Dark": "ダーク",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate はマイクと通話の音声を録音し、文字起こしをこの Mac に保存します。他の人を録音するには、地域によっては相手の同意が必要です。",
        "Don't Record": "録音しない",
