        "Check Audio Setup": "オーディオ設定を確認",
        "Clear All Filters": "すべてのフィルタを解除",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "Fキーはシステム操作（輝度・メディア）も兼ねています — macOS は両方を実行します。通常のキーとして使うには、キーボード設定で「Use F1, F2, etc. as standard function keys」をオンにしてください。",
        "How this works": "仕組み",
        "Input device changed": "入力デバイスが変わりました",
        "Insert text by": "テキストの挿入方法",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "接続後に失効または差し替えられています。キーチェーンから削除しました — このキーで再送信は行っていません。",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "ブラウザで通話に参加し、録音を開始してください。Dictate はマイクと通話音声を取り込み、両方をこの Mac 上で文字起こしし、ここに保存します。何もアップロードされません。",
        "No meeting has all of these tags": "これらのタグをすべて持つミーティングはありません",
        "No meeting has this tag": "このタグを持つミーティングはありません",
        "Nothing was said, or nothing was heard": "何も話されなかったか、何も聞こえませんでした",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "ここには未確定の末尾だけが表示されます — 残りはすでに書類の中にあります",
        "Open Console": "コンソールを開く",
        "Open Settings": "設定を開く",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "ペーストは瞬時ですが、一瞬クリップボードを使います。タイプ入力は、ペーストを受け付けない一部のターミナルやリモートデスクトップでも機能します。",
        "Pasting it at once": "一括でペースト",
        "Recording ended here — this Mac went to sleep.": "録音はここで終了 — この Mac はスリープしました。",
        "Remove “%@”": "「%@」を外す",
        "Return sends · Shift-Return adds a line · Esc clears": "Return で送信 · Shift-Return で改行 · Esc でクリア",
        "Show Floating Timer": "フローティングタイマーを表示",
        "Start Recording a Meeting": "ミーティングを録音",
        "Still recognizing the previous dictation": "前の音声入力をまだ認識中",
        "Still recognizing the previous dictation · %d words": "前の音声入力をまだ認識中 · %d 語",
        "Switched to %@": "%@ に切り替わりました",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "タグフィルタは「かつ」で組み合わされます — 選んだタグをすべて持つミーティングだけが表示されます。",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "回答が途中で止まりました。質問は上に残っています — 接続が戻ったら再試行してください。検索と文字起こしは使えます。",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "録音は行われましたが、どちら側の音声も認識されませんでした。多くの場合、通話音声が取り込まれていません — 音声権限のないブラウザタブか、出力デバイスの誤りです。",
        "The saved key no longer works": "保存されたキーが使えなくなりました",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "System Settings › Privacy & Security › Calendars で許可されるまでスイッチはオフのままです。読み取るのは録音と重なるイベントのタイトルだけです。",
        "This Mac is offline": "この Mac はオフラインです",
        "Too many questions at once": "一度に質問が多すぎます",
        "Typing as you speak": "話しながら入力中",
        "Typing into %@ as you speak": "話しながら %@ に入力中",
        "Typing it out character by character": "一文字ずつタイプ",
        "Your provider account is out of credit": "プロバイダのアカウントのクレジットが不足しています",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "プロバイダがレート制限中です。数秒待って再試行してください — 何も失われていません。",
        "macOS denied calendar access": "macOS がカレンダーへのアクセスを拒否しました",
        "API key": "APIキー",
        "All Meetings": "すべてのミーティング",
        "Assistant": "アシスタント",
        "Checking the key with %@. No transcript is sent — only a test request.": "%@ でキーを確認しています。文字起こしは送信されません — テストリクエストのみです。",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "ウインドウを閉じても録音は止まりません。ここで停止するか、いつでもメニューバーから停止できます。",
        "Connect an assistant to answer questions": "アシスタントを接続して質問に答える",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate はブラウザ通話を録音し、文字起こしをこの Mac に保存できます。次の通話が始まったらメニューバーから開始してください — 同意は一度だけ求められます。",
        "Done": "完了",
        "Every change takes effect immediately.": "変更はすべて即座に反映されます。",
        "Get one at %@.": "%@ で取得できます。",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "キーを押しながら話し、離すだけ。話した内容が、この Mac のどのアプリでもカーソルの位置に入力されます。",
        "Keys": "キー",
        "Languages": "言語",
        "Library": "ライブラリ",
        "Paste a key from your own account.": "自分のアカウントのキーを貼り付けてください。",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "キーチェーンに保存されましたが未確認です — この Mac はオフラインです。最初の質問時に確認されます。",
        "Set Up Dictate": "Dictate を設定",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "この Mac の macOS キーチェーンに保存されます。設定ファイルに書き込まれることも、同期されることもありません。",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "キーが拒否されました。失効している、別のプロバイダのもの、またはクレジット切れの可能性があります — キー自体は保存されていません。",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "文字起こし・検索・引用はこれなしで動作します。アシスタントは回答を書くためだけに必要です。",
        "Try Again": "再試行",
        "Updates": "アップデート",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "質問ごとにプロバイダへ支払います — 通常は1セント未満です。送信されるのは質問と引用箇所のみで、録音がこの Mac の外に出ることはありません。",
        "Send": "送信",
        "Conversations": "会話",
        "New question": "新しい質問",
        "Deleted “%@”": "「%@」を削除しました",
        "Undo": "取り消す",
        "Questions you ask are kept here so you can return to an answer.": "質問はここに保存され、回答にいつでも戻れます。",
        "Rename": "名称変更",
        "Delete": "削除",
        "Voices are matched by sound — the name applies only to this voice's turns.": "声は音で照合されます — 名前はこの声の発言にのみ適用されます。",
        "Give two voices the same name to merge them.": "二つの声に同じ名前を付けるとまとめられます。",
        "Voices are told apart by sound — one person can show up as two.": "声は音で聞き分けられます — 一人が二人として表示されることがあります。",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "名前をクリックすると声の名前を変えられます — 同じ名前を付けると二つが一つにまとまります。要約と回答は、誰が言ったかではなく、何が言われたかに基づきます。",
        "Voice separation improves over time.": "声の聞き分けは時間とともに改善されます。",
        "About voice separation": "声の聞き分けについて",
        "Call · voice %d": "通話 · 声 %d",
        "Starred": "スター付き",
        "Other browser calls": "その他のブラウザ通話",
        "Sources": "ソース",
        "Star meeting": "スターを付ける",
        "Unstar meeting": "スターを外す",
        "Export transcript…": "文字起こしを書き出す…",
        "Still recording": "録音は継続中",
        "Got it": "了解",
