        "Release %@ to insert": "%@を離すと挿入",
        "Also recording this meeting": "このミーティングも録音中です",
        "%@ MB/s · about %@ left": "%@ MB/秒 · 残り約%@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "ディスク空き容量が不足：ダウンロードには約%d MB必要ですが、空きは%d MBです。空き容量を確保して再試行してください。",
        "Fix…": "修正…",
        "Checked automatically · last %@": "自動チェック · 前回: %@",
        "Source code": "ソースコード",
        "Report an issue": "問題を報告",
        "Finishing the transcript…": "文字起こしを仕上げています…",
        "Disk almost full — will stop to keep the transcript": "ディスクがほぼ満杯です — 記録を守るため停止します",
        "Dictate is running from its disk image": "Dictateはディスクイメージから実行されています",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "ディスクイメージから付与した権限は取り出すと失われ、モデルも毎回ダウンロードし直しになります。まずDictateをアプリケーションフォルダに移動してください。",
        "Move to Applications": "アプリケーションに移動",
        "Quit": "終了",
        "Couldn't move Dictate automatically": "Dictateを自動的に移動できませんでした",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "ディスクイメージからDictateをアプリケーションフォルダにドラッグし、そこから起動してください。",
        "OK": "OK",
        "Inserted into %@": "%@に挿入しました",
        "Inserted": "挿入しました",
        "Accessibility is off — dictation can hear you but cannot type": "アクセシビリティがオフです — 音声は聞こえますが入力できません",
        "Open Privacy & Security…": "「プライバシーとセキュリティ」を開く…",
        "1 dictation still being recognized": "1件の音声入力を認識中",
        "%d dictations still being recognized": "%d件の音声入力を認識中",
        "Language Packs…": "言語パック…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "オフにすると、Dictateはメニューバーのみになります。Dockアイコンをクリックするとミーティングが開きます。メニューバーのアイコンは常に表示されます。",
        "Interface language": "インターフェイスの言語",
        "Granted": "許可済み",
        "No": "いいえ",
        "Model ready": "モデルは準備完了",
        "On-device recognition": "デバイス上での認識",
        "Spoken language": "話す言語",
        "Download failed. Check your connection and retry.": "ダウンロードに失敗しました。接続を確認して再試行してください。",
        "Not set": "未設定",
        "Remove": "削除",
        "Download & continue": "ダウンロードして続ける",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "約 %@。ダウンロードは 1 回だけです。Dictate がインターネットを必要とするのはこのときだけです。",
        "Hold %@ and say something — the recognized text shows up below.": "%@ を押しながら何か話してみてください。認識されたテキストが下に表示されます。",
        "Recognized text appears here…": "認識されたテキストがここに表示されます…",
        // Menu bar
        "Settings…": "設定…",
        "Quit Dictate": "Dictate を終了",
        "Dictate — voice dictation": "Dictate — 音声入力",
        // HUD
        "Recognizing…": "認識中…",
        "Esc to cancel": "Escでキャンセル",
        // Errors
        "Couldn't start recording: %@": "録音を開始できませんでした: %@",
        "Recording truncated at %d seconds (limit)": "録音は %d 秒で打ち切られました（上限）",
        "Audio device changed during recording — recording cancelled, please try again.": "録音中にオーディオデバイスが変わったため、録音をキャンセルしました。もう一度お試しください。",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "「アクセシビリティ」の許可がオフのため、キーを検知できません。システム設定 → プライバシーとセキュリティ → アクセシビリティでオンにしてください。Dictate が自動的に認識するので、再起動は不要です。",
        "Microphone unavailable (no input audio format)": "マイクを使用できません（入力オーディオフォーマットがありません）",
        // Key names
        "Right Option (⌥)": "右 Option (⌥)",
        "Left Option (⌥)": "左 Option (⌥)",
        "Right Command (⌘)": "右 Command (⌘)",
        "Left Command (⌘)": "左 Command (⌘)",
        "Right Shift (⇧)": "右 Shift (⇧)",
        "Left Shift (⇧)": "左 Shift (⇧)",
        "Right Control (⌃)": "右 Control (⌃)",
        "Left Control (⌃)": "左 Control (⌃)",
        "Space": "スペース",
        "Follow system": "システムに合わせる",
        "Translating…": "翻訳中…",
        "Tip: hold %@ instead — your speech comes out in English.": "ヒント: 代わりに %@ を押し続けると、話した内容が英語で入力されます。",
        "Hold to talk in your language, release to insert it in English.": "押しながら母語で話し、離すと英語で挿入されます。",
        "Hold %@ and say it again — this time it's typed in English.": "%@ を押しながらもう一度言ってみてください。今度は英語で入力されます。",
        "Translate to": "翻訳先",
        "Translation data isn't downloaded — open Settings to get it": "翻訳データが未ダウンロードです — 設定でダウンロードしてください",
        "Translation data": "翻訳データ",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "翻訳キーはまず発話を文字起こしし、その後 macOS がこの Mac 上で翻訳します。言語を選ぶと、macOS が翻訳データを一度だけダウンロードすることがあります。",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "認識は Mac の Neural Engine 上で動作します。Whisper large-v3-turbo は 100 言語に対応し、なまりにも強く、リアルタイム表示に十分な速さです。翻訳もこの Mac 上で行われます。あなたの声がこのコンピュータの外に出ることはありません。",
        "Hold %@ and say it again — this time it comes out in %@.": "%@ を押しながらもう一度言ってみてください。今度は %@ で出力されます。",
        "Hold to talk in your language, release to insert it in %@.": "押しながら母語で話し、離すと %@ で挿入されます。",
        "Not downloaded": "未ダウンロード",
        "Translation languages": "翻訳言語",
        "Downloaded": "ダウンロード済み",
        "Manage in System Settings…": "システム設定で管理…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "システム設定ではオンなのにここが緑になりませんか？Dictate のスイッチを一度オフにしてオンに戻してください。アップデート後、macOS が古い項目を保持していることがあります。",
        "Agent: %@, on your key.": "エージェント: %@、あなたのキーで。",
        "Agent: off.": "エージェント: オフ。",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "この Mac では、この地域または言語で Apple Intelligence を利用できません。自分のキーを使うエージェントは引き続き使えます。",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence には macOS 26 が必要です。自分のキーを使うエージェントは引き続き使えます。",
        "Copy diagnostics": "診断情報をコピー",
        "Debug audio dumps": "デバッグ用音声ダンプ",
        "Diagnostics": "診断",
        "Downloading…": "ダウンロード中…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "%@ を解放します。もう一度ダウンロードするまで、新しいミーティングは日付の名前のままです。すでに書かれた要約は残ります。",
        "Frees %@. Nothing else changes — reading your meetings is off.": "%@ を解放します。ほかは何も変わりません — ミーティングの読み取りはオフです。",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "%@ を解放します。タイトルと要約は Apple Intelligence が書くようになります。",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "インストール済みですが動いていません: この Mac のメモリは %d GB で、必要なのは 16 GB です。",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "インストール済みですが動いていません: この Mac のメモリは %d GB で、必要なのは 16 GB です。この Mac でミーティングを読むものはありません。",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "インストール済みですが動いていません: この Mac のメモリは %d GB で、必要なのは 16 GB です。代わりにタイトルと要約は Apple Intelligence が書きます。",
        "Installed · %@": "インストール済み · %@",
        "Installed, not in use · %@": "インストール済み、未使用 · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "書いている間、約 %@ のメモリを使います。この Mac では体感できる量です。",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac、macOS、バージョン、オンになっている機能。文字起こしやキーは含まれません。",
        "Meeting archive": "ミーティングのアーカイブ",
        "Meeting model": "ミーティングモデル",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "ミーティングモデルをインストールしました。新しいミーティングには、この Mac 上でタイトルと要約が付きます。",
        "Meeting reading: Apple Intelligence.": "ミーティングの読み取り: Apple Intelligence。",
        "Meeting reading: nothing on this Mac can do it yet.": "ミーティングの読み取り: この Mac ではまだ何もできません。",
        "Meeting reading: the downloaded model (%@).": "ミーティングの読み取り: ダウンロード済みのモデル (%@)。",
        "Not available on this Mac.": "この Mac では利用できません。",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "未インストール。%@ を一度ダウンロードすれば、タイトル・要約・目次を書きます。",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "この Mac ではまだ何も読めません: ここでは Apple Intelligence を利用できません。自分のキーを使うエージェントは引き続き使えます。",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "この Mac ではまだ何も読めません: 下でミーティングモデルをダウンロードするか、エージェント用のキーを追加してください。",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "この Mac ではまだ何も読めません: 下でミーティングモデルをダウンロードするか、システム設定で Apple Intelligence をオンにしてください。",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "この Mac ではまだ何も読めません: macOS が Apple Intelligence をまだ準備中です。自分のキーを使うエージェントは引き続き使えます。",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "この Mac ではまだ何も読めません: システム設定で Apple Intelligence をオンにするか、エージェント用のキーを追加してください。",
        "Open System Settings": "システム設定を開く",
        "Paused: not enough free memory right now. It resumes on its own.": "一時停止中: 今は空きメモリが足りません。自動的に再開します。",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "この Mac のプロセッサ用にモデルを準備しています… 数分かかりますが、一度だけです。",
        "Raw call audio kept for debugging only.": "デバッグのためだけに保持している通話の生音声。",
        "Reading is on, but nothing on this Mac can read yet.": "読み取りはオンですが、この Mac ではまだ何も読めません。",
        "Reads with Apple Intelligence.": "Apple Intelligence で読みます。",
        "Reads with the downloaded model.": "ダウンロード済みのモデルで読みます。",
        "Recognition runs on the Neural Engine.": "認識は Neural Engine 上で動作します。",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "認識はこの Mac のプロセッサ上で動作します。Whisper large-v3-turbo は 100 言語に対応し、なまりにも強いモデルです。Apple Silicon より遅く、翻訳もこの Mac 上で行われます。あなたの声がこのコンピュータの外に出ることはありません。",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "認識はこの Mac のプロセッサ上で動作します — Apple Silicon より遅くなります。",
        "Remove the debug audio dumps?": "デバッグ用音声ダンプを削除しますか？",
        "Remove the meeting model?": "ミーティングモデルを削除しますか？",
        "Remove…": "削除…",
        "Speaker models": "話者モデル",
        "Speech model": "音声モデル",
        "Storage": "ストレージ",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "この Mac の要約は Apple Intelligence が書きます。ダウンロードできるモデルには 16 GB のメモリが必要ですが、この Mac は %d GB です。",
        "Summary paused: not enough free memory. It resumes on its own.": "要約を一時停止中: 空きメモリが足りません。自動的に再開します。",
        "Tell the voices on a call apart.": "通話の声を聞き分けます。",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "ミーティングモデルには 16 GB のメモリが必要ですが、この Mac は %d GB です。",
        "These are recordings kept only for debugging. Nothing else is affected.": "これらはデバッグのためだけに保持している録音です。ほかには何も影響しません。",
        "This Mac": "この Mac",
        "This build of Dictate does not include the meeting model.": "このビルドの Dictate にはミーティングモデルが含まれていません。",
        "Titles and summaries come from Apple Intelligence instead.": "代わりにタイトルと要約は Apple Intelligence が書きます。",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "システム設定 › Apple Intelligence と Siri で Apple Intelligence をオンにするか、エージェント用のキーを追加してください。",
        "Waiting for the call to end.": "通話の終了を待っています。",
        "Your transcripts, as Markdown files you own.": "あなたの文字起こしを、あなた自身が所有する Markdown ファイルとして。",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS が Apple Intelligence をまだ準備中です — 後でもう一度確認するか、エージェント用のキーを追加してください。",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@。レポートはいずれにせよミーティングのファイルに残ります。これはコピーを作ります。",
        "%d fields": "%d 項目",
        "Add field": "項目を追加",
        "Agent & reports": "エージェントとレポート",
        "Also one table (CSV): a row per meeting, a column per field": "加えて表を 1 つ（CSV）：ミーティングごとに 1 行、項目ごとに 1 列",
        "Answers with": "回答に使うもの",
        "Choose folder…": "フォルダを選択…",
        "Copy report": "レポートをコピー",
        "Date": "日付",
        "Export %d “%@” reports": "%d 件の“%@”レポートを書き出す",
        "Export reports…": "レポートを書き出す…",
        "Export report…": "レポートを書き出す…",
        "Export the “%@” report": "“%@”レポートを書き出す",
        "Field name": "項目名",
        "Fields": "項目",
        "Format:": "形式:",
        "Markdown": "Markdown",
        "Meeting": "ミーティング",
        "New template": "新規テンプレート",
        "New template…": "新規テンプレート…",
        "No reports written with “%@” yet.": "“%@”で書いたレポートはまだありません。",
        "No templates yet.": "テンプレートはまだありません。",
        "Not discussed": "未協議",
        "One empty field. You name it.": "空の項目が 1 つ。名前はあなたが付けます。",
        "One file per meeting, named by date and title, in a folder you choose. Transcripts are not included.": "ミーティングごとに 1 ファイル、日付とタイトルで名前を付け、選んだフォルダに保存します。文字起こしは含まれません。",
        "PDF": "PDF",
