        "Remove field": "項目を削除",
        "Remove template": "テンプレートを削除",
        "Remove template…": "テンプレートを削除…",
        "Remove “%@”?": "“%@”を削除しますか?",
        "Report": "レポート",
        "Report not written": "レポートは書かれませんでした",
        "Reports": "レポート",
        "Reports already written with it stay in their meetings.": "これで書いたレポートは、それぞれのミーティングに残ります。",
        "Same as Dictate": "Dictate と同じ",
        "Template name": "テンプレート名",
        "Templates": "テンプレート",
        "The model returned no report.": "モデルはレポートを返しませんでした。",
        "The model stopped before the report was finished.": "モデルはレポートを書き終える前に止まりました。",
        "The saved key no longer works. It has been removed from the Keychain.": "保存したキーが使えなくなりました。キーチェーンから削除されました。",
        "What is sent": "送られるもの",
        "Writing · about a minute": "作成中 · 約 1 分",
        "Written by Dictate on this Mac from the transcript": "この Mac 上で Dictate が文字起こしから作成",
        "Your %@ account refused the request for billing reasons.": "あなたの %@ アカウントが課金上の理由でリクエストを拒否しました。",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "この文字起こしをあなたのキーで %@ に送ります。レポートはミーティングのファイルに保存されます。",
        "Set up templates…": "テンプレートを設定…",
        "Write report": "レポートを書く",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@ がリクエストを制限しています。何も失われていません。1 分後にもう一度お試しください。",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "この Mac はオフラインです。何も送信されていません。接続が戻ってからもう一度お試しください。",
        "Write a “%@” report?": "「%@」レポートを書きますか？",
        "Action items": "アクション項目",
        "Dates and deadlines": "日付と期限",
        "Decisions": "決定事項",
        "Decisions & actions": "決定事項とアクション",
        "Every date, deadline or time window that was mentioned, and what it is for": "言及されたすべての日付・期限・時間枠と、それが何のためのものか",
        "Key points": "要点",
        "Meeting summary": "ミーティング要約",
        "Next step": "次のステップ",
        "Open questions": "未解決の質問",
        "Purpose": "目的",
        "Risks and concerns": "リスクと懸念",
        "The main arguments and facts, with the numbers, names and dates that were said": "主な論点と事実。発言された数字・名前・日付を含める",
        "The next meeting or checkpoint, if one was agreed": "次のミーティングやチェックポイント（合意があれば）",
        "Waiting on": "待ち事項",
        "We are the team on this call; the reader took part in it.": "私たちはこの通話のチームで、読者もこの通話に参加しました。",
        "What could go wrong, who raised it, how serious it sounded": "何がうまくいかない可能性があるか、誰が指摘したか、どれほど深刻に聞こえたか",
        "What each side is waiting for from the other": "各側が相手に何を待っているか",
        "What was decided, by whom, and what it replaces": "何が決まり、誰が決め、何に代わるのか",
        "What was raised and not settled, and who owns it": "提起されたが未解決の事項と、その担当者",
        "Who does what, by when — one line per task": "誰が何をいつまでに——1 タスク 1 行",
        "Why we met and what we set out to settle": "なぜ集まり、何を決めようとしたか",
        "%d more": "他 %d 人",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "タイトルはミーティングの言語のまま、要約とすべてのレポートはこの言語で書かれます。レポートの項目名は入力したままです。",
        "About “%@”:": "「%@」について：",
        "Replace the report with a new “%@” one?": "レポートを新しい「%@」レポートに置き換えますか？",
        "Replace report": "レポートを置き換える",
        "Written · replaces it": "作成済み · 置き換えます",
        "Dictate updated to %@.": "Dictate は %@ に更新されました。",
        "Dismiss": "閉じる",
        "New": "New",
        "New in this version": "このバージョンの新機能",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "ミーティングを開き、ヘッダーの Write report を押してテンプレートを選びます。レポートはカードに表示され、PDF として Dictate Meetings › Reports に保存されます。",
        "Reports from templates": "テンプレートからレポート",
        "See what’s new": "新機能を見る",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "設定 › ミーティング › 要約とレポートを書く言語：通話の言語にかかわらず、要約とすべてのレポートがあなたの読む言語で届きます。",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "設定 › テンプレート：「ミーティング要約」や「決定事項とアクション」から始めるか、独自の項目を名付けて、その下に何を書くかをモデルに伝えます。",
        "Summaries in your language": "あなたの言語で要約",
        "What’s new": "新機能",
        "What’s new in Dictate %@": "Dictate %@ の新機能",
        "Your own templates": "自分のテンプレート",
        "Install update %@ and relaunch": "アップデート %@ をインストールして再起動",
        "The update waits until the recording ends.": "アップデートは録音が終わるまで待ちます。",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "アップデート %@ をダウンロード中です。次の空いたタイミングで自動的にインストールされます。メニューバーからならすぐに実行できます。",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "アップデート %@ の準備ができました。メニューバーからインストールするか、次の空いたタイミングで自動的にインストールされます。",
        "An update is already on its way — it installs itself at the next quiet moment.": "アップデートはすでに進行中です。次の空いたタイミングで自動的にインストールされます。",
        "Downloading update %@…": "アップデート %@ をダウンロード中…",
        "Preparing update %@…": "アップデート %@ を準備中…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate は %@ に更新されました。新機能はミーティングウインドウにあります。",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence はこのミーティングの要約を拒否しました。",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "文字起こし、検索、エージェントは影響を受けません。この Mac に保存されるダウンロード版モデルにはこの制限がありません。",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "ミーティングを記録し構造化：話者、要約、アウトライン、検索。Dictate は通話の録音を提案するだけで、返答なしに録音することはありません。",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "ミーティングモデルには 16 GB のメモリが必要ですが、この Mac は %d GB です。動いておらず、ディスク上の %@ は解放できます。",
        "Clipboard restored.": "クリップボードを元に戻しました。",
        "Your words were inserted untranslated.": "話した内容は翻訳されずに挿入されました。",
        "A small panel appears when a call starts, and you decide there.": "通話が始まったときに小さなパネルが現れ、そこで決められます。",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "要約とアウトラインを書き、エージェントに答える材料を与えます。いずれにせよ、どこにも何も送信されません。",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "オフでは自分のマイクのみ、オンでは相手側も文字起こしされます。",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "ひとつの塊のテキストを名前付きの発言に変えます。聞き分けは音によるもので正確でないことがあり、名前は変更できます。",
        "Find in this transcript…": "この文字起こし内を検索…",
        "%d of %d": "%d / %d 件",
        "No matches": "一致なし",
        "Previous match": "前の一致",
        "Next match": "次の一致",
        "Close find": "検索を閉じる",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "%@ が選ばれていますが、キーがまだありません。キーを追加するまでエージェントとレポートはオフのままです。",
        "%@ · required for dictation, cannot be removed.": "%@ · 音声入力に必要なため削除できません。",
        "%@ — not written": "%@ — 未作成",
        "%d h": "%d 時間",
        "%d meetings have a %@ report. They stay if this template goes.": "%d 件のミーティングに「%@」レポートがあります。このテンプレートを削除しても残ります。",
        "%d min ago": "%d 分前",
        "%d written": "%d 件作成済み",
        "%d written, %d not written": "%d 件作成済み、%d 件未作成",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 言語。このウインドウとメニューバーにすぐ反映されます。話す言語は「音声入力」で設定します。",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "ご自身の %@ アカウントのキー。キーチェーンに保存され、設定ファイルには決して書かれません。",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "質問は、質問文と検索で見つかった箇所を送ります。レポートはそのミーティングの文字起こし全体を送ります — 1 時間の会話で約 12,000 語です。どちらもあなたのキーで %@ に、あなたが求めたときだけ送られます。録音がこの Mac を離れることはありません。",
        "About": "情報",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "この Mac では Apple Intelligence を利用できないため、代わりになるものがありません。",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence にはこの Mac より新しい macOS が必要なため、代わりになるものがありません。",
        "Applies to this window, the meetings window and the panels over your other apps.": "このウインドウ、ミーティングのウインドウ、ほかのアプリの上に出るパネルに適用されます。",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "尋ねるのは一度だけ。以後このパネルは短い版になり、答えるまで残ります。通話中はいつでもメニューバーから録音を始めることもできます。",
        "Calendar": "カレンダー",
        "Collapse %@": "%@ を折りたたむ",
        "Copy": "コピー",
        "Dictation": "音声入力",
        "Expand %@": "%@ を展開",
        "Export…": "書き出す…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "「最近の音声入力」にもあるので、クリップボードはいつでも自由に使えます。",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "このミーティングのファイル内に保存され、文字起こしと一緒に移動します。書き出すと好きな場所にコピーを作れます。",
        "No report": "レポートなし",
        "No report for this meeting yet.": "このミーティングのレポートはまだありません。",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "削除しても失われるものはありません。文字起こし、検索、エージェントはこれに依存しません。",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "ここでは何も設定しません。上の各行は、この Mac にできることを示すか、それを担当するパネルを指しています。",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "この Mac ではまだ何も読めません。Apple Intelligence には新しい macOS が必要です。ご自身のキーを使うエージェントは動作します。",
        "Nothing was kept from this take — earlier ones are still here.": "今回の分は何も残りませんでした — 以前のものはまだここにあります。",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "何も録音されなかったので、何も残りませんでした。以前のものはまだここにあります。",
        "Off — dictation cannot type": "オフ — 音声入力が文字を入力できません",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "オフ：文字起こし、要約、アウトライン、検索はこれまで通り使えます。エージェントはミーティング全体にわたる質問に答え、テンプレートからレポートを書きます。ご自身の API キーでクラウド上で動作します。",
        "On this Mac": "この Mac 上で",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "再開できる 1 つのファイルです。Dictate を終了すると一時停止し、止まったところから再開します。",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "%@ を一度ダウンロードすれば、タイトル、要約、アウトラインはすべてこの Mac 上で作られます。実行には 16 GB のメモリが必要で、書いている間は約 %@ を使います。",
        "Open System Settings…": "システム設定を開く…",
        "Or start from the menu bar later in the call.": "または通話の途中でメニューバーから始めることもできます。",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "現在一時停止中：空きメモリが足りません。自動的に再開し、要約を待つミーティングの文字起こしはそのまま残ります。",
        "Permissions": "アクセス権",
        "Reads with Apple Intelligence until the download finishes.": "ダウンロードが終わるまでは Apple Intelligence で読みます。",
        "Reads with the downloaded model — paused until there is free memory.": "ダウンロード済みのモデルで読みます — 空きメモリができるまで一時停止中。",
        "Report templates are under Templates; written reports are in the library, under Reports.": "レポートのテンプレートは「テンプレート」に、作成済みのレポートはライブラリの「レポート」にあります。",
        "Report · %@": "レポート · %@",
        "Report · %@ +%d": "レポート · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "レポートにはエージェントが必要ですが、オフになっています。「要約とレポート」で Claude または ChatGPT を選んでください。それまでテンプレートは保持されます。",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "すべてこの Mac 上で動作します。これがない場合、タイトルと要約は Apple Intelligence が作ります。",
        "Startup": "起動",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "キーチェーンに保存され、設定ファイルには決して書かれません。エージェントはミーティング全体にわたる質問に答え、テンプレートからレポートを書きます。",
        "Summaries": "要約",
        "Summaries & reports": "要約とレポート",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "ダウンロードすれば、Apple Intelligence なしでもこの Mac で要約が使えます。文字起こしと検索はどちらでも使えます。",
        "This Mac was offline. Nothing was sent.": "この Mac はオフラインでした。何も送信されていません。",
        "This take was not kept. Earlier ones are still here.": "今回の分は残りませんでした。以前のものはまだここにあります。",
        "Uses 41 MB of speaker models.": "41 MB の話者モデルを使います。",
        "What’s new in %@": "%@ の新機能",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "これらの録音を何かが読むかどうか — 要約、アウトライン、レポート、エージェント — は「要約とレポート」で設定します。このパネルはこの Mac で何を録音するかについてだけです。",
        "Write again": "もう一度作成",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "上の「レポートを作成」に %d 件のテンプレートが並びます。作成すると、この文字起こしがあなたのキーで %@ に送られます。レポートはこのミーティングのファイル内に保存され、文字起こしと一緒に移動します。書き出すと好きな場所にコピーを作れます。",
        "Written %@": "%@ に作成",
        "Written by %@": "%@ が作成",
        "Written by %@ %@ at %@": "%@ が %@ %@ に作成",
        "Written in": "書く言語",
        "Your agent, on your key": "あなたのエージェント、あなたのキーで",
        "click to insert": "クリックで挿入",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS はまだ Apple Intelligence を設定中です。時間がかかることがあり、ここからは急がせられません。",
        "macOS resets this switch after some updates and never asks a second time.": "macOS は一部のアップデート後にこのスイッチをリセットし、二度目は尋ねません。",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-クリックでコピー。Dictate の終了時に消去されます。",
        "Meeting names": "ミーティング名",
        "%d meetings, reports included": "%d 件のミーティング、レポートを含む",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "「要約とレポート」でミーティングモデルをダウンロードするか、エージェント用のキーを追加してください。",
        "Calls": "通話",
        "Reports folder": "レポートフォルダ",
        "%d PDFs written before %@": "%@ より前に作成された PDF %d 件",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate はもう自動で PDF を作成しません。これらはあなたのものです。残しても削除しても構いません。アプリ内で依存するものはありません。",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "作成済みのレポートは置き換えられます。この文字起こしをあなたのキーで %@ に送ります。",
        "%@ · report not written": "%@ · レポート未作成",
        "%d of %d selected · %d meetings without one": "%d / %d 件を選択 · レポートのないミーティング %d 件",
        "%d passages from %d meetings": "%d 箇所、%d 件のミーティングから",
        "%d written across %d templates": "%d 件作成済み、テンプレート %d 件",
        "%d written · %d meetings without one · %d fields": "%d 件作成済み · レポートのないミーティング %d 件 · フィールド %d 個",
        "%d written · writing %d · %d not written": "%d 件作成済み · 作成中 %d 件 · 未作成 %d 件",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "レポートは求めに応じて作成されます — ミーティングのカードから、またはここで選択したものに対して。それぞれがそのミーティングの文字起こしをあなたのキーで %@ に送り、ミーティングのファイル内に保存されます。",
        "All reports": "すべてのレポート",
        "Answer": "回答",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "%@ が回答、%d 件のミーティングを参照（全 %d 件中）。引用はこの Mac 上の文字起こしからそのまま引いています。",
        "Copy as Markdown": "Markdown としてコピー",
        "Copy as plain text": "プレーンテキストとしてコピー",
        "Copy the answer only": "回答のみコピー",
        "Copy with quotes": "引用付きでコピー",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "テンプレートごとにレポートが分かれています。作成済みのものと、作成できるミーティングです。テンプレート自体は「設定 › テンプレート」で編集します。",
        "Edit template…": "テンプレートを編集…",
        "No report yet · %d meetings": "レポートなし · %d 件のミーティング",
        "None written · %d fields": "未作成 · フィールド %d 個",
        "Nothing written from this template yet": "このテンプレートからはまだ何も作成されていません",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "オフの場合、その %d 件は飛ばして %d 件のレポートを作成します。置き換えは元に戻せません。",
        "Pick a template": "テンプレートを選択",
        "Quotes": "引用",
        "Replace the %d that already have one": "すでにある %d 件を置き換える",
        "Report not written — the request was refused. The meeting has the detail.": "レポート未作成 — リクエストが拒否されました。詳細はミーティングにあります。",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "%d 件の文字起こしを %@ にあなたのキーで送ります — 約 %@ 語。各レポートはそのミーティングのファイル内に保存されます。録音がこの Mac を離れることはありません。",
        "The %d existing reports are overwritten. This cannot be undone.": "既存の %d 件のレポートが上書きされます。元に戻せません。",
        "Write": "作成",
        "Write %d": "%d 件作成",
        "Write %d reports…": "%d 件のレポートを作成…",
        "Write a “%@” report for %d meetings?": "「%@」レポートを作成しますか？対象は %d 件のミーティングです。",
        "Write a “%@” report for “%@”?": "「%@」レポートを作成しますか？対象は「%@」です。",
        "Write all %d…": "%d 件すべて作成…",
        "Write for a selection…": "選択したものに作成…",
        "Write report › %@": "レポートを作成 › %@",
        "Written": "作成済み",
        "No instruction — goes by its name alone": "指示なし — 名前だけで判断",
        "Drag to reorder": "ドラッグして並べ替え",
        "Every report is kept inside its meeting’s file.": "すべてのレポートはそのミーティングのファイル内に保存されます。",
        "A refusal stops that meeting only; the rest continue.": "拒否されてもそのミーティングだけが止まり、残りは続きます。",
        "Always assume": "常に前提とする",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "通話では語られないが、どのレポートも前提とすべき事実：あなたは誰か、どちらが顧客か、チーム内で特別な意味で使う言葉。このテンプレートのすべてのレポートと一緒に送られます。",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "任意。なければモデルは前提なしに通話を読みます。同僚同士のミーティングなら大抵問題ありませんが、外部との通話では間違えます。",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "私たちは営業代理店です。顧客は常に相手側であり、私たちではありません。「シート」は有料ユーザーライセンスを指します。",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "ミーティングのカード、ライブラリの「レポート」、作成されたレポート内の見出しに表示されます。",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "各フィールドはこの順番でレポートの見出しになります。ハンドルをドラッグして移動します。指示は任意で、必要なだけ長くできます。指示のないフィールドは名前だけで判断されます。",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "各フィールドはこの通話の文字起こしからのみ埋められます。通話で触れられなかったフィールドは「Not discussed」になります。",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "テンプレートは名前といくつかのフィールドからなります。レポートは求めに応じてそこから作成され、ミーティングごとにテンプレートにつき 1 件です。",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "テンプレートはまだありません。テンプレートは名前といくつかのフィールドからなり、レポートはミーティングのカードから求めに応じて作成され、ミーティングごとにテンプレートにつき 1 件です。",
    ]

