        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate가 다운로드한 이미지에서 실행 중입니다 — «응용 프로그램»으로 드래그하고 이미지를 추출한 뒤 거기서 실행하세요. 이 임시 복사본에 부여한 권한은 유지되지 않습니다.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "여전히 안 되나요? 권한을 재설정하세요 — macOS의 손상된 기록이 삭제되며, 새 요청에서 다시 허용하면 됩니다.",
        "Words: %d · %.1f s": "단어: %d · %.1f초",
        "Words: %d": "단어: %d",
        "Cancelled": "취소됨",
        "Changed your mind? Esc cancels the recording.": "마음이 바뀌었나요? Esc로 녹음을 취소할 수 있습니다.",
        "About Dictate": "Dictate에 관하여",
        // Onboarding — general
        "Welcome to Dictate": "Dictate에 오신 것을 환영합니다",
        "Back": "뒤로",
        "Next": "다음",
        "Step %d of %d": "%d/%d 단계",
        // Welcome
        // Hotkey
        "Dictation key": "받아쓰기 키",
        "This key types characters — they'll end up in your text while you hold it. A modifier (Option, Cmd, Shift, Ctrl) or an F-key is safer.": "이 키는 문자를 입력하는 키라서 누르고 있는 동안 글자가 텍스트에 들어갑니다. 보조 키(Option, Cmd, Shift, Ctrl)나 F 키가 더 안전합니다.",
        // Permissions
        "Microphone": "마이크",
        "Accessibility": "손쉬운 사용(Accessibility)",
        // Settings
        "Dictate Settings": "Dictate 설정",
        "This key types characters — they'll go into the text during dictation. A modifier or F-key is better.": "이 키는 문자를 입력하므로 받아쓰기 중에 글자가 텍스트에 들어갑니다. 보조 키나 F 키가 더 좋습니다.",
        "Launch at login": "로그인 시 실행",
        "Show in Dock": "Dock에 표시",
        "The agent searches and reads your transcripts on this Mac, and every answer names the meetings it drew from.": "에이전트는 이 Mac에서 전사본을 검색하고 읽으며, 모든 답변은 근거가 된 회의를 밝힙니다.",
        "Undo remove": "제거 취소",
        "Call started": "통화가 시작됨",
        "Recording stopped by itself — the call ended.": "녹음이 스스로 중지되었습니다 — 통화가 끝났습니다.",
        "Recording stopped by itself — ten minutes of silence.": "녹음이 스스로 중지되었습니다 — 10분간 무음이었습니다.",
        "%@ call started": "%@ 통화가 시작됨",
        "Not this one": "이번은 아님",
        "Record": "녹음",
        "Record this call": "이 통화 녹음",
        "Dictation that works offline — recognition runs entirely on this Mac.": "오프라인으로 동작하는 받아쓰기 — 인식은 전부 이 Mac에서 이루어집니다.",
        "Translation that works offline — speak your language, another comes out.": "오프라인으로 동작하는 번역 — 내 언어로 말하면 다른 언어로 나옵니다.",
        "An optional agent that knows your meetings — answers quote the moment they came from.": "회의를 아는 선택형 에이전트 — 답변은 출처가 된 순간을 인용합니다.",
        "%d MB of %d MB": "%d MB / %d MB",
        "Already clicked and nothing changed?": "클릭했는데 아무 변화가 없나요?",
        "Applications": "응용 프로그램",
        "Downloading the speech model": "음성 모델 다운로드 중",
        "Grant…": "허용…",
        "Nothing here leaves this window. Two small things to try, then you are done.": "여기서의 내용은 이 창을 벗어나지 않습니다. 작은 시도 두 가지면 끝입니다.",
        "Resume Download": "다운로드 재개",
        "Show me where to look": "어디를 봐야 하는지 보기",
        "Start Dictate when I log in — it appears in the Dock and the menu bar, and the Dock icon can be hidden later in Settings": "로그인 시 Dictate 시작 — Dock과 메뉴 막대에 나타나며, Dock 아이콘은 나중에 설정에서 숨길 수 있습니다",
        "Start Using Dictate": "Dictate 사용 시작",
        "Stopped · %d MB of %d MB kept on disk": "중지됨 · %d MB / %d MB 디스크에 보관됨",
        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "연결이 끊겼습니다. 재개하면 멈춘 곳부터 이어집니다 — %d MB 전체를 다시 받지 않습니다.",
        "The download stopped at %d MB": "다운로드가 %d MB에서 멈췄습니다",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "이후 인식이 빠르도록 칩에 맞게 모델을 컴파일하는 중입니다. 첫 실행 시 1분 정도 걸리며 다시는 일어나지 않습니다.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "한 번만 일어나는 일입니다. 모델은 Mac에 남아 있어, 이후 받아쓰기가 인터넷 없이 동작하는 이유입니다.",
        "To hear you. Audio is processed on this Mac and discarded.": "당신의 말을 듣기 위해. 오디오는 이 Mac에서 처리된 뒤 폐기됩니다.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "인식된 텍스트를 사용 중인 앱에 입력하기 위해. 앱이 다른 곳에 텍스트를 넣을 수 있는 유일한 방법입니다.",
        "Try it here first": "먼저 여기서 해보세요",
        "Two permissions from macOS": "macOS의 두 가지 권한",
        "macOS asks for these, not us. Dictate cannot work without both.": "요청하는 것은 macOS이지 우리가 아닙니다. 둘 다 없으면 Dictate는 동작하지 않습니다.",
        "Show or hide the conversations": "대화 목록 표시 또는 가리기",
        "Show or hide the sidebar": "사이드바 표시 또는 가리기",
        "Show or hide the meeting list": "회의 목록 표시 또는 가리기",
        "Preparing the model for this Mac": "이 Mac에 맞게 모델 준비 중",
        "Not ready yet — this takes a few seconds after launch. Keep holding %@ and it will start.": "아직 준비되지 않았습니다 — 시작 후 몇 초 걸립니다. %@ 키를 계속 누르고 있으면 시작됩니다.",
        "Transcript text": "전사 텍스트",
        "Smaller text": "작은 텍스트",
        "Standard text": "표준 텍스트",
        "Larger text": "큰 텍스트",
        "100 languages · from your system settings": "100개 언어 · 시스템 설정 기준",
        "Add tag": "태그 추가",
        "Appearance": "화면 모드",
        "Asked once. After this, recording starts from the menu bar without a prompt. Esc means don't record.": "한 번만 묻습니다. 이후에는 메뉴 막대에서 확인 없이 녹음이 시작됩니다. Esc는 녹음하지 않겠다는 뜻입니다.",
        "Check for updates": "업데이트 확인",
        "Choose your keys and languages": "키와 언어 선택",
        "Click, then press a key": "클릭한 다음 키를 누르세요",
        "Dark": "다크",
        "Dictate will record your microphone and the audio from the call, and keep the transcript on this Mac. Recording other people may require their consent where you are.": "Dictate는 마이크와 통화 오디오를 녹음하고 전사본을 이 Mac에 보관합니다. 다른 사람을 녹음하려면 지역에 따라 동의가 필요할 수 있습니다.",
        "Don't Record": "녹음 안 함",
        "Hold the key while you speak. Anything can be changed later in Settings.": "말하는 동안 키를 누르고 계세요. 모두 나중에 설정에서 바꿀 수 있습니다.",
        "I speak": "사용하는 언어",
        "Light": "라이트",
        "Looking through %d meetings…": "회의 %d개 살펴보는 중…",
        "Match system": "시스템과 동일",
        "Modifier keys work best: they never insert a character when you hold them. Esc always cancels a dictation in progress.": "수정 키가 가장 좋습니다. 누르고 있어도 문자가 입력되지 않습니다. Esc는 진행 중인 받아쓰기를 언제나 취소합니다.",
        "Reading “%@”…": "“%@” 읽는 중…",
        "Record this call?": "이 통화를 녹음할까요?",
        "Searching your meetings…": "회의를 검색하는 중…",
        "Start Recording": "녹음 시작",
        "Tags": "태그",
        "Voices": "음성",
        "Summary": "요약",
        "Outline": "개요",
        "Hide outline": "개요 숨기기",
        "Show outline": "개요 보기",
        "two levels": "2단계",
        "%d moments": "모먼트 %d개",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "이 Mac에 보관됩니다. 삭제는 즉시이며, 50개가 넘으면 가장 오래된 대화부터 사라집니다.",
        "Ask across all meetings…": "모든 미팅에 질문…",
        "Recently Added": "최근 추가됨",
        "%d meetings · %d h of audio": "미팅 %d개 · 오디오 %d시간",
        "%d meetings · %d min of audio": "미팅 %d개 · 오디오 %d분",
        "Show more": "더 보기",
        "Try one of these": "이 중 하나를 시도해 보세요",
        "Accessibility access is turned off": "손쉬운 사용 접근이 꺼져 있습니다",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "받아쓰기가 듣고는 있지만 입력할 수 없습니다. 다시 켜야 계속됩니다.",
        "Recent dictations": "최근 받아쓰기",
        "Secure input is active — the hotkey cannot work": "보안 입력이 활성화됨 — 단축키가 작동할 수 없습니다",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "어떤 앱의 암호 필드에 포커스가 있습니다. macOS는 어느 앱인지 알려주지 않습니다. 일반 텍스트 필드를 클릭하면 다시 작동합니다.",
        "Start Recording Meeting": "미팅 녹음",
        "Stop Recording Meeting": "미팅 녹음 중지",
        "dictate in %@": "%@ 받아쓰기",
        "dictate in any language": "모든 언어로 받아쓰기",
        "translate %@ → %@": "%@ → %@ 번역",
        "translate into %@": "%@로 번역",
        "%d waiting": "%d개 대기 중",
        "%d words typed": "%d개 단어 입력됨",
        "Add a Key…": "키 추가…",
        "Both will be inserted in the order you spoke them": "말한 순서대로 둘 다 삽입됩니다",
        "Check Audio Setup": "오디오 설정 확인",
        "Clear All Filters": "모든 필터 지우기",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "F키는 시스템 제어(밝기, 미디어)도 겸합니다 — macOS는 둘 다 수행합니다. 일반 키로 쓰려면 키보드 설정에서 'Use F1, F2, etc. as standard function keys'를 켜세요.",
        "How this works": "작동 방식",
        "Input device changed": "입력 장치가 변경됨",
        "Insert text by": "텍스트 삽입 방식",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "연결 후 취소되었거나 교체되었습니다. 키체인에서 제거했으며 — 이 키로 재시도하지 않았습니다.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "브라우저에서 통화에 참여한 뒤 녹음을 시작하세요. Dictate는 마이크와 통화 오디오를 캡처해 둘 다 이 Mac에서 전사하고 여기에 보관합니다. 아무것도 업로드되지 않습니다.",
        "No meeting has all of these tags": "이 태그를 모두 가진 미팅이 없습니다",
        "No meeting has this tag": "이 태그를 가진 미팅이 없습니다",
        "Nothing was said, or nothing was heard": "아무 말도 없었거나, 아무것도 들리지 않았습니다",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "여기에는 미확정 꼬리만 표시됩니다 — 나머지는 이미 문서에 있습니다",
        "Open Console": "콘솔 열기",
        "Open Settings": "설정 열기",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "붙여넣기는 즉각적이지만 잠시 클립보드를 대체합니다. 타이핑은 일부 터미널이나 원격 데스크톱처럼 붙여넣기를 막는 앱에서 작동합니다.",
        "Pasting it at once": "한 번에 붙여넣기",
        "Recording ended here — this Mac went to sleep.": "녹음이 여기서 끝났습니다 — 이 Mac이 잠들었습니다.",
        "Remove “%@”": "'%@' 제거",
        "Return sends · Shift-Return adds a line · Esc clears": "Return 전송 · Shift-Return 줄바꿈 · Esc 지우기",
        "Show Floating Timer": "플로팅 타이머 보기",
        "Start Recording a Meeting": "미팅 녹음",
        "Still recognizing the previous dictation": "이전 받아쓰기를 아직 인식 중",
        "Still recognizing the previous dictation · %d words": "이전 받아쓰기를 아직 인식 중 · %d개 단어",
        "Switched to %@": "%@(으)로 전환됨",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "태그 필터는 '그리고'로 결합됩니다 — 선택한 태그를 모두 가진 미팅만 표시됩니다.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "답변이 중단되었습니다. 질문은 위에 남아 있습니다 — 연결이 돌아오면 다시 시도하세요. 검색과 전사는 계속 작동합니다.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "녹음은 진행됐지만 어느 쪽에서도 음성이 인식되지 않았습니다. 대개 통화 오디오가 캡처되지 않은 경우입니다 — 오디오 권한이 없는 브라우저 탭이거나 잘못된 출력 장치입니다.",
        "The saved key no longer works": "저장된 키가 더 이상 작동하지 않습니다",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "System Settings › Privacy & Security › Calendars에서 허용되기 전까지 스위치는 꺼진 상태로 유지됩니다. 녹음과 겹치는 일정 제목만 읽습니다.",
        "This Mac is offline": "이 Mac은 오프라인입니다",
        "Too many questions at once": "한 번에 질문이 너무 많습니다",
        "Typing as you speak": "말하는 동안 입력 중",
        "Typing into %@ as you speak": "말하는 동안 %@에 입력 중",
        "Typing it out character by character": "한 글자씩 타이핑",
        "Your provider account is out of credit": "제공업체 계정에 크레딧이 없습니다",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "제공업체가 요청 빈도를 제한하고 있습니다. 몇 초 뒤 다시 시도하세요 — 아무것도 잃지 않았습니다.",
        "macOS denied calendar access": "macOS가 캘린더 접근을 거부했습니다",
        "API key": "API 키",
        "All Meetings": "모든 미팅",
        "Assistant": "어시스턴트",
        "Checking the key with %@. No transcript is sent — only a test request.": "%@에서 키를 확인하는 중입니다. 전사는 전송되지 않으며 테스트 요청만 보냅니다.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "창을 닫아도 녹음은 멈추지 않습니다. 여기서 멈추거나 언제든 메뉴 막대에서 멈출 수 있습니다.",
        "Connect an assistant to answer questions": "질문에 답할 어시스턴트 연결",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate는 브라우저 통화를 녹음하고 전사를 이 Mac에 보관할 수 있습니다. 다음 통화가 시작되면 메뉴 막대에서 시작하세요 — 동의는 한 번만 요청됩니다.",
        "Done": "완료",
        "Every change takes effect immediately.": "모든 변경 사항은 즉시 적용됩니다.",
        "Get one at %@.": "%@에서 발급받으세요.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "키를 누른 채 말하고 놓으세요. 말한 내용이 이 Mac의 어떤 앱에서든 커서 위치에 입력됩니다.",
        "Keys": "키",
        "Languages": "언어",
        "Library": "보관함",
        "Paste a key from your own account.": "본인 계정의 키를 붙여넣으세요.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "키체인에 저장되었지만 확인되지 않았습니다 — 이 Mac은 오프라인입니다. 처음 질문할 때 확인됩니다.",
        "Set Up Dictate": "Dictate 설정하기",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "이 Mac의 macOS 키체인에 저장됩니다. 설정 파일에 기록되거나 동기화되지 않습니다.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "키가 거부되었습니다. 취소되었거나, 다른 제공업체의 키이거나, 크레딧이 없을 수 있습니다 — 키 자체는 저장되지 않았습니다.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "전사, 검색, 인용은 이것 없이도 작동합니다. 어시스턴트는 답변을 작성할 때만 필요합니다.",
        "Try Again": "다시 시도",
        "Updates": "업데이트",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "질문마다 제공업체에 비용을 지불합니다 — 보통 1센트 미만입니다. 질문과 인용된 구절만 전송되며 녹음은 이 Mac을 떠나지 않습니다.",
        "Send": "보내기",
        "Conversations": "대화",
        "New question": "새 질문",
        "Deleted “%@”": "“%@” 삭제됨",
        "Undo": "실행 취소",
        "Questions you ask are kept here so you can return to an answer.": "질문은 여기에 저장되어 답변으로 돌아올 수 있습니다.",
        "Rename": "이름 변경",
        "Delete": "삭제",
        "Voices are matched by sound — the name applies only to this voice's turns.": "음성은 소리로 매칭됩니다 — 이름은 이 음성의 발언에만 적용됩니다.",
        "Give two voices the same name to merge them.": "두 음성에 같은 이름을 붙이면 하나로 합쳐집니다.",
        "Voices are told apart by sound — one person can show up as two.": "음성은 소리로 구분됩니다 — 한 사람이 두 명으로 나타날 수 있습니다.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "이름을 클릭하면 음성의 이름을 바꿀 수 있습니다 — 같은 이름을 붙이면 둘이 하나로 합쳐집니다. 요약과 답변은 누가 말했는지가 아니라 무엇을 말했는지에 기반합니다.",
        "Voice separation improves over time.": "음성 구분은 시간이 지나며 개선됩니다.",
        "About voice separation": "음성 구분에 관하여",
        "Call · voice %d": "통화 · 음성 %d",
        "Starred": "별표",
        "Other browser calls": "기타 브라우저 통화",
        "Sources": "소스",
        "Star meeting": "별표 추가",
        "Unstar meeting": "별표 제거",
        "Export transcript…": "기록 내보내기…",
        "Still recording": "여전히 녹음 중",
        "Got it": "확인",
        "Call": "통화",
        "Dictating": "받아쓰기 중",
        "Dictating in %@": "%@로 받아쓰기 중",
        "Translating into English": "영어로 번역 중",
        "Translating into %@": "%@로 번역 중",
        "Release %@ to insert": "%@ 키를 놓으면 삽입됩니다",
        "Also recording this meeting": "이 회의도 녹음 중입니다",
        "%@ MB/s · about %@ left": "%@ MB/s · 약 %@ 남음",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "디스크 공간 부족: 다운로드에 약 %d MB가 필요하지만 %d MB만 남았습니다. 공간을 확보한 뒤 다시 시도하세요.",
        "Fix…": "해결…",
        "Checked automatically · last %@": "자동 확인 · 마지막: %@",
        "Source code": "소스 코드",
        "Report an issue": "문제 신고",
        "Finishing the transcript…": "기록을 마무리하는 중…",
        "Disk almost full — will stop to keep the transcript": "디스크가 거의 가득 참 — 기록 보존을 위해 곧 중지됩니다",
        "Dictate is running from its disk image": "Dictate가 디스크 이미지에서 실행 중입니다",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "디스크 이미지에서 부여한 권한은 추출하는 순간 사라지고, 모델도 매번 다시 다운로드됩니다. 먼저 Dictate를 응용 프로그램 폴더로 이동하세요.",
        "Move to Applications": "응용 프로그램으로 이동",
        "Quit": "종료",
        "Couldn't move Dictate automatically": "Dictate를 자동으로 이동할 수 없습니다",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "디스크 이미지에서 Dictate를 응용 프로그램 폴더로 드래그한 다음 거기서 실행하세요.",
        "OK": "확인",
        "Inserted into %@": "%@에 삽입됨",
        "Inserted": "삽입됨",
        "Accessibility is off — dictation can hear you but cannot type": "손쉬운 사용이 꺼져 있습니다 — 받아쓰기가 들리지만 입력할 수 없습니다",
        "Open Privacy & Security…": "개인정보 보호 및 보안 열기…",
        "1 dictation still being recognized": "받아쓰기 1개 인식 중",
        "%d dictations still being recognized": "받아쓰기 %d개 인식 중",
        "Language Packs…": "언어 팩…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "끄면 Dictate는 메뉴 막대에만 표시됩니다. Dock 아이콘을 클릭하면 회의가 열립니다. 메뉴 막대 아이콘은 항상 표시됩니다.",
        "Interface language": "인터페이스 언어",
        "Granted": "허용됨",
        "No": "없음",
        "Model ready": "모델 준비 완료",
        "On-device recognition": "온디바이스 인식",
        "Spoken language": "말하는 언어",
        "Download failed. Check your connection and retry.": "다운로드에 실패했습니다. 연결을 확인하고 다시 시도하세요.",
        "Not set": "지정 안 됨",
        "Remove": "제거",
        "Download & continue": "다운로드 후 계속",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "약 %@ — 한 번만 다운로드합니다. Dictate에 인터넷이 필요한 순간은 이때뿐입니다.",
        "Hold %@ and say something — the recognized text shows up below.": "%@ 키를 누른 채 아무 말이나 해보세요 — 인식된 텍스트가 아래에 표시됩니다.",
        "Recognized text appears here…": "인식된 텍스트가 여기에 표시됩니다…",
        // Menu bar
        "Settings…": "설정…",
        "Quit Dictate": "Dictate 종료",
        "Dictate — voice dictation": "Dictate — 음성 받아쓰기",
        // HUD
        "Recognizing…": "인식 중…",
        "Esc to cancel": "Esc로 취소",
        // Errors
        "Couldn't start recording: %@": "녹음을 시작할 수 없습니다: %@",
        "Recording truncated at %d seconds (limit)": "녹음이 %d초에서 잘렸습니다(제한)",
        "Audio device changed during recording — recording cancelled, please try again.": "녹음 중 오디오 장치가 변경되어 녹음이 취소되었습니다. 다시 시도해 주세요.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "손쉬운 사용 권한이 꺼져 있어 키를 감지할 수 없습니다. 시스템 설정 → 개인정보 보호 및 보안 → 손쉬운 사용에서 켜세요 — Dictate가 자동으로 적용하며, 재시동은 필요 없습니다.",
        "Microphone unavailable (no input audio format)": "마이크를 사용할 수 없습니다(입력 오디오 포맷 없음)",
        // Key names
        "Right Option (⌥)": "오른쪽 Option(⌥)",
        "Left Option (⌥)": "왼쪽 Option(⌥)",
        "Right Command (⌘)": "오른쪽 Command(⌘)",
        "Left Command (⌘)": "왼쪽 Command(⌘)",
        "Right Shift (⇧)": "오른쪽 Shift(⇧)",
        "Left Shift (⇧)": "왼쪽 Shift(⇧)",
        "Right Control (⌃)": "오른쪽 Control(⌃)",
        "Left Control (⌃)": "왼쪽 Control(⌃)",
        "Space": "스페이스",
        "Follow system": "시스템 언어 따르기",
        "Translating…": "번역 중…",
        "Tip: hold %@ instead — your speech comes out in English.": "팁: 대신 %@ 키를 누르고 있으면 말한 내용이 영어로 입력됩니다.",
        "Hold to talk in your language, release to insert it in English.": "누른 채 모국어로 말하고 놓으면 영어로 입력됩니다.",
        "Hold %@ and say it again — this time it's typed in English.": "%@ 키를 누른 채 같은 말을 다시 해 보세요. 이번에는 영어로 입력됩니다.",
        "Translate to": "번역 대상",
        "Translation data isn't downloaded — open Settings to get it": "번역 데이터가 없습니다 — 설정에서 다운로드하세요",
        "Translation data": "번역 데이터",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "번역 키는 먼저 말을 받아쓴 다음 macOS가 이 Mac에서 번역합니다. 언어를 선택하면 macOS가 번역 데이터를 한 번 다운로드할 수 있습니다.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "인식은 Mac의 Neural Engine에서 실행됩니다 — Whisper large-v3-turbo: 100개 언어, 억양에도 강하고 실시간 텍스트를 보여줄 만큼 빠릅니다. 번역도 이 Mac에서 이루어집니다. 당신의 목소리는 이 컴퓨터를 떠나지 않습니다.",
        "Hold %@ and say it again — this time it comes out in %@.": "%@ 키를 누른 채 같은 말을 다시 해 보세요. 이번에는 %@(으)로 나옵니다.",
        "Hold to talk in your language, release to insert it in %@.": "누른 채 모국어로 말하고 놓으면 %@(으)로 입력됩니다.",
        "Not downloaded": "다운로드 안 됨",
        "Translation languages": "번역 언어",
        "Downloaded": "다운로드됨",
        "Manage in System Settings…": "시스템 설정에서 관리…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "시스템 설정에서는 켜져 있는데 여기서 녹색이 아닌가요? Dictate 스위치를 껐다가 다시 켜세요. 업데이트 후 macOS가 오래된 항목을 유지할 때가 있습니다.",
        "Agent: %@, on your key.": "에이전트: %@, 내 키로.",
        "Agent: off.": "에이전트: 꺼짐.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "이 지역 또는 언어에서는 이 Mac에서 Apple Intelligence를 사용할 수 없습니다. 내 키를 쓰는 에이전트는 여전히 작동합니다.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence에는 macOS 26이 필요합니다. 내 키를 쓰는 에이전트는 여전히 작동합니다.",
        "Copy diagnostics": "진단 정보 복사",
        "Debug audio dumps": "디버그 오디오 덤프",
        "Diagnostics": "진단",
        "Downloading…": "다운로드 중…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "%@의 공간을 확보합니다. 다시 내려받기 전까지 새 회의는 날짜 이름을 그대로 씁니다. 이미 작성된 요약은 남습니다.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "%@의 공간을 확보합니다. 그 외에는 달라지지 않습니다 — 회의 읽기가 꺼져 있습니다.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "%@의 공간을 확보합니다. 제목과 요약은 Apple Intelligence가 맡게 됩니다.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "설치되어 있지만 실행되지 않음: 이 Mac의 메모리는 %dGB이고 16GB가 필요합니다.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "설치되어 있지만 실행되지 않음: 이 Mac의 메모리는 %dGB이고 16GB가 필요합니다. 이 Mac에서 회의를 읽는 것은 없습니다.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "설치되어 있지만 실행되지 않음: 이 Mac의 메모리는 %dGB이고 16GB가 필요합니다. 제목과 요약은 대신 Apple Intelligence가 맡습니다.",
        "Installed · %@": "설치됨 · %@",
        "Installed, not in use · %@": "설치됨, 사용 안 함 · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "쓰는 동안 약 %@의 메모리를 차지하며 이 Mac에서는 체감됩니다.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, 버전, 켜진 기능. 전사도 키도 포함되지 않습니다.",
        "Meeting archive": "회의 보관함",
        "Meeting model": "회의 모델",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "회의 모델이 설치되었습니다. 새 회의는 이 Mac에서 제목과 요약을 받습니다.",
        "Meeting reading: Apple Intelligence.": "회의 읽기: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "회의 읽기: 이 Mac에서 아직 할 수 있는 것이 없습니다.",
        "Meeting reading: the downloaded model (%@).": "회의 읽기: 내려받은 모델(%@).",
        "Not available on this Mac.": "이 Mac에서는 사용할 수 없습니다.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "설치되지 않음. %@ 한 번만 내려받으면 제목과 요약, 목차를 씁니다.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "이 Mac에서 아직 읽을 수 있는 것이 없습니다: 여기서는 Apple Intelligence를 사용할 수 없습니다. 내 키를 쓰는 에이전트는 여전히 작동합니다.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "이 Mac에서 아직 읽을 수 있는 것이 없습니다: 아래에서 회의 모델을 내려받거나, 에이전트용 키를 추가하세요.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "이 Mac에서 아직 읽을 수 있는 것이 없습니다: 아래에서 회의 모델을 내려받거나, 시스템 설정에서 Apple Intelligence를 켜세요.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "이 Mac에서 아직 읽을 수 있는 것이 없습니다: macOS가 아직 Apple Intelligence를 설정하는 중입니다. 내 키를 쓰는 에이전트는 여전히 작동합니다.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "이 Mac에서 아직 읽을 수 있는 것이 없습니다: 시스템 설정에서 Apple Intelligence를 켜거나, 에이전트용 키를 추가하세요.",
        "Open System Settings": "시스템 설정 열기",
        "Paused: not enough free memory right now. It resumes on its own.": "일시 정지됨: 지금은 여유 메모리가 부족합니다. 자동으로 재개됩니다.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "이 Mac의 프로세서용으로 모델을 준비하는 중… 몇 분 걸리며, 한 번만 하면 됩니다.",
        "Raw call audio kept for debugging only.": "디버깅 용도로만 보관되는 원본 통화 오디오입니다.",
        "Reading is on, but nothing on this Mac can read yet.": "읽기는 켜져 있지만 이 Mac에서 아직 읽을 수 있는 것이 없습니다.",
        "Reads with Apple Intelligence.": "Apple Intelligence로 읽습니다.",
        "Reads with the downloaded model.": "내려받은 모델로 읽습니다.",
        "Recognition runs on the Neural Engine.": "인식은 Neural Engine에서 실행됩니다.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "인식은 이 Mac의 프로세서에서 실행됩니다 — Whisper large-v3-turbo: 100개 언어, 억양에도 강합니다. Apple Silicon보다 느리며, 번역도 이 Mac에서 이루어집니다. 당신의 목소리는 이 컴퓨터를 떠나지 않습니다.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "인식은 이 Mac의 프로세서에서 실행됩니다 — Apple Silicon보다 느립니다.",
        "Remove the debug audio dumps?": "디버그 오디오 덤프를 제거할까요?",
        "Remove the meeting model?": "회의 모델을 제거할까요?",
        "Remove…": "제거…",
        "Speaker models": "화자 모델",
        "Speech model": "음성 모델",
        "Storage": "저장 공간",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "이 Mac의 요약은 Apple Intelligence가 맡습니다. 내려받는 모델은 16GB의 메모리가 필요한데, 이 Mac은 %dGB입니다.",
        "Summary paused: not enough free memory. It resumes on its own.": "요약 일시 정지됨: 여유 메모리가 부족합니다. 자동으로 재개됩니다.",
        "Tell the voices on a call apart.": "통화 속 목소리를 구분합니다.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "회의 모델은 16GB의 메모리가 필요한데, 이 Mac은 %dGB입니다.",
        "These are recordings kept only for debugging. Nothing else is affected.": "디버깅 용도로만 보관된 녹음입니다. 그 외에는 영향이 없습니다.",
        "This Mac": "이 Mac",
        "This build of Dictate does not include the meeting model.": "이 Dictate 빌드에는 회의 모델이 포함되어 있지 않습니다.",
        "Titles and summaries come from Apple Intelligence instead.": "제목과 요약은 대신 Apple Intelligence가 맡습니다.",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "시스템 설정 › Apple Intelligence 및 Siri에서 Apple Intelligence를 켜거나, 에이전트용 키를 추가하세요.",
        "Waiting for the call to end.": "통화가 끝나기를 기다리는 중.",
        "Your transcripts, as Markdown files you own.": "전사본을 내 소유의 Markdown 파일로 보관합니다.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS가 아직 Apple Intelligence를 설정하는 중입니다 — 나중에 다시 확인하거나, 에이전트용 키를 추가하세요.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. 보고서는 어느 쪽이든 회의 파일에 남으며, 이 작업은 사본을 만듭니다.",
        "%d fields": "필드 %d개",
        "Add field": "필드 추가",
        "Agent & reports": "에이전트 및 보고서",
        "Also one table (CSV): a row per meeting, a column per field": "표 하나(CSV)도 함께: 회의당 한 행, 필드당 한 열",
        "Answers with": "답변 제공자",
        "Choose folder…": "폴더 선택…",
        "Copy report": "보고서 복사",
        "Date": "날짜",
        "Export %d “%@” reports": "%d개의 “%@” 보고서 내보내기",
        "Export reports…": "보고서 내보내기…",
        "Export report…": "이 보고서 내보내기…",
        "Export the “%@” report": "“%@” 보고서 내보내기",
        "Field name": "필드 이름",
        "Fields": "필드",
        "Format:": "형식:",
        "Markdown": "Markdown",
        "Meeting": "회의",
        "New template": "새 템플릿",
        "New template…": "새 템플릿…",
        "No reports written with “%@” yet.": "아직 “%@”(으)로 작성된 보고서가 없습니다.",
        "No templates yet.": "아직 템플릿이 없습니다.",
        "Not discussed": "논의되지 않음",
        "One empty field. You name it.": "빈 필드 하나. 이름은 직접 정합니다.",
        "One file per meeting, named by date and title, in a folder you choose. Transcripts are not included.": "회의당 파일 하나, 날짜와 제목으로 이름 붙여 선택한 폴더에 저장합니다. 기록은 포함되지 않습니다.",
        "PDF": "PDF",
        "Plain text": "일반 텍스트",
        "Questions across your meetings, and reports.": "회의 전반에 대한 질문과 보고서.",
        "Remove field": "필드 제거",
        "Remove template": "템플릿 제거",
        "Remove template…": "템플릿 제거…",
        "Remove “%@”?": "“%@”을(를) 제거할까요?",
        "Report": "보고서",
        "Report not written": "보고서가 작성되지 않음",
        "Reports": "보고서",
        "Reports already written with it stay in their meetings.": "이 템플릿으로 이미 작성된 보고서는 각 회의에 그대로 남습니다.",
        "Same as Dictate": "Dictate와 동일",
        "Template name": "템플릿 이름",
        "Templates": "템플릿",
        "The model returned no report.": "모델이 보고서를 반환하지 않았습니다.",
        "The model stopped before the report was finished.": "보고서가 완성되기 전에 모델이 멈췄습니다.",
        "The saved key no longer works. It has been removed from the Keychain.": "저장된 키가 더 이상 작동하지 않습니다. 키체인에서 제거했습니다.",
        "What is sent": "전송되는 내용",
        "Writing · about a minute": "작성 중 · 약 1분",
        "Written by Dictate on this Mac from the transcript": "이 Mac에서 Dictate가 기록을 바탕으로 작성",
        "Your %@ account refused the request for billing reasons.": "%@ 계정이 결제 문제로 요청을 거부했습니다.",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "이 전사를 내 키로 %@에 보냅니다. 보고서는 회의 파일에 저장됩니다.",
        "Set up templates…": "템플릿 설정…",
        "Write report": "보고서 쓰기",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@에서 요청 속도를 제한하고 있습니다. 잃은 것은 없으니 1분 뒤에 다시 시도하세요.",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "이 Mac은 오프라인입니다. 아무것도 보내지 않았으니 연결이 돌아오면 다시 시도하세요.",
        "Write a “%@” report?": "“%@” 보고서를 쓸까요?",
        "Action items": "실행 항목",
        "Dates and deadlines": "날짜와 기한",
        "Decisions": "결정 사항",
        "Decisions & actions": "결정과 실행 항목",
        "Every date, deadline or time window that was mentioned, and what it is for": "언급된 모든 날짜, 기한, 시간대와 그것이 무엇을 위한 것인지",
        "Key points": "핵심 요점",
        "Meeting summary": "회의 요약",
        "Next step": "다음 단계",
        "Open questions": "미해결 질문",
        "Purpose": "목적",
        "Risks and concerns": "위험과 우려",
        "The main arguments and facts, with the numbers, names and dates that were said": "주요 논점과 사실. 언급된 숫자, 이름, 날짜 포함",
        "The next meeting or checkpoint, if one was agreed": "합의된 경우 다음 회의 또는 점검 시점",
        "Waiting on": "대기 중",
        "We are the team on this call; the reader took part in it.": "우리는 이 통화의 팀이며, 읽는 사람도 이 통화에 참여했습니다.",
        "What could go wrong, who raised it, how serious it sounded": "무엇이 잘못될 수 있는지, 누가 제기했는지, 얼마나 심각하게 들렸는지",
        "What each side is waiting for from the other": "각 측이 상대에게 무엇을 기다리고 있는지",
        "What was decided, by whom, and what it replaces": "무엇이 결정되었고, 누가 결정했으며, 무엇을 대체하는지",
        "What was raised and not settled, and who owns it": "제기되었지만 해결되지 않은 것과 그 담당자",
        "Who does what, by when — one line per task": "누가 무엇을 언제까지 — 작업당 한 줄",
        "Why we met and what we set out to settle": "왜 모였고 무엇을 결정하려 했는지",
        "%d more": "%d명 더",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "제목은 회의의 언어를 유지하고, 요약과 모든 보고서는 이 언어로 작성됩니다. 보고서의 항목 이름은 입력한 그대로 유지됩니다.",
        "About “%@”:": "“%@”에 대해:",
        "Replace the report with a new “%@” one?": "보고서를 새 “%@” 보고서로 대체할까요?",
        "Replace report": "보고서 대체",
        "Written · replaces it": "작성됨 · 대체됩니다",
        "Dictate updated to %@.": "Dictate가 %@(으)로 업데이트되었습니다.",
        "Dismiss": "닫기",
        "New": "새로움",
        "New in this version": "이 버전의 새 기능",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "회의를 열고 머리글의 Write report를 누른 뒤 템플릿을 고르세요. 보고서는 카드에 표시되고 Dictate Meetings › Reports에 PDF로 저장됩니다.",
        "Reports from templates": "템플릿으로 보고서 작성",
        "See what’s new": "새 기능 보기",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "설정 › 회의 › 요약과 보고서 작성 언어: 통화가 어떤 언어였든 요약과 모든 보고서가 내가 읽는 언어로 작성됩니다.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "설정 › 템플릿: 회의 요약이나 결정과 실행 항목으로 시작하거나, 직접 항목을 정하고 각 항목 아래에 무엇을 쓸지 모델에게 알려 주세요.",
        "Summaries in your language": "내 언어로 된 요약",
        "What’s new": "새 기능",
        "What’s new in Dictate %@": "Dictate %@의 새 기능",
        "Your own templates": "나만의 템플릿",
        "Install update %@ and relaunch": "업데이트 %@ 설치 후 다시 시작",
        "The update waits until the recording ends.": "업데이트는 녹음이 끝날 때까지 기다립니다.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "업데이트 %@ 다운로드 중입니다. 다음 한가한 순간에 자동으로 설치되며, 메뉴 막대에서 더 일찍 설치할 수 있습니다.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "업데이트 %@ 준비됨 — 메뉴 막대에서 설치하거나 다음 한가한 순간에 자동으로 설치됩니다.",
        "An update is already on its way — it installs itself at the next quiet moment.": "업데이트가 이미 진행 중입니다. 다음 한가한 순간에 자동으로 설치됩니다.",
        "Downloading update %@…": "업데이트 %@ 다운로드 중…",
        "Preparing update %@…": "업데이트 %@ 준비 중…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate가 %@(으)로 업데이트되었습니다. 새 기능은 회의 창에 있습니다.",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence가 이 회의의 요약을 거부했습니다.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "전사, 검색, 에이전트는 그대로입니다. 이 Mac에 보관되는 다운로드 모델에는 그런 제한이 없습니다.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "회의를 기록하고 구조화: 화자, 요약, 아웃라인, 검색. Dictate는 통화 녹음을 제안할 뿐, 답하기 전에는 절대 녹음하지 않습니다.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "회의 모델은 16GB의 메모리가 필요한데, 이 Mac은 %dGB입니다. 실행되지 않으며, 디스크에서 차지하는 %@는 정리할 수 있습니다.",
        "Clipboard restored.": "클립보드를 복원했습니다.",
        "Your words were inserted untranslated.": "말한 내용이 번역되지 않은 채 삽입되었습니다.",
        "A small panel appears when a call starts, and you decide there.": "통화가 시작될 때 작은 패널이 나타나 거기서 결정하면 됩니다.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "요약과 개요를 쓰고 에이전트에게 답할 재료를 줍니다. 어느 쪽이든 아무것도 어디로도 전송되지 않습니다.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "꺼져 있으면 내 마이크만, 켜면 상대방도 기록됩니다.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "한 덩어리 텍스트를 이름이 붙은 발언으로 나눕니다. 구분은 소리로 이루어져 부정확할 수 있으며, 이름은 바꿀 수 있습니다.",
        "Find in this transcript…": "이 전사에서 찾기…",
        "%d of %d": "%d / %d",
        "No matches": "일치 항목 없음",
        "Previous match": "이전 일치 항목",
        "Next match": "다음 일치 항목",
        "Close find": "찾기 닫기",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "%@을(를) 선택했지만 아직 키가 없습니다. 키를 추가할 때까지 에이전트와 보고서는 꺼져 있습니다.",
        "%@ · required for dictation, cannot be removed.": "%@ · 받아쓰기에 필요하며 제거할 수 없습니다.",
        "%@ — not written": "%@ — 작성되지 않음",
        "%d h": "%d시간",
        "%d meetings have a %@ report. They stay if this template goes.": "%d개 회의에 「%@」 보고서가 있습니다. 이 템플릿을 지워도 그대로 남습니다.",
        "%d min ago": "%d분 전",
        "%d written": "%d개 작성됨",
        "%d written, %d not written": "%d개 작성됨, %d개 작성되지 않음",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12개 언어. 이 창과 메뉴 막대에 바로 적용됩니다. 말하는 언어는 받아쓰기에서 설정합니다.",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "본인의 %@ 계정 키입니다. 키체인에 저장되며 설정 파일에는 절대 저장되지 않습니다.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "질문은 질문과 검색이 찾은 구절을 보냅니다. 보고서는 그 회의의 전체 대본을 보냅니다. 한 시간 대화에 약 12,000 단어입니다. 둘 다 본인 키로 %@에, 요청할 때만 전송됩니다. 녹음은 이 Mac을 절대 떠나지 않습니다.",
        "About": "정보",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "이 Mac에서는 Apple Intelligence를 사용할 수 없어 대신할 것이 없습니다.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence에는 이 Mac보다 새로운 macOS가 필요해 대신할 것이 없습니다.",
        "Applies to this window, the meetings window and the panels over your other apps.": "이 창, 회의 창, 다른 앱 위에 뜨는 패널에 적용됩니다.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "한 번만 묻습니다. 이후 패널은 짧은 버전이 되며 답할 때까지 남아 있습니다. 통화 중 언제든 메뉴 막대에서 녹음을 시작할 수도 있습니다.",
        "Calendar": "캘린더",
        "Collapse %@": "%@ 접기",
        "Copy": "복사",
        "Dictation": "받아쓰기",
        "Expand %@": "%@ 펼치기",
        "Export…": "내보내기…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "최근 받아쓰기에도 있으니 클립보드는 언제든 다시 쓸 수 있습니다.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "이 회의 파일 안에 보관되어 대본과 함께 이동합니다. 내보내기는 원하는 곳에 사본을 만듭니다.",
        "No report": "보고서 없음",
        "No report for this meeting yet.": "이 회의의 보고서가 아직 없습니다.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "제거해도 잃는 것은 없습니다. 대본, 검색, 에이전트는 이것에 의존하지 않습니다.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "여기서는 아무것도 설정하지 않습니다. 위의 각 줄은 이 Mac이 할 수 있는 일을 알리거나 담당 패널을 가리킵니다.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "이 Mac에서는 아직 아무것도 읽을 수 없습니다. Apple Intelligence에는 새로운 macOS가 필요합니다. 본인 키를 쓰는 에이전트는 여전히 동작합니다.",
        "Nothing was kept from this take — earlier ones are still here.": "이번 시도에서는 남은 것이 없습니다. 이전 것들은 여전히 여기 있습니다.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "녹음된 것이 없어 남은 것도 없습니다. 이전 것들은 여전히 여기 있습니다.",
        "Off — dictation cannot type": "꺼짐 — 받아쓰기가 입력할 수 없음",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "꺼짐: 대본, 요약, 개요, 검색은 전과 같이 동작합니다. 에이전트는 모든 회의에 걸쳐 질문에 답하고 템플릿으로 보고서를 씁니다. 본인의 API 키로 클라우드에서 실행됩니다.",
        "On this Mac": "이 Mac에서",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "이어받기 가능한 파일 하나입니다. Dictate를 닫으면 일시 정지되고 멈춘 곳부터 다시 이어집니다.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "%@을(를) 한 번만 다운로드하면 제목, 요약, 개요가 전부 이 Mac에서 만들어집니다. 실행에 16GB 메모리가 필요하며 작성 중 약 %@을(를) 차지합니다.",
        "Open System Settings…": "시스템 설정 열기…",
        "Or start from the menu bar later in the call.": "또는 통화 중 나중에 메뉴 막대에서 시작하세요.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "지금 일시 정지됨: 여유 메모리가 부족합니다. 저절로 다시 시작되며 요약을 기다리는 회의는 대본을 그대로 유지합니다.",
        "Permissions": "권한",
        "Reads with Apple Intelligence until the download finishes.": "다운로드가 끝날 때까지 Apple Intelligence로 읽습니다.",
        "Reads with the downloaded model — paused until there is free memory.": "다운로드한 모델로 읽습니다. 여유 메모리가 생길 때까지 일시 정지됨.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "보고서 템플릿은 템플릿에 있고, 작성된 보고서는 보관함의 보고서에 있습니다.",
        "Report · %@": "보고서 · %@",
        "Report · %@ +%d": "보고서 · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "보고서에는 에이전트가 필요한데 꺼져 있습니다. 요약 및 보고서에서 Claude 또는 ChatGPT를 선택하세요. 그때까지 템플릿은 유지됩니다.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "전부 이 Mac에서 실행됩니다. 없으면 제목과 요약은 Apple Intelligence가 만듭니다.",
        "Startup": "시작",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "키체인에 저장되며 설정 파일에는 절대 저장되지 않습니다. 에이전트는 모든 회의에 걸쳐 질문에 답하고 템플릿으로 보고서를 씁니다.",
        "Summaries": "요약",
        "Summaries & reports": "요약 및 보고서",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "다운로드하면 Apple Intelligence 없이도 이 Mac에서 요약을 쓸 수 있습니다. 대본과 검색은 어느 쪽이든 동작합니다.",
        "This Mac was offline. Nothing was sent.": "이 Mac이 오프라인이었습니다. 아무것도 전송되지 않았습니다.",
