        "Write again": "다시 작성",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "위의 보고서 작성에 템플릿 %d개가 나열됩니다. 하나를 작성하면 이 대본이 본인 키로 %@에 전송됩니다. 보고서는 이 회의 파일 안에 보관되어 대본과 함께 이동합니다. 내보내기는 원하는 곳에 사본을 만듭니다.",
        "Written %@": "%@에 작성됨",
