        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS가 아직 Apple Intelligence를 설정 중입니다. 시간이 걸릴 수 있으며 여기서 재촉할 수는 없습니다.",
        "macOS resets this switch after some updates and never asks a second time.": "macOS는 일부 업데이트 후 이 스위치를 초기화하며 두 번 다시 묻지 않습니다.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-클릭하면 대신 복사합니다. Dictate를 종료하면 지워집니다.",
        "Meeting names": "회의 이름",
        "%d meetings, reports included": "회의 %d개, 보고서 포함",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "요약 및 보고서에서 회의 모델을 다운로드하거나 에이전트용 키를 추가하세요.",
        "Calls": "통화",
        "Reports folder": "보고서 폴더",
        "%d PDFs written before %@": "%@ 이전에 작성된 PDF %d개",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate는 더 이상 스스로 PDF를 쓰지 않습니다. 이 파일들은 보관하든 삭제하든 자유입니다. 앱의 어떤 기능도 이에 의존하지 않습니다.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "이미 작성된 보고서가 교체됩니다. 이 대본을 본인 키로 %@에 보냅니다.",
        "%@ · report not written": "%@ · 보고서 작성되지 않음",
        "%d of %d selected · %d meetings without one": "%d/%d개 선택 · 보고서 없는 회의 %d개",
        "%d passages from %d meetings": "구절 %d개, 회의 %d개에서",
        "%d written across %d templates": "%d개 작성됨, 템플릿 %d개",
        "%d written · %d meetings without one · %d fields": "%d개 작성됨 · 보고서 없는 회의 %d개 · 필드 %d개",
        "%d written · writing %d · %d not written": "%d개 작성됨 · 작성 중 %d개 · 작성되지 않음 %d개",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "보고서는 요청 시 작성됩니다. 회의 카드에서, 또는 여기서 선택한 회의에 대해. 각각은 그 회의의 대본을 본인 키로 %@에 보내고 회의 파일 안에 보관됩니다.",
        "All reports": "모든 보고서",
        "Answer": "답변",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "%@이(가) 답변, 회의 %d개 참조(전체 %d개 중). 인용은 이 Mac의 대본에서 그대로 가져왔습니다.",
        "Copy as Markdown": "Markdown으로 복사",
        "Copy as plain text": "일반 텍스트로 복사",
        "Copy the answer only": "답변만 복사",
        "Copy with quotes": "인용과 함께 복사",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "템플릿마다 보고서를 따로 둡니다. 작성된 것과 작성할 수 있는 회의입니다. 템플릿 자체는 설정 › 템플릿에서 편집합니다.",
        "Edit template…": "템플릿 편집…",
        "No report yet · %d meetings": "아직 보고서 없음 · 회의 %d개",
        "None written · %d fields": "작성된 것 없음 · 필드 %d개",
        "Nothing written from this template yet": "이 템플릿으로 작성된 것이 아직 없습니다",
