        "Pick a template": "템플릿 선택",
        "Quotes": "인용",
        "Replace the %d that already have one": "이미 있는 %d개 교체",
        "Report not written — the request was refused. The meeting has the detail.": "보고서 작성되지 않음. 요청이 거부되었습니다. 자세한 내용은 회의에 있습니다.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "대본 %d개를 %@에 본인 키로 보냅니다. 약 %@ 단어입니다. 각 보고서는 해당 회의 파일 안에 보관됩니다. 녹음은 이 Mac을 절대 떠나지 않습니다.",
        "The %d existing reports are overwritten. This cannot be undone.": "기존 보고서 %d개를 덮어씁니다. 되돌릴 수 없습니다.",
        "Write": "작성",
        "Write %d": "%d개 작성",
        "Write %d reports…": "보고서 %d개 작성…",
        "Write a “%@” report for %d meetings?": "「%@」 보고서를 작성할까요? 회의 %d개 대상입니다.",
        "Write a “%@” report for “%@”?": "「%@」 보고서를 작성할까요? 대상은 「%@」입니다.",
        "Write all %d…": "%d개 모두 작성…",
        "Write for a selection…": "선택한 회의에 작성…",
        "Write report › %@": "보고서 작성 › %@",
        "Written": "작성됨",
        "No instruction — goes by its name alone": "지침 없음 — 이름만으로",
        "Drag to reorder": "끌어서 순서 변경",
        "Every report is kept inside its meeting’s file.": "모든 보고서는 해당 회의 파일 안에 보관됩니다.",
        "A refusal stops that meeting only; the rest continue.": "거부되면 그 회의만 멈추고 나머지는 계속됩니다.",
        "Always assume": "항상 전제",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "통화에서는 말하지 않지만 모든 보고서가 전제로 삼아야 할 사실: 당신이 누구인지, 어느 쪽이 고객인지, 팀에서 특정한 뜻으로 쓰는 단어. 이 템플릿의 모든 보고서와 함께 전송됩니다.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "선택 사항. 없으면 모델은 아무 전제 없이 통화를 읽습니다. 동료 간 회의에는 대개 괜찮지만 외부와의 통화에는 틀리게 됩니다.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "우리는 영업 대행사입니다. 고객은 항상 상대방이며 우리가 아닙니다. 「시트」는 유료 사용자 라이선스를 뜻합니다.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "회의 카드, 보관함의 보고서, 작성된 보고서 안의 제목에 표시됩니다.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "각 필드는 이 순서대로 보고서의 제목이 됩니다. 손잡이를 끌어 필드를 옮깁니다. 지침은 선택 사항이며 필요한 만큼 길어도 됩니다. 지침이 없는 필드는 이름만으로 처리됩니다.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "각 필드는 이 통화의 대본에서만 채워집니다. 통화에서 다루지 않은 필드는 「Not discussed」로 표시됩니다.",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "템플릿은 이름과 몇 개의 필드입니다. 보고서는 요청 시 여기서 작성되며 회의당 템플릿마다 하나입니다.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "아직 템플릿이 없습니다. 템플릿은 이름과 몇 개의 필드이며 보고서는 회의 카드에서 요청 시 작성되고 회의당 템플릿마다 하나입니다.",
    ]

    static let vi: [String: String] = [
