        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Tác nhân trả lời các câu hỏi về mọi thứ bạn đã ghi — “chúng ta đã quyết gì về ngày chốt” — và nêu rõ cuộc họp cùng thời điểm chứa câu trả lời. Nó cần mô hình đọc các cuộc họp của bạn, hiện đang tắt. Dù thế nào, không có gì rời khỏi máy Mac này.",
