        "Dictate is running from the downloaded image — drag it into Applications, eject the image, and launch it from there. Permissions granted to this temporary copy won't stick.": "Dictate đang chạy từ tệp ảnh đã tải về — hãy kéo nó vào «Ứng dụng», đẩy tệp ảnh ra rồi mở từ đó. Quyền cấp cho bản sao tạm thời này sẽ không được giữ lại.",
        "Still stuck? Reset the permission — this clears the broken macOS record, then grant the fresh request.": "Vẫn kẹt? Đặt lại quyền — thao tác này xóa bản ghi hỏng của macOS, sau đó hãy cấp quyền trong hộp thoại mới.",
