        "The connection was interrupted. Resuming continues from where it stopped — you will not download the whole %d MB again.": "Kết nối bị gián đoạn. Tiếp tục sẽ bắt đầu từ chỗ dừng — bạn sẽ không tải lại toàn bộ %d MB.",
        "The download stopped at %d MB": "Tải xuống dừng ở %d MB",
        "The model is being compiled for your chip so recognition is fast later. This takes a minute on first launch and never happens again.": "Mô hình đang được biên dịch cho chip của bạn để nhận dạng nhanh về sau. Mất một phút ở lần khởi động đầu và không bao giờ lặp lại.",
        "This happens once. The model stays on your Mac and is the reason dictation works without an internet connection afterwards.": "Điều này chỉ xảy ra một lần. Mô hình ở lại trên máy Mac — đó là lý do đọc chính tả sau này hoạt động không cần internet.",
        "To hear you. Audio is processed on this Mac and discarded.": "Để nghe bạn. Âm thanh được xử lý trên máy Mac này và bị loại bỏ.",
        "To type the recognized text into the app you are using. It is the only way an app can insert text elsewhere.": "Để gõ văn bản đã nhận dạng vào ứng dụng bạn đang dùng. Đó là cách duy nhất một ứng dụng chèn văn bản vào nơi khác.",
