        "Insert text by": "Chèn văn bản bằng",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Nó đã bị thu hồi hoặc thay thế sau khi kết nối. Đã xóa khỏi Keychain — không thử lại gì với nó.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Tham gia cuộc gọi trong trình duyệt rồi bắt đầu ghi âm. Dictate thu micrô và âm thanh cuộc gọi, phiên âm cả hai trên máy Mac này và giữ bản ghi tại đây. Không tải lên bất cứ thứ gì.",
        "No meeting has all of these tags": "Không cuộc họp nào có tất cả các thẻ này",
        "No meeting has this tag": "Không cuộc họp nào có thẻ này",
        "Nothing was said, or nothing was heard": "Không ai nói gì, hoặc không nghe thấy gì",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Ở đây chỉ hiển thị phần đuôi chưa xác nhận — phần còn lại đã ở trong tài liệu",
        "Open Console": "Mở console",
        "Open Settings": "Mở Cài đặt",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Dán thì tức thời nhưng chiếm bảng nhớ tạm trong giây lát. Gõ hoạt động ở các ứng dụng chặn dán, như một số terminal và màn hình từ xa.",
        "Pasting it at once": "Dán một lần",
        "Recording ended here — this Mac went to sleep.": "Bản ghi kết thúc tại đây — máy Mac này đã ngủ.",
        "Remove “%@”": "Bỏ «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return gửi · Shift-Return xuống dòng · Esc xóa",
        "Show Floating Timer": "Hiện đồng hồ nổi",
        "Start Recording a Meeting": "Ghi âm cuộc họp",
        "Still recognizing the previous dictation": "Vẫn đang nhận dạng lần đọc trước",
        "Still recognizing the previous dictation · %d words": "Vẫn đang nhận dạng lần đọc trước · %d từ",
        "Switched to %@": "Đã chuyển sang %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Bộ lọc thẻ kết hợp bằng «và» — cuộc họp phải mang đủ mọi thẻ đã chọn.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Câu trả lời đã dừng. Câu hỏi của bạn còn ở trên — thử lại khi có mạng. Tìm kiếm và bản ghi vẫn hoạt động.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Bản ghi đã chạy nhưng không nhận dạng được giọng nói ở bên nào. Thường nghĩa là âm thanh cuộc gọi chưa từng được thu — tab trình duyệt không có quyền âm thanh, hoặc sai thiết bị đầu ra.",
        "The saved key no longer works": "Khóa đã lưu không còn hoạt động",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Công tắc sẽ tắt cho đến khi được cấp trong System Settings › Privacy & Security › Calendars. Chỉ đọc tiêu đề sự kiện trùng thời gian ghi.",
        "This Mac is offline": "Máy Mac này đang ngoại tuyến",
        "Too many questions at once": "Quá nhiều câu hỏi cùng lúc",
        "Typing as you speak": "Đang gõ khi bạn nói",
        "Typing into %@ as you speak": "Đang gõ vào %@ khi bạn nói",
        "Typing it out character by character": "Gõ từng ký tự",
        "Your provider account is out of credit": "Tài khoản nhà cung cấp của bạn hết tín dụng",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Nhà cung cấp đang giới hạn tần suất. Đợi vài giây rồi thử lại — không mất gì cả.",
        "macOS denied calendar access": "macOS đã từ chối quyền truy cập lịch",
        "API key": "Khóa API",
        "All Meetings": "Tất cả cuộc họp",
        "Assistant": "Trợ lý",
        "Checking the key with %@. No transcript is sent — only a test request.": "Đang kiểm tra khóa với %@. Không gửi bản ghi nào — chỉ một yêu cầu thử.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Đóng cửa sổ không dừng ghi âm. Dừng tại đây hoặc từ thanh menu bất cứ lúc nào.",
        "Connect an assistant to answer questions": "Kết nối trợ lý để trả lời câu hỏi",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Dictate có thể ghi âm cuộc gọi trên trình duyệt và giữ bản ghi trên máy Mac này. Bắt đầu từ thanh menu khi cuộc gọi tiếp theo diễn ra — sự đồng ý chỉ được hỏi một lần.",
        "Done": "Xong",
        "Every change takes effect immediately.": "Mọi thay đổi có hiệu lực ngay lập tức.",
        "Get one at %@.": "Lấy khóa tại %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Giữ một phím, nói, rồi thả ra. Những gì bạn nói được gõ vào nơi con trỏ đang đứng, trong mọi ứng dụng trên máy Mac này.",
        "Keys": "Phím",
        "Languages": "Ngôn ngữ",
        "Library": "Thư viện",
        "Paste a key from your own account.": "Dán khóa từ tài khoản của chính bạn.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Đã lưu vào Keychain nhưng chưa xác minh — máy Mac này đang ngoại tuyến. Sẽ kiểm tra khi bạn hỏi lần đầu.",
        "Set Up Dictate": "Thiết lập Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Được lưu trong Keychain của macOS trên máy Mac này. Không bao giờ ghi vào tệp cài đặt, không bao giờ đồng bộ.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Khóa bị từ chối. Có thể đã bị thu hồi, thuộc nhà cung cấp khác hoặc hết tín dụng — khóa chưa được lưu.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Bản ghi, tìm kiếm và trích dẫn hoạt động mà không cần điều này. Trợ lý chỉ cần để viết câu trả lời.",
        "Try Again": "Thử lại",
        "Updates": "Cập nhật",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Bạn trả phí cho nhà cung cấp theo từng câu hỏi — thường chỉ một phần xu. Chỉ câu hỏi và các đoạn trích được gửi đi; bản ghi âm không bao giờ rời khỏi máy Mac này.",
        "Send": "Gửi",
        "Conversations": "Cuộc trò chuyện",
        "New question": "Câu hỏi mới",
        "Deleted “%@”": "Đã xóa “%@”",
        "Undo": "Hoàn tác",
        "Questions you ask are kept here so you can return to an answer.": "Các câu hỏi được lưu ở đây để bạn quay lại câu trả lời.",
        "Rename": "Đổi tên",
        "Delete": "Xóa",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Giọng nói được so khớp theo âm thanh — tên chỉ áp dụng cho lượt nói của giọng này.",
        "Give two voices the same name to merge them.": "Đặt cùng một tên cho hai giọng để gộp chúng.",
        "Voices are told apart by sound — one person can show up as two.": "Các giọng nói được phân biệt theo âm thanh — một người có thể hiện thành hai.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "Bấm vào tên để đổi tên một giọng — tên giống nhau sẽ gộp hai giọng làm một. Bản tóm tắt và câu trả lời dựa trên những gì được nói, không phải ai đã nói.",
        "Voice separation improves over time.": "Việc phân tách giọng nói sẽ tốt hơn theo thời gian.",
        "About voice separation": "Về phân tách giọng nói",
        "Call · voice %d": "Cuộc gọi · giọng %d",
        "Starred": "Đã gắn sao",
        "Other browser calls": "Cuộc gọi trình duyệt khác",
        "Sources": "Nguồn",
        "Star meeting": "Gắn sao",
        "Unstar meeting": "Bỏ gắn sao",
        "Export transcript…": "Xuất bản ghi…",
        "Still recording": "Vẫn đang ghi âm",
        "Got it": "Đã hiểu",
        "Call": "Cuộc gọi",
        "Dictating": "Đang đọc chính tả",
        "Dictating in %@": "Đang đọc chính tả bằng %@",
        "Translating into English": "Đang dịch sang tiếng Anh",
        "Translating into %@": "Đang dịch sang %@",
        "Release %@ to insert": "Thả %@ để chèn",
        "Also recording this meeting": "Cuộc họp này cũng đang được ghi âm",
        "%@ MB/s · about %@ left": "%@ MB/s · còn khoảng %@",
        "Not enough disk space: the download needs about %d MB and %d MB is free. Free up space and try again.": "Không đủ dung lượng đĩa: bản tải cần khoảng %d MB nhưng chỉ còn %d MB trống. Hãy giải phóng dung lượng rồi thử lại.",
        "Fix…": "Sửa…",
        "Checked automatically · last %@": "Kiểm tra tự động · lần cuối: %@",
        "Source code": "Mã nguồn",
        "Report an issue": "Báo cáo sự cố",
        "Finishing the transcript…": "Đang hoàn tất bản ghi…",
        "Disk almost full — will stop to keep the transcript": "Đĩa sắp đầy — sẽ dừng để giữ bản ghi",
        "Dictate is running from its disk image": "Dictate đang chạy từ ảnh đĩa",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Quyền cấp từ ảnh đĩa sẽ mất ngay khi đẩy ra, và mô hình sẽ phải tải lại mỗi lần. Hãy chuyển Dictate vào thư mục Ứng dụng trước.",
        "Move to Applications": "Chuyển vào Ứng dụng",
        "Quit": "Thoát",
        "Couldn't move Dictate automatically": "Không thể tự động chuyển Dictate",
        "Drag Dictate from the disk image into the Applications folder, then launch it from there.": "Kéo Dictate từ ảnh đĩa vào thư mục Ứng dụng, rồi mở từ đó.",
        "OK": "OK",
        "Inserted into %@": "Đã chèn vào %@",
        "Inserted": "Đã chèn",
        "Accessibility is off — dictation can hear you but cannot type": "Trợ năng đang tắt — đọc chính tả nghe được bạn nhưng không thể gõ",
        "Open Privacy & Security…": "Mở Quyền riêng tư & Bảo mật…",
        "1 dictation still being recognized": "1 lần đọc vẫn đang được nhận dạng",
        "%d dictations still being recognized": "%d lần đọc vẫn đang được nhận dạng",
        "Language Packs…": "Gói ngôn ngữ…",
        "With this off, Dictate is menu-bar only. Clicking the Dock icon opens Meetings; the menu bar item is always there either way.":
            "Khi tắt, Dictate chỉ nằm trên thanh menu. Bấm biểu tượng Dock sẽ mở Cuộc họp; biểu tượng trên thanh menu luôn có mặt.",
        "Interface language": "Ngôn ngữ giao diện",
        "Granted": "Đã cấp",
        "No": "Chưa",
        "Model ready": "Mô hình đã sẵn sàng",
        "On-device recognition": "Nhận dạng trên thiết bị",
        "Spoken language": "Ngôn ngữ nói",
        "Download failed. Check your connection and retry.": "Tải không thành công. Hãy kiểm tra kết nối và thử lại.",
        "Not set": "Chưa gán",
        "Remove": "Gỡ bỏ",
        "Download & continue": "Tải về và tiếp tục",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Khoảng %@ — chỉ tải một lần. Đây là lần duy nhất Dictate cần internet.",
        "Hold %@ and say something — the recognized text shows up below.": "Giữ %@ và nói gì đó — văn bản được nhận dạng sẽ hiện bên dưới.",
        "Recognized text appears here…": "Văn bản được nhận dạng sẽ hiện ở đây…",
        // Menu bar
        "Settings…": "Cài đặt…",
        "Quit Dictate": "Thoát Dictate",
        "Dictate — voice dictation": "Dictate — đọc chính tả bằng giọng nói",
        // HUD
        "Recognizing…": "Đang nhận dạng…",
        "Esc to cancel": "Esc để hủy",
        // Errors
        "Couldn't start recording: %@": "Không thể bắt đầu ghi âm: %@",
        "Recording truncated at %d seconds (limit)": "Bản ghi bị cắt ở giây thứ %d (giới hạn)",
        "Audio device changed during recording — recording cancelled, please try again.": "Thiết bị âm thanh thay đổi trong lúc ghi — bản ghi đã bị hủy, vui lòng thử lại.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "Quyền Trợ năng đang tắt nên không nhận biết được phím. Hãy bật trong Cài đặt hệ thống → Quyền riêng tư & Bảo mật → Trợ năng — Dictate sẽ tự nhận ngay, không cần khởi động lại.",
        "Microphone unavailable (no input audio format)": "Micrô không khả dụng (không có định dạng âm thanh đầu vào)",
        // Key names
        "Right Option (⌥)": "Option phải (⌥)",
        "Left Option (⌥)": "Option trái (⌥)",
        "Right Command (⌘)": "Command phải (⌘)",
        "Left Command (⌘)": "Command trái (⌘)",
        "Right Shift (⇧)": "Shift phải (⇧)",
        "Left Shift (⇧)": "Shift trái (⇧)",
        "Right Control (⌃)": "Control phải (⌃)",
        "Left Control (⌃)": "Control trái (⌃)",
        "Space": "Phím cách",
        "Follow system": "Theo hệ thống",
        "Translating…": "Đang dịch…",
        "Tip: hold %@ instead — your speech comes out in English.": "Mẹo: giữ %@ thay vì phím thường — lời nói của bạn sẽ thành tiếng Anh.",
        "Hold to talk in your language, release to insert it in English.": "Giữ phím và nói bằng ngôn ngữ của bạn, thả ra — văn bản chèn vào bằng tiếng Anh.",
        "Hold %@ and say it again — this time it's typed in English.": "Giữ %@ và nói lại câu đó — lần này sẽ được gõ bằng tiếng Anh.",
        "Translate to": "Dịch sang",
        "Translation data isn't downloaded — open Settings to get it": "Chưa tải dữ liệu dịch — hãy tải trong Cài đặt",
        "Translation data": "Dữ liệu dịch",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "Phím dịch phiên âm lời bạn nói, rồi macOS dịch ngay trên máy Mac này. Khi chọn ngôn ngữ, macOS có thể tải dữ liệu dịch một lần.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "Nhận dạng chạy trên Neural Engine của máy Mac — Whisper large-v3-turbo: 100 ngôn ngữ, xử lý tốt giọng vùng miền và đủ nhanh để hiện văn bản trực tiếp. Việc dịch cũng diễn ra trên máy Mac này. Giọng nói của bạn không bao giờ rời khỏi máy tính này.",
        "Hold %@ and say it again — this time it comes out in %@.": "Giữ %@ và nói lại câu đó — lần này sẽ ra bằng %@.",
        "Hold to talk in your language, release to insert it in %@.": "Giữ phím và nói bằng ngôn ngữ của bạn, thả ra — văn bản chèn vào bằng %@.",
        "Not downloaded": "Chưa tải xuống",
        "Translation languages": "Ngôn ngữ dịch",
        "Downloaded": "Đã tải",
        "Manage in System Settings…": "Quản lý trong Cài đặt Hệ thống…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "Đã BẬT trong Cài đặt Hệ thống nhưng ở đây chưa xanh? Tắt rồi bật lại công tắc Dictate — sau khi cập nhật, macOS đôi khi giữ mục đăng ký cũ.",
        "Agent: %@, on your key.": "Tác nhân: %@, bằng khóa của bạn.",
        "Agent: off.": "Tác nhân: tắt.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "Apple Intelligence không khả dụng trên máy Mac này ở khu vực hoặc ngôn ngữ này. Tác nhân với khóa của riêng bạn vẫn hoạt động.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Apple Intelligence cần macOS 26. Tác nhân với khóa của riêng bạn vẫn hoạt động.",
        "Copy diagnostics": "Sao chép chẩn đoán",
        "Debug audio dumps": "Tệp âm thanh gỡ lỗi",
        "Diagnostics": "Chẩn đoán",
        "Downloading…": "Đang tải…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Giải phóng %@. Các cuộc họp mới sẽ giữ tên theo ngày cho đến khi bạn tải lại. Những tóm tắt đã viết vẫn còn.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Giải phóng %@. Không gì khác thay đổi — tính năng đọc cuộc họp đang tắt.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Giải phóng %@. Tiêu đề và tóm tắt sẽ đến từ Apple Intelligence.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Đã cài nhưng không chạy: máy Mac này có %d GB bộ nhớ và nó cần 16.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Đã cài nhưng không chạy: máy Mac này có %d GB bộ nhớ và nó cần 16. Không gì trên máy Mac này đọc cuộc họp.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Đã cài nhưng không chạy: máy Mac này có %d GB bộ nhớ và nó cần 16. Thay vào đó, tiêu đề và tóm tắt đến từ Apple Intelligence.",
        "Installed · %@": "Đã cài · %@",
        "Installed, not in use · %@": "Đã cài, không dùng · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Khi viết, nó chiếm khoảng %@ bộ nhớ, máy Mac này sẽ cảm nhận được.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, phiên bản và những tính năng đang bật. Không có bản ghi chép, không có khóa.",
        "Meeting archive": "Kho lưu cuộc họp",
        "Meeting model": "Mô hình cuộc họp",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Đã cài mô hình cuộc họp. Các cuộc họp mới có tiêu đề và tóm tắt trên máy Mac này.",
        "Meeting reading: Apple Intelligence.": "Đọc cuộc họp: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Đọc cuộc họp: chưa có gì trên máy Mac này làm được.",
        "Meeting reading: the downloaded model (%@).": "Đọc cuộc họp: mô hình đã tải (%@).",
        "Not available on this Mac.": "Không khả dụng trên máy Mac này.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "Chưa cài. Một lần tải %@ sẽ viết tiêu đề, tóm tắt và mục lục.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "Chưa có gì trên máy Mac này đọc được: Apple Intelligence không khả dụng ở đây. Tác nhân với khóa của riêng bạn vẫn hoạt động.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "Chưa có gì trên máy Mac này đọc được: tải mô hình cuộc họp bên dưới, hoặc thêm khóa cho tác nhân.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "Chưa có gì trên máy Mac này đọc được: tải mô hình cuộc họp bên dưới, hoặc bật Apple Intelligence trong Cài đặt Hệ thống.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "Chưa có gì trên máy Mac này đọc được: macOS vẫn đang thiết lập Apple Intelligence. Tác nhân với khóa của riêng bạn vẫn hoạt động.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "Chưa có gì trên máy Mac này đọc được: bật Apple Intelligence trong Cài đặt Hệ thống, hoặc thêm khóa cho tác nhân.",
        "Open System Settings": "Mở Cài đặt Hệ thống",
        "Paused: not enough free memory right now. It resumes on its own.": "Tạm dừng: hiện không đủ bộ nhớ trống. Nó sẽ tự tiếp tục.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Đang chuẩn bị mô hình cho bộ xử lý của máy Mac này… Vài phút, chỉ một lần.",
        "Raw call audio kept for debugging only.": "Âm thanh cuộc gọi thô, chỉ giữ để gỡ lỗi.",
        "Reading is on, but nothing on this Mac can read yet.": "Đọc đang bật, nhưng chưa có gì trên máy Mac này đọc được.",
        "Reads with Apple Intelligence.": "Đọc bằng Apple Intelligence.",
        "Reads with the downloaded model.": "Đọc bằng mô hình đã tải.",
        "Recognition runs on the Neural Engine.": "Nhận dạng chạy trên Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "Nhận dạng chạy trên bộ xử lý của máy Mac này — Whisper large-v3-turbo: 100 ngôn ngữ, xử lý tốt giọng vùng miền. Chậm hơn trên Apple Silicon, và việc dịch cũng diễn ra trên máy Mac này. Giọng nói của bạn không bao giờ rời khỏi máy tính này.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "Nhận dạng chạy trên bộ xử lý của máy Mac này — chậm hơn trên Apple Silicon.",
        "Remove the debug audio dumps?": "Gỡ bỏ các tệp âm thanh gỡ lỗi?",
        "Remove the meeting model?": "Gỡ bỏ mô hình cuộc họp?",
        "Remove…": "Gỡ bỏ…",
        "Speaker models": "Mô hình người nói",
        "Speech model": "Mô hình giọng nói",
        "Storage": "Lưu trữ",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Tóm tắt trên máy Mac này đến từ Apple Intelligence. Mô hình tải về cần 16 GB bộ nhớ; máy Mac này có %d.",
        "Summary paused: not enough free memory. It resumes on its own.": "Tóm tắt tạm dừng: không đủ bộ nhớ trống. Nó sẽ tự tiếp tục.",
        "Tell the voices on a call apart.": "Phân biệt các giọng nói trong cuộc gọi.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "Mô hình cuộc họp cần 16 GB bộ nhớ; máy Mac này có %d.",
        "These are recordings kept only for debugging. Nothing else is affected.": "Đây là các bản ghi chỉ giữ để gỡ lỗi. Không gì khác bị ảnh hưởng.",
        "This Mac": "Máy Mac này",
        "This build of Dictate does not include the meeting model.": "Bản dựng Dictate này không bao gồm mô hình cuộc họp.",
        "Titles and summaries come from Apple Intelligence instead.": "Thay vào đó, tiêu đề và tóm tắt đến từ Apple Intelligence.",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "Bật Apple Intelligence trong Cài đặt Hệ thống › Apple Intelligence & Siri, hoặc thêm khóa cho tác nhân.",
        "Waiting for the call to end.": "Đang chờ cuộc gọi kết thúc.",
        "Your transcripts, as Markdown files you own.": "Bản ghi chép của bạn, dưới dạng tệp Markdown do bạn sở hữu.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "macOS vẫn đang thiết lập Apple Intelligence — hãy quay lại sau, hoặc thêm khóa cho tác nhân.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. Báo cáo vẫn nằm trong tệp cuộc họp dù thế nào; thao tác này tạo một bản sao.",
        "%d fields": "%d trường",
        "Add field": "Thêm trường",
        "Agent & reports": "Tác nhân & báo cáo",
        "Also one table (CSV): a row per meeting, a column per field": "Thêm một bảng (CSV): mỗi cuộc họp một hàng, mỗi trường một cột",
        "Answers with": "Trả lời bằng",
        "Choose folder…": "Chọn thư mục…",
        "Copy report": "Sao chép báo cáo",
        "Date": "Ngày",
        "Export %d “%@” reports": "Xuất %d báo cáo “%@”",
        "Export reports…": "Xuất báo cáo…",
        "Export report…": "Xuất báo cáo này…",
        "Export the “%@” report": "Xuất báo cáo “%@”",
        "Field name": "Tên trường",
        "Fields": "Trường",
        "Format:": "Định dạng:",
        "Markdown": "Markdown",
        "Meeting": "Cuộc họp",
        "New template": "Mẫu mới",
        "New template…": "Mẫu mới…",
        "No reports written with “%@” yet.": "Chưa có báo cáo nào viết bằng “%@”.",
        "No templates yet.": "Chưa có mẫu nào.",
        "Not discussed": "Không thảo luận",
        "One empty field. You name it.": "Một trường trống. Bạn tự đặt tên.",
        "One file per meeting, named by date and title, in a folder you choose. Transcripts are not included.": "Mỗi cuộc họp một tệp, đặt tên theo ngày và tiêu đề, trong thư mục bạn chọn. Không kèm bản ghi.",
        "PDF": "PDF",
        "Plain text": "Văn bản thuần",
        "Questions across your meetings, and reports.": "Câu hỏi xuyên suốt các cuộc họp, và báo cáo.",
        "Remove field": "Bỏ trường",
        "Remove template": "Bỏ mẫu",
        "Remove template…": "Bỏ mẫu…",
        "Remove “%@”?": "Bỏ “%@”?",
        "Report": "Báo cáo",
        "Report not written": "Báo cáo chưa được viết",
        "Reports": "Báo cáo",
        "Reports already written with it stay in their meetings.": "Các báo cáo đã viết bằng nó vẫn ở trong cuộc họp của chúng.",
        "Same as Dictate": "Giống Dictate",
        "Template name": "Tên mẫu",
        "Templates": "Mẫu",
        "The model returned no report.": "Mô hình không trả về báo cáo.",
        "The model stopped before the report was finished.": "Mô hình dừng trước khi báo cáo hoàn tất.",
        "The saved key no longer works. It has been removed from the Keychain.": "Khóa đã lưu không còn hoạt động. Đã xóa khỏi Keychain.",
        "What is sent": "Những gì được gửi",
        "Writing · about a minute": "Đang viết · khoảng một phút",
        "Written by Dictate on this Mac from the transcript": "Viết bởi Dictate trên máy Mac này từ bản ghi",
        "Your %@ account refused the request for billing reasons.": "Tài khoản %@ của bạn đã từ chối yêu cầu vì lý do thanh toán.",
        "Sends this transcript to %@ on your key. The report lands in the meeting’s file.": "Gửi bản ghi này tới %@ bằng khóa của bạn. Báo cáo được lưu vào tệp cuộc họp.",
        "Set up templates…": "Thiết lập mẫu…",
        "Write report": "Viết báo cáo",
        "%@ is rate limiting. Nothing was lost — try again in a minute.": "%@ đang giới hạn tần suất yêu cầu. Không mất gì cả — hãy thử lại sau một phút.",
        "This Mac is offline. Nothing was sent — try again when the connection returns.": "Mac này đang ngoại tuyến. Chưa gửi gì cả — hãy thử lại khi có kết nối.",
        "Write a “%@” report?": "Viết báo cáo “%@”?",
        "Action items": "Việc cần làm",
        "Dates and deadlines": "Ngày và hạn chót",
        "Decisions": "Quyết định",
        "Decisions & actions": "Quyết định và việc cần làm",
        "Every date, deadline or time window that was mentioned, and what it is for": "Mọi ngày, hạn chót hoặc khoảng thời gian được nhắc đến, và dành cho việc gì",
        "Key points": "Điểm chính",
        "Meeting summary": "Tóm tắt cuộc họp",
        "Next step": "Bước tiếp theo",
        "Open questions": "Câu hỏi còn mở",
        "Purpose": "Mục đích",
        "Risks and concerns": "Rủi ro và lo ngại",
        "The main arguments and facts, with the numbers, names and dates that were said": "Các lập luận và sự kiện chính, kèm số liệu, tên và ngày đã được nói",
        "The next meeting or checkpoint, if one was agreed": "Cuộc họp hoặc mốc kiểm tra tiếp theo, nếu đã thống nhất",
        "Waiting on": "Đang chờ",
        "We are the team on this call; the reader took part in it.": "Chúng tôi là nhóm trong cuộc gọi này; người đọc đã tham gia.",
        "What could go wrong, who raised it, how serious it sounded": "Điều gì có thể sai, ai nêu ra, nghe nghiêm trọng đến mức nào",
        "What each side is waiting for from the other": "Mỗi bên đang chờ gì từ bên kia",
        "What was decided, by whom, and what it replaces": "Điều gì đã được quyết định, bởi ai, và thay thế điều gì",
        "What was raised and not settled, and who owns it": "Điều gì được nêu nhưng chưa giải quyết, và ai chịu trách nhiệm",
        "Who does what, by when — one line per task": "Ai làm gì, đến khi nào — mỗi việc một dòng",
        "Why we met and what we set out to settle": "Vì sao chúng tôi họp và muốn giải quyết điều gì",
        "%d more": "%d nữa",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "Tiêu đề giữ ngôn ngữ của cuộc họp; bản tóm tắt và mọi báo cáo được viết bằng ngôn ngữ này. Tên trường trong báo cáo giữ nguyên như đã nhập.",
        "About “%@”:": "Về “%@”:",
        "Replace the report with a new “%@” one?": "Thay báo cáo bằng báo cáo “%@” mới?",
        "Replace report": "Thay báo cáo",
        "Written · replaces it": "Đã viết · sẽ thay thế",
        "Dictate updated to %@.": "Dictate đã cập nhật lên %@.",
        "Dismiss": "Đóng",
        "New": "Mới",
        "New in this version": "Mới trong phiên bản này",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Mở một cuộc họp, bấm Write report ở phần đầu rồi chọn mẫu. Báo cáo xuất hiện trên thẻ và dưới dạng PDF trong Dictate Meetings › Reports.",
        "Reports from templates": "Báo cáo từ mẫu",
        "See what’s new": "Xem có gì mới",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Cài đặt › Cuộc họp › Viết tóm tắt và báo cáo bằng: tóm tắt và mọi báo cáo được viết bằng ngôn ngữ bạn đọc, bất kể cuộc gọi dùng ngôn ngữ nào.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Cài đặt › Mẫu: bắt đầu từ Tóm tắt cuộc họp hoặc Quyết định và việc cần làm, hoặc tự đặt tên các trường và cho mô hình biết cần viết gì dưới mỗi trường.",
        "Summaries in your language": "Tóm tắt bằng ngôn ngữ của bạn",
        "What’s new": "Có gì mới",
        "What’s new in Dictate %@": "Có gì mới trong Dictate %@",
        "Your own templates": "Mẫu của riêng bạn",
        "Install update %@ and relaunch": "Cài bản cập nhật %@ và khởi động lại",
        "The update waits until the recording ends.": "Bản cập nhật sẽ đợi đến khi ghi âm kết thúc.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "Bản cập nhật %@ đang tải về. Nó sẽ tự cài vào lúc rảnh tiếp theo; thanh menu cho phép cài sớm hơn.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "Bản cập nhật %@ đã sẵn sàng — cài từ thanh menu, hoặc nó sẽ tự cài vào lúc rảnh tiếp theo.",
        "An update is already on its way — it installs itself at the next quiet moment.": "Bản cập nhật đã đang tải — nó sẽ tự cài vào lúc rảnh tiếp theo.",
        "Downloading update %@…": "Đang tải bản cập nhật %@…",
        "Preparing update %@…": "Đang chuẩn bị bản cập nhật %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Dictate đã cập nhật lên %@. Có gì mới nằm trong cửa sổ Cuộc họp.",
        "Apple Intelligence declined to summarize this meeting.": "Apple Intelligence đã từ chối tóm tắt cuộc họp này.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "Biên bản, tìm kiếm và tác nhân không bị ảnh hưởng. Mô hình tải về, lưu trên máy Mac này, không có giới hạn đó.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Cuộc họp được ghi và cấu trúc: người nói, tóm tắt, dàn ý, tìm kiếm. Dictate đề nghị ghi cuộc gọi — không bao giờ ghi khi bạn chưa trả lời.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "Mô hình cuộc họp cần 16 GB bộ nhớ; máy Mac này có %d. Nó không chạy, và %@ nó chiếm trên đĩa có thể được giải phóng.",
        "Clipboard restored.": "Đã khôi phục bảng nhớ tạm.",
        "Your words were inserted untranslated.": "Lời bạn nói đã được chèn mà chưa dịch.",
        "A small panel appears when a call starts, and you decide there.": "Một bảng nhỏ xuất hiện khi cuộc gọi bắt đầu và bạn quyết định tại đó.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Viết tóm tắt và dàn ý, và cho tác nhân thứ để trả lời. Dù thế nào cũng không có gì được gửi đi đâu.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Tắt, bạn chỉ có micrô của mình; bật, phía bên kia cũng được ghi chép.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Biến một khối văn bản thành các lượt nói có tên. Việc phân tách dựa theo âm thanh và có thể thiếu chính xác; tên có thể đổi.",
        "Find in this transcript…": "Tìm trong biên bản này…",
        "%d of %d": "%d / %d",
        "No matches": "Không có kết quả",
        "Previous match": "Kết quả trước",
        "Next match": "Kết quả sau",
        "Close find": "Đóng tìm kiếm",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "Đã chọn %@, nhưng chưa có khóa. Trợ lý và báo cáo vẫn tắt cho đến khi thêm khóa.",
        "%@ · required for dictation, cannot be removed.": "%@ · cần cho đọc chính tả, không thể gỡ bỏ.",
        "%@ — not written": "%@ — chưa viết",
        "%d h": "%d giờ",
        "%d meetings have a %@ report. They stay if this template goes.": "%d cuộc họp có báo cáo “%@”. Chúng vẫn còn nếu mẫu này bị xóa.",
        "%d min ago": "%d phút trước",
        "%d written": "đã viết %d",
        "%d written, %d not written": "đã viết %d, chưa viết %d",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 ngôn ngữ. Áp dụng ngay cho cửa sổ này và thanh menu. Ngôn ngữ bạn nói được đặt trong Đọc chính tả.",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Khóa từ tài khoản %@ của riêng bạn. Lưu trong Keychain, không bao giờ trong tệp cài đặt.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Câu hỏi gửi đi câu hỏi và các đoạn mà tìm kiếm tìm thấy. Báo cáo gửi toàn bộ bản ghi của cuộc họp đó — khoảng 12.000 từ cho một giờ trò chuyện. Cả hai đều đến %@ bằng khóa của bạn, và chỉ khi bạn yêu cầu. Bản ghi âm không bao giờ rời khỏi máy Mac này.",
        "About": "Giới thiệu",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "Apple Intelligence không khả dụng trên máy Mac này, nên không có phương án dự phòng.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Apple Intelligence cần macOS mới hơn phiên bản trên máy Mac này, nên không có phương án dự phòng.",
        "Applies to this window, the meetings window and the panels over your other apps.": "Áp dụng cho cửa sổ này, cửa sổ cuộc họp và các bảng hiện trên các ứng dụng khác của bạn.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Chỉ hỏi một lần. Sau đó bảng này là phiên bản ngắn và ở lại cho đến khi bạn trả lời. Bạn cũng có thể bắt đầu ghi từ thanh menu bất cứ lúc nào trong cuộc gọi.",
        "Calendar": "Lịch",
        "Collapse %@": "Thu gọn %@",
        "Copy": "Sao chép",
        "Dictation": "Đọc chính tả",
        "Expand %@": "Mở rộng %@",
        "Export…": "Xuất…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "Nó cũng có trong Đọc chính tả gần đây, nên bạn có thể dùng lại bảng tạm bất cứ khi nào muốn.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Được giữ trong tệp của cuộc họp này, nên đi cùng bản ghi. Xuất sẽ tạo bản sao ở bất cứ đâu bạn muốn.",
        "No report": "Không có báo cáo",
        "No report for this meeting yet.": "Chưa có báo cáo cho cuộc họp này.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "Gỡ bỏ không mất gì cả: bản ghi, tìm kiếm và trợ lý không phụ thuộc vào nó.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Không có gì được đặt ở đây. Mỗi dòng phía trên hoặc cho biết máy Mac này làm được gì, hoặc chỉ đến bảng phụ trách.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "Chưa có gì trên máy Mac này đọc được: Apple Intelligence cần macOS mới hơn. Trợ lý dùng khóa riêng của bạn vẫn hoạt động.",
        "Nothing was kept from this take — earlier ones are still here.": "Lần này không giữ được gì — những lần trước vẫn còn ở đây.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "Không ghi được gì nên không giữ gì cả. Những lần trước vẫn còn ở đây.",
        "Off — dictation cannot type": "Tắt — đọc chính tả không thể gõ",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Tắt: bản ghi, tóm tắt, dàn ý và tìm kiếm vẫn hoạt động như trước. Trợ lý trả lời câu hỏi trên mọi cuộc họp của bạn và viết báo cáo từ mẫu của bạn; nó chạy trên đám mây bằng khóa API của riêng bạn.",
        "On this Mac": "Trên máy Mac này",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Một tệp có thể tải tiếp. Đóng Dictate sẽ tạm dừng; sau đó tiếp tục từ chỗ đã dừng.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Tải một lần %@, sau đó tiêu đề, tóm tắt và dàn ý được tạo hoàn toàn trên máy Mac này. Cần 16 GB bộ nhớ để chạy và chiếm khoảng %@ khi đang viết.",
        "Open System Settings…": "Mở Cài đặt Hệ thống…",
        "Or start from the menu bar later in the call.": "Hoặc bắt đầu từ thanh menu sau đó trong cuộc gọi.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "Đang tạm dừng: không đủ bộ nhớ trống. Nó sẽ tự tiếp tục, và các cuộc họp đang chờ tóm tắt vẫn giữ bản ghi.",
        "Permissions": "Quyền",
        "Reads with Apple Intelligence until the download finishes.": "Đọc bằng Apple Intelligence cho đến khi tải xong.",
        "Reads with the downloaded model — paused until there is free memory.": "Đọc bằng mô hình đã tải — tạm dừng cho đến khi có bộ nhớ trống.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Mẫu báo cáo nằm trong Mẫu; báo cáo đã viết nằm trong thư viện, mục Báo cáo.",
        "Report · %@": "Báo cáo · %@",
        "Report · %@ +%d": "Báo cáo · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Báo cáo cần trợ lý, nhưng trợ lý đang tắt. Chọn Claude hoặc ChatGPT trong Tóm tắt và báo cáo; các mẫu vẫn được giữ cho đến lúc đó.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Chạy hoàn toàn trên máy Mac này. Nếu không có, tiêu đề và tóm tắt đến từ Apple Intelligence.",
        "Startup": "Khởi động",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Lưu trong Keychain, không bao giờ trong tệp cài đặt. Trợ lý trả lời câu hỏi trên mọi cuộc họp của bạn và viết báo cáo từ mẫu của bạn.",
        "Summaries": "Tóm tắt",
        "Summaries & reports": "Tóm tắt và báo cáo",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "Tải về là cách để có tóm tắt trên máy Mac này mà không cần Apple Intelligence. Bản ghi và tìm kiếm vẫn hoạt động dù thế nào.",
        "This Mac was offline. Nothing was sent.": "Máy Mac này đã ngoại tuyến. Không có gì được gửi đi.",
        "This take was not kept. Earlier ones are still here.": "Lần này không được giữ. Những lần trước vẫn còn ở đây.",
        "Uses 41 MB of speaker models.": "Dùng 41 MB mô hình người nói.",
        "What’s new in %@": "Có gì mới trong %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Có thứ gì đọc các bản ghi âm này hay không — tóm tắt, dàn ý, báo cáo và trợ lý — được đặt trong Tóm tắt và báo cáo. Bảng này chỉ nói về những gì được ghi trên máy Mac này.",
        "Write again": "Viết lại",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "Viết báo cáo ở trên liệt kê %d mẫu của bạn. Viết một báo cáo sẽ gửi bản ghi này đến %@ bằng khóa của bạn; báo cáo được giữ trong tệp của cuộc họp này nên đi cùng bản ghi. Xuất sẽ tạo bản sao ở bất cứ đâu bạn muốn.",
        "Written %@": "Viết lúc %@",
        "Written by %@": "Viết bởi %@",
        "Written by %@ %@ at %@": "Viết bởi %@ ngày %@ lúc %@",
        "Written in": "Viết bằng",
        "Your agent, on your key": "Trợ lý của bạn, bằng khóa của bạn",
        "click to insert": "bấm để chèn",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "macOS vẫn đang thiết lập Apple Intelligence. Có thể mất một lúc và không thể thúc nhanh từ đây.",
        "macOS resets this switch after some updates and never asks a second time.": "macOS đặt lại công tắc này sau một số bản cập nhật và không bao giờ hỏi lần thứ hai.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-bấm để sao chép thay vì chèn. Xóa khi thoát Dictate.",
        "Meeting names": "Tên cuộc họp",
        "%d meetings, reports included": "%d cuộc họp, gồm cả báo cáo",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "Tải mô hình cuộc họp trong Tóm tắt và báo cáo, hoặc thêm khóa cho trợ lý.",
        "Calls": "Cuộc gọi",
        "Reports folder": "Thư mục báo cáo",
        "%d PDFs written before %@": "%d PDF được ghi trước %@",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Dictate không còn tự ghi PDF nữa. Các tệp này là của bạn, giữ hay xóa tùy ý; không có gì trong ứng dụng phụ thuộc vào chúng.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "Báo cáo đã viết sẽ bị thay thế. Gửi bản ghi này đến %@ bằng khóa của bạn.",
        "%@ · report not written": "%@ · báo cáo chưa viết",
        "%d of %d selected · %d meetings without one": "đã chọn %d trên %d · %d cuộc họp chưa có",
        "%d passages from %d meetings": "%d đoạn từ %d cuộc họp",
        "%d written across %d templates": "đã viết %d với %d mẫu",
        "%d written · %d meetings without one · %d fields": "đã viết %d · %d cuộc họp chưa có · %d trường",
        "%d written · writing %d · %d not written": "đã viết %d · đang viết %d · chưa viết %d",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Báo cáo được viết khi bạn yêu cầu — từ thẻ cuộc họp, hoặc cho các cuộc họp được chọn ở đây. Mỗi báo cáo gửi bản ghi của cuộc họp đó đến %@ bằng khóa của bạn và được giữ trong tệp của cuộc họp.",
        "All reports": "Tất cả báo cáo",
        "Answer": "Câu trả lời",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Trả lời bởi %@ từ %d trên %d cuộc họp. Trích dẫn nguyên văn từ bản ghi trên máy Mac này.",
        "Copy as Markdown": "Sao chép dạng Markdown",
        "Copy as plain text": "Sao chép dạng văn bản thuần",
        "Copy the answer only": "Chỉ sao chép câu trả lời",
        "Copy with quotes": "Sao chép kèm trích dẫn",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "Mỗi mẫu giữ báo cáo riêng: những gì đã viết, và các cuộc họp có thể có báo cáo. Bản thân mẫu được chỉnh trong Cài đặt › Mẫu.",
        "Edit template…": "Sửa mẫu…",
        "No report yet · %d meetings": "Chưa có báo cáo · %d cuộc họp",
        "None written · %d fields": "Chưa viết · %d trường",
        "Nothing written from this template yet": "Chưa có gì được viết từ mẫu này",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Tắt thì bỏ qua %d cuộc họp đó và viết %d báo cáo. Thay thế không thể hoàn tác.",
        "Pick a template": "Chọn một mẫu",
        "Quotes": "Trích dẫn",
        "Replace the %d that already have one": "Thay thế %d cuộc họp đã có",
        "Report not written — the request was refused. The meeting has the detail.": "Báo cáo chưa viết — yêu cầu bị từ chối. Chi tiết ở cuộc họp.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Gửi %d bản ghi đến %@ bằng khóa của bạn — khoảng %@ từ. Mỗi báo cáo được giữ trong tệp cuộc họp của nó. Bản ghi âm không bao giờ rời khỏi máy Mac này.",
        "The %d existing reports are overwritten. This cannot be undone.": "%d báo cáo hiện có sẽ bị ghi đè. Không thể hoàn tác.",
        "Write": "Viết",
        "Write %d": "Viết %d",
        "Write %d reports…": "Viết %d báo cáo…",
        "Write a “%@” report for %d meetings?": "Viết báo cáo “%@” cho %d cuộc họp?",
        "Write a “%@” report for “%@”?": "Viết báo cáo “%@” cho “%@”?",
        "Write all %d…": "Viết tất cả %d…",
        "Write for a selection…": "Viết cho các cuộc họp đã chọn…",
        "Write report › %@": "Viết báo cáo › %@",
        "Written": "Đã viết",
        "No instruction — goes by its name alone": "Không có hướng dẫn — chỉ theo tên",
        "Drag to reorder": "Kéo để sắp xếp lại",
        "Every report is kept inside its meeting’s file.": "Mọi báo cáo được giữ trong tệp cuộc họp của nó.",
        "A refusal stops that meeting only; the rest continue.": "Bị từ chối chỉ dừng cuộc họp đó; các cuộc họp còn lại tiếp tục.",
        "Always assume": "Luôn mặc định",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Những điều cuộc gọi không bao giờ nói ra nhưng mọi báo cáo nên coi là hiển nhiên: bạn là ai, bên nào là khách hàng, những từ nhóm bạn dùng theo nghĩa riêng. Gửi kèm mọi báo cáo từ mẫu này.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Tùy chọn. Không có nó, mô hình đọc cuộc gọi mà không biết gì trước: thường ổn với cuộc họp giữa đồng nghiệp, nhưng sai với cuộc gọi cùng bên ngoài.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Chúng tôi là đại lý bán hàng. Khách hàng luôn là bên kia, không bao giờ là chúng tôi. “Seats” nghĩa là giấy phép người dùng trả phí.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Hiển thị trên thẻ cuộc họp, trong thư viện mục Báo cáo, và làm tiêu đề trong báo cáo đã viết.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Mỗi trường trở thành một tiêu đề trong báo cáo, theo thứ tự này. Kéo trường bằng tay cầm để di chuyển. Hướng dẫn là tùy chọn và có thể dài tùy ý; trường không có hướng dẫn chỉ theo tên.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Mỗi trường chỉ được điền từ bản ghi của cuộc gọi này. Trường mà cuộc gọi không đề cập sẽ ghi “Not discussed”.",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Mẫu gồm tên và vài trường. Báo cáo được viết từ mẫu khi bạn yêu cầu, mỗi mẫu một báo cáo cho mỗi cuộc họp.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Chưa có mẫu nào. Mẫu gồm tên và vài trường; báo cáo được viết từ mẫu khi bạn yêu cầu từ thẻ cuộc họp, mỗi mẫu một báo cáo cho mỗi cuộc họp.",
    ]

    static let tl: [String: String] = [
        "Settings": "Mga Setting",
        "Keyboard shortcuts": "Mga keyboard shortcut",
        "Storage & models": "Storage at mga model",
        "The Keychain refused to save the key — it stays in the field. Try again after unlocking the keychain.": "Tumanggi ang Keychain na i-save ang key — nanatili ito sa field. I-unlock ang keychain at subukan ulit.",
        "Couldn't reach the update server. Try again once you're online.": "Hindi maabot ang update server. Subukan ulit kapag online ka na.",
        "You're up to date — Dictate %@ is the newest version.": "Updated ka na — ang Dictate %@ ang pinakabagong bersyon.",
        "Recorded meetings appear here.": "Dito lalabas ang mga na-record na meeting.",
        "This is your microphone only — the other side of the call was not recorded and cannot be recovered.": "Mikropono mo lang ito — ang kabilang panig ng tawag ay hindi na-record at hindi na maibabalik.",
        "Turning both on covers the calls that come next.": "Kapag binuksan pareho, sakop na ang mga susunod na tawag.",
        "%@ refused the request for billing reasons. Add credit in your provider account, or disconnect the agent in Settings.": "Tinanggihan ng %@ ang request dahil sa billing. Magdagdag ng credit sa provider account mo, o idiskonekta ang agent sa Settings.",
        "Agent": "Agent",
        "Ask your agent": "Tanungin ang agent",
        "Ask your agent anything…": "Itanong kahit ano sa agent mo…",
        "Has read %d of %d meetings": "Nabasa na ang %d sa %d meeting",
        "Has read 1 meeting": "Nabasa na ang 1 meeting",
        "Has read all %d meetings": "Nabasa na ang lahat ng %d meeting",
        "Meetings & Agent…": "Mga Meeting at Agent…",
        "Not now keeps the agent off and hidden. Search and transcripts are unaffected.": "Ang Hindi muna ay pananatilihing naka-off at nakatago ang agent. Hindi maaapektuhan ang paghahanap at mga transcript.",
        "Nothing to read yet": "Wala pang mababasa",
        "Off — has read nothing yet": "Naka-off — wala pang nabasa",
        "Reading %d of %d meetings…": "Binabasa ang %d sa %d meeting…",
        "This is what writes the summary and the outline, and what gives your agent something to answer from. Off, you get the raw transcript — no summary, no outline, and no agent. Nothing is sent anywhere either way.": "Ito ang sumusulat ng buod at balangkas, at nagbibigay sa agent mo ng masasagot. Kapag naka-off, hilaw na transcript lang — walang buod, walang balangkas, at walang agent. Anuman ang mangyari, walang ipinapadala kahit saan.",
        "Your agent answers questions across everything you have recorded — “what did we decide about the freeze date” — and cites the meeting and moment it came from. It needs the model that reads your meetings, which is currently off. Nothing leaves this Mac either way.": "Sinasagot ng agent mo ang mga tanong sa lahat ng na-record mo — “ano ang napagdesisyunan natin sa freeze date” — at binabanggit ang meeting at sandaling pinagmulan nito. Kailangan nito ang model na nagbabasa ng mga meeting mo, na naka-off ngayon. Anuman ang mangyari, walang umaalis sa Mac na ito.",
        "Your agent has nothing to read yet": "Wala pang mababasa ang agent mo",
        "Your agent has read 1 meeting": "Nabasa na ng agent mo ang 1 meeting",
        "Your agent has read all %d meetings": "Nabasa na ng agent mo ang lahat ng %d meeting",
        "Your agent is off": "Naka-off ang agent mo",
        "Your agent is reading — %d of %d meetings so far": "Nagbabasa ang agent mo — %d sa %d meeting sa ngayon",
        "answers with %@": "sumasagot gamit ang %@",
        "Nothing here can hear a call until it is granted in System Settings › Privacy & Security › Microphone.": "Walang makakarinig ng tawag dito hangga't hindi ito pinapayagan sa System Settings › Privacy & Security › Microphone.",
        "There is no summary or outline — reading your meetings is off.": "Walang buod o balangkas — naka-off ang pagbabasa ng mga meeting mo.",
        "This is your microphone only — the other side of the call is missing, the text is one unbroken block, and there is no summary or outline.": "Mikropono mo lang ito — wala ang kabilang panig ng tawag, iisang tuloy-tuloy na bloke ang teksto, at walang buod o balangkas.",
        "Turn both on": "Buksan pareho",
        "Turn it on": "Buksan ito",
        "Turning it on also writes them for the recordings that come next. Writing one now leaves the switch off.": "Kapag binuksan, maisusulat din ang mga ito para sa mga susunod na recording. Ang pagsulat ngayon ay mananatiling naka-off ang switch.",
        "Waiting on microphone access.": "Naghihintay ng access sa mikropono.",
        "Waits for “%@” above — there is no call audio to separate yet.": "Naghihintay sa “%@” sa itaas — wala pang audio ng tawag na paghihiwalayin.",
        "Write one, this once": "Sumulat ng isa, ngayon lang",
        "Writing one now reads only this transcript and leaves the switches off. The other side of this call was not recorded and cannot be recovered.": "Ang pagsulat ngayon ay babasahin lang ang transcript na ito at mananatiling naka-off ang mga switch. Ang kabilang panig ng tawag na ito ay hindi na-record at hindi na maibabalik.",
        "Writing…": "Sinusulat…",
        "macOS denied microphone access": "Tinanggihan ng macOS ang access sa mikropono",
        "%@ call — not being recorded": "Tawag sa %@ — hindi nire-record",
        "Call recording is off, so this one is passing untranscribed. Turning it on gives you a searchable transcript and a summary afterwards, kept on this Mac.": "Naka-off ang pag-record ng tawag, kaya lilipas ito nang walang transcript. Kapag binuksan, magkakaroon ka pagkatapos ng transcript na mahahanap at buod, nakatago sa Mac na ito.",
        "Call — not being recorded": "Tawag — hindi nire-record",
        "Calls are not noticed automatically. You can start each one here, or let Dictate offer when a call begins.": "Hindi awtomatikong napapansin ang mga tawag. Maaari mong simulan ang bawat isa dito, o hayaang mag-alok ang Dictate kapag nagsimula ang tawag.",
        "Connect a provider…": "Ikonekta ang provider…",
        "Dictation still works. Each switch below says what it adds; you can turn on one and leave the rest alone.": "Gumagana pa rin ang dictation. Sinasabi ng bawat switch sa ibaba kung ano ang idinadagdag nito; maaari mong buksan ang isa at hayaan ang iba.",
        "Dictation works already — hold the dictation key and speak anywhere. Everything below is about meetings, and none of it is required. Turn on what you want; the rest stays off.": "Gumagana na ang dictation — pindutin nang matagal ang dictation key at magsalita kahit saan. Ang lahat sa ibaba ay tungkol sa mga meeting, at walang kinakailangan dito. Buksan ang gusto mo; mananatiling naka-off ang iba.",
        "Don't offer this again": "Huwag nang i-alok ulit",
        "Everything here is off, so calls pass unnoticed": "Naka-off ang lahat dito, kaya lumilipas ang mga tawag nang hindi napapansin",
        "Let the model read your meetings": "Hayaang basahin ng model ang mga meeting mo",
        "Not watching for calls": "Hindi nagbabantay sa mga tawag",
        "Notice when a call starts": "Pansinin kapag nagsimula ang tawag",
        "Off, a recording holds your microphone only — your half of the conversation, in one unbroken block. On, both sides are transcribed as named turns.": "Kapag naka-off, ang recording ay mikropono mo lang — ang kalahati mo ng usapan, sa iisang tuloy-tuloy na bloke. Kapag naka-on, parehong panig ang naitatala bilang may pangalang pagkakasunod.",
        "On": "Naka-on",
        "Or leave this and set them up later in Settings.": "O iwanan ito at i-set up mamaya sa Settings.",
        "Read meeting names from Calendar": "Basahin ang pangalan ng meeting mula sa Calendar",
        "Record the call audio too": "I-record din ang audio ng tawag",
        "Record the call audio, and separate the voices": "I-record ang audio ng tawag, at paghiwalayin ang mga boses",
        "Recordings arrive already titled instead of as “Zoom call, 14:02”. Only titles overlapping a recording are read.": "Dumarating ang mga recording na may pamagat na, sa halip na “Zoom call, 14:02”. Tanging mga pamagat na tumatapat sa recording ang binabasa.",
        "Separate the voices": "Paghiwalayin ang mga boses",
        "Set up calls…": "I-set up ang mga tawag…",
        "The agent searches and reads your transcripts on this Mac; the written answer comes from a provider you connect with your own key.": "Naghahanap at nagbabasa ang agent ng mga transcript mo sa Mac na ito; ang nakasulat na sagot ay galing sa provider na ikinonekta mo gamit ang sarili mong key.",
        "Three things are off. Here is what each one adds.": "Tatlong bagay ang naka-off. Narito kung ano ang idinadagdag ng bawat isa.",
        "Turn all on": "Buksan lahat",
