        "%d s": "%d s",
        "System audio recording is not allowed. Enable Dictate in System Settings → Privacy & Security → Screen & System Audio Recording, then try again.": "Hindi pinapayagan ang pag-record ng system audio. I-enable ang Dictate sa System Settings → Privacy & Security → Screen & System Audio Recording, at subukang muli.",
        "Stop": "Ihinto",
        "Automatic (any language)": "Awtomatiko (anumang wika)",
        "detect while you speak": "natutukoy habang nagsasalita",
