        "Show outline": "Ipakita ang balangkas",
        "two levels": "dalawang antas",
        "%d moments": "%d sandali",
        "Kept on this Mac. Deleting is immediate; beyond 50 conversations the oldest age out.": "Nakatago sa Mac na ito. Agad ang pagbura; lampas sa 50 na usapan, natatanggal ang pinakaluma.",
        "Ask across all meetings…": "Magtanong sa lahat ng meeting…",
        "Recently Added": "Kamakailang Idinagdag",
        "%d meetings · %d h of audio": "%d meeting · %d oras ng audio",
        "%d meetings · %d min of audio": "%d meeting · %d minuto ng audio",
        "Show more": "Ipakita pa",
        "Try one of these": "Subukan ang isa sa mga ito",
        "Accessibility access is turned off": "Naka-off ang Accessibility access",
        "Dictation can hear you but cannot type. Re-enable it to continue.": "Naririnig ka ng dictation pero hindi makapag-type. I-enable muli para magpatuloy.",
        "Recent dictations": "Mga kamakailang diktasyon",
        "Secure input is active — the hotkey cannot work": "Aktibo ang secure input — hindi gagana ang hotkey",
        "Something has a password field focused. macOS does not say which app. Click into an ordinary text field and dictation works again.": "May app na naka-focus sa password field. Hindi sinasabi ng macOS kung alin. Mag-click sa karaniwang text field at gagana muli ang dictation.",
        "Start Recording Meeting": "Mag-record ng Meeting",
        "Stop Recording Meeting": "Ihinto ang Pag-record ng Meeting",
        "dictate in %@": "mag-dikta sa %@",
        "dictate in any language": "mag-dikta sa kahit anong wika",
        "translate %@ → %@": "isalin %@ → %@",
        "translate into %@": "isalin sa %@",
        "%d waiting": "%d ang naghihintay",
        "%d words typed": "%d salita ang na-type",
        "Add a Key…": "Magdagdag ng Key…",
        "Both will be inserted in the order you spoke them": "Pareho silang ilalagay sa pagkakasunod ng pagsabi mo",
        "Check Audio Setup": "Suriin ang Audio Setup",
        "Clear All Filters": "Alisin ang Lahat ng Filter",
        "F-keys can also trigger a system control (brightness, media) — macOS will do both. To use one as a plain key, turn on “Use F1, F2, etc. as standard function keys” in Keyboard settings.": "Ang mga F-key ay nagpapagana rin ng system control (brightness, media) — gagawin ng macOS ang pareho. Para gamitin bilang karaniwang key, i-on ang «Use F1, F2, etc. as standard function keys» sa keyboard settings.",
        "How this works": "Paano ito gumagana",
        "Input device changed": "Nagbago ang input device",
        "Insert text by": "Ilagay ang teksto sa pamamagitan ng",
        "It was revoked or replaced since you connected. It has been removed from the Keychain — nothing was retried with it.": "Binawi o pinalitan na ito mula nang kumonekta ka. Inalis na ito sa Keychain — walang in-ulit gamit ito.",
        "Join a call in the browser, then start recording. Dictate captures your microphone and the call audio, transcribes both on this Mac, and keeps the transcript here. Nothing is uploaded.": "Sumali sa tawag sa browser, saka simulan ang pag-record. Kinukuha ng Dictate ang mikropono mo at audio ng tawag, tina-transcribe pareho sa Mac na ito, at itinatago rito ang transcript. Walang ina-upload.",
        "No meeting has all of these tags": "Walang meeting na may lahat ng tag na ito",
        "No meeting has this tag": "Walang meeting na may tag na ito",
        "Nothing was said, or nothing was heard": "Walang sinabi, o walang narinig",
        "Only the unconfirmed tail is shown here — the rest is already in the document": "Ang hindi pa kumpirmadong dulo lang ang makikita rito — ang iba ay nasa dokumento na",
        "Open Console": "Buksan ang Console",
        "Open Settings": "Buksan ang Settings",
        "Pasting is instant but replaces your clipboard for a moment. Typing works in apps that block paste, such as some terminals and remote desktops.": "Mabilis ang pag-paste pero pansamantalang pinapalitan ang clipboard. Gumagana ang pag-type sa mga app na humaharang sa paste, gaya ng ilang terminal at remote desktop.",
        "Pasting it at once": "Pag-paste nang isahan",
        "Recording ended here — this Mac went to sleep.": "Natapos ang recording dito — natulog ang Mac na ito.",
        "Remove “%@”": "Alisin ang «%@»",
        "Return sends · Shift-Return adds a line · Esc clears": "Return para ipadala · Shift-Return para sa bagong linya · Esc para burahin",
        "Show Floating Timer": "Ipakita ang Floating Timer",
        "Start Recording a Meeting": "Mag-record ng Meeting",
        "Still recognizing the previous dictation": "Kinikilala pa ang naunang diktasyon",
        "Still recognizing the previous dictation · %d words": "Kinikilala pa ang naunang diktasyon · %d salita",
        "Switched to %@": "Lumipat sa %@",
        "Tag filters combine with “and” — a meeting must carry every selected tag to appear.": "Pinagsasama ang mga tag filter gamit ang «at» — dapat taglay ng meeting ang bawat piniling tag.",
        "The answer stopped. Your question is kept above — retry when the connection returns. Search and transcripts still work.": "Huminto ang sagot. Nasa itaas pa rin ang tanong mo — subukan muli kapag bumalik ang koneksyon. Gumagana pa rin ang paghahanap at mga transcript.",
        "The recording ran, but no speech was recognized on either side. Usually this means the call audio was never captured — a browser tab without audio permission, or the wrong output device.": "Tumakbo ang recording pero walang nakilalang boses sa magkabilang panig. Kadalasan ibig sabihin ay hindi nakuha ang audio ng tawag — browser tab na walang audio permission, o maling output device.",
        "The saved key no longer works": "Hindi na gumagana ang naka-save na key",
        "The switch stays off until it is granted in System Settings › Privacy & Security › Calendars. Only event titles that overlap a recording are ever read.": "Mananatiling naka-off ang switch hanggang payagan sa System Settings › Privacy & Security › Calendars. Mga pamagat lang ng event na tumatapat sa recording ang binabasa.",
        "This Mac is offline": "Offline ang Mac na ito",
        "Too many questions at once": "Sobrang daming tanong nang sabay-sabay",
        "Typing as you speak": "Nagta-type habang nagsasalita ka",
        "Typing into %@ as you speak": "Nagta-type sa %@ habang nagsasalita ka",
        "Typing it out character by character": "Pag-type nang paisa-isang titik",
        "Your provider account is out of credit": "Ubos na ang credit ng account ng provider mo",
        "Your provider is rate limiting. Wait a few seconds and retry — nothing was lost.": "Nililimitahan ng provider mo ang dalas. Maghintay ng ilang segundo at subukan muli — walang nawala.",
        "macOS denied calendar access": "Tinanggihan ng macOS ang access sa kalendaryo",
        "API key": "API key",
        "All Meetings": "Lahat ng Meeting",
        "Assistant": "Assistant",
        "Checking the key with %@. No transcript is sent — only a test request.": "Sinusuri ang key sa %@. Walang transcript na ipinapadala — isang test request lang.",
        "Closing the window does not stop the recording. Stop it here, or from the menu bar at any time.": "Hindi hihinto ang pag-record kapag isinara ang window. Ihinto ito rito o mula sa menu bar anumang oras.",
        "Connect an assistant to answer questions": "Ikonekta ang assistant para sagutin ang mga tanong",
        "Dictate can record a browser call and keep the transcript on this Mac. Start one from the menu bar when your next call begins — you will be asked for consent once.": "Kayang i-record ng Dictate ang tawag sa browser at itago ang transcript sa Mac na ito. Simulan mula sa menu bar kapag nagsimula ang susunod mong tawag — isang beses lang hihingin ang pahintulot.",
        "Done": "Tapos na",
        "Every change takes effect immediately.": "Agad na nagkakabisa ang bawat pagbabago.",
        "Get one at %@.": "Kumuha sa %@.",
        "Hold a key, speak, let go. What you said is typed where your cursor is, in any app on this Mac.": "Pindutin nang matagal ang key, magsalita, bitawan. Ang sinabi mo ay itina-type kung nasaan ang cursor, sa kahit anong app sa Mac na ito.",
        "Keys": "Mga Key",
        "Languages": "Mga Wika",
        "Library": "Library",
        "Paste a key from your own account.": "I-paste ang key mula sa sarili mong account.",
        "Saved to your Keychain, but not verified — this Mac is offline. It will be checked the first time you ask something.": "Na-save sa iyong Keychain pero hindi pa na-verify — offline ang Mac na ito. Susuriin sa unang tanong mo.",
        "Set Up Dictate": "I-set Up ang Dictate",
        "Stored in the macOS Keychain on this Mac. Never written to a settings file, never synced.": "Nakaimbak sa macOS Keychain sa Mac na ito. Hindi kailanman isinusulat sa settings file, hindi kailanman sini-sync.",
        "The key was refused. It may be revoked, from a different provider, or out of credit — the key itself was not saved.": "Tinanggihan ang key. Maaaring bawi na ito, mula sa ibang provider, o ubos na ang credit — hindi na-save ang key.",
        "Transcripts, search and quotes work without this. An assistant is only needed to write the answer.": "Gumagana ang mga transcript, paghahanap at quote nang wala nito. Kailangan lang ang assistant para isulat ang sagot.",
        "Try Again": "Subukan Muli",
        "Updates": "Mga Update",
        "You pay your provider per question — typically a fraction of a cent. Only your question and the quoted passages are sent; recordings never leave this Mac.": "Nagbabayad ka sa provider mo kada tanong — kadalasan ay bahagi lang ng isang sentimo. Ang tanong mo at mga siniping sipi lang ang ipinapadala; hindi kailanman aalis ang mga recording sa Mac na ito.",
        "Send": "Ipadala",
        "Conversations": "Mga Usapan",
        "New question": "Bagong tanong",
        "Deleted “%@”": "Tinanggal ang “%@”",
        "Undo": "I-undo",
        "Questions you ask are kept here so you can return to an answer.": "Naka-imbak dito ang mga tanong para mabalikan ang sagot.",
        "Rename": "Palitan ang pangalan",
        "Delete": "Tanggalin",
        "Voices are matched by sound — the name applies only to this voice's turns.": "Tinutugma ang mga boses sa tunog — ang pangalan ay para lang sa mga linya ng boses na ito.",
        "Give two voices the same name to merge them.": "Bigyan ng parehong pangalan ang dalawang boses para pagsamahin ang mga ito.",
        "Voices are told apart by sound — one person can show up as two.": "Pinagkakakilanlan ang mga boses sa tunog — maaaring lumabas na dalawa ang iisang tao.",
        "Click a name to rename a voice — the same name merges two. Summaries and answers rely on what was said, not who said it.": "I-click ang pangalan para palitan ang pangalan ng boses — pinagsasama ng parehong pangalan ang dalawa. Ang mga buod at sagot ay nakabatay sa kung ano ang sinabi, hindi kung sino ang nagsabi.",
        "Voice separation improves over time.": "Bumubuti ang paghihiwalay ng mga boses sa paglipas ng panahon.",
