        "Dictate is running from its disk image": "Tumatakbo ang Dictate mula sa disk image nito",
        "Permissions granted from a disk image are lost as soon as it is ejected, and the model would download again every time. Move Dictate to your Applications folder first.": "Ang mga pahintulot mula sa disk image ay nawawala sa sandaling i-eject ito, at muling dada-download ang model bawat beses. Ilipat muna ang Dictate sa Applications folder.",
