        "Download failed. Check your connection and retry.": "Hindi natuloy ang download. I-check ang connection mo at subukan ulit.",
        "Not set": "Hindi nakatakda",
        "Remove": "Alisin",
        "Download & continue": "I-download at magpatuloy",
        "About %@ — downloaded once. This is the only time Dictate needs the internet.": "Mga %@ — isang beses lang ida-download. Ito lang ang pagkakataong kailangan ng Dictate ng internet.",
        "Hold %@ and say something — the recognized text shows up below.": "I-hold ang %@ at magsabi ng kahit ano — lalabas sa ibaba ang na-recognize na text.",
        "Recognized text appears here…": "Dito lalabas ang na-recognize na text…",
        // Menu bar
