        "Recording truncated at %d seconds (limit)": "Naputol ang recording sa %d segundo (limit)",
        "Audio device changed during recording — recording cancelled, please try again.": "Nagbago ang audio device habang nagre-record — kinansela ang recording, subukan ulit.",
        "Accessibility permission is off, so the key can't be heard. Turn it on in System Settings → Privacy & Security → Accessibility — Dictate picks it up automatically, no restart needed.": "Naka-off ang Accessibility permission, kaya hindi maririnig ang key. I-on ito sa System Settings → Privacy & Security → Accessibility — awtomatiko itong makukuha ng Dictate, hindi na kailangang mag-restart.",
        "Microphone unavailable (no input audio format)": "Hindi magamit ang microphone (walang input audio format)",
        // Key names
        "Right Option (⌥)": "Kanang Option (⌥)",
        "Left Option (⌥)": "Kaliwang Option (⌥)",
        "Right Command (⌘)": "Kanang Command (⌘)",
        "Left Command (⌘)": "Kaliwang Command (⌘)",
        "Right Shift (⇧)": "Kanang Shift (⇧)",
        "Left Shift (⇧)": "Kaliwang Shift (⇧)",
