        "Left Control (⌃)": "Kaliwang Control (⌃)",
        "Space": "Space",
        "Follow system": "Sundan ang system",
        "Translating…": "Nagsasalin…",
        "Tip: hold %@ instead — your speech comes out in English.": "Tip: pindutin nang matagal ang %@ — lalabas sa English ang sinabi mo.",
        "Hold to talk in your language, release to insert it in English.": "Pindutin nang matagal at magsalita sa wika mo; bitawan at English ang mailalagay.",
        "Hold %@ and say it again — this time it's typed in English.": "Pindutin nang matagal ang %@ at ulitin — sa English na ito mata-type.",
        "Translate to": "Isalin sa",
        "Translation data isn't downloaded — open Settings to get it": "Hindi pa na-download ang data ng pagsasalin — i-download ito sa Mga Setting",
        "Translation data": "Data ng pagsasalin",
        "The translate key transcribes your speech, then macOS translates it on this Mac. Picking a language may download its translation data once.": "Nita-transcribe ng translate key ang sinasabi mo, tapos isinasalin iyon ng macOS sa Mac na ito. Kapag pumili ng wika, maaaring mag-download ang macOS ng translation data nito nang isang beses.",
        "Recognition runs on your Mac's Neural Engine — Whisper large-v3-turbo: 100 languages, great with accents, fast enough for live text. Translation runs on this Mac too. Your voice never leaves this computer.": "Tumatakbo ang recognition sa Neural Engine ng iyong Mac — Whisper large-v3-turbo: 100 wika, magaling sa accent, at sapat ang bilis para sa live na teksto. Sa Mac na ito rin ginagawa ang pagsasalin. Hindi kailanman aalis sa computer na ito ang boses mo.",
        "Hold %@ and say it again — this time it comes out in %@.": "Pindutin nang matagal ang %@ at ulitin — sa %@ na ito lalabas.",
        "Hold to talk in your language, release to insert it in %@.": "Pindutin nang matagal at magsalita sa wika mo; bitawan at %@ ang mailalagay.",
        "Not downloaded": "Hindi pa nada-download",
        "Translation languages": "Mga wika ng pagsasalin",
        "Downloaded": "Na-download na",
        "Manage in System Settings…": "Pamahalaan sa System Settings…",
        "Already ON in System Settings but not green here? Turn the Dictate switch off and back on — after an app update macOS sometimes keeps a stale entry.": "Naka-ON na sa System Settings pero hindi pa green dito? I-off at i-on muli ang switch ng Dictate — pagkatapos ng update, minsan may lumang entry na naiiwan ang macOS.",
        "Agent: %@, on your key.": "Agent: %@, gamit ang key mo.",
        "Agent: off.": "Agent: naka-off.",
        "Apple Intelligence isn't available on this Mac in this region or language. The agent with your own key still works.": "Hindi available ang Apple Intelligence sa Mac na ito sa rehiyon o wikang ito. Gumagana pa rin ang agent gamit ang sarili mong key.",
        "Apple Intelligence needs macOS 26. The agent with your own key still works.": "Kailangan ng Apple Intelligence ang macOS 26. Gumagana pa rin ang agent gamit ang sarili mong key.",
        "Copy diagnostics": "Kopyahin ang diagnostics",
        "Debug audio dumps": "Mga debug audio dump",
        "Diagnostics": "Diagnostics",
        "Downloading…": "Dina-download…",
        "Frees %@. New meetings will keep their date names until you download it again. Summaries already written stay.": "Magpapalaya ng %@. Mananatili ang mga petsang pangalan ng mga bagong meeting hanggang i-download mo itong muli. Mananatili ang mga buod na naisulat na.",
        "Frees %@. Nothing else changes — reading your meetings is off.": "Magpapalaya ng %@. Walang ibang magbabago — naka-off ang pagbabasa ng mga meeting mo.",
        "Frees %@. Titles and summaries will come from Apple Intelligence.": "Magpapalaya ng %@. Manggagaling sa Apple Intelligence ang mga pamagat at buod.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16.": "Naka-install pero hindi tumatakbo: may %d GB na memory ang Mac na ito at 16 ang kailangan nito.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Nothing on this Mac reads meetings.": "Naka-install pero hindi tumatakbo: may %d GB na memory ang Mac na ito at 16 ang kailangan nito. Walang nagbabasa ng mga meeting sa Mac na ito.",
        "Installed but not running: this Mac has %d GB of memory and it needs 16. Titles and summaries come from Apple Intelligence instead.": "Naka-install pero hindi tumatakbo: may %d GB na memory ang Mac na ito at 16 ang kailangan nito. Sa halip, manggagaling sa Apple Intelligence ang mga pamagat at buod.",
        "Installed · %@": "Naka-install · %@",
        "Installed, not in use · %@": "Naka-install, hindi ginagamit · %@",
        "It holds about %@ of memory while it writes, which this Mac will feel.": "Humahawak ito ng mga %@ ng memory habang nagsusulat, na mararamdaman ng Mac na ito.",
        "Mac": "Mac",
        "Mac, macOS, version and which features are on. No transcripts, no keys.": "Mac, macOS, bersyon at kung aling mga feature ang naka-on. Walang transcript, walang key.",
        "Meeting archive": "Archive ng meeting",
        "Meeting model": "Meeting model",
        "Meeting model installed. New meetings get titles and summaries on this Mac.": "Naka-install na ang meeting model. Makakakuha ng mga pamagat at buod ang mga bagong meeting sa Mac na ito.",
        "Meeting reading: Apple Intelligence.": "Pagbabasa ng meeting: Apple Intelligence.",
        "Meeting reading: nothing on this Mac can do it yet.": "Pagbabasa ng meeting: wala pang makakagawa nito sa Mac na ito.",
        "Meeting reading: the downloaded model (%@).": "Pagbabasa ng meeting: ang na-download na model (%@).",
        "Not available on this Mac.": "Hindi available sa Mac na ito.",
        "Not installed. A one-time %@ download writes titles, summaries and a table of contents.": "Hindi naka-install. Isang beses na download na %@ ang magsusulat ng mga pamagat, buod at talaan ng nilalaman.",
        "Nothing on this Mac can read yet: Apple Intelligence isn't available here. The agent with your own key still works.": "Wala pang makakabasa sa Mac na ito: hindi available dito ang Apple Intelligence. Gumagana pa rin ang agent gamit ang sarili mong key.",
        "Nothing on this Mac can read yet: download the meeting model below, or add a key for the agent.": "Wala pang makakabasa sa Mac na ito: i-download ang meeting model sa ibaba, o magdagdag ng key para sa agent.",
        "Nothing on this Mac can read yet: download the meeting model below, or turn on Apple Intelligence in System Settings.": "Wala pang makakabasa sa Mac na ito: i-download ang meeting model sa ibaba, o buksan ang Apple Intelligence sa System Settings.",
        "Nothing on this Mac can read yet: macOS is still setting up Apple Intelligence. The agent with your own key still works.": "Wala pang makakabasa sa Mac na ito: sine-set up pa ng macOS ang Apple Intelligence. Gumagana pa rin ang agent gamit ang sarili mong key.",
        "Nothing on this Mac can read yet: turn on Apple Intelligence in System Settings, or add a key for the agent.": "Wala pang makakabasa sa Mac na ito: buksan ang Apple Intelligence sa System Settings, o magdagdag ng key para sa agent.",
        "Open System Settings": "Buksan ang System Settings",
        "Paused: not enough free memory right now. It resumes on its own.": "Naka-pause: kulang ang libreng memory ngayon. Magpapatuloy ito nang kusa.",
        "Preparing the model for this Mac's processor… A few minutes, one time.": "Inihahanda ang model para sa processor ng Mac na ito… Ilang minuto, isang beses lang.",
        "Raw call audio kept for debugging only.": "Hilaw na audio ng tawag na itinatago para sa debugging lang.",
        "Reading is on, but nothing on this Mac can read yet.": "Naka-on ang pagbabasa, pero wala pang makakabasa sa Mac na ito.",
        "Reads with Apple Intelligence.": "Nagbabasa gamit ang Apple Intelligence.",
        "Reads with the downloaded model.": "Nagbabasa gamit ang na-download na model.",
        "Recognition runs on the Neural Engine.": "Tumatakbo ang recognition sa Neural Engine.",
        "Recognition runs on this Mac's processor — Whisper large-v3-turbo: 100 languages, great with accents. Slower than on Apple Silicon, and translation runs on this Mac too. Your voice never leaves this computer.": "Tumatakbo ang recognition sa processor ng Mac na ito — Whisper large-v3-turbo: 100 wika, magaling sa accent. Mas mabagal kaysa sa Apple Silicon, at sa Mac na ito rin ginagawa ang pagsasalin. Hindi kailanman aalis sa computer na ito ang boses mo.",
        "Recognition runs on this Mac's processor — slower than on Apple Silicon.": "Tumatakbo ang recognition sa processor ng Mac na ito — mas mabagal kaysa sa Apple Silicon.",
        "Remove the debug audio dumps?": "Alisin ang mga debug audio dump?",
        "Remove the meeting model?": "Alisin ang meeting model?",
        "Remove…": "Alisin…",
        "Speaker models": "Mga speaker model",
        "Speech model": "Speech model",
        "Storage": "Storage",
        "Summaries on this Mac come from Apple Intelligence. The downloadable model needs 16 GB of memory; this Mac has %d.": "Galing sa Apple Intelligence ang mga buod sa Mac na ito. Kailangan ng dina-download na model ng 16 GB na memory; %d ang sa Mac na ito.",
        "Summary paused: not enough free memory. It resumes on its own.": "Naka-pause ang buod: kulang ang libreng memory. Magpapatuloy ito nang kusa.",
        "Tell the voices on a call apart.": "Paghiwalayin ang mga boses sa tawag.",
        "The meeting model needs 16 GB of memory; this Mac has %d.": "Kailangan ng meeting model ng 16 GB na memory; %d ang sa Mac na ito.",
        "These are recordings kept only for debugging. Nothing else is affected.": "Mga recording ito na itinatago para sa debugging lang. Walang ibang maaapektuhan.",
        "This Mac": "Ang Mac na ito",
        "This build of Dictate does not include the meeting model.": "Hindi kasama sa build na ito ng Dictate ang meeting model.",
        "Titles and summaries come from Apple Intelligence instead.": "Sa halip, manggagaling sa Apple Intelligence ang mga pamagat at buod.",
        "Turn on Apple Intelligence in System Settings › Apple Intelligence & Siri, or add a key for the agent.": "Buksan ang Apple Intelligence sa System Settings › Apple Intelligence & Siri, o magdagdag ng key para sa agent.",
        "Waiting for the call to end.": "Naghihintay na matapos ang tawag.",
        "Your transcripts, as Markdown files you own.": "Ang mga transcript mo, bilang mga Markdown file na pag-aari mo.",
        "macOS is still setting up Apple Intelligence — check back later, or add a key for the agent.": "Sine-set up pa ng macOS ang Apple Intelligence — bumalik mamaya, o magdagdag ng key para sa agent.",
        "%@ · %@. The report stays in the meeting’s file either way; this makes a copy.": "%@ · %@. Nananatili ang report sa file ng meeting anuman ang mangyari; gumagawa ito ng kopya.",
