        "Not discussed": "Hindi natalakay",
        "One empty field. You name it.": "Isang blangkong field. Ikaw ang magpapangalan.",
        "One file per meeting, named by date and title, in a folder you choose. Transcripts are not included.": "Isang file bawat meeting, pinangalanan ayon sa petsa at pamagat, sa folder na pipiliin mo. Hindi kasama ang mga transcript.",
