        "The main arguments and facts, with the numbers, names and dates that were said": "Ang mga pangunahing argumento at katotohanan, kasama ang mga numero, pangalan at petsang nabanggit",
        "The next meeting or checkpoint, if one was agreed": "Ang susunod na meeting o checkpoint, kung napagkasunduan",
        "Waiting on": "Hinihintay mula sa",
        "We are the team on this call; the reader took part in it.": "Kami ang team sa tawag na ito; kasali ang mambabasa dito.",
        "What could go wrong, who raised it, how serious it sounded": "Ano ang maaaring magkamali, sino ang nagbanggit, gaano ito kaseryoso",
        "What each side is waiting for from the other": "Ano ang hinihintay ng bawat panig mula sa isa’t isa",
        "What was decided, by whom, and what it replaces": "Ano ang napagdesisyunan, sino ang nagdesisyon, at ano ang pinalitan nito",
        "What was raised and not settled, and who owns it": "Ano ang nabanggit na hindi naresolba, at sino ang may hawak",
        "Who does what, by when — one line per task": "Sino ang gagawa ng ano, kailan — isang linya bawat gawain",
        "Why we met and what we set out to settle": "Bakit kami nagkita at ano ang nais naming ayusin",
        "%d more": "%d pa",
        "The title keeps the meeting’s language; the summary and every report are written in this one. Field names in a report stay exactly as typed.": "Nananatili ang wika ng meeting sa pamagat; ang buod at bawat report ay isinusulat sa wikang ito. Nananatili ang mga pangalan ng field sa report gaya ng na-type.",
        "About “%@”:": "Tungkol sa “%@”:",
        "Replace the report with a new “%@” one?": "Palitan ang report ng bagong “%@”?",
