        "Written · replaces it": "Naisulat na · papalitan",
        "Dictate updated to %@.": "Na-update ang Dictate sa %@.",
        "Dismiss": "Isara",
        "New": "Bago",
        "New in this version": "Bago sa bersyong ito",
        "Open a meeting and press Write report in its header, then pick a template. The report lands on the card and as a PDF in Dictate Meetings › Reports.": "Buksan ang isang meeting, pindutin ang Write report sa header nito, at pumili ng template. Lalabas ang report sa card at bilang PDF sa Dictate Meetings › Reports.",
        "Reports from templates": "Mga report mula sa mga template",
        "See what’s new": "Tingnan ang bago",
        "Settings › Meetings › Write summaries and reports in: the summary line and every report come in the language you read, whatever language the call was in.": "Settings › Meetings › Isulat ang mga buod at report sa: ang buod at bawat report ay darating sa wikang binabasa mo, anuman ang wika ng tawag.",
        "Settings › Templates: start from Meeting summary or Decisions & actions, or name your own fields and tell the model what goes under each.": "Settings › Templates: magsimula sa Buod ng meeting o Mga desisyon at aksyon, o pangalanan ang sarili mong mga field at sabihin sa model kung ano ang isusulat sa ilalim ng bawat isa.",
        "Summaries in your language": "Mga buod sa iyong wika",
        "What’s new": "Ano ang bago",
        "What’s new in Dictate %@": "Ano ang bago sa Dictate %@",
        "Your own templates": "Sarili mong mga template",
        "Install update %@ and relaunch": "I-install ang update %@ at i-relaunch",
        "The update waits until the recording ends.": "Maghihintay ang update hanggang matapos ang recording.",
        "Update %@ is on its way — downloading now. It installs itself at the next quiet moment; the menu bar offers it sooner.": "Parating na ang update %@ — dina-download ngayon. Mag-i-install ito nang kusa sa susunod na tahimik na sandali; mas maaga sa menu bar.",
        "Update %@ is ready — install it from the menu bar, or it installs itself at the next quiet moment.": "Handa na ang update %@ — i-install mula sa menu bar, o mag-i-install ito nang kusa sa susunod na tahimik na sandali.",
        "An update is already on its way — it installs itself at the next quiet moment.": "May update nang parating — mag-i-install ito nang kusa sa susunod na tahimik na sandali.",
        "Downloading update %@…": "Dina-download ang update %@…",
        "Preparing update %@…": "Inihahanda ang update %@…",
        "Dictate updated to %@. What’s new is in the Meetings window.": "Na-update ang Dictate sa %@. Nasa window ng Meetings ang bago.",
        "Apple Intelligence declined to summarize this meeting.": "Tumanggi ang Apple Intelligence na buurin ang meeting na ito.",
        "The transcript, search and the agent are unchanged. A downloadable model, kept on this Mac, is not restricted that way.": "Hindi apektado ang transcript, paghahanap at agent. Ang nada-download na model, na nakatago sa Mac na ito, ay walang ganoong limitasyon.",
        "Meetings, recorded and structured: speakers, summary, outline, search. Dictate offers to record a call — it never records without your answer.": "Mga meeting na naitala at nakaayos: mga nagsalita, buod, outline, paghahanap. Nag-aalok lang ang Dictate na i-record ang tawag — hindi kailanman nagre-record nang walang sagot mo.",
        "The meeting model needs 16 GB of memory; this Mac has %d. It is not running, and the %@ it takes on disk can be freed.": "Kailangan ng meeting model ng 16 GB na memory; %d ang sa Mac na ito. Hindi ito tumatakbo, at maaaring palayain ang %@ na sinasakop nito sa disk.",
        "Clipboard restored.": "Naibalik na ang clipboard.",
        "Your words were inserted untranslated.": "Nailagay ang iyong mga salita nang hindi isinalin.",
        "A small panel appears when a call starts, and you decide there.": "Lumilitaw ang maliit na panel kapag nagsimula ang tawag at doon ka magdedesisyon.",
        "Writes the summary and the outline, and gives your agent something to answer from. Nothing is sent anywhere either way.": "Sumusulat ng buod at balangkas, at nagbibigay sa agent mo ng masasagot. Anuman ang mangyari, walang ipinapadala kahit saan.",
        "Off, you get only your own microphone; on, the other side is transcribed as well.": "Kapag naka-off, sarili mong mikropono lang; kapag naka-on, naitatala rin ang kabilang panig.",
        "Turns one block of text into named turns. The split is by sound and can be imprecise; the names are yours to change.": "Ginagawa nitong may pangalang pagkakasunod ang iisang bloke ng teksto. Ang paghihiwalay ay batay sa tunog at maaaring hindi eksakto; maaaring baguhin ang mga pangalan.",
        "Find in this transcript…": "Hanapin sa transcript na ito…",
        "%d of %d": "%d sa %d",
        "No matches": "Walang tugma",
        "Previous match": "Naunang tugma",
        "Next match": "Susunod na tugma",
        "Close find": "Isara ang paghahanap",
        "%@ is chosen, but there is no key yet. The agent and reports stay off until one is added.": "Napili ang %@, pero wala pang key. Nakapatay ang agent at mga report hanggang may maidagdag.",
        "%@ · required for dictation, cannot be removed.": "%@ · kailangan sa pagdidikta, hindi maaaring alisin.",
        "%@ — not written": "%@ — hindi naisulat",
        "%d h": "%d oras",
        "%d meetings have a %@ report. They stay if this template goes.": "%d meeting ang may report na “%@”. Mananatili ang mga ito kahit alisin ang template.",
        "%d min ago": "%d min ang nakalipas",
        "%d written": "%d ang naisulat",
        "%d written, %d not written": "%d ang naisulat, %d ang hindi",
        "12 languages. Applies to this window and the menu bar right away. What you speak is set under Dictation.": "12 wika. Agad na naaangkop sa window na ito at sa menu bar. Ang wikang sinasalita mo ay itinatakda sa Pagdidikta.",
        "A key from your own %@ account. Stored in your Keychain, never in a settings file.": "Key mula sa sarili mong %@ account. Nakatago sa Keychain mo, hindi kailanman sa settings file.",
        "A question sends the question and the passages the search found. A report sends that meeting’s whole transcript — about 12,000 words for an hour of talk. Both go to %@ on your key, and only when you ask. The recordings never leave this Mac.": "Ang tanong ay nagpapadala ng tanong at ng mga bahaging nahanap ng search. Ang report ay nagpapadala ng buong transcript ng meeting — mga 12,000 salita kada oras ng usapan. Pareho itong pumupunta sa %@ gamit ang key mo, at kapag hiniling mo lang. Hindi kailanman umaalis sa Mac na ito ang mga recording.",
        "About": "Tungkol",
        "Apple Intelligence isn’t available on this Mac, so there is nothing to fall back on.": "Hindi available ang Apple Intelligence sa Mac na ito, kaya walang mapagbabalikan.",
        "Apple Intelligence needs a newer macOS than this Mac is running, so there is nothing to fall back on.": "Kailangan ng Apple Intelligence ng mas bagong macOS kaysa sa nasa Mac na ito, kaya walang mapagbabalikan.",
        "Applies to this window, the meetings window and the panels over your other apps.": "Naaangkop sa window na ito, sa window ng mga meeting at sa mga panel sa ibabaw ng iba mong app.",
        "Asked once. After this, the panel is the short version, and it stays until you answer it. You can also start recording from the menu bar at any point during a call.": "Isang beses lang itatanong. Pagkatapos nito, maikling bersyon na ang panel at mananatili hanggang sagutin mo. Maaari ka ring magsimulang mag-record mula sa menu bar anumang oras sa tawag.",
        "Calendar": "Kalendaryo",
        "Collapse %@": "I-collapse ang %@",
        "Copy": "Kopyahin",
        "Dictation": "Pagdidikta",
        "Expand %@": "I-expand ang %@",
        "Export…": "I-export…",
        "It is also in Recent dictations, so the clipboard is yours again whenever you like.": "Nasa Kamakailang pagdidikta rin ito, kaya sa iyo ulit ang clipboard kailan mo man gusto.",
        "Kept inside this meeting’s file, so they travel with the transcript. Export makes a copy anywhere you like.": "Nakatago sa loob ng file ng meeting na ito, kaya kasama ng transcript. Ang export ay gumagawa ng kopya kahit saan mo gusto.",
        "No report": "Walang report",
        "No report for this meeting yet.": "Wala pang report para sa meeting na ito.",
        "Nothing is lost by removing it: the transcript, search and the agent do not depend on it.": "Walang mawawala kapag inalis ito: hindi umaasa rito ang transcript, search at agent.",
        "Nothing is set here. Every line above either reports what this Mac can do or points at the pane that owns it.": "Walang itinatakda rito. Bawat linya sa itaas ay nag-uulat kung ano ang kaya ng Mac na ito o tumuturo sa pane na may hawak nito.",
        "Nothing on this Mac can read yet: Apple Intelligence needs a newer macOS. The agent with your own key still works.": "Wala pang makakabasa sa Mac na ito: kailangan ng Apple Intelligence ng mas bagong macOS. Gumagana pa rin ang agent gamit ang sarili mong key.",
        "Nothing was kept from this take — earlier ones are still here.": "Walang naitago mula sa take na ito — nandito pa rin ang mga nauna.",
        "Nothing was recorded, so nothing was kept. Earlier ones are still here.": "Walang na-record, kaya walang naitago. Nandito pa rin ang mga nauna.",
        "Off — dictation cannot type": "Naka-off — hindi makapag-type ang pagdidikta",
        "Off: transcripts, summaries, outlines and search work as before. The agent answers questions across your meetings and writes reports from your templates; it runs in the cloud on your own API key.": "Naka-off: gumagana gaya ng dati ang mga transcript, buod, outline at search. Sinasagot ng agent ang mga tanong sa lahat ng meeting mo at sumusulat ng mga report mula sa mga template mo; tumatakbo ito sa cloud gamit ang sarili mong API key.",
        "On this Mac": "Sa Mac na ito",
        "One resumable file. Closing Dictate pauses it; it picks up where it stopped.": "Isang file na maaaring ituloy. Kapag isinara ang Dictate, mapapahinto ito at magpapatuloy kung saan tumigil.",
        "One-time %@ download, then titles, summaries and outlines run entirely on this Mac. It needs 16 GB of memory to run and holds about %@ while it writes.": "Isang beses na download na %@, at pagkatapos ay ginagawa nang buo sa Mac na ito ang mga pamagat, buod at outline. Kailangan nito ng 16 GB na memory para tumakbo at umaabot sa mga %@ habang nagsusulat.",
        "Open System Settings…": "Buksan ang System Settings…",
        "Or start from the menu bar later in the call.": "O magsimula mula sa menu bar mamaya sa tawag.",
        "Paused right now: not enough free memory. It resumes on its own, and the meetings waiting for a summary keep their transcripts.": "Nakahinto ngayon: kulang ang libreng memory. Kusa itong magpapatuloy, at nananatili ang transcript ng mga meeting na naghihintay ng buod.",
        "Permissions": "Mga pahintulot",
        "Reads with Apple Intelligence until the download finishes.": "Nagbabasa gamit ang Apple Intelligence hanggang matapos ang download.",
        "Reads with the downloaded model — paused until there is free memory.": "Nagbabasa gamit ang na-download na model — nakahinto hanggang may libreng memory.",
        "Report templates are under Templates; written reports are in the library, under Reports.": "Nasa Mga template ang mga template ng report; nasa library, sa ilalim ng Mga report, ang mga naisulat na report.",
        "Report · %@": "Report · %@",
        "Report · %@ +%d": "Report · %@ +%d",
        "Reports need the agent, which is off. Choose Claude or ChatGPT under Summaries & reports; the templates keep until then.": "Kailangan ng mga report ang agent, na naka-off. Pumili ng Claude o ChatGPT sa ilalim ng Mga buod at report; mananatili ang mga template hanggang doon.",
        "Runs entirely on this Mac. Without it, titles and summaries come from Apple Intelligence.": "Tumatakbo nang buo sa Mac na ito. Kung wala ito, galing sa Apple Intelligence ang mga pamagat at buod.",
        "Startup": "Pagsisimula",
        "Stored in your Keychain, never in a settings file. The agent answers questions across your meetings and writes reports from your templates.": "Nakatago sa Keychain mo, hindi kailanman sa settings file. Sinasagot ng agent ang mga tanong sa lahat ng meeting mo at sumusulat ng mga report mula sa mga template mo.",
        "Summaries": "Mga buod",
        "Summaries & reports": "Mga buod at report",
        "The download is the way to get summaries on this Mac without Apple Intelligence. The transcript and search work either way.": "Ang download ang paraan para magkaroon ng mga buod sa Mac na ito nang walang Apple Intelligence. Gumagana ang transcript at search kahit alin.",
        "This Mac was offline. Nothing was sent.": "Offline ang Mac na ito. Walang naipadala.",
        "This take was not kept. Earlier ones are still here.": "Hindi naitago ang take na ito. Nandito pa rin ang mga nauna.",
        "Uses 41 MB of speaker models.": "Gumagamit ng 41 MB na mga speaker model.",
        "What’s new in %@": "Ano ang bago sa %@",
        "Whether anything reads these recordings — summaries, outlines, reports and the agent — is under Summaries & reports. This pane is only about what gets recorded on this Mac.": "Kung may bumabasa sa mga recording na ito — mga buod, outline, report at ang agent — ay nasa ilalim ng Mga buod at report. Ang pane na ito ay tungkol lang sa kung ano ang nire-record sa Mac na ito.",
        "Write again": "Isulat muli",
        "Write report above lists your %d templates. Writing one sends this transcript to %@ on your key; the report is kept inside this meeting’s file, so it travels with the transcript. Export makes a copy anywhere you like.": "Nakalista sa Isulat ang report sa itaas ang %d template mo. Ang pagsulat ng isa ay nagpapadala ng transcript na ito sa %@ gamit ang key mo; nakatago ang report sa loob ng file ng meeting na ito, kaya kasama ng transcript. Ang export ay gumagawa ng kopya kahit saan mo gusto.",
        "Written %@": "Isinulat noong %@",
        "Written by %@": "Isinulat ng %@",
        "Written by %@ %@ at %@": "Isinulat ng %@ noong %@ nang %@",
        "Written in": "Isinusulat sa",
        "Your agent, on your key": "Ang agent mo, gamit ang key mo",
        "click to insert": "i-click para ipasok",
        "macOS is still setting up Apple Intelligence. It may take a while and cannot be hurried from here.": "Sine-set up pa ng macOS ang Apple Intelligence. Maaaring magtagal at hindi ito mapapabilis mula rito.",
        "macOS resets this switch after some updates and never asks a second time.": "Nire-reset ng macOS ang switch na ito pagkatapos ng ilang update at hindi na muling nagtatanong.",
        "⌥-click to copy instead. Cleared when Dictate quits.": "⌥-click para kopyahin sa halip. Binubura kapag nag-quit ang Dictate.",
        "Meeting names": "Mga pangalan ng meeting",
        "%d meetings, reports included": "%d meeting, kasama ang mga report",
        "Download the meeting model under Summaries & reports, or add a key for the agent.": "I-download ang meeting model sa ilalim ng Mga buod at report, o magdagdag ng key para sa agent.",
        "Calls": "Mga tawag",
        "Reports folder": "Folder ng mga report",
        "%d PDFs written before %@": "%d PDF na naisulat bago ang %@",
        "Dictate no longer writes PDFs on its own. These are yours to keep or delete; nothing in the app depends on them.": "Hindi na kusang sumusulat ng PDF ang Dictate. Sa iyo ang mga ito, itago man o burahin; walang umaasa sa mga ito sa app.",
        "The report already written is replaced. Sends this transcript to %@ on your key.": "Papalitan ang report na naisulat na. Ipinapadala ang transcript na ito sa %@ gamit ang key mo.",
        "%@ · report not written": "%@ · hindi naisulat ang report",
        "%d of %d selected · %d meetings without one": "%d sa %d ang napili · %d meeting na wala pa",
        "%d passages from %d meetings": "%d bahagi mula sa %d meeting",
        "%d written across %d templates": "%d ang naisulat sa %d template",
        "%d written · %d meetings without one · %d fields": "%d ang naisulat · %d meeting na wala pa · %d field",
        "%d written · writing %d · %d not written": "%d ang naisulat · isinusulat ang %d · %d ang hindi naisulat",
        "A report is written on demand — from a meeting’s card, or for a selection here. Each one sends that meeting’s transcript to %@ on your key and is kept inside the meeting’s file.": "Ang report ay isinusulat kapag hiniling — mula sa card ng meeting, o para sa napili rito. Bawat isa ay nagpapadala ng transcript ng meeting na iyon sa %@ gamit ang key mo at nakatago sa loob ng file ng meeting.",
        "All reports": "Lahat ng report",
        "Answer": "Sagot",
        "Answered by %@ from %d of %d meetings. Quotes are verbatim from transcripts on this Mac.": "Sinagot ng %@ mula sa %d sa %d meeting. Ang mga sipi ay salita-por-salita mula sa mga transcript sa Mac na ito.",
        "Copy as Markdown": "Kopyahin bilang Markdown",
        "Copy as plain text": "Kopyahin bilang plain text",
        "Copy the answer only": "Kopyahin ang sagot lang",
        "Copy with quotes": "Kopyahin kasama ang mga sipi",
        "Each template keeps its own reports: what is written, and the meetings that could have one. Templates themselves are edited in Settings › Templates.": "Bawat template ay may sariling mga report: kung ano ang naisulat, at ang mga meeting na maaaring magkaroon nito. Ang mga template mismo ay ini-edit sa Settings › Mga template.",
        "Edit template…": "I-edit ang template…",
        "No report yet · %d meetings": "Wala pang report · %d meeting",
        "None written · %d fields": "Wala pang naisulat · %d field",
        "Nothing written from this template yet": "Wala pang naisulat mula sa template na ito",
        "Off, those %d are skipped and %d reports are written. Replacing cannot be undone.": "Kapag naka-off, lalaktawan ang %d na iyon at %d report ang isusulat. Hindi maibabalik ang pagpapalit.",
        "Pick a template": "Pumili ng template",
        "Quotes": "Mga sipi",
        "Replace the %d that already have one": "Palitan ang %d na mayroon na",
        "Report not written — the request was refused. The meeting has the detail.": "Hindi naisulat ang report — tinanggihan ang kahilingan. Nasa meeting ang detalye.",
        "Sends %d transcripts to %@ on your key — about %@ words. Each report is kept inside its own meeting’s file. The recordings never leave this Mac.": "Nagpapadala ng %d transcript sa %@ gamit ang key mo — mga %@ salita. Bawat report ay nakatago sa file ng sarili nitong meeting. Hindi kailanman umaalis sa Mac na ito ang mga recording.",
        "The %d existing reports are overwritten. This cannot be undone.": "Mapapatungan ang %d umiiral na report. Hindi ito maibabalik.",
        "Write": "Isulat",
        "Write %d": "Isulat ang %d",
        "Write %d reports…": "Isulat ang %d report…",
        "Write a “%@” report for %d meetings?": "Isulat ang report na “%@” para sa %d meeting?",
        "Write a “%@” report for “%@”?": "Isulat ang report na “%@” para sa “%@”?",
        "Write all %d…": "Isulat lahat ng %d…",
        "Write for a selection…": "Isulat para sa napili…",
        "Write report › %@": "Isulat ang report › %@",
        "Written": "Naisulat",
        "No instruction — goes by its name alone": "Walang tagubilin — sa pangalan lang",
        "Drag to reorder": "Hilahin para ayusin ang pagkakasunod",
        "Every report is kept inside its meeting’s file.": "Bawat report ay nakatago sa file ng meeting nito.",
        "A refusal stops that meeting only; the rest continue.": "Ang pagtanggi ay pumipigil lang sa meeting na iyon; nagpapatuloy ang iba.",
        "Always assume": "Palaging ipagpalagay",
        "Facts the call never states but every report should take as given: who you are, which side is the client, words your team uses in a particular way. Sent with every report from this template.": "Mga katotohanang hindi sinasabi sa tawag pero dapat ipagpalagay ng bawat report: kung sino ka, aling panig ang kliyente, mga salitang may partikular na gamit sa team mo. Ipinapadala kasama ng bawat report mula sa template na ito.",
        "Optional. Without it the model reads the call cold, which is usually fine for a meeting between colleagues and wrong for a call with an outside party.": "Opsyonal. Kung wala ito, binabasa ng model ang tawag nang walang batayan — karaniwang ayos para sa meeting ng magkakasamahan, mali para sa tawag sa taga-labas.",
        "We are a sales agency. The client is always the other party, never us. “Seats” means paid user licences.": "Sales agency kami. Ang kliyente ay palaging ang kabilang panig, hindi kami. Ang “seats” ay mga bayad na user license.",
        "Shown on the meeting’s card, in the library under Reports, and as the heading inside the written report.": "Ipinapakita sa card ng meeting, sa library sa ilalim ng Mga report, at bilang heading sa loob ng naisulat na report.",
        "Each field becomes a heading in the report, in this order. Drag a field by its handle to move it. An instruction is optional and can be as long as it needs to be; a field without one goes by its name alone.": "Bawat field ay nagiging heading sa report, sa ganitong pagkakasunod. Hilahin ang field sa hawakan nito para ilipat. Opsyonal ang tagubilin at maaaring kasinghaba ng kailangan; ang field na wala nito ay sa pangalan lang.",
        "Every field is filled from this call’s transcript and nothing else. One the call did not cover reads “Not discussed”.": "Bawat field ay pinupunan mula sa transcript ng tawag na ito at wala nang iba. Ang hindi natalakay sa tawag ay magbabasang “Not discussed”.",
        "A template is a name and a few fields. A report is written from it on demand, one per template per meeting.": "Ang template ay pangalan at ilang field. Ang report ay isinusulat mula rito kapag hiniling, isa kada template kada meeting.",
        "No templates yet. A template is a name and a few fields; a report is written from it on demand from a meeting’s card, one per template per meeting.": "Wala pang template. Ang template ay pangalan at ilang field; ang report ay isinusulat mula rito kapag hiniling mula sa card ng meeting, isa kada template kada meeting.",
    ]
}
